__reload_all = true
local System = require("System.System")
local readonly = System.readonly
local Text_Voice = readonly({
  Voice_100335_AwakerVoiceContent = {
    Text = "Custode, quando potrò tornare al cimitero dei Mythag? Le grandi anime sepolte là devono darmi grandi ispirazioni! Non preoccuparti, prometto che non dissotterrerò quei cadaveri per esaminarli da vicino un'altra volta..."
  },
  Voice_100335_AwakerVoiceTitle = {
    Text = "Dialogo: A proposito dei Modelli"
  },
  Voice_100336_AwakerVoiceContent = {
    Text = "Aspettate! Ho concepito una nuova tecnica. Provocherà uno scuotimento nell'intero mondo dell'arte!"
  },
  Voice_100336_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_100337_AwakerVoiceContent = {
    Text = "Io sono il sanguinare della luce nell'ombra. Io sono il sussurro di pigmento e vernice. Io sono... la fame che dipinge!"
  },
  Voice_100337_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_100338_AwakerVoiceContent = {
    Text = "Hmm? ...C'è un colore nella vostra psiche, uno che non ho mai visto... cos'è..."
  },
  Voice_100338_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_100338_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_100339_AwakerVoiceContent = {
    Text = "Ah, una squisita vernice nera! Un tempo usavo molto liquido di Dissoluzione per i dipinti, ma quelle opere sono tutte svanite. Colori dall'universo antico, che divorano il mio dipinto, dimenticati per sempre dal mondo... Non è forse ancora meglio?!"
  },
  Voice_100339_AwakerVoiceTitle = {
    Text = "Chiacchiere: Riguardo alla Crisi"
  },
  Voice_100340_AwakerVoiceContent = {
    Text = "Lasciatemi avvicinare... lasciatemi vedere di più! Queste luci, queste ombre, queste forme... tutto ciò che ho dipinto prima è spazzatura al confronto..."
  },
  Voice_100340_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_100340_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_100341_AwakerVoiceContent = {
    Text = "Doresain dice sempre che la sua cucina è arte. Ma per favore. Mangiare non ha niente a che fare con l'arte! Spreca tempo prezioso per dipingere nella preparazione di cadaveri, e dopo aver creato un piatto dall'aspetto e dal sapore gradevole, devo masticarlo e ingoiarlo! È un crimine contro l'arte!"
  },
  Voice_100341_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_100342_AwakerVoiceContent = {Text = "Ugh..."},
  Voice_100342_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_100343_AwakerVoiceContent = {
    Text = "Che modella insopportabile..."
  },
  Voice_100343_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_100344_AwakerVoiceContent = {
    Text = "No, no, un altro dipinto orribile... Dove posso trovare l'intuizione? In un cimitero? O in un patibolo..."
  },
  Voice_100344_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_100345_AwakerVoiceContent = {
    Text = "Di solito trovo la scultura rigida e noiosa, ma quella scultrice, Sanga, il suo scalpello ha un potere che va oltre la tecnica... una vera genialità!"
  },
  Voice_100345_AwakerVoiceTitle = {
    Text = "Dialogo: A proposito di Sanga"
  },
  Voice_100345_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliatore \"Sanga\""
  },
  Voice_100346_AwakerVoiceContent = {
    Text = "Avete visto questo, Custode? È il vostro ritratto. Guardate come siete incantevole mentre divorate cadaveri! So che non tutti comprendono il mio lavoro, ma voi dovete percepire la splendida follia che vi è racchiusa, vero?! Per me, questo basta. Più che abbastanza..."
  },
  Voice_100346_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_100346_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_100347_AwakerVoiceContent = {
    Text = "Volete comprare questo dipinto... davvero?! G-grazie, Custode! G-gli esseri umani raramente lo comprendono..."
  },
  Voice_100347_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_100347_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_100348_AwakerVoiceContent = {
    Text = "Custode, hai tempo per posare di nuovo? Rispetto a ciò che ho visto in te l'ultima volta, gli altri modelli sono solo uno spreco del mio tempo..."
  },
  Voice_100348_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_100349_AwakerVoiceContent = {
    Text = "In questo dipinto, assisti a una nuova nascita!"
  },
  Voice_100349_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_100350_AwakerVoiceContent = {
    Text = "Guarda che linee vivaci!"
  },
  Voice_100350_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_100351_AwakerVoiceContent = {
    Text = "Questa pennellata... sarà un capolavoro di impasto! Ne resteranno sbalorditi!"
  },
  Voice_100351_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_100352_AwakerVoiceContent = {
    Text = "Ah! Un pigmento inedito! Devo applicarlo dove meglio completerà la composizione!"
  },
  Voice_100352_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_100353_AwakerVoiceContent = {
    Text = "Questo posto mi ispira! Ho un nuovo lavoro, Custode. Avete tempo per visitare il mio studio? Venite, venite!"
  },
  Voice_100353_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_100353_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_100354_AwakerVoiceContent = {
    Text = "Esatto, perfetto! Una vittoria dipinta nel sangue! Che composizione brillante!"
  },
  Voice_100354_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_100355_AwakerVoiceContent = {Text = "Ugh..."},
  Voice_100355_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_100356_AwakerVoiceContent = {
    Text = "Ah! Prego, sedetevi, Custode. Posare per me è un lavoro difficile, lo so. Fidatevi, farò di voi un capolavoro."
  },
  Voice_100356_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_100356_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_100357_AwakerVoiceContent = {
    Text = "Un artista dovrebbe vedere solo l'opera, senza curarsi del giudizio altrui... ma io non ci riesco. Da quando ho impugnato un pennello per la prima volta, ho voluto mostrare a tutti la vera bellezza."
  },
  Voice_100357_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_100357_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_100358_AwakerVoiceContent = {
    Text = "Questo posto mi riporta ai tempi dell'accademia d'arte. La maggior parte degli insegnanti e degli studenti non capiva nulla d'arte, ma c'erano sempre uno o due che sapevano vedere la bellezza nei miei dipinti."
  },
  Voice_100358_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_100359_AwakerVoiceContent = {
    Text = "Che genere di arte folle partorirà questa performance barbarica?!"
  },
  Voice_100359_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_100360_AwakerVoiceContent = {
    Text = "La mia tavolozza!"
  },
  Voice_100360_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_100361_AwakerVoiceContent = {
    Text = "Anche il dolore è arte..."
  },
  Voice_100361_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_100362_AwakerVoiceContent = {
    Text = "Ah! Lo vedo... l'Occhio Senza Pupilla sotto l'Abisso, l'ultima visione dell'universo... Solo un momento ancora, Custode, è quasi finito!"
  },
  Voice_100362_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_100362_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_100363_AwakerVoiceContent = {
    Text = "Il mio pennello, ricavato dalla mia tibia. La tavolozza, questi colori provenienti dai cimiteri di venti città diverse... e la mia preziosa tela di pelle! Custode, prendete tutto questo e dipingetemi! No, no, non vi serve abilità... Credo che quando le nostre anime si incontreranno sulla tela, sarà un capolavoro al di là dei miei sogni...!"
  },
  Voice_100363_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_100363_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_100364_AwakerVoiceContent = {
    Text = "Io sono il sanguinare della luce nell'ombra. Io sono il sussurro di pigmento e vernice. Io sono... la fame che dipinge!"
  },
  Voice_100364_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_100365_AwakerVoiceContent = {
    Text = "Ti piace questo colore?"
  },
  Voice_100365_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_100366_AwakerVoiceContent = {
    Text = "La vera essenza dell'arte risiede nella Follia...!"
  },
  Voice_100366_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_100367_AwakerVoiceContent = {
    Text = "Cosa? Stai suggerendo un primo piano su questa parte del corpo nel mio prossimo lavoro? Hmm... Non ci avevo mai pensato! Buona idea!"
  },
  Voice_100367_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_100368_AwakerVoiceContent = {Text = "Attento!"},
  Voice_100368_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_100369_AwakerVoiceContent = {
    Text = "La vera essenza dell'arte risiede nella Follia...!"
  },
  Voice_100369_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_100370_AwakerVoiceContent = {
    Text = "La mia tavolozza!"
  },
  Voice_100370_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_100371_AwakerVoiceContent = {
    Text = "Oh! Guardate quella mascella affilata! Quegli occhi brillanti! E una figura dalle proporzioni ideali... per non parlare del vasto cielo stellato del vostro spirito che traspare... Sono il pittore Pickman! Potrei avere il supremo onore di ritrarvi come mio modello?"
  },
  Voice_100371_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_100372_AwakerVoiceContent = {
    Text = "La mia arte parla di follia e tumulto, ma la musica di quel Hameln è serrata, come lapidi in un cimitero. Eppure, per qualche ragione, vedo sempre il peggior caos dell'universo in quelle note ordinate..."
  },
  Voice_100372_AwakerVoiceTitle = {
    Text = "Dialogo: A proposito di Hameln"
  },
  Voice_100372_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliatore \"Sanga\""
  },
  Voice_100373_AwakerVoiceContent = {
    Text = "Guardate, Custode! La scena eterna e folle sulla tela! Così bella, così devastante! Ciò che germoglia da questa follia e da questo dolore è arte..."
  },
  Voice_100373_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_100373_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_100374_AwakerVoiceContent = {
    Text = "Ah! M-mi perdonate, Custode... vedo qualcosa in voi... più terribile, e più incantevole dell'Abisso..."
  },
  Voice_100374_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_100374_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_100375_AwakerVoiceContent = {
    Text = "Non capisco. Perché qualcuno dovrebbe rifiutare l'occasione di diventare un ghoul?! Questa bellezza sanguinaria e folle è molto più divertente che essere un noioso umano in una grande casa, no?!"
  },
  Voice_100375_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_100376_AwakerVoiceContent = {Text = "Ha!"},
  Voice_100376_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_116964_AwakerVoiceContent = {
    Text = "Punizione！"
  },
  Voice_116964_AwakerVoiceTitle = {
    Text = "Abilità Speciale: I"
  },
  Voice_116965_AwakerVoiceContent = {
    Text = "Punizione！"
  },
  Voice_116965_AwakerVoiceTitle = {
    Text = "Abilità Speciale: II"
  },
  Voice_117791_AwakerVoiceContent = {
    Text = "Ammetto che possiede una rozza abilità nel rubare, ma una dama raffinata come me non ha bisogno di trucchi così spregevoli. Se desidero qualcosa, faccio semplicemente in modo che me lo consegnino \"volontariamente.\""
  },
  Voice_117791_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Jenkin"
  },
  Voice_117791_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Jenkin\""
  },
  Voice_117792_AwakerVoiceContent = {
    Text = "Hahaha! Mie, tutte mie! Tutte le caramelle di Mythag appartengono a me! Che cosa state aspettando? Seguitemi, la grande Strega delle Caramelle! Conquisteremo ogni pasticceria di Londinium, adesso!"
  },
  Voice_117792_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_117792_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_117793_AwakerVoiceContent = {
    Text = "Niente caramelle? Allora questa Strega sarà costretta a fare sul serio!"
  },
  Voice_117793_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_117794_AwakerVoiceContent = {
    Text = "Come fanno a mettere il ripieno dentro? Non riesco a trovare giunture né fori! Vorrei che questi inventori di caramelle entrassero nello staff di Mythag e inventassero un nuovo dolce per me ogni singolo giorno!"
  },
  Voice_117794_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_117795_AwakerVoiceContent = {
    Text = "Non osate sfidare la Strega!"
  },
  Voice_117795_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_117796_AwakerVoiceContent = {
    Text = "Un tempo trovavo le caramelle troppo semplici e non abbastanza eleganti rispetto alle torte, ma ora mi rendo conto di aver sottovalutato queste piccole cose in involucri di plastica colorata. Hanno una scadenza così lunga! Potrei accumularne quante ne voglio, potrei riempirci l'intera stanza!"
  },
  Voice_117796_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_117797_AwakerVoiceContent = {
    Text = "Hai trovato una nuova caramella? Fammi vedere... Tsk, questo Ring Pop è così ridicolo! Un anello di \"diamante\" grande come un uovo? Aspetta! Che intendi presentandomi un anello? Spiegati immediatamente!"
  },
  Voice_117797_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_117797_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_117798_AwakerVoiceContent = {
    Text = "Ho sentito che le streghe hanno un gatto nero misterioso. Ma quel disgustoso randagio del campus è troppo imbarazzante per una dama raffinata come me. Quindi, è deciso. Mettiti questa cerchietta da {Male=catboy,Female=catgirl}. Farò di te il mio piccolo gatto nero."
  },
  Voice_117798_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_117798_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_117799_AwakerVoiceContent = {
    Text = "La Resistenza è inutile."
  },
  Voice_117799_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_117800_AwakerVoiceContent = {Text = "BLEEEHHH!"},
  Voice_117800_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_117801_AwakerVoiceContent = {
    Text = "Esistono davvero le Streghe? Se vivono in foreste deserte, chi si occupa della cucina, delle pulizie e della preparazione dei dolci? Se non riesci nemmeno a organizzare un tè pomeridiano, che senso ha quella vita? Non sopporto nemmeno il pensiero."
  },
  Voice_117801_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_117801_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_117802_AwakerVoiceContent = {
    Text = "La Strega sta arrivando!"
  },
  Voice_117802_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_117803_AwakerVoiceContent = {
    Text = "Hai ancora del cioccolato? Eccellente, dallo tutto a me. Come? Le tue cose sono le mie cose; non è forse naturale?"
  },
  Voice_117803_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_117803_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_117804_AwakerVoiceContent = {
    Text = "Quale dolcetto mi piace di più? Fammi pensare... Il croccante alla nocciola è fragrante, il cioccolato al caramello è delizioso, quelle gelatine al gusto di fragola e uva hanno una consistenza davvero divertente, e poi c'è uno zucchero di malto che si può tirare lunghissimo e ha un bel colore dorato come il miele... No, mi rifiuto di scegliere. Ogni dolcetto ha il suo fascino unico! In ogni caso, ho un sacco di cestini di zucca, quindi li prendo tutti!"
  },
  Voice_117804_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_117804_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_117805_AwakerVoiceContent = {
    Text = "Il mio attuale obiettivo nella vita è mangiare ogni singola caramella al mondo. Il solo pensiero degli innumerevoli tipi di caramelle che mi aspettano là fuori... è la mia unica ragione per alzarmi dal letto. Torta, dici? La torta è il mio altro obiettivo nella vita."
  },
  Voice_117805_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_117805_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_117806_AwakerVoiceContent = {
    Text = "Non lasciatevi ingannare dal suo aspetto! Tulu sembra un bambino, ma è praticamente un residente della tomba. Non ha alcun bisogno di ciò che una persona viva apprezza, tantomeno delle caramelle. Quindi, le caramelle a lui destinate... dovreste consegnarle tutte a me. Sono l'unica che le apprezzerà davvero."
  },
  Voice_117806_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Tulu"
  },
  Voice_117806_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Tulu\""
  },
  Voice_117807_AwakerVoiceContent = {
    Text = "Se fossi una strega, il mio palazzo sarebbe il massimo del lusso, naturalmente. Assumerei dieci chef stellati per preparare torte e caramelle nuove ogni giorno... Dite che sarei una principessa, non una strega? E allora? Sarò la Principessa Strega!"
  },
  Voice_117807_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_117807_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_117808_AwakerVoiceContent = {
    Text = "Ehi! Vai a prendermi diverse varietà di dentifricio, presto! No, non ho mangiato così tante caramelle! E non ho una carie! È solo che... mi fa un po' male quando dormo..."
  },
  Voice_117808_AwakerVoiceTitle = {
    Text = "Chat: A proposito delle caramelle"
  },
  Voice_117809_AwakerVoiceContent = {
    Text = "Le regole del ristorante di Mythag sono spesso irritanti, ma le loro abilità in pasticceria... hmm, sono appena passabili, suppongo."
  },
  Voice_117809_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_117810_AwakerVoiceContent = {
    Text = "Il mondo è pieno di cose oscure e disgustose. Invece di preoccuparti della sua fine, faresti meglio a usare quel tempo per mangiare qualche altra caramella prima che accada."
  },
  Voice_117810_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_117811_AwakerVoiceContent = {Text = "Ahi!"},
  Voice_117811_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_117812_AwakerVoiceContent = {
    Text = "Niente più tappeti di morbida pelle d'agnello, collane di perle nere o pigiami di seta dall'estremo oriente... eppure, svegliarsi ogni giorno in una stanza piena di dolcetti, con i cestini che traboccano... forse è questo il vero aspetto della felicità... Ehi, togliti quel sorriso sciocco dalla faccia! Se vuoi servirmi per sempre, hai ancora un sacco di lavoro da fare!"
  },
  Voice_117812_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_117812_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_117813_AwakerVoiceContent = {
    Text = "Quegli spregevoli di Mythag, che osano impedirmi l'accesso alle caramelle! Visto? Alla fine le ho ottenute lo stesso!"
  },
  Voice_117813_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_117814_AwakerVoiceContent = {
    Text = "Vuoi un po' delle mie caramelle? Hmph. Mi sento generosa, quindi potrei concederti un pezzo... se mi supplichi a dovere, s'intende."
  },
  Voice_117814_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_117815_AwakerVoiceContent = {
    Text = "Come osi chiamarla \"rapina\"? Sto semplicemente esercitando il nobile privilegio di una dama!"
  },
  Voice_117815_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_117816_AwakerVoiceContent = {
    Text = "La Giusta Strega delle Caramelle è arrivata! Tutti i dolci smarriti torneranno alla loro legittima, gloriosa proprietaria!"
  },
  Voice_117816_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_117817_AwakerVoiceContent = {
    Text = "Maledizione a te, essere avaro! Mi ricorderò la tua faccia..."
  },
  Voice_117817_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_117818_AwakerVoiceContent = {
    Text = "Perché quel topolino può rubare caramelle spudoratamente, e io no? Questa è palese discriminazione contro una dama! Che mancanza di rispetto!"
  },
  Voice_117818_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_117819_AwakerVoiceContent = {
    Text = "Niente caramelle? Allora questa Strega sarà costretta a fare sul serio!"
  },
  Voice_117819_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_117820_AwakerVoiceContent = {
    Text = "Prendi una caramella!"
  },
  Voice_117820_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_117821_AwakerVoiceContent = {
    Text = "Sei molto più premuroso di quei terribili camerieri — hai persino riservato delle caramelle solo per me. Continua così, mio servitore esclusivo."
  },
  Voice_117821_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_117821_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_117822_AwakerVoiceContent = {Text = "BLEEEHHH!"},
  Voice_117822_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_117823_AwakerVoiceContent = {Text = "È troppo!"},
  Voice_117823_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_117824_AwakerVoiceContent = {
    Text = "Perché mi fermi? Come mio fedele servitore, non dovresti aiutarmi attivamente a rapina... voglio dire, ad acquisire tutte le caramelle?"
  },
  Voice_117824_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_117825_AwakerVoiceContent = {
    Text = "Fermi! Questa è una rapina! Vi consiglio di essere ragionevoli e consegnare tutte le vostre caramelle, altrimenti... Hmph."
  },
  Voice_117825_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_117826_AwakerVoiceContent = {
    Text = "Morbide, dure, croccanti, sfogliose, al latte, alla frutta, alle noci, al cioccolato... Ah, com'è possibile che ci siano ancora così tante varietà che non ho assaggiato? Ho deciso: Mythag deve rendere Halloween una festività settimanale!"
  },
  Voice_117826_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_117827_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_117827_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_117828_AwakerVoiceContent = {
    Text = "La Grande Strega trionferà! Il grande dio delle caramelle mi protegge, e io, a mia volta, proteggo tutte le caramelle! AHAHAHA!"
  },
  Voice_117828_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_117829_AwakerVoiceContent = {
    Text = "La Resistenza è inutile."
  },
  Voice_117829_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_117830_AwakerVoiceContent = {
    Text = "Tutte le caramelle alla fine apparterranno a me!"
  },
  Voice_117830_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_117831_AwakerVoiceContent = {
    Text = "Quella bambina è spaventosamente obbediente. Consegna tutte le sue caramelle senza fiatare... il che in effetti mi fa sentire marginalmente in colpa. Ahem! Voglio dire, dato che è così ragionevole, la benevola Strega le lascerà naturalmente qualche caramella... come piccola ricompensa!"
  },
  Voice_117831_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Lily"
  },
  Voice_117831_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Lily\""
  },
  Voice_117832_AwakerVoiceContent = {
    Text = "Non osate sfidare la Strega!"
  },
  Voice_117832_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_117833_AwakerVoiceContent = {
    Text = "Adesso sono ufficialmente furiosa!"
  },
  Voice_117833_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_117834_AwakerVoiceContent = {
    Text = "Tutte le caramelle alla fine apparterranno a me!"
  },
  Voice_117834_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_117835_AwakerVoiceContent = {
    Text = "Cosa? Questo tipo di marshmallow si può arrostire? Ma diventerà caldo e appiccicoso... Sei sicuro che sia buono? Fammi provare... Va bene, ne prendo un morsetto. Se osi ingannarmi... Eh?! Questa consistenza morbida e croccante è davvero incredibile!"
  },
  Voice_117835_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_117835_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_122115_AwakerVoiceContent = {
    Text = "Illusione, Inversione... Questi sono gli strumenti del Fato!"
  },
  Voice_122115_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_122117_AwakerVoiceContent = {
    Text = "Illusione, Inversione... Questi sono gli strumenti del Fato!"
  },
  Voice_122117_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_123312_AwakerVoiceContent = {
    Text = "Quindi il mio vero io non ti spaventa perché hai \"visto il vero terrore\"? Hmph... una risposta astuta. Ma questo mi fa solo... venire ancora più voglia di smontarti pezzo per pezzo."
  },
  Voice_123312_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_123312_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_123313_AwakerVoiceContent = {
    Text = "Com'è il mondo ai tuoi Occhi? Dove sono i limiti del vero terrore? Non limitarti a dirmelo; voglio andare a sentirlo in prima persona con te, sentire tutta la Follia, la morte e l'Orrore! Sì, ho deciso! Non mi muoverò dal tuo fianco finché la mia curiosità non sarà soddisfatta!"
  },
  Voice_123313_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_123313_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_123314_AwakerVoiceContent = {
    Text = "Una maniaca incontrollabile? Bingo! Questo non è il mio mondo; nessuna legge tediosa o Regole possono trattenermi... Qui faccio quello che voglio. Quindi stai attento, Custode, non sai mai quando una maniaca potrebbe dare un Morso."
  },
  Voice_123314_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_123314_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_123315_AwakerVoiceContent = {
    Text = "Vuoi una conversazione profonda per la mia salute mentale? Dai, risparmiamelo. Se proprio dobbiamo annoiarci, almeno facciamola breve."
  },
  Voice_123315_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_123315_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_123316_AwakerVoiceContent = {
    Text = "Dici che sto solo fingendo di essere normale quando rispondo alle tue domande? Heh, mi hai scoperto. Allora, sei pronto a vedere cosa sono davvero?"
  },
  Voice_123316_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_123316_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_123770_AwakerVoiceContent = {
    Text = "Via la testa."
  },
  Voice_123770_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_123771_AwakerVoiceContent = {
    Text = "Ecco la preferita di tutti—Brillante☆Tornado!"
  },
  Voice_123771_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_123772_AwakerVoiceContent = {
    Text = "Non dovrei essere io..."
  },
  Voice_123772_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_123773_AwakerVoiceContent = {
    Text = "Brillante☆Impatto!"
  },
  Voice_123773_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_123774_AwakerVoiceContent = {
    Text = "Vuoi salvare questo mondo contorto e terrificante? Sarà un modo follemente divertente di morire. Vediamo fin dove riesci ad arrivare."
  },
  Voice_123774_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_123775_AwakerVoiceContent = {
    Text = "Volete assaggiare la mia ascia, dolcezze? Non temete, eccola che arriva..."
  },
  Voice_123775_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_123776_AwakerVoiceContent = {
    Text = "Custode, credo di aver visto una luce... Ha funzionato stavolta...? Chissà come stanno i miei colleghi? Spero non mi lascino una montagna di lavoro arretrato; non farò straordinari."
  },
  Voice_123776_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_123776_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_123777_AwakerVoiceContent = {
    Text = "Questo Rito mi riporta al Focolare? Sei sicuro? Quante volte abbiamo provato...? Beh, tentare non nuoce, suppongo."
  },
  Voice_123777_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_123777_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_123778_AwakerVoiceContent = {
    Text = "Ahah, questa sì che è vita! Molto meglio della solita noiosa routine quotidiana!"
  },
  Voice_123778_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_123779_AwakerVoiceContent = {Text = "Ha!"},
  Voice_123779_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_123780_AwakerVoiceContent = {
    Text = "Non dovrei essere io..."
  },
  Voice_123780_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_123781_AwakerVoiceContent = {
    Text = "Brillante☆Supernova—ESPLOSIONE!"
  },
  Voice_123781_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_123782_AwakerVoiceContent = {
    Text = "Ecco la preferita di tutti—Brillante☆Tornado!"
  },
  Voice_123782_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_123783_AwakerVoiceContent = {
    Text = "Mi sembra di entrare di nuovo nella Nebbia. A proposito, mi mancano già quelle piccole creature nella Nebbia. Peccato che non possa più sfogare il mio malumore su di loro."
  },
  Voice_123783_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_123783_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_123784_AwakerVoiceContent = {
    Text = "Odio? Non direi. Desidero semplicemente che quelle riunioni tediose, gli obblighi sociali e i valori universali un giorno possano... Puf! Sparire."
  },
  Voice_123784_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_123785_AwakerVoiceContent = {
    Text = "Ecco... Mi sto avvicinando al mio \"vero io\". Lo sento..."
  },
  Voice_123785_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_123786_AwakerVoiceContent = {
    Text = "Ah... Quindi non ha funzionato. Me lo aspettavo. La vita è piena di alti e bassi—beh, soprattutto bassi... prima o poi ci si abitua. Comunque, grazie per averci provato."
  },
  Voice_123786_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_123786_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_123787_AwakerVoiceContent = {
    Text = "Della Dissoluzione ne so quanto del Disastro di Nebbia a casa mia—nulla, cioè. Ma è proprio questo che li rende così affascinanti, no?"
  },
  Voice_123787_AwakerVoiceTitle = {
    Text = "Chiacchiere: Riguardo alla Crisi"
  },
  Voice_123788_AwakerVoiceContent = {
    Text = "Mi chiamo Mouchette, Investigatore di... Oh giusto, non sono più l'avanguardia dell'A.U.G.E. Lasciate che mi presenti di nuovo—sono Mouchette, solo una dolce e adorabile Bambina."
  },
  Voice_123788_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_123789_AwakerVoiceContent = {Text = "Vattene!"},
  Voice_123789_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_123790_AwakerVoiceContent = {
    Text = "Siamo troppo vicini agli insediamenti umani qui; adulti noiosi ovunque... Hai mai pensato di spostare la scuola nelle profondità della Catena Montuosa deserta?"
  },
  Voice_123790_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_123791_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_123791_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_123792_AwakerVoiceContent = {
    Text = "Comincio ad amare questa sensazione di essere intrappolata in un altro mondo! Risvegliati Forti, Dissoluzione terrificante e divinità misteriose! Ah, la pura euforia di essere lontani dalla banalità!"
  },
  Voice_123792_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_123793_AwakerVoiceContent = {
    Text = "Tutto qui? Stavo appena iniziando a divertirmi! Avanti, chi è il prossimo da fare a pezzi?"
  },
  Voice_123793_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_123794_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_123794_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_123795_AwakerVoiceContent = {
    Text = "Dicono che un fallimento non ti definisce... Non sono d'accordo! Sarà la mia ascia a definirvi, quindi tenete gli occhi ben aperti!"
  },
  Voice_123795_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_123796_AwakerVoiceContent = {
    Text = "Nuova missione? La prossima volta risparmia i convenevoli; siamo ben oltre il bisogno di eseguire i \"rituali di socializzazione\" ormai."
  },
  Voice_123796_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_123797_AwakerVoiceContent = {
    Text = "Sacrificarsi per gli altri? Che idea stupida. È esasperante. Nessuno ha il diritto di chiederlo a qualcuno, nemmeno un dio."
  },
  Voice_123797_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Salvador"
  },
  Voice_123797_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risveglio \"Salvador\""
  },
  Voice_123798_AwakerVoiceContent = {
    Text = "Hah, niente male..."
  },
  Voice_123798_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_123799_AwakerVoiceContent = {
    Text = "Finalmente, basta fingere... Ora, divertiamoci <Italic:davvero>."
  },
  Voice_123799_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_123800_AwakerVoiceContent = {
    Text = "Il Rito non è ancora finito? Voglio davvero tornare. Ultimamente ho una gran voglia di Pesce stufato di Ravenlog e di un fumante Tè Kava alla Nocciola. Anche se il Tè nero di Ceylon e i Churros Andalusi di qui non sono niente male."
  },
  Voice_123800_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_123800_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_123801_AwakerVoiceContent = {
    Text = "Quindi continui a potenziarmi. Non hai paura che un giorno potrei perdere il controllo? Scherzo... Ahah!"
  },
  Voice_123801_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_123802_AwakerVoiceContent = {
    Text = "Sai, non sembra poi così male restare qui per un po'. Ricorderò tutto ciò che accade qui, lo metterò per iscritto e lo condividerò con loro al Focolare. Che ne dici del titolo <Italic:Le Avventure di Mouchette nell'Altro Mondo>? Ha un bel suono, no?"
  },
  Voice_123802_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_123802_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_123803_AwakerVoiceContent = {
    Text = "Ammetto che è piuttosto carina... Sì, è adorabile quando insegue e combatte quei randagi del campus."
  },
  Voice_123803_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Murphy"
  },
  Voice_123803_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risveglio \"Murphy\""
  },
  Voice_123804_AwakerVoiceContent = {
    Text = "Sono ancora bloccata qui, ma ehi, diventare più forte fa sempre piacere."
  },
  Voice_123804_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_123805_AwakerVoiceContent = {
    Text = "Un'Ancella? Lo sono stata anch'io. Dovrei trovare il tempo di mostrarle le mie mosse con l'aspirapolvere in Battaglia!"
  },
  Voice_123805_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Karen"
  },
  Voice_123805_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risveglio \"Karen\""
  },
  Voice_123806_AwakerVoiceContent = {
    Text = "Ahah, questa sì che è vita! Molto meglio della solita noiosa routine quotidiana!"
  },
  Voice_123806_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_124737_AwakerVoiceContent = {
    Text = "Un colpo, una vittima."
  },
  Voice_124737_AwakerVoiceTitle = {
    Text = "Abilità Speciale: II"
  },
  Voice_124738_AwakerVoiceContent = {
    Text = "Mettetevi in fila per la mia ascia!"
  },
  Voice_124738_AwakerVoiceTitle = {
    Text = "Abilità Speciale: I"
  },
  Voice_124769_AwakerVoiceContent = {Text = "Svanisci!"},
  Voice_124769_AwakerVoiceTitle = {
    Text = "Abilità Speciale: I"
  },
  Voice_126946_AwakerVoiceContent = {
    Text = "Non pensate, non vi affannate; ascoltate ciecamente, obbedite mutamente, poiché la Spoglia Mortale non è che Fardello!"
  },
  Voice_126946_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_126947_AwakerVoiceContent = {
    Text = "Non pensate, non vi affannate; ascoltate ciecamente, obbedite mutamente, poiché la Spoglia Mortale non è che Fardello!"
  },
  Voice_126947_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_126948_AwakerVoiceContent = {
    Text = "Chiedi perché i Loro crani siano così vacui? Hmm, forse è semplicemente la Loro natura."
  },
  Voice_126948_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_126949_AwakerVoiceContent = {
    Text = "Non soffrite Furia alcuna, non conoscete Risentimento, poiché Tutto è Nullità."
  },
  Voice_126949_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_126950_AwakerVoiceContent = {
    Text = "Tanta premura mi fa venire voglia di stuzzicarti ancora di più."
  },
  Voice_126950_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_126951_AwakerVoiceContent = {Text = "Oops!"},
  Voice_126951_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_126952_AwakerVoiceContent = {
    Text = "Attendi da me una bellezza più grande, o un terrore più grande?"
  },
  Voice_126952_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_126953_AwakerVoiceContent = {
    Text = "C'era una volta una Principessa nata dal Piacere. Le sue vesti erano intessute d'oro, la sua pelle simile all'avorio, il profumo di legno d'agaro aleggiava intorno a lei, e il semplice volgere del suo Sguardo poteva rubare un'anima."
  },
  Voice_126953_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_126953_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_126954_AwakerVoiceContent = {
    Text = "Ben presto si stancò del gioco. I suoi devoti non facevano che ripetere lo stesso teatro, consumati dall'Amore nato dalla Lussuria, o dalla Lussuria nata dall'Amore. La loro stoltezza — il loro strazio per il tradimento e la perdita — la annoiava. Anche le loro lacrime la annoiavano."
  },
  Voice_126954_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_126954_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_126955_AwakerVoiceContent = {
    Text = "Lo sguardo di menti così meschine e comuni mi è di assoluto tormento."
  },
  Voice_126955_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_126956_AwakerVoiceContent = {
    Text = "Quella Dama in Rosso una volta mi inviò diversi inviti per i suoi salotti.\nI dolci stranieri erano passabili, ma...\nAvrebbe dovuto informarmi prima che nella sua residenza, \"dessert\" e \"servitù\" non fossero sinonimi."
  },
  Voice_126956_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Sorel"
  },
  Voice_126956_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Sorel\""
  },
  Voice_126958_AwakerVoiceContent = {
    Text = "Non mi ami forse? Allora perché ti rannicchi quando sei avvolto? Non mi detesti forse? Allora perché piangi quando non c'è ritorno?\nOh, ora temi la mia ombra? La fragranza della magnolia bianca è diventata per te un muschio stucchevole e inspiegabile?"
  },
  Voice_126958_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_126958_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_126959_AwakerVoiceContent = {Text = "Certo."},
  Voice_126959_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_126960_AwakerVoiceContent = {
    Text = "Oh? Chiedi perché portassero quei segni sotto le braccia? Non lo trovi assolutamente spassoso?"
  },
  Voice_126960_AwakerVoiceTitle = {
    Text = "Chiacchiere: L'Ordine della Grazia Crescente"
  },
  Voice_126961_AwakerVoiceContent = {Text = "Oops!"},
  Voice_126961_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_126963_AwakerVoiceContent = {
    Text = "Questi piccoli svaghi mi aggradano più delle offerte dei miei devoti."
  },
  Voice_126963_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_126964_AwakerVoiceContent = {
    Text = "Prima il Loro portamento, poi la Loro forma, finché non possedettero anche un paio di... o meglio, finché tutto ciò che restava degno di memoria non fu un paio di begli Occhi che Catturano l'Anima — occhi identici ai miei."
  },
  Voice_126964_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_126964_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_126965_AwakerVoiceContent = {
    Text = "Oggi sono terribilmente annoiata. Non c'è alcun desiderio che vorresti che io esaudissi?\n\nPeccato che non ce ne siano. Così tanti sono disposti a brandire la falce e offrirmi dolci bocconi per fini ben più futili.\nMa se sei tu a chiedere..."
  },
  Voice_126965_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_126965_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_126966_AwakerVoiceContent = {
    Text = "Perché l'Ordine della Grazia Crescente mi segue, e quale fu la sua genesi? Una domanda divertente. Anche tu hai conosciuto la persona irraggiungibile, o il rimpianto di una lotta fallita?\nHmm, a quanto pare no. Che spreco. Quell'espressione di lotta disperata—sarebbe così delizioso vederla sul tuo volto."
  },
  Voice_126966_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_126966_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_126967_AwakerVoiceContent = {
    Text = "...Se continuerai a oltrepassare questi confini, le sembianze che assumo per te potrebbero non restare così gradevoli."
  },
  Voice_126967_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_126968_AwakerVoiceContent = {
    Text = "Ho quasi del tutto dimenticato la sua storia, ma era una storia di Estasi, una di Crudeltà, una che iniziava con l'Abbandono e la Retribuzione, e si concludeva con il Sacrificio e l'Obbedienza Cieca."
  },
  Voice_126968_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_126968_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_126969_AwakerVoiceContent = {
    Text = "Dilettami. Trucidarvi l'un l'altro nel dolore e nel terrore!"
  },
  Voice_126969_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_126970_AwakerVoiceContent = {
    Text = "...Questo, almeno, mi concede una lieve scintilla d'interesse."
  },
  Voice_126970_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_126971_AwakerVoiceContent = {
    Text = "Sotto il mio ventaglio, ogni anima vede il volto della persona più cara. Presto questo potere ai deboli, affinché lo brandiscano come una lama per il mio divertimento.\n\nMa forse—dico solo forse. Se tu ne fossi ammaliato, conoscerei un'Estasi vera e incontaminata."
  },
  Voice_126971_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_126971_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_126972_AwakerVoiceContent = {
    Text = [[
Non ti crucciare; tu non sei come quella moltitudine comune. 
Silenzio. Non guardare dietro di me. Non badare alla carezza invisibile. Guarda nei miei occhi, e solo nei miei occhi.]]
  },
  Voice_126972_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_126972_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_126973_AwakerVoiceContent = {
    Text = "Hehe... C'è qualcuno tra voi che osi contemplare la mia vera forma?"
  },
  Voice_126973_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_126975_AwakerVoiceContent = {
    Text = "Fastidioso."
  },
  Voice_126975_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_126976_AwakerVoiceContent = {
    Text = "Ah, fissi di nuovo il mio ventaglio, rapito? Hehe. Non importa quale volto desideri, te lo concederò. Avanti, avvicinati—\nOh? Rifiuti? Parole così fredde, eppure un'espressione così adorabile..."
  },
  Voice_126976_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_126976_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_126977_AwakerVoiceContent = {
    Text = "Cosa cerchi nella mia Terra senza sogni?"
  },
  Voice_126977_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_126978_AwakerVoiceContent = {
    Text = "Non soffrite Furia alcuna, non conoscete Risentimento, poiché Tutto è Nullità."
  },
  Voice_126978_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_126979_AwakerVoiceContent = {
    Text = "Frena la tua impudenza."
  },
  Voice_126979_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_126980_AwakerVoiceContent = {Text = "Certo."},
  Voice_126980_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_126981_AwakerVoiceContent = {
    Text = "Anch'io un tempo avevo una ragazza così graziosa e compiacente. Un bocciolo tentatore, naturalmente aveva bisogno di qualche spina... non poteva semplicemente essere messa in un vaso."
  },
  Voice_126981_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Lily"
  },
  Voice_126981_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Lily\""
  },
  Voice_126982_AwakerVoiceContent = {
    Text = "L'Università ha respinto con tanta fermezza la mia richiesta per l'ufficio di terapia psicologica. Che strano; quale obiezione potevano mai avere?"
  },
  Voice_126982_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_126983_AwakerVoiceContent = {
    Text = "Tutte le cose finiscono nel Vuoto. Perché non cercare qualche ulteriore piacere con me prima di allora?\n\nStai tranquillo, se dovesse giungere il giorno in cui non potrai più resistere alla Dissoluzione, non permetterò che ti reclami per prima."
  },
  Voice_126983_AwakerVoiceTitle = {
    Text = "Chiacchiere: Riguardo alla Crisi"
  },
  Voice_126984_AwakerVoiceContent = {Text = "Noioso."},
  Voice_126984_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_126985_AwakerVoiceContent = {
    Text = "Sei davvero una meraviglia, così preoccupato per le banalità del corporeo, in un mondo già segnato dalla rovina.\n\nMi spinge a interessarmi personalmente."
  },
  Voice_126985_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_126985_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_126986_AwakerVoiceContent = {
    Text = "Non avanzare!"
  },
  Voice_126986_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_126988_AwakerVoiceContent = {
    Text = "Io sono Xu, la Signora della Terra senza sogni. Se, nel tuo cuore, vi è qualcuno che brami vedere, eppure non puoi raggiungere, abbasserò il mio ventaglio e ti concederò uno sguardo."
  },
  Voice_126988_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_127088_AwakerVoiceContent = {
    Text = "Tutti gli esseri appena nati sono una seccatura. Piccoli, morbidi, rumorosi, comandano inconsciamente tutto ciò che li circonda.\n\nApprezzo gli spettacoli, ma decisamente non quel genere. Vi prego, fate in modo che restino lontani, molto lontani."
  },
  Voice_127088_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_127089_AwakerVoiceContent = {
    Text = "Tu? Tu sei la mia piccola Jasmine, la mia cara obbediente, il delizioso gioco della casetta a cui partecipo così volentieri...\nAh, meri vaneggiamenti felici. Vi prego, non fateci caso."
  },
  Voice_127089_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_127090_AwakerVoiceContent = {
    Text = "Nelle leggende dell'Impero Panlong, il pavone è una bestia avvenente, sgargiante e malevola. Bello e crudele—fa battere il cuore. Brutto e gentile, invece, è piuttosto noioso."
  },
  Voice_127090_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_129651_AwakerVoiceContent = {
    Text = "Divorare! Gnam gnam!"
  },
  Voice_129651_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_129652_AwakerVoiceContent = {Text = "Glu glu~"},
  Voice_129652_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_129653_AwakerVoiceContent = {
    Text = "Coalsie, io, mangiare, insieme? Insieme!"
  },
  Voice_129653_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_129653_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_129654_AwakerVoiceContent = {
    Text = "Vortice! Molto forte!"
  },
  Voice_129654_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_129655_AwakerVoiceContent = {
    Text = "Abisso! Spirale! Svanito, tutto — tutto diventa Vortice!"
  },
  Voice_129655_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_129656_AwakerVoiceContent = {Text = "Ahi!"},
  Voice_129656_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_129657_AwakerVoiceContent = {
    Text = "Non toccare! Tu rompere!"
  },
  Voice_129657_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_129657_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_129658_AwakerVoiceContent = {
    Text = "Conchiglia, luccicante! Bella! Per te!"
  },
  Voice_129658_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_129658_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_129659_AwakerVoiceContent = {
    Text = "Freddo, paura. Vortice, nascondersi!"
  },
  Voice_129659_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito di Doll"
  },
  Voice_129659_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Doll\""
  },
  Voice_129660_AwakerVoiceContent = {Text = "Evviva!"},
  Voice_129660_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_129661_AwakerVoiceContent = {
    Text = "Caccia! Cattivi! Rompere! Vortice, colpirli, rompere!"
  },
  Voice_129661_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_129662_AwakerVoiceContent = {
    Text = "Troppo bello! Prossima volta! Ancora!"
  },
  Voice_129662_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_129662_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_129663_AwakerVoiceContent = {
    Text = "Pat pat, bene! Vortice, tu, pat pat!"
  },
  Voice_129663_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_129664_AwakerVoiceContent = {
    Text = "No, no! Coalsie, Vortice protegge!"
  },
  Voice_129664_AwakerVoiceTitle = {
    Text = "Chiacchiere: Riguardo alla Crisi"
  },
  Voice_129665_AwakerVoiceContent = {
    Text = "Ancora? Ancora!"
  },
  Voice_129665_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_129666_AwakerVoiceContent = {
    Text = "Hehe, Vortice, giocare!"
  },
  Voice_129666_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_129667_AwakerVoiceContent = {
    Text = "Onda grossa in arrivo!"
  },
  Voice_129667_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_129668_AwakerVoiceContent = {Text = "Bang!"},
  Voice_129668_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_129669_AwakerVoiceContent = {Text = "Ahi!"},
  Voice_129669_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_129670_AwakerVoiceContent = {Text = "Eek!"},
  Voice_129670_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_129671_AwakerVoiceContent = {
    Text = "Rito?! Porta me!"
  },
  Voice_129671_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_129671_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_129672_AwakerVoiceContent = {
    Text = "Vortice! Forte! Bene!"
  },
  Voice_129672_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_129672_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_129673_AwakerVoiceContent = {Text = "Bang!"},
  Voice_129673_AwakerVoiceTitle = {
    Text = "Abilità Speciale: I"
  },
  Voice_129674_AwakerVoiceContent = {Text = "Evviva!"},
  Voice_129674_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_129675_AwakerVoiceContent = {
    Text = "Whoosh whoosh~"
  },
  Voice_129675_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_129676_AwakerVoiceContent = {Text = "Lotta!"},
  Voice_129676_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Golia"
  },
  Voice_129676_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Golia\""
  },
  Voice_129677_AwakerVoiceContent = {
    Text = "Trovare tanti, luccicante!"
  },
  Voice_129677_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_129677_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_129678_AwakerVoiceContent = {
    Text = "Abisso! Spirale! Svanito, tutto — tutto diventa Vortice!"
  },
  Voice_129678_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_129679_AwakerVoiceContent = {Text = "Yahoo!"},
  Voice_129679_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_129680_AwakerVoiceContent = {Text = "Eek!"},
  Voice_129680_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_129681_AwakerVoiceContent = {
    Text = "Vortice! Molto forte!"
  },
  Voice_129681_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_129682_AwakerVoiceContent = {
    Text = "Divorare! Gnam gnam!"
  },
  Voice_129682_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_129683_AwakerVoiceContent = {
    Text = "Nautilus, Nautila, Coalsie! Luccicanti!"
  },
  Voice_129683_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_129684_AwakerVoiceContent = {
    Text = "Vortice, carica!"
  },
  Voice_129684_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_129685_AwakerVoiceContent = {
    Text = "Vortice, spazza via!"
  },
  Voice_129685_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_129686_AwakerVoiceContent = {
    Text = "Abbraccio! Vortice! Piace!"
  },
  Voice_129686_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_129686_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_129687_AwakerVoiceContent = {
    Text = "Coalsie, amica! Vortice, per sempre!"
  },
  Voice_129687_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_129688_AwakerVoiceContent = {
    Text = "Presto, presto!"
  },
  Voice_129688_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_129688_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_129689_AwakerVoiceContent = {
    Text = "Vortice! Coalsie! Insieme, sempre? Per sempre!"
  },
  Voice_129689_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_129689_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_129690_AwakerVoiceContent = {
    Text = "Whoosh whoosh~ Onda grande su!"
  },
  Voice_129690_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_129690_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_129691_AwakerVoiceContent = {
    Text = "Amici! Tanti! Piace!"
  },
  Voice_129691_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_129692_AwakerVoiceContent = {
    Text = "Vortice! Grande!"
  },
  Voice_129692_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_129693_AwakerVoiceContent = {
    Text = "Nautila, mi manchi... Eh? Nautila, Vortice, qui, Vortice, QUI!"
  },
  Voice_129693_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Nautila"
  },
  Voice_129693_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Nautila\""
  },
  Voice_129694_AwakerVoiceContent = {
    Text = "Vortice! Forte!"
  },
  Voice_129694_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_129695_AwakerVoiceContent = {
    Text = "Io! Vortice! Yahoo!"
  },
  Voice_129695_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_130511_AwakerVoiceContent = {Text = "Phew—"},
  Voice_130511_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_133720_AwakerVoiceContent = {
    Text = "L'errore va corretto."
  },
  Voice_133720_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_133721_AwakerVoiceContent = {
    Text = "La tragedia che hai davanti è solo uno sguardo tra innumerevoli possibilità.\n\nOltre il sipario del fato giace un palcoscenico inghiottito dall'oscurità—\nluci spente, attori scomparsi, tutto che ritorna nel profondo.\n\nMa non è lì che finisce.\nPorto con me la determinazione di sopportare questa fatica ingrata, fino al giorno in cui le luci torneranno."
  },
  Voice_133721_AwakerVoiceTitle = {
    Text = "Chiacchiere: Riguardo alla Crisi"
  },
  Voice_133722_AwakerVoiceContent = {
    Text = "Il destino di ogni anima è trasportato dai fili... ma il tuo è un copione che non riesco a decifrare. Mi ritrovo ad attendere con impazienza qualunque improvvisazione porterai in questo mondo."
  },
  Voice_133722_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_133723_AwakerVoiceContent = {
    Text = "Il palcoscenico è sempre stato tuo. Fatti avanti, cara marionetta."
  },
  Voice_133723_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_133724_AwakerVoiceContent = {Text = "Hm?"},
  Voice_133724_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_133725_AwakerVoiceContent = {
    Text = "Tutto è un epilogo passato. Tutto è un nuovo prologo. Il nuovo capitolo tra noi attende che sia tu a scriverlo, Custode."
  },
  Voice_133725_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_133725_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_133726_AwakerVoiceContent = {
    Text = "Se la commedia è la tua inclinazione, <Italic:Sogno di una notte di mezza estate> farebbe al caso tuo. Sono particolarmente affezionato alle birichinate di Puck—nascosto nella risata di uno spiritello, il fato lascia sempre sfuggire qualcosa."
  },
  Voice_133726_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_133726_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_133727_AwakerVoiceContent = {
    Text = "Sottomettiti."
  },
  Voice_133727_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_133728_AwakerVoiceContent = {
    Text = "Il fuso del fato ora gira."
  },
  Voice_133728_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_133729_AwakerVoiceContent = {
    Text = "Prigioniero del fato, miserabile come sempre... ciò che è scritto non può essere rifiutato."
  },
  Voice_133729_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_133730_AwakerVoiceContent = {
    Text = "Anche chi osserva ogni cosa resta un attore maldestro nel proprio copione. Reggere la tela del fato, eppure essere legati dai suoi fili—percorriamo strade diverse in questa circostanza predestinata, ma nessuno dei due ha mai veramente abbandonato le proprie fatiche ingrate. Sciocco, forse. Illuso, forse. Così è per me, e così è per lei."
  },
  Voice_133730_AwakerVoiceTitle = {
    Text = "Conversazione: A proposito di Tawil"
  },
  Voice_133730_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risveglio \"Tawil\""
  },
  Voice_133731_AwakerVoiceContent = {
    Text = "Una svolta inattesa?"
  },
  Voice_133731_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_133732_AwakerVoiceContent = {
    Text = "Grazie per avermi accompagnato attraverso tanti sipari che si alzano e si abbassano. Non ti deluderò—ci sono ancora molte serate a venire che ti commuoveranno in modi che non ti aspetti."
  },
  Voice_133732_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_133732_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_133733_AwakerVoiceContent = {
    Text = "Che cantante dotata. Una voce donata dalla grazia, limpida e ardente al tempo stesso, come se sorgesse dal fato in persona. Se si esibisse nel mio teatro, immagino che persino il pubblico più esigente ne resterebbe spiazzato."
  },
  Voice_133733_AwakerVoiceTitle = {
    Text = "Conversazione: A proposito di Tintura"
  },
  Voice_133733_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Tinct\""
  },
  Voice_133734_AwakerVoiceContent = {
    Text = "I fili invisibili che appartengono a te e a me si sono avvolti strettamente l'uno all'altro da tempo, tessendo al contempo una gabbia e una strada.\nNon riesco a vedere dove finisce la gabbia, né dove conduce la strada.\nÈ proprio questo che rende questa storia così avvincente."
  },
  Voice_133734_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_133734_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_133735_AwakerVoiceContent = {
    Text = "I fili del fato pendono immobili."
  },
  Voice_133735_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_133736_AwakerVoiceContent = {
    Text = "Visita spesso il mio teatro... ma so che non viene per le opere. Sembra usare questo palcoscenico per conferire una certa raffinatezza alla propria immagine. Un'abilità notevole, tuttavia—spenderla solo come spettatrice sembra uno spreco. Quella signora non è il tipo che sboccia nell'oscurità della platea. Il suo posto è sotto i riflettori."
  },
  Voice_133736_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Sorel"
  },
  Voice_133736_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Sorel\""
  },
  Voice_133737_AwakerVoiceContent = {
    Text = "Una volta l'ho sentito suonare. Quella musica faceva tremare l'anima... Forse dovrei invitarlo a comporre una sinfonia del fato per la mia prossima produzione."
  },
  Voice_133737_AwakerVoiceTitle = {
    Text = "Dialogo: A proposito di Hameln"
  },
  Voice_133737_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliatore \"Sanga\""
  },
  Voice_133738_AwakerVoiceContent = {
    Text = "Un'altra storia, splendidamente compiuta, volge al termine."
  },
  Voice_133738_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_133739_AwakerVoiceContent = {
    Text = "L'ho vista infine nella sua interezza. L'infinita rete del fato."
  },
  Voice_133739_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_133740_AwakerVoiceContent = {
    Text = "Se me lo concedessi... desidero tessere un'opera che appartenga solo a te e a me. \nNessun pubblico, nessuna prova. Desidero semplicemente vedere come il filo che nemmeno io riesco a leggere comincerà a muoversi... quando entrerai nella luce."
  },
  Voice_133740_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_133740_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_133741_AwakerVoiceContent = {
    Text = "Che danzatrice sfortunata. Ho osservato i suoi passi. La sua è una bellezza che avanza verso la rovina—ogni giro accende fiamme verdi, come se cercasse di bruciare i fili del fato, sebbene alla fine quei fili non faranno che scolpire qualcosa di straziante e vivido da lei. Se se ne presentasse l'occasione, vorrei scrivere un balletto solo per lei."
  },
  Voice_133741_AwakerVoiceTitle = {
    Text = "Conversazione: A proposito di Liz"
  },
  Voice_133741_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Liz\""
  },
  Voice_133742_AwakerVoiceContent = {
    Text = "Qui viene tessuto. Qui viene soppesato. Qui viene reciso."
  },
  Voice_133742_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_133743_AwakerVoiceContent = {
    Text = "Resta immobile..."
  },
  Voice_133743_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_133744_AwakerVoiceContent = {
    Text = "Un altro filo si fa chiaro."
  },
  Voice_133744_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_133745_AwakerVoiceContent = {
    Text = "Il sipario è aperto per te, e il copione del destino attende di iniziare. Dimmi: quale cammino predestinato preferiresti percorrere? Un finale di dolore, o un'apertura di gioia?"
  },
  Voice_133745_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_133745_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_133746_AwakerVoiceContent = {
    Text = "Mi sono affezionato a questa tessitura, giorno dopo giorno... Nel silenzioso, ripetuto tirare di ciascun filo, vedo attraverso gli inizi e le fini di tutte le storie. Guardando ogni sipario calare, a volte mi sento come se mi fossi elevato al di sopra del fato stesso. Eppure non si può sfuggire alla tela del fato, e limitarsi a osservare lascia, alla fine, un senso di vuoto.\nIn quei momenti, vado a teatro. Per interpretare i dolori e le gioie che ho tessuto con le mie mani, ma che non ho mai vissuto."
  },
  Voice_133746_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_133747_AwakerVoiceContent = {Text = "Ugh..."},
  Voice_133747_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_133748_AwakerVoiceContent = {Text = "Heh..."},
  Voice_133748_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_133749_AwakerVoiceContent = {
    Text = "Qui viene tessuto. Qui viene soppesato. Qui viene reciso."
  },
  Voice_133749_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_133750_AwakerVoiceContent = {
    Text = "Il fato si agita. Il suo sussurro si avvicina."
  },
  Voice_133750_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_133751_AwakerVoiceContent = {
    Text = "Il teatro ha messo in scena una nuova commedia romantica, e ti ho riservato un posto tra il pubblico del fato. Attraverso ogni lunga notte in cui i destini si intrecciano, attenderò in silenzio il momento in cui le nostre stelle si incontreranno."
  },
  Voice_133751_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_133751_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_133752_AwakerVoiceContent = {
    Text = "Tirare con tanta insistenza i fili del fato...\n\nSembri piuttosto impaziente di leggere la tua storia, non è vero?"
  },
  Voice_133752_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_133753_AwakerVoiceContent = {
    Text = "Ciò che era scritto si avvicina."
  },
  Voice_133753_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_133754_AwakerVoiceContent = {
    Text = "Se desideri entrare nella sala della tragedia, permettimi di presentarti <Italic:Antigone>. Intrappolata tra la legge divina e il decreto mortale, ogni passo che compie cade su fili che il fato ha già tessuto, finché non varca infine l'ombra profonda della tomba di pietra. È proprio perché quelle catene non possono essere spezzate che la volontà che arde nel suo esile corpo risplende così vivida contro la lunga notte."
  },
  Voice_133754_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_133754_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_133755_AwakerVoiceContent = {
    Text = "Nessun finale è mai davvero certo, eppure nessuno sfugge alla rete di causa e conseguenza..."
  },
  Voice_133755_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_133756_AwakerVoiceContent = {
    Text = "Sui fili, vedo i colori mutare attraverso ogni sfumatura dell'arcobaleno.\nSi estendono attraverso una trama infinita, tessendo mondi sconfinati e possibilità illimitate, fino a comporre un disegno più bello di qualsiasi altro mai visto.\n\nAlla fine—dio o mortale, eroe o villain—ciascuno è guidato da quei fili sottili, precipitandosi a capofitto verso il proprio destino sotto lo sguardo impassibile del fato."
  },
  Voice_133756_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_133757_AwakerVoiceContent = {
    Text = "Pensavo che nulla al mondo potesse più sorprendermi... Il tuo gusto teatrale mi ha colpito."
  },
  Voice_133757_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_133757_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_133758_AwakerVoiceContent = {
    Text = "I fili del fato si connettono sempre nell'ombra... Tu ne hai disturbato uno, e così mi hai colto di sorpresa."
  },
  Voice_133758_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_133758_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_133759_AwakerVoiceContent = {
    Text = "Non ho mai amato le rappresentazioni che si limitano a ripetersi. Il motivo stesso per cui si entra in un teatro è assistere a un palcoscenico vivo—uno che non può essere ricreato.\nSe non fa altro che girare come un meccanismo a orologeria, il palcoscenico diventa una gabbia ornata, e guardare non diventa altro che un tedioso pellegrinaggio verso un finale che già conosci.\nUna mascherata senz'anima, per quanto magnifica sia la produzione. Tu che ne pensi?"
  },
  Voice_133759_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_133760_AwakerVoiceContent = {
    Text = "Quei fili un tempo scorrevano in perfetto ordine tra le mie mani... finché non sei apparso tu, e hai mandato increspature nel loro corso che non avevo mai previsto."
  },
  Voice_133760_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_133760_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_133761_AwakerVoiceContent = {
    Text = "Prigioniero del fato, miserabile come sempre... ciò che è scritto non può essere rifiutato."
  },
  Voice_133761_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_133762_AwakerVoiceContent = {
    Text = "Da fili infiniti, tesso l'unico cammino."
  },
  Voice_133762_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_133763_AwakerVoiceContent = {
    Text = "Sul grande palcoscenico del fato, tutte le anime attendono il loro segnale nella rete di causa e conseguenza, le loro gioie e i loro dolori prendono silenziosamente forma mentre gli ingranaggi girano...\nIl sipario si è alzato, Custode. È qui che la tua storia, e la mia, ha inizio."
  },
  Voice_133763_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_133764_AwakerVoiceContent = {
    Text = "Il conflitto è qui. Vuoi giocare l'eroe che spezza la rete, o il burattino che si muove solo come i fili gli concedono?"
  },
  Voice_133764_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_133765_AwakerVoiceContent = {
    Text = "Resistenza futile."
  },
  Voice_133765_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_139865_AwakerVoiceContent = {
    Text = "Grazie per questo regalo. Lo conserverò con cura."
  },
  Voice_139865_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_139866_AwakerVoiceContent = {
    Text = "Ho studiato parecchio la struttura dei Risvegliatori, quindi ormai mi definirei un'esperta. Ma la \"spiritualità\" all'interno dei Nuclei d'Argento... quella parte ancora non la capisco del tutto."
  },
  Voice_139866_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_139866_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_139867_AwakerVoiceContent = {
    Text = "Questo è... il luogo dove inizia un nuovo mondo."
  },
  Voice_139867_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_139868_AwakerVoiceContent = {
    Text = "Io so fare cose del genere, sai. Come riorganizzare o modificare i corpi di altre creature..."
  },
  Voice_139868_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_139868_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_139869_AwakerVoiceContent = {
    Text = "Ogni essere vivente è diverso, quindi prima di iniziare a modificare qualcosa, bisogna davvero studiarli con attenzione."
  },
  Voice_139869_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_139869_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_139870_AwakerVoiceContent = {
    Text = "Non hai paura di me? Aww... che noia..."
  },
  Voice_139870_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_139871_AwakerVoiceContent = {
    Text = "Non permetterò a nessuno di ostacolarci."
  },
  Voice_139871_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_139872_AwakerVoiceContent = {
    Text = "Sono pronta, in qualsiasi momento."
  },
  Voice_139872_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_139873_AwakerVoiceContent = {
    Text = "Gli esseri viventi sono davvero pieni di diversità. Voglio imparare ancora tanto!"
  },
  Voice_139873_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_139875_AwakerVoiceContent = {
    Text = "Vuoi giocare con Saya?"
  },
  Voice_139875_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_139876_AwakerVoiceContent = {Text = "SQUEAK!"},
  Voice_139876_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_139877_AwakerVoiceContent = {
    Text = "Questo è... il luogo dove inizia un nuovo mondo."
  },
  Voice_139877_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_139878_AwakerVoiceContent = {
    Text = "Sono piena. Grazie per il pranzo!"
  },
  Voice_139878_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_139880_AwakerVoiceContent = {
    Text = "Ehi, Custode... hai mai amato qualcuno? Hai mai sentito davvero la mancanza di qualcuno con tutto il cuore?"
  },
  Voice_139880_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_139880_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_139881_AwakerVoiceContent = {Text = "Ngh!"},
  Voice_139881_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_139882_AwakerVoiceContent = {Text = "È qui?"},
  Voice_139882_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_139883_AwakerVoiceContent = {
    Text = "Bel lavoro! Hai trovato qualcosa di buono?"
  },
  Voice_139883_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_139884_AwakerVoiceContent = {
    Text = "Dopo tutti i miei esperimenti, ora capisco molto di più. La \"spiritualità\" che ogni Risvegliatore porta con sé—sono tutte completamente diverse. E sembra che la spiritualità del mio Nucleo d'Argento sia... \"amore.\""
  },
  Voice_139884_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_139884_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_139885_AwakerVoiceContent = {
    Text = "Allora? Ti ho beccato, eh?"
  },
  Voice_139885_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_139886_AwakerVoiceContent = {
    Text = "Questo è il mio ultimo dono... per te."
  },
  Voice_139886_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_139887_AwakerVoiceContent = {
    Text = [[
"<Italic:Su una di queste stelle, il mio fiore sta sbocciando...>"
Mi sembra che tu abbia detto qualcosa di simile una volta.]]
  },
  Voice_139887_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_139887_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_139888_AwakerVoiceContent = {
    Text = "Sembra che i \"Nuclei d'Argento\" siano ciascuno collegati a una volontà proveniente da molto lontano. Che mistero…"
  },
  Voice_139888_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_139888_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_139889_AwakerVoiceContent = {
    Text = "Questo è il mio ultimo dono... per te."
  },
  Voice_139889_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_139891_AwakerVoiceContent = {Text = "Argh!"},
  Voice_139891_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_139892_AwakerVoiceContent = {
    Text = "Il Piccolo Principe dice che la sua rosa è diventata speciale perché se ne è preso cura... Tu cosa ne pensi?"
  },
  Voice_139892_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_139892_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_139893_AwakerVoiceContent = {
    Text = "Ieri ho trovato un libro intitolato <Italic:Il Piccolo Principe> sullo scaffale di Lily. Era davvero bello! Vuoi leggerlo?"
  },
  Voice_139893_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_139893_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_139895_AwakerVoiceContent = {
    Text = "Sì, ho studiato la struttura dei Nuclei d'Argento e sto iniziando a capire come funzionano i Risvegliatori."
  },
  Voice_139895_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_139895_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_139896_AwakerVoiceContent = {Text = "Argh!"},
  Voice_139896_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_139897_AwakerVoiceContent = {Text = "Heyo!"},
  Voice_139897_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_139899_AwakerVoiceContent = {
    Text = "Molto piacere!"
  },
  Voice_139899_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_139900_AwakerVoiceContent = {
    Text = "Ciao! ...Si dice così, giusto?\nSono Saya, e... piacere di conoscerti!"
  },
  Voice_139900_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_139901_AwakerVoiceContent = {
    Text = "Conosci i denti di leone, vero? Quelli che affidano i loro semi al vento. Un piccolo seme viene portato lontano, lontano dalla sua terra natale... e magari atterra in un deserto dove non cresce nulla—nemmeno un filo d'erba. Mi chiedo... cosa potrebbe provare quel singolo, piccolo seme...?"
  },
  Voice_139901_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_139901_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_139902_AwakerVoiceContent = {
    Text = "Non importa quante volte si faccia, è sempre divertente!"
  },
  Voice_139902_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_139903_AwakerVoiceContent = {Text = "Ehi!"},
  Voice_139903_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_139906_AwakerVoiceContent = {Text = "Attento!"},
  Voice_139906_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_140533_AwakerVoiceContent = {
    Text = "Adoro il buon cibo! E mi piacciono le persone che sono gentili con me! Quando qualcuno è dolce con me... mi rende davvero felice."
  },
  Voice_140533_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_140534_AwakerVoiceContent = {
    Text = "È lei che mi ha risvegliato? Sembra davvero... abbagliante. Allora, l'hai aiutata a trovare sua sorella?"
  },
  Voice_140534_AwakerVoiceTitle = {
    Text = "Conversazione: A proposito di Tintura"
  },
  Voice_140534_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Tinct\""
  },
  Voice_140535_AwakerVoiceContent = {
    Text = "Ogni volta che sono vicino a te, persone strane spuntano fuori e si radunano intorno a noi. In realtà preferivo quando eravamo solo noi due nel Dominio."
  },
  Voice_140535_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_140536_AwakerVoiceContent = {
    Text = "Capito. Ci penso io!"
  },
  Voice_140536_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_140537_AwakerVoiceContent = {
    Text = "Custode, Legame, Risvegliatore. È così che siamo connessi. Me ne hai parlato tu. Riesco a sentire le nostre anime legate insieme... come un filo d'argento? Hmm, sembra un po' troppo complicato..."
  },
  Voice_140537_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_140538_AwakerVoiceContent = {
    Text = "Diffusione di semi attraverso carne e sangue? Hmm... interessante. In realtà sono un po' curioso delle sue pecore."
  },
  Voice_140538_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Thais"
  },
  Voice_140538_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Thais\""
  },
  Voice_140539_AwakerVoiceContent = {
    Text = "Là fuori ci sono certe minacce che potrebbero portare un'oscurità abbastanza grande da distruggere questo mondo, giusto? Lo so. Me ne ha parlato la Professoressa Doll."
  },
  Voice_140539_AwakerVoiceTitle = {
    Text = "Chiacchiere: Riguardo alla Crisi"
  },
  Voice_140540_AwakerVoiceContent = {
    Text = "Non mi piacciono le persone brusche. Mi danno una brutta sensazione..."
  },
  Voice_140540_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_140541_AwakerVoiceContent = {
    Text = "Oh? Quindi la sua specie si riproduce su nuovi pianeti predando altre specie. Huh, capisco..."
  },
  Voice_140541_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Winkle"
  },
  Voice_140541_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Winkle\""
  },
  Voice_141963_AwakerVoiceContent = {
    Text = "Brava bambina."
  },
  Voice_141963_AwakerVoiceTitle = {
    Text = "Abilità Speciale: II"
  },
  Voice_141964_AwakerVoiceContent = {Text = "Ehi!"},
  Voice_141964_AwakerVoiceTitle = {
    Text = "Abilità Speciale: III"
  },
  Voice_141965_AwakerVoiceContent = {Text = "Certo."},
  Voice_141965_AwakerVoiceTitle = {
    Text = "Colpo·Cinque"
  },
  Voice_143501_AwakerVoiceContent = {
    Text = "Che peccato. Quando cambierai idea, sai dove trovarmi."
  },
  Voice_143501_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_143501_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_143502_AwakerVoiceContent = {Text = "Merda..."},
  Voice_143502_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_143503_AwakerVoiceContent = {
    Text = "Pelle, muscoli, nervi, ossa — tutto verrà ricostruito, di nuovo sano e integro, di nuovo pieno di vitalità."
  },
  Voice_143503_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_143503_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_143504_AwakerVoiceContent = {
    Text = "Di fronte al Mare Profondo, non esiste nemico indistruttibile!"
  },
  Voice_143504_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_143505_AwakerVoiceContent = {
    Text = "Banchetti, Caccia, rifugio?\nPrega me, le acque più antiche ti sveleranno il mio nome.\nIo sono il signore degli abissi, Pontos."
  },
  Voice_143505_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_143506_AwakerVoiceContent = {
    Text = "Oh oh, nostalgia dei momenti trascorsi a Ebwynnos?…\nÈ qui, in questo corpo, e ti accoglie sempre a braccia aperte."
  },
  Voice_143506_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_143507_AwakerVoiceContent = {
    Text = "Anche se non l'ho fatto, se un giorno dovessi sentire nelle orecchie il suono dell'acqua marina e il fruscio di ali, non preoccuparti, è del tutto normale."
  },
  Voice_143507_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_143508_AwakerVoiceContent = {
    Text = "Offri i tuoi sensi e rifletti per l'eternità negli abissi!"
  },
  Voice_143508_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_143509_AwakerVoiceContent = {
    Text = "Mi piacciono i giovani pieni di vitalità. Peccato che Mythag abbia controlli così severi sui festeggiamenti — non c'è nemmeno un campo di caccia degno di questo nome.\nPer di più, lì dentro c'è quella cosa sporca che osa aggirarsi alla luce del sole, persino con il titolo di professore."
  },
  Voice_143509_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_143510_AwakerVoiceContent = {Text = "Ugh!"},
  Voice_143510_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_143511_AwakerVoiceContent = {
    Text = "Ho fatto così tanto, eppure non sei disposto nemmeno a chiamarmi zio un'altra volta. Che seccatura."
  },
  Voice_143511_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_143513_AwakerVoiceContent = {
    Text = "Non abbiate fretta, l'Oscurità nel punto più profondo del Mare Profondo vi Divorerà."
  },
  Voice_143513_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_143514_AwakerVoiceContent = {
    Text = "Inginocchiati, diventa nutrimento per Ebwynnos."
  },
  Voice_143514_AwakerVoiceTitle = {
    Text = "Abilità Speciale: III"
  },
  Voice_143515_AwakerVoiceContent = {
    Text = "Quanto all'essere che mi ha scelto… posso solo dire che è tanto benevolo quanto crudele.\nDove ti fa cadere dipende interamente dal suo umore: ti salverà certamente da una situazione pericolosa, ma se quella situazione sia o meno un altro pericolo, non è qualcosa di cui questo \"viaggio\" debba preoccuparsi.\nChe cosa interessante, che cosa imprevedibile. Sto considerando di perpetuare questa tradizione."
  },
  Voice_143515_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_143515_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_143516_AwakerVoiceContent = {
    Text = "Ho un legame speciale con Ebwynnos — anzi, potrei dire che io sono Ebwynnos, e Ebwynnos sussiste in me, esistendo attraverso il mio corpo."
  },
  Voice_143516_AwakerVoiceTitle = {
    Text = "Chat: riguardo a Ebwynnos"
  },
  Voice_143517_AwakerVoiceContent = {
    Text = "Alza la testa, mostrami la tua gola."
  },
  Voice_143517_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_143518_AwakerVoiceContent = {
    Text = "Cancellare i ricordi, cancellare l'esistenza. Qualcosa di familiare… capisci cosa intendo. Pur avendo origini diverse, sembra che proliferino sempre dall'oscurità."
  },
  Voice_143518_AwakerVoiceTitle = {
    Text = "Chiacchiere: Riguardo alla Crisi"
  },
  Voice_143519_AwakerVoiceContent = {
    Text = "Non avreste dovuto essere così stupidi da osare sfidare la mia maestà."
  },
  Voice_143519_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_143520_AwakerVoiceContent = {
    Text = "Troppo debole."
  },
  Voice_143520_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_143521_AwakerVoiceContent = {
    Text = "A Ebwynnos, i festeggiamenti non cesseranno mai, e i nemici di Ebwynnos non troveranno mai pace."
  },
  Voice_143521_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_143521_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_143522_AwakerVoiceContent = {
    Text = "Ah, percepisco il tuo tremore come mio, ma è del tutto inutile, mio giovane amico.\nAccetta la tua paura della mediocrità e dell'essere consumato, guardami, e capirai che hai sempre un'altra scelta."
  },
  Voice_143522_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_143522_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_143523_AwakerVoiceContent = {
    Text = "Già, so che quella catastrofe non è stata da lui direttamente orchestrata, solo un accidente capitato mentre si divertiva. Ma questo, ovviamente, non fa che aumentare la mia voglia di ucciderlo.\nQuella nebbia nera farebbe meglio a non restare sola, e a non farsi prendere da me."
  },
  Voice_143523_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_143524_AwakerVoiceContent = {
    Text = "Quegli Esseri degli Abissi viscidi non sono miei amici, bensì miei nemici. Sorprendente? Il Mare Profondo non è mai appartenuto a loro."
  },
  Voice_143524_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_143524_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_143525_AwakerVoiceContent = {
    Text = "Per sempre, rimani qui!"
  },
  Voice_143525_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_143526_AwakerVoiceContent = {
    Text = "Siete pronti, prede!"
  },
  Voice_143526_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_143527_AwakerVoiceContent = {
    Text = "La spiritualità genera nuovi corpi, i corpi vengono riempiti di sapere irrilevante, e poi quegli individui splendidi e vivaci si riuniranno per sempre in un unico luogo.\nRicordi ciò che ho detto? Il punto più profondo del Mare Profondo accoglie tutto… e trattiene tutto."
  },
  Voice_143527_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_143527_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_143528_AwakerVoiceContent = {
    Text = "Incubo, bloccali."
  },
  Voice_143528_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_143529_AwakerVoiceContent = {
    Text = "Spero che queste piccole creature non ti mandino in rovina, sai, mantenere una grande famiglia non è davvero cosa semplice."
  },
  Voice_143529_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_143530_AwakerVoiceContent = {
    Text = "Molto, molto tempo fa, prima che la terra emergesse dal Mare Profondo, questo pianeta aveva già risvegliato certe spiritualità speciali. Potenti, maestose, imperscrutabili.\nNon possono essere definite né ostili né amichevoli; gli esseri umani, come innumerevoli creature prima di loro, erano irrilevanti ai loro occhi: verrebbero spazzati via come polvere, oppure protetti insieme al territorio."
  },
  Voice_143530_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_143530_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_143531_AwakerVoiceContent = {
    Text = "Solo l'invecchiamento è l'avventura che devi affrontare da solo, il tuo migliore amico e il tuo nemico più ostico; le luci di Ebwynnos lo scacceranno via… Appena qualche ricordo insignificante, non hai bisogno di essere ancorato a essi."
  },
  Voice_143531_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_143531_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_143532_AwakerVoiceContent = {
    Text = "Abbandonate ogni illusione di Fuga."
  },
  Voice_143532_AwakerVoiceTitle = {
    Text = "Abilità Speciale: I"
  },
  Voice_143533_AwakerVoiceContent = {
    Text = "Sarai ridotto in polvere grigia e cenere."
  },
  Voice_143533_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_143534_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_143534_AwakerVoiceTitle = {Text = "Colpo"},
  Voice_143535_AwakerVoiceContent = {
    Text = "Molto astuto, piccolo, i Credenti dei Mostri stranieri sono sempre così stupidi da gettare i cadaveri in Mare Profondo — quello non conta come Dono, vero?"
  },
  Voice_143535_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_143536_AwakerVoiceContent = {
    Text = "Sei già nel mirino."
  },
  Voice_143536_AwakerVoiceTitle = {
    Text = "Abilità Speciale: II"
  },
  Voice_143537_AwakerVoiceContent = {
    Text = "Anche se non voglio ammetterlo, in certi rarissimi momenti mi capita di pensare che l'invecchiamento non sia l'unica cosa che il tempo porta con sé, ma solo un simbolo.\nPerciò, lo lascio esistere in me. Certo — solo nell'aspetto esteriore."
  },
  Voice_143537_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_143539_AwakerVoiceContent = {
    Text = "La Preghiera è efficace. Immagina: anche se degli insetti formassero davanti a te delle parole in scrittura Reo, prenderesti comunque in considerazione di rispondere alle loro richieste."
  },
  Voice_143539_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_143539_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_143540_AwakerVoiceContent = {
    Text = "Ahahaha, basta, non fare quella Espressione, mio piccolo amico.\nÈ solo una tradizione che certi cosiddetti \"vecchi dei\" devono seguire. Quanto a te, senza alcun prezzo o condizione, starò sempre dalla tua parte."
  },
  Voice_143540_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_143540_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_143554_AwakerVoiceContent = {
    Text = "Hmph, un piccolo Mostro che si mescola con i Mostri stranieri.\nC'è persino qualche stupido che mi mette sullo stesso altare con lui — un vero insulto!"
  },
  Voice_143554_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Tulu"
  },
  Voice_143554_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Tulu\""
  },
  Voice_143555_AwakerVoiceContent = {
    Text = "Il nemico del mio nemico è mio amico. Se ne avessi l'occasione, non mi dispiacerebbe concludere un buon affare strappando il giocattolo preferito al mio acerrimo rivale."
  },
  Voice_143555_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Ryker"
  },
  Voice_143555_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Ryker\""
  },
  Voice_146158_AwakerVoiceContent = {
    Text = "Oh? Vuoi combattere con me, qui? Per me va bene."
  },
  Voice_146158_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_146159_AwakerVoiceContent = {
    Text = "Ancora—dammi ancora più potere!"
  },
  Voice_146159_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_146160_AwakerVoiceContent = {
    Text = "Non mi piacciono coloro che hanno un cuore diviso, poiché tale divisione di solito significa Debolezza. Ma tu sei un'eccezione. Un tempo credevo che chi porta troppo non potesse mai andare lontano. Ma il cammino che hai scelto mi sorprende… Forse un avversario che percorre un sentiero diverso è più degno di essere affinato e sfidato. Non sei d'accordo, \"avversario\"?"
  },
  Voice_146160_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_146161_AwakerVoiceContent = {
    Text = "Ceto del Mare Astrale—divorali tutti!"
  },
  Voice_146161_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_146162_AwakerVoiceContent = {
    Text = "Sii onorato di affrontarmi!"
  },
  Voice_146162_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_146163_AwakerVoiceContent = {
    Text = "Che le stelle assistano all'annientamento!"
  },
  Voice_146163_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_146164_AwakerVoiceContent = {
    Text = "Non basta. Siamo lontani dall'essere abbastanza…"
  },
  Voice_146164_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_146165_AwakerVoiceContent = {Text = "Heh."},
  Voice_146165_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_146166_AwakerVoiceContent = {Text = "Hmph."},
  Voice_146166_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_146167_AwakerVoiceContent = {
    Text = "Mi importa poco della decadenza di questo mondo — ma non lo lascerò ostacolare la mia ricerca del Potere."
  },
  Voice_146167_AwakerVoiceTitle = {
    Text = "Chiacchiere: Riguardo alla Crisi"
  },
  Voice_146168_AwakerVoiceContent = {
    Text = "Dubitare del valore dell'esistenza solo perché l'oblio ci attende... Non ho alcun interesse in dibattiti così infantili. La Distruzione non significa nulla, né lo fa il ricordo. Il Potere stesso è il significato."
  },
  Voice_146168_AwakerVoiceTitle = {
    Text = "Chat: Su Doll: Inferno"
  },
  Voice_146168_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risveglio \"Doll: Inferno\"."
  },
  Voice_146169_AwakerVoiceContent = {
    Text = "Vedo una volontà aliena nei tuoi occhi. Impura, ma abbastanza tenace. Vieni, mostrami quale potere o desiderio ti ha condotto davanti a me."
  },
  Voice_146169_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_146170_AwakerVoiceContent = {Text = "Ha!"},
  Voice_146170_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_146171_AwakerVoiceContent = {
    Text = "Sii onorato di affrontarmi!"
  },
  Voice_146171_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_146172_AwakerVoiceContent = {
    Text = "Il profumo del caos—quanto è nostalgico… Dal momento in cui sono nata da questo vuoto, la mia ricerca non è mai cambiata."
  },
  Voice_146172_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_146172_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_146173_AwakerVoiceContent = {
    Text = "Vuoi sfidarmi? Ammiro il tuo coraggio, e ti concederò l'onore di essere sconfitto. Consideralo il mio rispetto per il \"Custode di Mythag.\""
  },
  Voice_146173_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_146173_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_146174_AwakerVoiceContent = {
    Text = "Un'utopia falsa, piena di deboli, codardi e stolti che si illudono. Ma non importa. Questo posto mi porta gli avversari più esaltanti — e questo è sufficiente."
  },
  Voice_146174_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_146175_AwakerVoiceContent = {
    Text = "Sprecare un Potere immenso, imprigionare il proprio talento in un lungo sogno per paura, senso di colpa e stanchezza. Che peccato."
  },
  Voice_146175_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Tulu"
  },
  Voice_146175_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Tulu\""
  },
  Voice_146176_AwakerVoiceContent = {
    Text = "Non vale nemmeno il mio tempo."
  },
  Voice_146176_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_146177_AwakerVoiceContent = {
    Text = "I sigilli si allentano un poco… Il potere dalle profondità dell'universo sta erompendo. Non lo sentivo da ere…"
  },
  Voice_146177_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_146177_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_146178_AwakerVoiceContent = {
    Text = "Ceto del Mare Astrale—divorali tutti!"
  },
  Voice_146178_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_146179_AwakerVoiceContent = {
    Text = "…Esaltante."
  },
  Voice_146179_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_146180_AwakerVoiceContent = {
    Text = "Ho vagato per il vasto cosmo per ere; ho gettato nell'abisso tutti quei \"potenti\". Sei unico, ma per stare al mio fianco, impara prima a tenere la testa alta. Non ho alcun uso per i codardi."
  },
  Voice_146180_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_146180_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_146181_AwakerVoiceContent = {
    Text = "Coraggioso o codardo, forte o fragile… Eh — no, non mi importa che tipo di persona sia il mio avversario. Qualsiasi avversario degno mi regala un'emozione autentica."
  },
  Voice_146181_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_146182_AwakerVoiceContent = {
    Text = "Debolezza. Di tutte le cose vili al mondo, la Debolezza è il peccato più miserabile. Ognuno nasce con una spada in mano; nessuno ha il diritto di cedere prima della fine, né di scendere sul campo di battaglia del destino già rassegnato alla sconfitta. Questo insulta sia il tuo avversario che te stesso."
  },
  Voice_146182_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_146183_AwakerVoiceContent = {
    Text = "Carcassa Astrale corrotta—risvegliati!"
  },
  Voice_146183_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_146184_AwakerVoiceContent = {
    Text = "Eh… Questo sì che è stato esaltante. La prossima volta, non mi tratterrò."
  },
  Voice_146184_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_146185_AwakerVoiceContent = {
    Text = "Le mie ossa tremano di gioia… Ho assistito al tuo sforzo. E questo dimostra che sei degno di stare al mio fianco, Custode."
  },
  Voice_146185_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_146185_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_146186_AwakerVoiceContent = {
    Text = "Eh… Lo vedi chiaramente, Custode. Le catene del potere sono fatte per essere spezzate!"
  },
  Voice_146186_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_146186_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_146187_AwakerVoiceContent = {Text = "Hm?"},
  Voice_146187_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_146188_AwakerVoiceContent = {Text = "Hm?"},
  Voice_146188_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_146189_AwakerVoiceContent = {
    Text = "Proprio lì davanti… il vertice del Potere che ho inseguito per tutta la vita… Hai percorso questo cammino con me e mi hai guidato fino a questa soglia. Non vedo l'ora di testimoniare quel giorno definitivo insieme a te!"
  },
  Voice_146189_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_146189_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_146190_AwakerVoiceContent = {
    Text = "Forse ti ho giudicato troppo in fretta... La tua crescita e il tuo Potere nascosto mi hanno sorpreso. Ho visto innumerevoli vite svanire nel tempo, ma tu... sei davvero diverso. Sono molto curioso della vera origine del tuo Potere."
  },
  Voice_146190_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_146190_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_146192_AwakerVoiceContent = {
    Text = "Fauci dell'Inferno, spalancatevi per me!"
  },
  Voice_146192_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_146193_AwakerVoiceContent = {
    Text = "Ah, capisco… il Potere non ha mai una fine. La vera sfida è appena cominciata! Sei stato tu a portarmi fin qui e a mostrarmi la realtà. Presto, ti presenterò un guerriero ancora più perfetto. Assicurati di tornare ancora più forte, mio \"avversario.\""
  },
  Voice_146193_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_146193_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_146194_AwakerVoiceContent = {
    Text = "Meschini trucchetti."
  },
  Voice_146194_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_146195_AwakerVoiceContent = {
    Text = "Il potere ribolle nel mio midollo!"
  },
  Voice_146195_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_146196_AwakerVoiceContent = {
    Text = "Divora—tutto quanto!"
  },
  Voice_146196_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_146197_AwakerVoiceContent = {
    Text = "Pietà, Debolezza, confusione… i tuoi occhi sono offuscati da impurità. Chi vacilla non potrà mai capire cos'è il Potere."
  },
  Voice_146197_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_146197_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_146198_AwakerVoiceContent = {
    Text = "Il vero Potere non ha mai avuto nulla a che fare con la vendetta o con il Guardiano. Il Potere è Solo Potere — quell'altra me non ha mai \"davvero\" compreso questa verità. Questa è la radice del perché Lei non era abbastanza forte."
  },
  Voice_146198_AwakerVoiceTitle = {
    Text = "Chat: Su Lotan"
  },
  Voice_146198_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Lotan\""
  },
  Voice_146199_AwakerVoiceContent = {
    Text = "Ascolta bene, lo dirò una volta sola:\nIo, Lotan, ti considero un avversario degno della mia pazienza.\nFinché non raggiungerai il tuo apice, sarò la tua lama più affidabile. Questa promessa non ha nulla a che fare con i sentimenti o la lealtà. Sei il mio rivale più esaltante, e non ti lascerò mai cadere lungo il cammino."
  },
  Voice_146199_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_146199_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_146200_AwakerVoiceContent = {
    Text = "Vieni—uccidimi, o sarai ucciso."
  },
  Voice_146200_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_146201_AwakerVoiceContent = {
    Text = "Fauci dell'Inferno, spalancatevi per me!"
  },
  Voice_146201_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_146521_AwakerVoiceContent = {
    Text = "Dove punta la lama d'osso, tutto si dissolve!"
  },
  Voice_146521_AwakerVoiceTitle = {
    Text = "Abilità Speciale: I"
  },
  Voice_147047_AwakerVoiceContent = {
    Text = "Il potere… non conosce limiti!"
  },
  Voice_147047_AwakerVoiceTitle = {
    Text = "Abilità Speciale: II"
  },
  Voice_147493_AwakerVoiceContent = {Text = "—"},
  Voice_147493_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_147493_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_147494_AwakerVoiceContent = {
    Text = "(Un canto roco e soave)"
  },
  Voice_147494_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_147495_AwakerVoiceContent = {
    Text = "Pubblico, ci serve più pubblico..."
  },
  Voice_147495_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_147496_AwakerVoiceContent = {
    Text = "Sabbia... Un deserto bianco... Qui è pericoloso. Andiamocene insieme."
  },
  Voice_147496_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_147496_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_147497_AwakerVoiceContent = {
    Text = "Ricordo ancora la mappa della nuova patria. Era colorata e bellissima. È lì che dovremmo andare. Possiamo cantare e possiamo trovare la felicità."
  },
  Voice_147497_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_147498_AwakerVoiceContent = {Text = "Ah!"},
  Voice_147498_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_147499_AwakerVoiceContent = {Text = "—"},
  Voice_147499_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_147499_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_147500_AwakerVoiceContent = {Text = "Hmm...?"},
  Voice_147500_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_147501_AwakerVoiceContent = {
    Text = "Quella è... la voce delle stelle"
  },
  Voice_147501_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_147502_AwakerVoiceContent = {
    Text = "Eccoti di nuovo. Come prima, siediti al mio fianco e aspetta con me. Aspettare cosa...? Aspettare e basta."
  },
  Voice_147502_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_147503_AwakerVoiceContent = {
    Text = "Prova perfetta. Credo di essere pronta a salire sul palco."
  },
  Voice_147503_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_147503_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_147504_AwakerVoiceContent = {Text = "Cadi."},
  Voice_147504_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_147505_AwakerVoiceContent = {
    Text = "Dedicato alla desolazione e alla morte."
  },
  Voice_147505_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_147506_AwakerVoiceContent = {
    Text = "Non sono pazza né ho mai provato dolore. Per favore, non credete a voci assurde."
  },
  Voice_147506_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_147507_AwakerVoiceContent = {
    Text = "Strano, sembra che temano il mio canto..."
  },
  Voice_147507_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_147508_AwakerVoiceContent = {Text = "Shh..."},
  Voice_147508_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_147509_AwakerVoiceContent = {
    Text = "Che splendido costume di scena, così scintillante, così abbagliante..."
  },
  Voice_147509_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_147509_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_147510_AwakerVoiceContent = {Text = "—"},
  Voice_147510_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_147511_AwakerVoiceContent = {
    Text = "Oh, i colori persistenti delle stelle."
  },
  Voice_147511_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_147512_AwakerVoiceContent = {Text = "Canta."},
  Voice_147512_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_147513_AwakerVoiceContent = {
    Text = "Un vero allenamento vocale...? Ma sono piuttosto soddisfatta della mia voce attuale."
  },
  Voice_147513_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_147513_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_147514_AwakerVoiceContent = {Text = "—"},
  Voice_147514_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_147515_AwakerVoiceContent = {
    Text = "Sembra che qualcosa sia cambiato..."
  },
  Voice_147515_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_147515_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_147516_AwakerVoiceContent = {
    Text = "Com'è stato il mio canto?"
  },
  Voice_147516_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_147517_AwakerVoiceContent = {
    Text = "Dormi bene..."
  },
  Voice_147517_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_147518_AwakerVoiceContent = {Text = "—"},
  Voice_147518_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_147519_AwakerVoiceContent = {Text = "Va bene."},
  Voice_147519_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_147520_AwakerVoiceContent = {Text = "Ah!"},
  Voice_147520_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_147521_AwakerVoiceContent = {
    Text = "Grazie... Dovrei dire grazie?"
  },
  Voice_147521_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_147522_AwakerVoiceContent = {Text = "*sigh*..."},
  Voice_147522_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_147523_AwakerVoiceContent = {
    Text = "Sboccia di luce."
  },
  Voice_147523_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_147524_AwakerVoiceContent = {
    Text = "È passato un po' di tempo... Finalmente di nuovo sul palco. Grazie, Custode."
  },
  Voice_147524_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_147524_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_147525_AwakerVoiceContent = {
    Text = "Scusa il disturbo... Potresti aiutarmi a scendere da quest'albero? Non ricordo perché ci sono salita. Forse le nuvole lassù mi hanno fatto venire nostalgia..."
  },
  Voice_147525_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_147526_AwakerVoiceContent = {
    Text = "I miei simili non mi hanno mai lasciata; sono solo andati molto, molto lontano."
  },
  Voice_147526_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito del suo clan"
  },
  Voice_147527_AwakerVoiceContent = {
    Text = "L'hai sentito?"
  },
  Voice_147527_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_147528_AwakerVoiceContent = {Text = "Oh."},
  Voice_147528_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_147529_AwakerVoiceContent = {
    Text = "Sembra che tu ti aggiri sempre intorno a me... Capisco, devi essere un mio fan."
  },
  Voice_147529_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_147529_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_147530_AwakerVoiceContent = {
    Text = "Lalala...Hmm? Sta accadendo un disastro che porrà fine al mondo? Capisco... ma prima devo sistemarmi i capelli e andare a cercare Tintura..."
  },
  Voice_147530_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_147531_AwakerVoiceContent = {
    Text = "Shh... Non parlare. Stanno arrivando i cattivi. Vogliono portare via me e mia sorella, e non ci lasciano salire sulla nave..."
  },
  Voice_147531_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito della sicurezza"
  },
  Voice_147532_AwakerVoiceContent = {Text = "—"},
  Voice_147532_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_147532_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_147533_AwakerVoiceContent = {
    Text = "Quando mi sono svegliata, il pianeta era in rovina. Ho visto il cielo notturno staccarsi a strisce, e il mondo è diventato una tela riempita di venti furiosi—prima si è deformato, poi si è lacerato e frantumato."
  },
  Voice_147533_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_147533_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_147534_AwakerVoiceContent = {
    Text = "Questo è il mio poster autografato, disegnato dal Sig. Pickman. Puoi tenerlo, %player%."
  },
  Voice_147534_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito di Faint"
  },
  Voice_147534_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Faint\""
  },
  Voice_149667_AwakerVoiceContent = {
    Text = "Hmm? Curioso, vero? Il caveau dei tesori di una Madrina non è per gli occhi degli estranei, sai. Se muori dalla voglia di sapere cosa c'è stipato dentro... perché non ti unisci subito all'Ordine Sacro... Eheh."
  },
  Voice_149667_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_149668_AwakerVoiceContent = {
    Text = "Non mi credi? Uh-uh... Suppongo che non si possa ingannare proprio tutti... La verità è che sono la figlia illegittima di Bohemond VI di @1, che vive nascosta tra i mortali, e ho detto di essere una fata solo per sfuggire alla caccia dei nemici... Ti ho rivelato il mio segreto più prezioso. Non è che non mi credi... vero?"
  },
  Voice_149668_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_149668_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_149669_AwakerVoiceContent = {Text = "Ahia~"},
  Voice_149669_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_149670_AwakerVoiceContent = {
    Text = "Troppe caramelle? No no no, questo è il segreto di una Madrina per mantenere il suo sorriso, sai. Come se mi fermassi per una piccola cosa come una carie?"
  },
  Voice_149670_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_149671_AwakerVoiceContent = {
    Text = "Vieni, stai qui accanto alla tua Fata. Cosa? Tutti condividono le offerte e mangiano insieme? ...Beh. Se questa è la tradizione di Mythag... allora io... non ho assolutamente nulla in contrario. Forza, tutti, facciamola diventare una festa!"
  },
  Voice_149671_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_149671_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_149672_AwakerVoiceContent = {
    Text = "Oh, ma guarda che agnellino devoto."
  },
  Voice_149672_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_149673_AwakerVoiceContent = {
    Text = "Ancora un po', e la Fata ti benedirà, hmm?"
  },
  Voice_149673_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_149674_AwakerVoiceContent = {
    Text = "Siete ancora tutti un po' acerbi~"
  },
  Voice_149674_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_149676_AwakerVoiceContent = {
    Text = "Questa cerimonia di culto sarà più grandiosa di tutte le precedenti—e le offerte dovranno essere in numero maggiore... Oh mio, non stiamo mica mozzando loro le membra, ovviamente! Sono una fata dal cuore gentile; non farei mai nulla per far del male a qualcuno~"
  },
  Voice_149676_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_149676_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_149677_AwakerVoiceContent = {
    Text = "Custode, sei pronto per la confessione più sincera di Caraboo, dal profondo del suo cuore?\nDa dove vengo non ha alcuna importanza. Ciò che conta davvero è questo: sei un dono del cielo per me, e ho deciso di restare al fianco del mio prezioso benefattore, per sempre e sempre. \nStai chiedendo se questa è un'altra bugia per impedirti di continuare a scavare nel mio passato? Eheh, cosa ne pensi?\nComunque... credo di meritare un piccolo premio per aver condiviso i miei veri sentimenti con te. Una caramella gommosa al gusto di mela andrebbe benissimo, per favore?"
  },
  Voice_149677_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_149677_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_149678_AwakerVoiceContent = {Text = "Eheheh~"},
  Voice_149678_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_149680_AwakerVoiceContent = {
    Text = "Non fa niente! La prossima volta, concentrati solo sul proteggere la tua Fata, e non fallirai~"
  },
  Voice_149680_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_149682_AwakerVoiceContent = {
    Text = "Non provare nemmeno a ingannarmi!"
  },
  Voice_149682_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_149683_AwakerVoiceContent = {
    Text = "Ooooh, così tanto tributo...! Ahem. Eheh, ben fatto, ti sei guadagnato una ricompensa! Vieni qui, ti concederò il bacio di una fata! ...A cosa stai pensando? Sulla fronte, ovviamente!"
  },
  Voice_149683_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_149683_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_149684_AwakerVoiceContent = {
    Text = "Grazie a tutti per le vostre offerte, fedeli! La vostra sempre comprensiva Madrina farà erigere anche una statua d'oro massiccio in vostro onore nel tempio. Oh mio—per catturare quella tua figura fredda ed elegante, dovrò semplicemente andare a raccogliere ancora un bel po'~"
  },
  Voice_149684_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_149684_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_149685_AwakerVoiceContent = {
    Text = "Tu? ...Sei uno del nostro gregge, non ancora illuminato. Caraboo aspetterà, pazientemente, il giorno in cui vedrai la vera natura del mondo. E quando quel giorno arriverà—ricordati di offrire il tuo corpo, la tua lealtà e i tuoi beni terreni alla Madrina di tutti. Eheh."
  },
  Voice_149685_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_149686_AwakerVoiceContent = {
    Text = "Tutto ciò che c'era nella lista... già raccolto? La fortuna di Mythag è più profonda di quanto riesca a immaginare... Se l'avessi saputo, avrei... Hmm? Cosa sto borbottando, mi chiedi? Sto solo ringraziando Lord Dexter per la sua generosità, eheheh~"
  },
  Voice_149686_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_149686_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_149687_AwakerVoiceContent = {
    Text = "Cosa odio di più? I maghi che non rispettano un contratto, ovviamente. Ecco un piccolo segreto, solo tra noi: ogni singolo mago è un gran bugiardo. Tutte le loro cosiddette profezie e maledizioni? Solo trucchi per derubarti fino all'ultimo centesimo! E come ti proteggi...? Semplice! Lascia che tutto il tuo denaro riceva la benedizione della Fata!"
  },
  Voice_149687_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_149688_AwakerVoiceContent = {
    Text = "Che piacere conoscerti! Sono una Fata Pallida proveniente da terre lontane. Vuoi saperne di più? La benedizione di una fata varia in potenza a seconda del tuo livello di abbonamento, eheheh~"
  },
  Voice_149688_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_149689_AwakerVoiceContent = {
    Text = "Nelle cerimonie di culto del passato, oltre al rito settuplice e al voto triplice, i fedeli mi costruivano un tempio nuovo di zecca e presentavano tributi sontuosi. Ecco la lista!"
  },
  Voice_149689_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_149689_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_149690_AwakerVoiceContent = {
    Text = "Dai, vieni... seppellisci tutto ciò che vuoi lasciarti alle spalle in fondo alla neve..."
  },
  Voice_149690_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_149691_AwakerVoiceContent = {
    Text = "Ho sentito che stai chiedendo da dove vengo. Eheh, questo è un piccolo segreto della Madrina. Maaaa, se proprio devi andare a scavare, l'Ordine Sacro conserva una biografia che ho scritto io stessa. Tua da leggere per soli centomila Argenti. Vuoi provare?"
  },
  Voice_149691_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_149691_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_149692_AwakerVoiceContent = {
    Text = "Oh, qui è meraviglioso—così tanti bambini adorabili, e sussidi di assistenza generosi fino all'eccesso. Con tutto questo, avrò messo da parte il denaro per il viaggio verso Oriente in men che non si dica..."
  },
  Voice_149692_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_149693_AwakerVoiceContent = {
    Text = "Non dimenticare di venerare la tua Madrina, eheheh."
  },
  Voice_149693_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_149694_AwakerVoiceContent = {
    Text = "Mi dispiace tanto, ma il dominio della Fata è terra sacra—qui non riceviamo strani lupi mannari... Qualcosa sull'odore di bugie nell'aria? Il suo naso deve essere semplicemente fuori uso."
  },
  Voice_149694_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Ryker"
  },
  Voice_149694_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Ryker\""
  },
  Voice_149695_AwakerVoiceContent = {
    Text = "Eh? Qualcuno sta dicendo che sono una fata falsa... Beh, sono scoperta. Eheh. Ma so che a te non importa... giusto?"
  },
  Voice_149695_AwakerVoiceTitle = {
    Text = "Chiacchiera: Sulle Voci"
  },
  Voice_149696_AwakerVoiceContent = {
    Text = "Mmm, delizioso~♪"
  },
  Voice_149696_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_149697_AwakerVoiceContent = {Text = "Su, su~"},
  Voice_149697_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_149698_AwakerVoiceContent = {
    Text = "Agnellini smarriti, la vostra Fata è qui per lavarvi via i peccati, eheheh~"
  },
  Voice_149698_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_149699_AwakerVoiceContent = {
    Text = "Non hai ancora rinunciato? Va bene, va bene—Caraboo te lo dirà lei stessa. Vedi, Caraboo è la figlia di Umapati, dea di una certa vetta innevata che fende le nuvole a Oriente... Hmm? Quella dea aveva due figli maschi e nessuna figlia? Beh, i resoconti del divino sono sempre un po'... incompleti, capisci."
  },
  Voice_149699_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_149699_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_149700_AwakerVoiceContent = {
    Text = "Ta-daa~ la luce della Fata splende su di te adesso. Vai e datti da fare!"
  },
  Voice_149700_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_149701_AwakerVoiceContent = {
    Text = "Va bene, va bene, smettila di scavare, vuoi? Sii un bravo {Male=boy,Female=girl} e lascia perdere questa maleducata piccola indagine, e in segreto condividerò con te metà delle mie caramelle più preziose. Sai, sui campi di battaglia della Crociata, le caramelle dolci erano un tesoro raro davvero."
  },
  Voice_149701_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_149701_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_149702_AwakerVoiceContent = {
    Text = "La benedizione di Caraboo può curare ogni malattia del mondo—inclusa questa peste nera, ovviamente... Certo che è vero! Devi solo essere abbastanza devoto, fidarti abbastanza di Caraboo, eheh."
  },
  Voice_149702_AwakerVoiceTitle = {
    Text = "Chiacchiere: Riguardo alla Crisi"
  },
  Voice_149703_AwakerVoiceContent = {Text = "Ahi~"},
  Voice_149703_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_149704_AwakerVoiceContent = {
    Text = "Ammira la luce della Fata!"
  },
  Voice_149704_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_149705_AwakerVoiceContent = {
    Text = "Il rito settuplice, il voto triplice — offri entrambi, e comprati l'assoluzione della Fata!"
  },
  Voice_149705_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_150079_AwakerVoiceContent = {Text = "Sentilo!"},
  Voice_150079_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_150104_AwakerVoiceContent = {
    Text = "Eh, come ha fatto Ogier a farti entrare? Aveva promesso che avrebbe tenuto tutti fuori. Sei il suo signore...? Ugh, i bambini inaffidabili sono proprio un mal di testa. Ho lavorato molto per preparare questo raduno, sai. Diciamo... cinquanta e cinquanta sulle offerte che raccogliamo, e tu fai finta di non vedere per me?"
  },
  Voice_150104_AwakerVoiceTitle = {
    Text = "Chiacchiera: Su Ogier"
  },
  Voice_150104_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Ogier\""
  },
  Voice_22276_AwakerVoiceContent = {
    Text = "Svelto, sbrigati! Non restare per strada."
  },
  Voice_22276_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_36679_AwakerVoiceContent = {
    Text = "Si è unito al culto mentre dormivo, quindi non ho alcun legame con lui.\nHo sentito che è venuto di sua volontà, volendo abbandonare la sua forma umana per diventare un Navigatore a tutti gli effetti... Hmph, un altro sciocco accecato dal potere."
  },
  Voice_36679_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito di Caecus"
  },
  Voice_36679_UnlockDesc = {
    Text = "Sbloccato dopo aver completato il Capitolo 6 della Storia Principale"
  },
  Voice_36680_AwakerVoiceContent = {
    Text = "Golia non è mai stato un animale fedele. Non riesco a capire perché Miryam lo apprezzi tanto... Se non fosse stato incatenato, sarebbe fuggito e l'avrebbe tradita immediatamente."
  },
  Voice_36680_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Golia"
  },
  Voice_36680_UnlockDesc = {
    Text = "Sbloccato dopo aver completato il Capitolo 6 della Storia Principale"
  },
  Voice_36681_AwakerVoiceContent = {
    Text = "I Navigatori non nascono così. Per mimetizzarsi, vivono la prima metà della loro vita proprio come gli umani...\nFaresti meglio a stare attento—il proprietario della tua pasticceria preferita potrebbe essere uno di loro!"
  },
  Voice_36681_AwakerVoiceTitle = {
    Text = "Chat: A proposito dei Navigatori"
  },
  Voice_36681_UnlockDesc = {
    Text = "Sbloccato dopo aver completato il Capitolo 6 della Storia Principale"
  },
  Voice_36682_AwakerVoiceContent = {
    Text = "Il Canto marinaresco stonato di Celeste, lo stufato di pesce affumicato tipico del Capitano, le coperte rigide e impregnate di salsedine dalla brezza marina... Per quanto tesi e pericolosi, non dimenticherò mai quei mesi di Esilio in mare."
  },
  Voice_36682_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito della \"Nave Fantasma\""
  },
  Voice_36682_UnlockDesc = {
    Text = "Sbloccato dopo aver completato il Capitolo 6 della Storia Principale"
  },
  Voice_36683_AwakerVoiceContent = {
    Text = "Tutti in questa scuola sembrano così indaffarati, ma...\nC'è una quiete pacifica qui che non ho mai conosciuto.\nLavorare insieme verso lo stesso obiettivo... Hmph, suppongo che non sia del tutto orribile."
  },
  Voice_36683_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito di Mythag II"
  },
  Voice_36683_UnlockDesc = {
    Text = "Sbloccato dopo aver completato il Capitolo 6 della Storia Principale"
  },
  Voice_36684_AwakerVoiceContent = {
    Text = "Il letto è troppo duro, il clima troppo freddo, il tè sa di acqua di risciacquo sporca... Ho mille motivi per disprezzare questo posto. \nTuttavia, dato che ci sei tu, suppongo di poterlo tollerare. Con riluttanza."
  },
  Voice_36684_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito del Custode III"
  },
  Voice_36684_UnlockDesc = {
    Text = "Sbloccato dopo aver completato il Capitolo 6 della Storia Principale"
  },
  Voice_36685_AwakerVoiceContent = {
    Text = "Grazie... E-Eh? Perché lo sto dicendo? Beh, ovviamente! È per tutto quello che hai fatto per me in mare...\nAspetta, perché stai ridendo?! Vuoi solo vedermi in imbarazzo!"
  },
  Voice_36685_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito del Custode II"
  },
  Voice_36685_UnlockDesc = {
    Text = "Sbloccato dopo aver completato il Capitolo 6 della Storia Principale"
  },
  Voice_36686_AwakerVoiceContent = {
    Text = "Un tempo credevo ci fosse una sorta di legame familiare tra noi...\nMa ora, dopo tutto quello che è successo, mi rendo conto che quei fugaci momenti di calore erano solo illusioni.\nQuello che fai con lei sono affari tuoi, basta che la tieni lontana da me."
  },
  Voice_36686_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito di Miryam II"
  },
  Voice_36686_UnlockDesc = {
    Text = "Sbloccato dopo aver completato il Capitolo 6 della Storia Principale"
  },
  Voice_36687_AwakerVoiceContent = {
    Text = "Che strano... Questa sensazione è così bizzarra.\nIl mio cuore si è fermato, eppure il mio corpo è ancora caldo... Ehi, vieni qui e toccami la mano. Dimmi che non è un qualche trucco."
  },
  Voice_36687_AwakerVoiceTitle = {
    Text = "Chat: A proposito dei \"Risvegliati\""
  },
  Voice_36687_UnlockDesc = {
    Text = "Sbloccato dopo aver completato il Capitolo 6 della Storia Principale"
  },
  Voice_45153_AwakerVoiceContent = {
    Text = "Forse non sono nato nel Regno di Leo, ma la Grande Cattedrale della Redenzione è il luogo dove ho ricevuto la mia seconda vita. Perché, dunque, non posso considerare questo posto la mia casa?"
  },
  Voice_45153_AwakerVoiceTitle = {
    Text = "Chat: A proposito della casa"
  },
  Voice_45154_AwakerVoiceContent = {
    Text = "Dopo anni di questa piaga invisibile, il Padre Supremo ha finalmente udito le mie preghiere e mi ha concesso la \"Benedizione\" capace di contrastare la sofferenza. Essa dona davvero la vita, ma richiede anche un prezzo. Come Suo esecutore, devo farmi carico di quel fardello al posto dei benedetti."
  },
  Voice_45154_AwakerVoiceTitle = {
    Text = "Chat: A proposito della Sua \"Benedizione\""
  },
  Voice_45155_AwakerVoiceContent = {
    Text = "Per me, la condizione di Risvegliatore è un dono del nostro Padre Supremo alle anime nel Suo abbraccio. È una seconda vita, un'opportunità per rimediare ai rimpianti passati. Continuerò la Sua opera, adempirò ai miei doveri come Suo delegato e allevierò ancora più sofferenza."
  },
  Voice_45155_AwakerVoiceTitle = {
    Text = "Chat: A proposito dei \"Risvegliati\""
  },
  Voice_45156_AwakerVoiceContent = {
    Text = "Lascia che ti esprima ancora una volta la mia gratitudine, Custode, per aver rispettato i miei desideri e aver mantenuto il mio segreto dal Comitato. Temo che il loro intervento mi impedirebbe di continuare il mio servizio alla Cattedrale della Vita."
  },
  Voice_45156_AwakerVoiceTitle = {
    Text = "Chat: A proposito del Custode: II"
  },
  Voice_45156_UnlockDesc = {
    Text = "Si sblocca dopo aver completato l'Operazione Speciale \"Colore del Sangue\""
  },
  Voice_45157_AwakerVoiceContent = {
    Text = "Quel ragazzo è sincero, Irremovibile e gentile, con un'anima luminosa rara. L'ultima volta che ho incontrato uno spirito simile fu durante il primo capitolo della mia vita."
  },
  Voice_45157_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito di Ogier"
  },
  Voice_45157_UnlockDesc = {
    Text = "Si sblocca dopo aver completato l'Operazione Speciale \"Colore del Sangue\""
  },
  Voice_45158_AwakerVoiceContent = {
    Text = "Perdere la vista non significa essere diventato cieco. Mentre il Padre Supremo mi ha portato l'Oscurità, mi ha anche concesso di vedere la tenue luce delle anime."
  },
  Voice_45158_AwakerVoiceTitle = {
    Text = "Chat: A proposito della Visuale"
  },
  Voice_45159_AwakerVoiceContent = {
    Text = "All'epoca, sebbene avessi ricevuto \"la Benedizione\", ero solo un uomo comune. Troppi soffrivano, troppi ne avevano bisogno. Volevo salvarli tutti, ma ho fallito. Questo è il mio più grande rimpianto e la mia colpa eterna."
  },
  Voice_45159_AwakerVoiceTitle = {
    Text = "Chat: A proposito della Sua prima vita"
  },
  Voice_45160_AwakerVoiceContent = {
    Text = "Molti nella Chiesa della Vita credono che la \"fiamma bianca\" nelle Scritture si riferisca alla luce lunare: un Pallido Messaggero che appare da essa per guidarci fuori dalla sofferenza.\nMa io so che la vera fiamma è l'anima che arde dentro di te e di me."
  },
  Voice_45160_AwakerVoiceTitle = {
    Text = "Chat: A proposito della \"Fiamma Pallida\""
  },
  Voice_45161_AwakerVoiceContent = {
    Text = "In realtà, è stato l'Arcivescovo a dirmi di nascondere la mia vera identità. Non ha elaborato, ma mi ha avvertito: anche nei luoghi più puri possono esistere ombre, e bisogna restare cauti, anche quando si fa del bene. Naturalmente, di te mi fido completamente."
  },
  Voice_45161_AwakerVoiceTitle = {
    Text = "Chat: A proposito del celare la propria identità"
  },
  Voice_45161_UnlockDesc = {
    Text = "Si sblocca dopo aver completato l'Operazione Speciale \"Colore del Sangue\""
  },
  Voice_4908_AwakerVoiceContent = {
    Text = "Il mio canto ti è stato d'aiuto?"
  },
  Voice_4908_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_4909_AwakerVoiceContent = {
    Text = "Maledizione, è solo un ragazzo! Perché lo trattate tutti con tanto rispetto?! Mostrate la stessa reverenza anche a me, intesi?!"
  },
  Voice_4909_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Tulu"
  },
  Voice_4909_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Tulu\""
  },
  Voice_4910_AwakerVoiceContent = {
    Text = "Ehi, sai cosa fanno di solito gli altri Risvegliati? Non fraintendere, non voglio amici, io solo... Sto semplicemente facendo un'ispezione!"
  },
  Voice_4910_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito della vita quotidiana"
  },
  Voice_4911_AwakerVoiceContent = {
    Text = "Maledizione! La prossima volta getterò i loro cadaveri ai ragni per cena!"
  },
  Voice_4911_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_4912_AwakerVoiceContent = {
    Text = "Bagliore residuo."
  },
  Voice_4912_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_4913_AwakerVoiceContent = {Text = "Ritmo."},
  Voice_4913_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_4914_AwakerVoiceContent = {
    Text = "Piuttosto audace da parte tua."
  },
  Voice_4914_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_4915_AwakerVoiceContent = {
    Text = "Rallentiamo un po'... C'è qualcosa che io possa fare per te?"
  },
  Voice_4915_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_4916_AwakerVoiceContent = {Text = "Come osi!"},
  Voice_4916_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_4917_AwakerVoiceContent = {
    Text = "(Interroga con vivo interesse)"
  },
  Voice_4917_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_4918_AwakerVoiceContent = {
    Text = "Cosa mi piace? Il mio bambino, il Feto Divino che mi ha conferito il mio prestigio, naturalmente. Pensi che non sia da me dirlo?"
  },
  Voice_4918_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_4919_AwakerVoiceContent = {
    Text = "Quali sono le tue intenzioni?"
  },
  Voice_4919_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_4920_AwakerVoiceContent = {
    Text = "Niente male, eh? Ora, il mio compenso. — Cosa? Pensavi che fosse gratis?!"
  },
  Voice_4920_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_4921_AwakerVoiceContent = {Text = "Vattene!"},
  Voice_4921_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_4922_AwakerVoiceContent = {Text = "Attento!"},
  Voice_4922_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_4923_AwakerVoiceContent = {
    Text = "Che vittoria gloriosa... Inciderò questo istante nell'eternità."
  },
  Voice_4923_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_4924_AwakerVoiceContent = {
    Text = "La sento... La Fonte dell'Impurità... Un passo più vicino alla Nostra vera forma... Ahhh, squarcerò questo mondo!"
  },
  Voice_4924_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_4924_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_4925_AwakerVoiceContent = {
    Text = "Siamo...pronti. Per favore, impartisci l'ordine, Custode."
  },
  Voice_4925_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_4925_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_4926_AwakerVoiceContent = {
    Text = "{Male=Signore,Female=Signora}, siete davvero gentile. Purtroppo non ho nulla con cui ripagarvi, inutile come sono..."
  },
  Voice_4926_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_4926_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_4927_AwakerVoiceContent = {
    Text = "...Ancora un poco, e sarò completamente separato da \"loro\"?"
  },
  Voice_4927_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_4927_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_4928_AwakerVoiceContent = {
    Text = "Eh? Sono ancora vivo... Voi... Davvero non mi ruberete gli organi né mi userete per esperimenti?"
  },
  Voice_4928_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_4928_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_4929_AwakerVoiceContent = {
    Text = "La specie nativa di Winkle può infiltrarsi nel cervello biologico, inducendo la Volontà Esterna fusa con me a temerla. Ma ora non è che una povera anima confinata in un guscio."
  },
  Voice_4929_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Winkle"
  },
  Voice_4929_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Winkle\""
  },
  Voice_4930_AwakerVoiceContent = {
    Text = "Tutto. Amo tutto. Che si tratti di tutti riuniti attorno alla tavola per un pasto e una preghiera, o dell'attesa quando il Custode è fuori in missione, aspettando il vostro trionfale ritorno... L'aria è sempre colma di felicità... Merito davvero una gioia simile?"
  },
  Voice_4930_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_4931_AwakerVoiceContent = {Text = "Sprofonda."},
  Voice_4931_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_4932_AwakerVoiceContent = {Text = "Sboccia."},
  Voice_4932_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_4933_AwakerVoiceContent = {
    Text = "Fiducia,\" \"Obbedienza Cieca,\" \"Schiava,\" \"Affetto,\" \"Rispetto\"... Ricostruzione e apprendimento del modulo linguistico in corso. Vi prego, Custode, guidatemi."
  },
  Voice_4933_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_4933_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_4934_AwakerVoiceContent = {
    Text = "Erica è attualmente in modalità standby. Il corpo completerà il raffreddamento in 1 ora e 15 minuti. <Del:Per accendere Erica, offrite il vostro cuore pulsante> Avvio d'emergenza? ... Verifica dei permessi in corso... Autorità massima del Custode verificata. Ciao, Custode."
  },
  Voice_4934_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_4934_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_4935_AwakerVoiceContent = {
    Text = "L'indice di rischio medio delle missioni investigative è 7, con un consumo medio di 8 bottiglie di integratori alchemici e una media di 10 ore necessarie per la gestione dei cadaveri. Conclusione: Il lavoro di un Custode è estremamente pericoloso. Fai attenzione durante le operazioni."
  },
  Voice_4935_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_4935_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_4936_AwakerVoiceContent = {
    Text = "Ricerca nei registri dei docenti: Erica Layfield, Docente di Meccatronica e Automazione Argento, Deceduta—Non era questo che cercavate? D'accordo, nuova ricerca per la parola chiave \"Erica.\""
  },
  Voice_4936_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_4936_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_4937_AwakerVoiceContent = {
    Text = "Se avete bisogno di consultare informazioni, fornite il nome completo del file. La funzione di ricerca approssimativa non è al momento disponibile."
  },
  Voice_4937_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_4937_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_4938_AwakerVoiceContent = {
    Text = "(Esclamazione)"
  },
  Voice_4938_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_4939_AwakerVoiceContent = {Text = "Ah!"},
  Voice_4939_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_4940_AwakerVoiceContent = {
    Text = "(Esclamazione)"
  },
  Voice_4940_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_4941_AwakerVoiceContent = {Text = "Ah!"},
  Voice_4941_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_4942_AwakerVoiceContent = {
    Text = "Carica completa, pronto a detonare."
  },
  Voice_4942_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_4943_AwakerVoiceContent = {
    Text = "Carica completa, pronto a detonare."
  },
  Voice_4943_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_4944_AwakerVoiceContent = {
    Text = "Non disturbare più il mio riposo con simili inezie."
  },
  Voice_4944_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_4945_AwakerVoiceContent = {
    Text = "Come ho protetto Tintura, proteggerò anche te."
  },
  Voice_4945_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_4946_AwakerVoiceContent = {
    Text = "Non sono nessuno di importante, soltanto un'anima devota fra innumerevoli. Ho dedicato la mia vita a quella magnifica presenza, e non cesserò mai di offrire tutto me stesso per guadagnarmi anche solo uno sguardo."
  },
  Voice_4946_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul passato"
  },
  Voice_4946_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Tulu\""
  },
  Voice_4947_AwakerVoiceContent = {Text = "Guardami!"},
  Voice_4947_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_4948_AwakerVoiceContent = {Text = "Guardami!"},
  Voice_4948_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_4949_AwakerVoiceContent = {
    Text = "...Non ha importanza, purché il loro zelo non mi desti. Condividere gli alloggi è tollerabile."
  },
  Voice_4949_AwakerVoiceTitle = {
    Text = "Chat: A proposito dei Navigatori"
  },
  Voice_4949_UnlockDesc = {
    Text = "Si sblocca dopo aver acquisito uno qualsiasi dei Risvegliatori \"Miryam\", \"Golia\", \"Caecus\", \"Sanga\" o \"Faros\"."
  },
  Voice_4950_AwakerVoiceContent = {
    Text = "Odio quella sensazione oscura, come se il mio cuore fosse stato svuotato. La sensazione di inappagamento mi fa prudere tutto il corpo..."
  },
  Voice_4950_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_4951_AwakerVoiceContent = {
    Text = "No, no, no, basta! Non parlarne..."
  },
  Voice_4951_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_4953_AwakerVoiceContent = {Text = "Ha!"},
  Voice_4953_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_4954_AwakerVoiceContent = {Text = "Certo."},
  Voice_4954_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_4955_AwakerVoiceContent = {
    Text = "Gli storici che proclamano la fine del Reame Divino sono tediosi nelle loro presunzioni... Eppure le mere parole sono schiuma inconsistente; nulla potrà arrestare la gloriosa restaurazione."
  },
  Voice_4955_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_4956_AwakerVoiceContent = {
    Text = "In realtà... lascia che ti sveli un segreto. Non sono del tutto soddisfatto della mia motocicletta attuale—non che non mi piaccia! È solo che sento che manca qualcosa..."
  },
  Voice_4956_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_4957_AwakerVoiceContent = {Text = "Ha!"},
  Voice_4957_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_4958_AwakerVoiceContent = {Text = "A pezzi!"},
  Voice_4958_AwakerVoiceTitle = {
    Text = "Abilità: II: Mania"
  },
  Voice_4959_AwakerVoiceContent = {
    Text = "Mi dispiace... Non volevo che accadesse..."
  },
  Voice_4959_AwakerVoiceTitle = {
    Text = "Abilità: II: Depressione"
  },
  Voice_4960_AwakerVoiceContent = {
    Text = "(Sussurro incuriosito)"
  },
  Voice_4960_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_4961_AwakerVoiceContent = {
    Text = "Nell'anno @1@2, il Sig. Ward Philips, il Sig. Khlarcus e la Sig.ra Tawil fondarono insieme il Collegio di Mythag. Dopo un lungo sviluppo, divenne <Del:questa maledetta prigione> l'Università di Mythag."
  },
  Voice_4961_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_4962_AwakerVoiceContent = {
    Text = "Giustizia, Lealtà, Spirito Tenace, disciplina. Sono incisi nel mio cuore da tempo immemore."
  },
  Voice_4962_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_4963_AwakerVoiceContent = {
    Text = "Porterò a termine con cura il compito che mi avete assegnato."
  },
  Voice_4963_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_4964_AwakerVoiceContent = {
    Text = "Che razza di genitori irresponsabili darebbero alla propria figlia il nome di uno scudo del personaggio fatto con la testa della Gorgone? ...Non ha genitori? Hmm... che questa conversazione resti fra noi."
  },
  Voice_4964_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Aigis"
  },
  Voice_4964_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Aigis\""
  },
  Voice_4965_AwakerVoiceContent = {
    Text = "Se ti annoi, perché non vieni a \"farmi compagnia\" nel labirinto? Dopotutto, la tua vita senza speranza non è diversa da questo dedalo senza fine!"
  },
  Voice_4965_AwakerVoiceTitle = {
    Text = "Chat: A proposito del Labirinto"
  },
  Voice_4966_AwakerVoiceContent = {
    Text = "Quando Doll è presente, l'efficienza degli investigatori aumenta del 78,312%, ma un numero maggiore di persone cade anche in crisi emotive. Come dice lei: \"Se certa gente tenesse la bocca chiusa, il mondo girerebbe più liscio.\""
  },
  Voice_4966_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito di Doll"
  },
  Voice_4966_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Doll\""
  },
  Voice_4967_AwakerVoiceContent = {Text = "Sprofonda!"},
  Voice_4967_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_4968_AwakerVoiceContent = {
    Text = "Ti è piaciuto?"
  },
  Voice_4968_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_4969_AwakerVoiceContent = {
    Text = "Chi non amerebbe l'avventura? Addentrarsi in reami misteriosi inesplorati, scoprire l'ignoto e tessere la propria storia... Che emozione!"
  },
  Voice_4969_AwakerVoiceTitle = {
    Text = "Chat: A proposito delle Avventure"
  },
  Voice_4970_AwakerVoiceContent = {
    Text = "Salve. Sono Nymphaea di Febvre. Mi avete donato un nuovo corpo, permettendomi finalmente di respirare liberamente... Come posso ricambiare questa grazia?"
  },
  Voice_4970_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_4971_AwakerVoiceContent = {
    Text = "Credo di aver appena udito di nuovo i lamenti di coloro che si proclamavano miei padroni. Che delizia."
  },
  Voice_4971_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_4971_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_4972_AwakerVoiceContent = {
    Text = "Posso saltare le verdure? Anche se Tintura ha detto di non essere schizzinosa, non mi piacciono i loro Colori..."
  },
  Voice_4972_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_4973_AwakerVoiceContent = {
    Text = "Il Padre di Tutto una volta disse: \"La sofferenza non è una mia creazione. Sopportatela e dissolvetela, miei emissari, e costruite una terra senza sofferenza.\" Per questo, offrirei ogni cosa. Persino la mia vita."
  },
  Voice_4973_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_4973_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_4974_AwakerVoiceContent = {
    Text = "Di fronte alla maledizione divorante della Dissoluzione, ogni altra sofferenza impallidisce. Anche se non posso sopportare la maledizione al posto degli altri, farò tutto il possibile per alleviare il loro dolore."
  },
  Voice_4974_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_4974_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_4975_AwakerVoiceContent = {
    Text = "Sono ora in grado di alleviare il loro dolore e confortare le loro anime?"
  },
  Voice_4975_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_4975_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_4976_AwakerVoiceContent = {
    Text = "Pertanto, sopporterò ogni sofferenza, per aprire a tutti gli esseri la via verso una terra libera dal dolore."
  },
  Voice_4976_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_4976_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_4977_AwakerVoiceContent = {
    Text = "Questo calore nel profondo della mia anima... Grazie per questo dono, Fiamma Pallida. Con questo potere, forse potrò finalmente adempiere al mio dovere di Suo emissario e salvare più Suoi figli."
  },
  Voice_4977_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_4977_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_4978_AwakerVoiceContent = {
    Text = "Posso davvero mangiare tutto questo?"
  },
  Voice_4978_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_4978_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_4979_AwakerVoiceContent = {
    Text = "Heh. Quello che stai guardando non è la morte. Solo il tuo futuro. Il mio. E quello di tutti gli altri."
  },
  Voice_4979_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_4980_AwakerVoiceContent = {
    Text = "Tintura... Udire il suo canto dolente mi fa venire voglia di danzare..."
  },
  Voice_4980_AwakerVoiceTitle = {
    Text = "Chat: A proposito della Tintura"
  },
  Voice_4980_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Tinct\""
  },
  Voice_4981_AwakerVoiceContent = {
    Text = "Le prove del mondo possono davvero risvegliare il potenziale della mia stirpe? Questo... non me lo aspettavo."
  },
  Voice_4981_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_4982_AwakerVoiceContent = {
    Text = "L'arma ora sembra più maneggevole."
  },
  Voice_4982_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_4983_AwakerVoiceContent = {
    Text = "Non credere che questo ti meriterà la mia gratitudine. Il mio Nobile lignaggio semplicemente non lo permetterebbe."
  },
  Voice_4983_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_4984_AwakerVoiceContent = {Text = "Ah, uh!"},
  Voice_4984_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_4985_AwakerVoiceContent = {
    Text = "Quell'uomo... Ehi, un momento, la nostra scommessa non è ancora finita, vero?"
  },
  Voice_4985_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito degli altri"
  },
  Voice_4986_AwakerVoiceContent = {
    Text = "Mi piace molto il registratore dell'accademia. Se solo potessi crearne una versione portatile che mi ricordi in tempo reale ciò che ho dimenticato..."
  },
  Voice_4986_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_4987_AwakerVoiceContent = {
    Text = "Hmph, un'adunata di formiche... No, nemmeno formiche — creature come voi non siete che briciole di pane, nutrimento per la Sua rinascita."
  },
  Voice_4987_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_4988_AwakerVoiceContent = {
    Text = "I rifornimenti sono arrivati."
  },
  Voice_4988_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_4989_AwakerVoiceContent = {
    Text = "I rifornimenti sono arrivati."
  },
  Voice_4989_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_4990_AwakerVoiceContent = {
    Text = "Hmm... Più forte, più forte. Sì, proprio così..."
  },
  Voice_4990_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_4991_AwakerVoiceContent = {
    Text = "La vittoria è giunta senza sforzo, ancor prima del pieno Risveglio della mia stirpe."
  },
  Voice_4991_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_4992_AwakerVoiceContent = {
    Text = "Oh no, il mio cappello è storto... Hmm, così va meglio? Sì! Perfetto!"
  },
  Voice_4992_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_4992_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_4993_AwakerVoiceContent = {
    Text = "\"Con tali capacità, sono davvero ancora umana?\" Me lo sono chiesta ogni giorno da quando ho iniziato ad addestrarmi per il combattimento. Amo questo mondo, nonostante la sua oscurità, sporcizia e monotonia, ma la tua presenza lo fa brillare come diamanti nella polvere. Un tempo temevo che, con il crescere del mio potere, la mia posizione di essere umano potesse vacillare... Ora sono grata di averti al mio fianco. Il nostro legame mi ancora saldamente al mondo umano. Per favore, continua a vegliare su di me, Custode."
  },
  Voice_4993_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_4993_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_4994_AwakerVoiceContent = {
    Text = "Ah... È naturale che tu abbia delle preoccupazioni. Non ci ho riflettuto abbastanza. Come tua compagna, avrei dovuto spiegarti tutto fin dall'inizio. Come puoi vedere, possiedo alcuni tratti insoliti, probabilmente legati alle mie origini. È impossibile non essere curiosi, vero? Ma avere un luogo come l'accademia è una benedizione per me, perciò scelgo di non sollevare il velo del destino."
  },
  Voice_4994_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_4994_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_4995_AwakerVoiceContent = {
    Text = "L'hai incontrata, vero? La Risvegliatrice con il velo bianco—è una delle fondatrici dell'università... Ma onestamente, non mi piace. Quell'atteggiamento distaccato, come se non le importasse nulla del mondo, mi dà proprio sui nervi... Oh, pensi che mi assomigli? Andiamo a farti controllare la vista all'ambulatorio del campus."
  },
  Voice_4995_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_4995_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_4996_AwakerVoiceContent = {
    Text = "Sei curioso del mio rapporto con il Professor Dexter? Non è un segreto. È il mio padre adottivo. Quanto a mia madre... Sono cresciuta qui alla scuola, accudita da tutti gli insegnanti. Tuttavia, tra loro, sono più legata alla Professoressa Doll."
  },
  Voice_4996_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_4996_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_4997_AwakerVoiceContent = {
    Text = "Che si tratti delle procedure dell'Ufficio Affari dei Risvegliati o della data del cibo indiano in mensa, posso rispondere a qualsiasi domanda su Mythag. Non preoccuparti, non mi disturbi. Ho davvero un aspetto così inavvicinabile?"
  },
  Voice_4997_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_4997_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_4998_AwakerVoiceContent = {
    Text = "Riflesso, Riflesso, chi è il più grande mago del mondo? Io? Esatto!"
  },
  Voice_4998_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_4998_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_4999_AwakerVoiceContent = {
    Text = "Niente male."
  },
  Voice_4999_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_5000_AwakerVoiceContent = {Text = "Grande!"},
  Voice_5000_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5001_AwakerVoiceContent = {
    Text = "(Esclamazione)"
  },
  Voice_5001_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_5002_AwakerVoiceContent = {
    Text = "Ha... funzionato davvero? Sono stata di un qualche aiuto genuino?"
  },
  Voice_5002_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_5003_AwakerVoiceContent = {Text = "Inutile!"},
  Voice_5003_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_5004_AwakerVoiceContent = {
    Text = "(Sopportare)"
  },
  Voice_5004_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_5005_AwakerVoiceContent = {
    Text = "Guarda da questa parte!"
  },
  Voice_5005_AwakerVoiceTitle = {
    Text = "Abilità Speciale: I"
  },
  Voice_5006_AwakerVoiceContent = {
    Text = "Rendiamo questo il nostro clamoroso mare di felicità!"
  },
  Voice_5006_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_5007_AwakerVoiceContent = {
    Text = "Hai bisogno che ti accompagni come Guardia? Se la tua Caccia è giusta, ti assisterò."
  },
  Voice_5007_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5008_AwakerVoiceContent = {
    Text = "Le fiamme non mi consumeranno."
  },
  Voice_5008_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5009_AwakerVoiceContent = {
    Text = "Le fiamme non mi consumeranno."
  },
  Voice_5009_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_5010_AwakerVoiceContent = {
    Text = "Oh... Vuoi un abbraccio?"
  },
  Voice_5010_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_5011_AwakerVoiceContent = {
    Text = "Guarda queste catene che porto — non sono ornamenti, ma moniti. Moniti di tradimento e umiliazione."
  },
  Voice_5011_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_5012_AwakerVoiceContent = {
    Text = "Se vuoi sapere del passato dell'accademia, ti consiglio di consultare gli archivi. Dai, includendo la sua predecessora, è una storia che copre 300 anni! Non pretenderai mica che te la racconti anno per anno, vero?"
  },
  Voice_5012_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_5013_AwakerVoiceContent = {
    Text = "È una provocazione? Sono pronta in qualsiasi momento!"
  },
  Voice_5013_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_5014_AwakerVoiceContent = {
    Text = "Possa il mare profondo concederti eterno riposo."
  },
  Voice_5014_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_5015_AwakerVoiceContent = {
    Text = "Possa il mare profondo concederti eterno riposo."
  },
  Voice_5015_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_5016_AwakerVoiceContent = {
    Text = "Sprofonda e brucia! Danza verso la distruzione!"
  },
  Voice_5016_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_5017_AwakerVoiceContent = {
    Text = "Ecco a voi, la Danza verso la Distruzione della Fiamma Verde Eterna!"
  },
  Voice_5017_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_5018_AwakerVoiceContent = {
    Text = "Quella signora sembra un faro... Se avessi potuto scorgere la sua luce abbagliante durante la navigazione nella Notte Eterna, forse non mi sarei perduta."
  },
  Voice_5018_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Faros"
  },
  Voice_5018_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Faros\""
  },
  Voice_5019_AwakerVoiceContent = {
    Text = "Faresti bene a dimostrarti degno di farmi uscire dal laboratorio, nuovo Custode."
  },
  Voice_5019_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5020_AwakerVoiceContent = {
    Text = "Io sono il padrone, tu sei il servitore. Qualunque cosa io desideri deve essermi portata immediatamente. Cosa? Ti aspetti una ricompensa? E va bene, prendila, allora!"
  },
  Voice_5020_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_5021_AwakerVoiceContent = {
    Text = "(Esclamazione)"
  },
  Voice_5021_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_5022_AwakerVoiceContent = {
    Text = "Ora mi monderò di quest'onta!"
  },
  Voice_5022_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_5023_AwakerVoiceContent = {
    Text = "(Esclamazione)"
  },
  Voice_5023_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_5024_AwakerVoiceContent = {
    Text = "(Esclamazione)"
  },
  Voice_5024_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_5025_AwakerVoiceContent = {
    Text = "Dare è ricevere."
  },
  Voice_5025_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5026_AwakerVoiceContent = {
    Text = "Dare è ricevere."
  },
  Voice_5026_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_5027_AwakerVoiceContent = {
    Text = "Ti farai male!"
  },
  Voice_5027_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_5028_AwakerVoiceContent = {
    Text = "Non avvicinarti!"
  },
  Voice_5028_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_5029_AwakerVoiceContent = {
    Text = "La luce dorata della luna piena mi incanta sempre: sotto di essa, il mare cattura la luce e brilla magnificamente mentre il vento misterioso e gentile soffia, tessendo una visuale romantica e onirica."
  },
  Voice_5029_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_5030_AwakerVoiceContent = {
    Text = "Se La Nostra Casa non avesse subito la Dissoluzione, Tintura e io non saremmo separate... Odio la Dissoluzione più di quanto odi le verdure."
  },
  Voice_5030_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_5031_AwakerVoiceContent = {
    Text = "La destinazione, che sia un tesoro segreto o un porto, per me non fa differenza. Il mio unico scopo è assicurare il tuo ritorno in sicurezza."
  },
  Voice_5031_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_5031_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_5032_AwakerVoiceContent = {
    Text = "Segui la traiettoria degli uccelli del paradiso; la destinazione attende più avanti, nel blu d'ispirazione."
  },
  Voice_5032_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_5032_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_5033_AwakerVoiceContent = {
    Text = "Spesso fisso lo sguardo sull'orizzonte, immaginando i paesaggi di quella terra lontana — quella a cui mi avvicino ma che non riesco mai a raggiungere. Se quel giorno dovesse mai arrivare, ti prego, vieni con me a contemplarla."
  },
  Voice_5033_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_5033_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_5034_AwakerVoiceContent = {
    Text = "Grazie al tuo favore, persino il mare in tempesta ora appare meno temibile. Lo affronterò per portarti le mie irremovibili benedizioni."
  },
  Voice_5034_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_5034_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_5035_AwakerVoiceContent = {
    Text = "Mi sembra di udire di nuovo i canti dei rematori... e di percepire il familiare profumo di casa."
  },
  Voice_5035_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_5035_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_5036_AwakerVoiceContent = {
    Text = "Sei qui per salvarmi? Dal mondo in decomposizione, dall'odio che macchia i miei occhi, dalla fiamma verde eterna..."
  },
  Voice_5036_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_5037_AwakerVoiceContent = {
    Text = "Canaglia impudente!"
  },
  Voice_5037_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5038_AwakerVoiceContent = {
    Text = "Considera questo il mio giuramento di lealtà verso di te."
  },
  Voice_5038_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_5038_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_5039_AwakerVoiceContent = {
    Text = "Impara la lezione!"
  },
  Voice_5039_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_5040_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_5040_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_5041_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_5041_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_5042_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_5042_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_5043_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_5044_AwakerVoiceContent = {
    Text = "Ti mostrerò cosa sa fare un topo!"
  },
  Voice_5044_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_5045_AwakerVoiceContent = {
    Text = "Ti mostrerò cosa sa fare un topo!"
  },
  Voice_5045_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_5046_AwakerVoiceContent = {
    Text = "Il dado è tratto. Ora, finiamola in fretta!"
  },
  Voice_5046_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_5047_AwakerVoiceContent = {
    Text = "Includerò il tuo nome nei miei ringraziamenti. Sei tu che hai permesso a questi piedi, macchiati di sangue oscuro, di calcare ancora una volta il meraviglioso mondo del balletto. D'ora in poi, guardami danzare, Custode."
  },
  Voice_5047_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_5047_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_5048_AwakerVoiceContent = {
    Text = "Per quanto tu lotti, non puoi sfidare il fato. Ma quell'istante fugace di splendore sarà cristallizzato nell'eternità."
  },
  Voice_5048_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_5048_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_5049_AwakerVoiceContent = {
    Text = "Che facciamo di questi falliti?"
  },
  Voice_5049_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_5050_AwakerVoiceContent = {
    Text = "Anche se il mio cuore non custodisce più alcun desiderio, continuerò a interpretare il ruolo del cigno."
  },
  Voice_5050_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_5050_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_5051_AwakerVoiceContent = {
    Text = "Chiudi gli occhi e dimmi, cosa vedi? Luce lunare immacolata, un lago tranquillo..."
  },
  Voice_5051_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_5051_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_5052_AwakerVoiceContent = {
    Text = "Ah, la calamità della distruzione e della sventura... Perché ha dovuto tormentare me e mia sorella?"
  },
  Voice_5052_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_5053_AwakerVoiceContent = {
    Text = "Accetta il mio affetto."
  },
  Voice_5053_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5054_AwakerVoiceContent = {
    Text = "Accetta il mio affetto."
  },
  Voice_5054_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_5055_AwakerVoiceContent = {
    Text = "Mi sento molto meglio ora, vi ringrazio per la vostra gentilezza."
  },
  Voice_5055_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_5056_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_5056_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_5057_AwakerVoiceContent = {
    Text = "Se vi fa piacere, vorrei offrirvi un ninfea viola pallido come pegno della mia sincera gratitudine."
  },
  Voice_5057_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_5058_AwakerVoiceContent = {
    Text = "Credi che anch'io possa diventare più forte?"
  },
  Voice_5058_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_5059_AwakerVoiceContent = {
    Text = "Si parte...!"
  },
  Voice_5059_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5060_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_5060_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_5061_AwakerVoiceContent = {
    Text = "Questa gamba ferita? Non mi aspettavo che ti importasse. L'ho avuta sul campo di battaglia prima di diventare una Risvegliatrice.\nNon preoccuparti, non interferisce più con le mie capacità di combattimento, ora che sono una Risvegliatrice.\nSe fa male, chiedi? No. Non ci ho pensato."
  },
  Voice_5061_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_5061_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_5062_AwakerVoiceContent = {
    Text = "Sylvia mi ha chiesto del mio stato mentale. L'hai mandata tu, non è vero? Ammetto che il dolore fantasma si riacutizza di tanto in tanto. Ma non preoccupartene. Sono la tua spada, la tua lama. Finché potrò combattere per la giustizia, un dolore di poco conto non avrà importanza."
  },
  Voice_5062_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_5062_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_5063_AwakerVoiceContent = {
    Text = "Festa del tè, festa del tè! Facciamo una festa del tè! Ho ottenuto un sacco di foglie di tè e dolcetti da Sylvia! Già, in cambio ho eseguito la Danza Furlesca!"
  },
  Voice_5063_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_5064_AwakerVoiceContent = {
    Text = "Il mio titolo? Sei davvero così interessato ai miei affari personali? Vuoi solo chiacchierare... E va bene.\nNell'esercito, non facciamo distinzioni tra commilitoni in base al genere—questo include forza, velocità e, naturalmente, acconciature e titoli. Col tempo, mi sono abituata a questo modo di esprimermi."
  },
  Voice_5064_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_5064_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_5065_AwakerVoiceContent = {
    Text = "Interessante... Non temi che ti riduca in Frammenti e ti dia in pasto ai pesci, una volta ottenuto il Potere?"
  },
  Voice_5065_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_5066_AwakerVoiceContent = {
    Text = "Ti impegni davvero per essere un Custode degno di me, a quanto vedo."
  },
  Voice_5066_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_5067_AwakerVoiceContent = {
    Text = "È ora di provare. Hmph. Che ne dici di tagliare la gola a qualche debole, per cominciare?"
  },
  Voice_5067_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_5068_AwakerVoiceContent = {
    Text = "La danza è pura. Le parole possono generare malintesi, ma i passi di danza mai."
  },
  Voice_5068_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito della danza"
  },
  Voice_5069_AwakerVoiceContent = {
    Text = "Odio il mare, e a buon ragione. L'oceano ha divorato tutto ciò che amavo..."
  },
  Voice_5069_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_5070_AwakerVoiceContent = {
    Text = "Che si tratti di oblio o di perdita, questa volta faremo sicuramente ritorno!"
  },
  Voice_5070_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_5071_AwakerVoiceContent = {
    Text = "Che si tratti di oblio o di perdita, questa volta faremo sicuramente ritorno!"
  },
  Voice_5071_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_5072_AwakerVoiceContent = {
    Text = "Ti prego, ti prego, non avvicinarti oltre. È pericoloso... per te."
  },
  Voice_5072_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5073_AwakerVoiceContent = {
    Text = "Toccami pure quanto vuoi... Queste sono le cicatrici che mi sono guadagnato nell'Arena, i distintivi d'onore di un uomo!"
  },
  Voice_5073_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_5074_AwakerVoiceContent = {
    Text = "(Grido di dolore)"
  },
  Voice_5074_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_5075_AwakerVoiceContent = {Text = "Ahi! Ahi!"},
  Voice_5075_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_5076_AwakerVoiceContent = {
    Text = "(Un'inspirazione sommessa, trattenuta)"
  },
  Voice_5076_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_5077_AwakerVoiceContent = {
    Text = "(Grugnito irritato)"
  },
  Voice_5077_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_5078_AwakerVoiceContent = {
    Text = "Sento qualcosa ribollire dentro di me. È questa la sensazione dell'Illuminare?"
  },
  Voice_5078_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_5078_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_5079_AwakerVoiceContent = {
    Text = "È una specie di nuova tecnologia? Il mio arto protesico sembra molto più leggero."
  },
  Voice_5079_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_5079_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_5080_AwakerVoiceContent = {
    Text = "La brezza salmastra del mare mi dice che la mia terra natia non è lontana."
  },
  Voice_5080_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_5080_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_5081_AwakerVoiceContent = {
    Text = "I miei congiunti defunti potranno ritrovare la via del focolare, seguendo questa luce?"
  },
  Voice_5081_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_5081_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_5082_AwakerVoiceContent = {
    Text = "Ho cercato per decine di migliaia di anni; un fugace secolo non è nulla al confronto. Fino a quando non raggiungerai la fine della tua vita, continuerò ad assisterti."
  },
  Voice_5082_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_5082_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_5083_AwakerVoiceContent = {
    Text = "Brillerò solo per la mia Terra dei Bianchi Uccelli. Quanto a te..."
  },
  Voice_5083_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_5083_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_5084_AwakerVoiceContent = {
    Text = "Ho sentito la brezza, che trasportava sabbia fine sui miei piedi."
  },
  Voice_5084_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_5084_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_5085_AwakerVoiceContent = {
    Text = "Il mio contributo al vostro potere finisce qui. Essere troppo bramosi non è cosa saggia, sapete."
  },
  Voice_5085_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_5085_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_5086_AwakerVoiceContent = {
    Text = "Cosa vi aspettate in cambio da me? Qualcosa oltre a prestarvi il mio potere nelle battaglie?"
  },
  Voice_5086_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_5086_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_5087_AwakerVoiceContent = {
    Text = "Teschio dell'Amore, Teschio del Risentimento, Teschio dell'Odio, Teschio del Desiderio... Oh, siete di nuovo qui, caro ospite?"
  },
  Voice_5087_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_5087_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_5088_AwakerVoiceContent = {
    Text = "Trattandosi di una transazione, non posso semplicemente accettare il vostro dono. Desiderate scegliere qualcosa dal mio negozio?"
  },
  Voice_5088_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_5088_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_50898_AwakerVoiceContent = {
    Text = "Ti insegnerò il piacere, l'ebbrezza di cavalcare quell'estasi... In cambio, mi svelerai i tuoi Desideri."
  },
  Voice_50898_AwakerVoiceTitle = {
    Text = "Chat: A proposito del Custode - 2"
  },
  Voice_50899_AwakerVoiceContent = {
    Text = "Io sono l'Albero Madre. L'Albero Madre sono io. La sua linfa scorre nelle mie vene, la sua volontà sussurra nella mia mente..."
  },
  Voice_50899_AwakerVoiceTitle = {
    Text = "Chat: A proposito dell'Albero Madre"
  },
  Voice_50899_UnlockDesc = {
    Text = "Si sblocca dopo aver completato il Capitolo 7 della Storia principale"
  },
  Voice_5089_AwakerVoiceContent = {
    Text = "Paga il prezzo del tuo tradimento!"
  },
  Voice_5089_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_50900_AwakerVoiceContent = {
    Text = "Ho intravisto la tua lapide tra le Ombre di Keygrave... Anche la mia carne mummificata riposerà qui, un giorno? No? Che peccato."
  },
  Voice_50900_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Keygrave"
  },
  Voice_50900_UnlockDesc = {
    Text = "Si sblocca dopo aver completato il Capitolo 7 della Storia principale"
  },
  Voice_50901_AwakerVoiceContent = {
    Text = "Quel ragazzo-lupo... Lo sapevi? Tra lui e quel N c'è qualcosa di... indescrivibile."
  },
  Voice_50901_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Ryker"
  },
  Voice_50901_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Ryker\""
  },
  Voice_50902_AwakerVoiceContent = {
    Text = "Avvicinati. Abbracciami. Assaporami... Non Dimenticare Mai."
  },
  Voice_50902_AwakerVoiceTitle = {
    Text = "Chat: A proposito del Custode - 3"
  },
  Voice_50902_UnlockDesc = {
    Text = "Si sblocca dopo aver completato il Capitolo 7 della Storia principale"
  },
  Voice_50903_AwakerVoiceContent = {
    Text = "È una fanciulla fin troppo cauta. Non che la biasimi — senza di lei, il mio popolo dallo spirito libero sarebbe perito da tempo, non è vero?"
  },
  Voice_50903_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Alva"
  },
  Voice_50903_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Alva\""
  },
  Voice_50904_AwakerVoiceContent = {
    Text = "Dalle sabbie gialle sei nato, e alle sabbie gialle farai Ritorno. In questo breve viaggio, non dovresti lasciare qualche ricordo lungo il cammino? Seminare qualche Seme?"
  },
  Voice_50904_AwakerVoiceTitle = {
    Text = "Chat: A proposito del Deserto"
  },
  Voice_50905_AwakerVoiceContent = {
    Text = "Tutti i desideri germogliano dall'amore; l'amore è il Seme che precede l'albero maestoso della fertilità."
  },
  Voice_50905_AwakerVoiceTitle = {
    Text = "Chat: A proposito del Desiderio"
  },
  Voice_50906_AwakerVoiceContent = {
    Text = "Oh cielo, un topolino è sgattaiolato via... Adorano rosicchiare cose proibite, non è vero? Ma questo è ancora troppo giovane."
  },
  Voice_50906_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Jenkin"
  },
  Voice_50906_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Jenkin\""
  },
  Voice_50907_AwakerVoiceContent = {
    Text = "Portavano il mio Sangue, la mia stirpe, divenendo le acque rigogliose di Remouahe... Ora, mia cara, devi far sì che la mia eredità sopravviva."
  },
  Voice_50907_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Aram"
  },
  Voice_50907_UnlockDesc = {
    Text = "Si sblocca dopo aver completato il Capitolo 7 della Storia principale"
  },
  Voice_50908_AwakerVoiceContent = {
    Text = "Ragni... Mmm~ Li adoro. Nascono già camminando e sono fertili oltre ogni invidia..."
  },
  Voice_50908_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Agrippa"
  },
  Voice_50908_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Agrippa\""
  },
  Voice_50909_AwakerVoiceContent = {
    Text = "Coloro in cui scorre il Sangue dell'albero sono i miei Fanciulli — tu, che ne hai Divorato i Semi, sei naturalmente tra loro."
  },
  Voice_50909_AwakerVoiceTitle = {
    Text = "Chat: A proposito della Progenie"
  },
  Voice_50909_UnlockDesc = {
    Text = "Si sblocca dopo aver completato il Capitolo 7 della Storia principale"
  },
  Voice_5090_AwakerVoiceContent = {
    Text = "La mia merce? Si potrebbe dire che ho tutto per soddisfare ogni vostro desiderio... a un certo prezzo."
  },
  Voice_5090_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_5090_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_50910_AwakerVoiceContent = {
    Text = "Oh cielo, questa volta ho perso contro di lei... Ma poiché ha scelto te, berrai la linfa dell'Albero Sacro e porterai il mio Sangue e i miei Semi in un nuovo mondo, sì?"
  },
  Voice_50910_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Tawil"
  },
  Voice_50910_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Ramona\""
  },
  Voice_50911_AwakerVoiceContent = {
    Text = "Quello, dei tre Eoni, è un Mostro avvolto in enigmi. Ti prego, non lasciarti sedurre dalle sue parole melliflue, o mi si spezzerà il cuore..."
  },
  Voice_50911_AwakerVoiceTitle = {
    Text = "Chat: A proposito di \"N\""
  },
  Voice_50912_AwakerVoiceContent = {
    Text = "Tutti gli esseri coscienti hanno desideri. Persino le macchine, sì?"
  },
  Voice_50912_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Erica"
  },
  Voice_50912_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Erica\""
  },
  Voice_5091_AwakerVoiceContent = {
    Text = "Paga il prezzo del tuo tradimento!"
  },
  Voice_5091_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_5092_AwakerVoiceContent = {
    Text = "Benvenuto nel paese delle meraviglie!"
  },
  Voice_5092_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_5093_AwakerVoiceContent = {
    Text = "(Borbottio)"
  },
  Voice_5093_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_5094_AwakerVoiceContent = {
    Text = "Conosco bene il dolore dell'intaglio e la bruciatura della trasformazione. Eppure tutto ciò svanisce al cospetto della bellezza eterna."
  },
  Voice_5094_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_5094_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_5095_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_5096_AwakerVoiceContent = {
    Text = "Ti trasmetterò queste parole inespresse attraverso la mia opera."
  },
  Voice_5096_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_5096_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_5097_AwakerVoiceContent = {
    Text = "(Esclamazione)"
  },
  Voice_5097_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_5098_AwakerVoiceContent = {
    Text = "Il Sovrano dormiente sussurra Deliri al mio orecchio, le rovine del Mare profondo si ricostruiscono incessantemente davanti ai miei occhi... Le innumerevoli scene oniriche si sono infine avverate?"
  },
  Voice_5098_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_5098_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_5099_AwakerVoiceContent = {
    Text = "Grazie per aver preparato questo atelier per me. Ogni cosa qui è immersa nella luce del sole; sembra che ogni opera, ogni coltello da intaglio, risplenda di una luce dorata. Oh, la Primavera è dorata."
  },
  Voice_5099_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_5099_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_5100_AwakerVoiceContent = {
    Text = "Sebbene i nostri temperamenti differiscano, ammiro davvero quella ragazza. Possiede un coraggio che trascende ogni avversità e ogni limite. Se fossi stata coraggiosa e resiliente come lei, forse non avrei scelto di porre fine alla mia vita nel mare..."
  },
  Voice_5100_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Murphy"
  },
  Voice_5100_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risveglio \"Murphy\""
  },
  Voice_5101_AwakerVoiceContent = {
    Text = "La Dama in Rosso è diversa da qualsiasi signore che abbia mai servito... No, non è che mi sia sgradita; è solo che... a volte faccio un po' fatica a sostenere il suo sguardo..."
  },
  Voice_5101_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Sorel"
  },
  Voice_5101_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Sorel\""
  },
  Voice_5102_AwakerVoiceContent = {
    Text = "Abbraccia la Follia!"
  },
  Voice_5102_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_5103_AwakerVoiceContent = {
    Text = "Topi morenti."
  },
  Voice_5103_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5104_AwakerVoiceContent = {Text = "Sterminio!"},
  Voice_5104_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5105_AwakerVoiceContent = {
    Text = "Non devi farlo per me..."
  },
  Voice_5105_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_5106_AwakerVoiceContent = {
    Text = "Il mio cuore è un abisso senza fondo, mai colmabile."
  },
  Voice_5106_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_5107_AwakerVoiceContent = {
    Text = "Non mi ha fatto provare nulla, ma... vi sono comunque terribilmente grata."
  },
  Voice_5107_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_5108_AwakerVoiceContent = {
    Text = "Ah... State parlando con me? Le mie scuse, ero persa nelle memorie della vista di quando ero legata all'albero maestro. Vi dispiacerebbe ripetere la vostra domanda?"
  },
  Voice_5108_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul passato"
  },
  Voice_5109_AwakerVoiceContent = {
    Text = "Tu sei il mio Padrone... La mia Mamma."
  },
  Voice_5109_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_5110_AwakerVoiceContent = {
    Text = "Un'apertura!"
  },
  Voice_5110_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_5111_AwakerVoiceContent = {
    Text = "Un'apertura!"
  },
  Voice_5111_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5112_AwakerVoiceContent = {Text = "Pronto—"},
  Voice_5112_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5113_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5113_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5114_AwakerVoiceContent = {
    Text = "Sì, più forte!"
  },
  Voice_5114_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5115_AwakerVoiceContent = {
    Text = "Questo è il calore del mio amore!"
  },
  Voice_5115_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_5116_AwakerVoiceContent = {
    Text = "La Dissoluzione... Non posso parlarne liberamente. Ma sappi questo: è apparsa molto prima di quanto immagini."
  },
  Voice_5116_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_5118_AwakerVoiceContent = {Text = "Huhhh—"},
  Voice_5118_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5119_AwakerVoiceContent = {Text = "Certo."},
  Voice_5119_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5120_AwakerVoiceContent = {Text = "Partiamo."},
  Voice_5120_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5121_AwakerVoiceContent = {
    Text = "Oh, la nostra Principessa marionetta sta piangendo di nuovo. Il biberon non va bene, o la Ninnananna non è abbastanza dolce?"
  },
  Voice_5121_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Murphy"
  },
  Voice_5121_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risveglio \"Murphy\""
  },
  Voice_5122_AwakerVoiceContent = {
    Text = "Buhuuu... non voglio affrontare quelle cose..."
  },
  Voice_5122_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_5123_AwakerVoiceContent = {
    Text = "Ora tocca a me ripagarti."
  },
  Voice_5123_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5124_AwakerVoiceContent = {
    Text = "L'Ondata di Potere è come fiamme ardenti che bruciano fin dentro le mie ossa."
  },
  Voice_5124_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_5125_AwakerVoiceContent = {
    Text = "Ah... Scusa, p-per favore non muoverti!"
  },
  Voice_5125_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_5126_AwakerVoiceContent = {
    Text = "Il calore, così vicino..."
  },
  Voice_5126_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_5127_AwakerVoiceContent = {
    Text = "Le rose nel cortile sono in piena fioritura."
  },
  Voice_5127_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_5128_AwakerVoiceContent = {
    Text = "Ottimo lavoro! Hai ancora l'energia per continuare?"
  },
  Voice_5128_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_5129_AwakerVoiceContent = {
    Text = "L'ideale di un cavaliere è privo di forma, plasmato dalla lealtà, dal coraggio e dalla virtù. La mia arma è la stessa cosa, resa concreta dalla volontà di proteggere: una lancia e uno scudo."
  },
  Voice_5129_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Cavaliere"
  },
  Voice_5130_AwakerVoiceContent = {
    Text = "Jenkin, Diana, Mac, T'yog, Brown... Woahh! Scusate, stavo solo parlando tra me e me! Chiedete perché recito questi nomi? Perché non voglio dimenticarli..."
  },
  Voice_5130_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sugli amici"
  },
  Voice_5131_AwakerVoiceContent = {Text = "Sparisci!"},
  Voice_5131_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5132_AwakerVoiceContent = {
    Text = "È insopportabile!"
  },
  Voice_5132_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_5133_AwakerVoiceContent = {Text = "Haaah!"},
  Voice_5133_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5134_AwakerVoiceContent = {Text = "Haaah!"},
  Voice_5134_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_5135_AwakerVoiceContent = {
    Text = "Grazie per il tuo richiamo. Se ci sarà un'occasione in cui la mia voce sarà necessaria, ti prego di avvisarmi in anticipo."
  },
  Voice_5135_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5137_AwakerVoiceContent = {
    Text = "Quello... è il liquido nero e viscoso che scorre nelle mie vene, il Potere supremo che riduce al Silenzio ogni urlo di dolore! \"Io\" sono nato da questo, nato per Distruggere! HAHAHA!"
  },
  Voice_5137_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_5138_AwakerVoiceContent = {
    Text = "Ehi, che si fa, andiamo a scommettere? ...Un'Indagine? Ah, no, sarebbe uno Spreco di una striscia fortunata..."
  },
  Voice_5138_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5139_AwakerVoiceContent = {
    Text = "Le lezioni teoriche sono piuttosto noiose. Leggo di nascosto i resoconti delle indagini in fondo all'aula. Non dirlo a Doll. È Il Nostro Segreto, d'accordo?"
  },
  Voice_5139_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_5140_AwakerVoiceContent = {
    Text = "Assapora le amare conseguenze!"
  },
  Voice_5140_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_5141_AwakerVoiceContent = {
    Text = "Assapora le amare conseguenze!"
  },
  Voice_5141_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5142_AwakerVoiceContent = {
    Text = "Non ho mai incolpato Juliette; era semplicemente una vittima della nera sofferenza. Ma... non sembra voler sentire queste parole da me. Potresti riferirglielo tu, Messaggero?"
  },
  Voice_5142_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Juliette"
  },
  Voice_5142_UnlockDesc = {
    Text = "Voce non ancora implementata"
  },
  Voice_5143_AwakerVoiceContent = {
    Text = "Più piano."
  },
  Voice_5143_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_5144_AwakerVoiceContent = {Text = "Certo."},
  Voice_5144_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_5145_AwakerVoiceContent = {
    Text = "Ehi! Giù le mani dal mio vestito, lo stai sgualcendo! ...Va bene, lo permetterò questa volta, magnanima come sono."
  },
  Voice_5145_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_5146_AwakerVoiceContent = {Text = "Non serve!"},
  Voice_5146_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_5147_AwakerVoiceContent = {Text = "Tsk!"},
  Voice_5147_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_5148_AwakerVoiceContent = {
    Text = "Dal giorno in cui mi hai Risvegliato dall'Oscurità, ho avuto la certezza che tu possa salvare tutti dalla disperazione della Dissoluzione e condurli alla terra priva di peccato. Attendo quel giorno con cuore speranzoso."
  },
  Voice_5148_AwakerVoiceTitle = {
    Text = "Chat: A proposito del Custode: I"
  },
  Voice_5149_AwakerVoiceContent = {
    Text = "Sento... l'odore del sangue."
  },
  Voice_5149_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_5150_AwakerVoiceContent = {
    Text = "Dov'è il bersaglio? Come segno di gratitudine per avermi risvegliato, me ne occuperò io per te."
  },
  Voice_5150_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5151_AwakerVoiceContent = {
    Text = "Il mio cappello non può più aspettare!"
  },
  Voice_5151_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_5152_AwakerVoiceContent = {
    Text = "Questo guscio non dovrebbe fremere per nessuno se non per Lui... Eppure... il tuo calore..."
  },
  Voice_5152_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_5153_AwakerVoiceContent = {
    Text = "Cosa. Vuoi combattere?"
  },
  Voice_5153_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_5154_AwakerVoiceContent = {
    Text = "Profanatore..."
  },
  Voice_5154_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5155_AwakerVoiceContent = {
    Text = "Imperdonabile."
  },
  Voice_5155_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_5156_AwakerVoiceContent = {
    Text = "Erica funziona normalmente ed è ben collegata alle apparecchiature elettriche dell'Università di Mythag. Desiderate che accenda le luci del dormitorio?"
  },
  Voice_5156_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Erica"
  },
  Voice_5157_AwakerVoiceContent = {
    Text = "Ah, è ora di mangiare. Hehe..."
  },
  Voice_5157_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_5159_AwakerVoiceContent = {
    Text = "Non lasciate che quella donna col cappello viola a tesa larga si avvicini al palco! Niente domande — tenetela lontana, se non volete che materia grigia appiccicosa vi coli fuori dal mio cappello!"
  },
  Voice_5159_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Daffodil"
  },
  Voice_5159_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Daffodil\""
  },
  Voice_5160_AwakerVoiceContent = {
    Text = "Sei sempre così? Ti fidi di tutti e volti loro le spalle? Ingenuo."
  },
  Voice_5160_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_5161_AwakerVoiceContent = {
    Text = "L'odio può essere alleviato, ma non potrà mai essere cancellato."
  },
  Voice_5161_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_5162_AwakerVoiceContent = {
    Text = "Risveglio? Hmm... Sì, le 7 di mattina sono l'orario migliore per svegliarsi! Andiamo a raccogliere conchiglie in spiaggia domattina alle 7!"
  },
  Voice_5162_AwakerVoiceTitle = {
    Text = "Chat: A proposito dei \"Risvegliatori\""
  },
  Voice_5163_AwakerVoiceContent = {
    Text = "Ora ti concedo la vita eterna!"
  },
  Voice_5163_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5164_AwakerVoiceContent = {Text = "Hah!"},
  Voice_5164_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_5165_AwakerVoiceContent = {Text = "Hah!"},
  Voice_5165_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5166_AwakerVoiceContent = {
    Text = "Scusate, se vi sto causando qualche problema, me ne andrò subito!"
  },
  Voice_5166_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_5166_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_5167_AwakerVoiceContent = {
    Text = "Mi hai offerto un posto dove stare, e te ne sono grato. Ma perdonami, non merito più di calcare quel palcoscenico."
  },
  Voice_5167_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5168_AwakerVoiceContent = {
    Text = "Grazie per avermi permesso di restare qui. Se c'è un modo in cui posso ricambiare, per favore fatelo sapere ad Aigis. Gradite del tè?"
  },
  Voice_5168_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_5168_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_5169_AwakerVoiceContent = {
    Text = "È così caldo che non voglio andarmene. Quando sono sola, è davvero buio, freddo e spaventoso..."
  },
  Voice_5169_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_5169_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_5170_AwakerVoiceContent = {
    Text = "Aigis... Posso davvero tornare tra la folla? Non sono ancora pronta, ma voi mi avete già accettata... In tal caso, continuate a prendervi cura di me... Custode."
  },
  Voice_5170_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_5170_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_5171_AwakerVoiceContent = {
    Text = "Ah... Ricordo tutto! Io... sono rimasta intrappolata da quel lurido sangue umano e non sono riuscita a trasformarmi! Come è possibile? Dove sono le mie branchie? Perché non si muovono?! Perché!"
  },
  Voice_5171_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5172_AwakerVoiceContent = {
    Text = "Adoro il polpo alla griglia, il polpo bollito, il polpo fritto... Qualcuno dice che sto commettendo una blasfemia. Ah, chiedo scusa, ma il polpo è semplicemente troppo delizioso, ahahah!"
  },
  Voice_5172_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_5173_AwakerVoiceContent = {
    Text = "Vermi. Stelle. Io sono... Uvhash! Uccidere... lasciatemi Uccidere!"
  },
  Voice_5173_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_5173_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_5174_AwakerVoiceContent = {
    Text = "Corpo Cremisi, Tentacoli pulsanti, apparato boccale che si apre e chiude senza sosta... Magnifico! Non vedo l'ora di squarciare una gola!"
  },
  Voice_5174_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_5174_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_5175_AwakerVoiceContent = {
    Text = "Hahaha, questa sì che è la sensazione giusta! Dammene ancora... il doppio, no, dieci volte la dose!"
  },
  Voice_5175_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_5175_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_5176_AwakerVoiceContent = {
    Text = "Lo sopporterò."
  },
  Voice_5176_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5177_AwakerVoiceContent = {
    Text = "Questa strana sensazione... niente male. Meglio della belladonna di quel Mago levantino."
  },
  Voice_5177_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_5177_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_5178_AwakerVoiceContent = {
    Text = "Compagni? Hmph... Non ne ho bisogno. Non mi farò gravare dallo stesso fardello due volte."
  },
  Voice_5178_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_5178_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_5179_AwakerVoiceContent = {
    Text = "Devo ricordarti che la nostra cooperazione dipende interamente dal tuo Potere. Qualora il tuo Potere venisse meno, questo Contratto cesserà immediatamente, e ti reciderò il capo senza alcuna esitazione."
  },
  Voice_5179_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_5179_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_5180_AwakerVoiceContent = {
    Text = "Vedo la luce nei tuoi occhi. Quel desiderio, quell'ambizione... arde. Ammettilo, mortale! Siamo della stessa pasta."
  },
  Voice_5180_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_5180_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_5181_AwakerVoiceContent = {
    Text = "Conosci l'albatros? Affronta coraggiosamente le tempeste, ma una volta esiliato a terra, circondato dallo scherno, quelle ali enormi e cadenti diventano ironicamente un patetico impedimento. In ogni caso, questa storia non significa nulla... Mi è venuta in mente perché mi sento molto rilassato in tua compagnia — solo chiacchiere."
  },
  Voice_5181_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_5181_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_5182_AwakerVoiceContent = {
    Text = "Forse i tempi sono davvero cambiati. Al giorno d'oggi, persino i deboli possono superare gli scogli, comandare le onde e diventare i re del cielo. Mortale, attendo il giorno in cui riscriverai la storia. Sarà un onore diventare la potente lama nella tua mano!"
  },
  Voice_5182_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_5182_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_5183_AwakerVoiceContent = {
    Text = "Il tasso di conversione è di gran lunga troppo basso. Presentati nel mio ufficio domani per un addestramento correttivo."
  },
  Voice_5183_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_5184_AwakerVoiceContent = {
    Text = "Hai incontrato l'altra Doll? La cosiddetta \"verità del mondo\" può frantumare completamente una mente serena. Noi... tu e io diventeremo uguali?"
  },
  Voice_5184_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito di @2"
  },
  Voice_5184_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato@2"
  },
  Voice_5185_AwakerVoiceContent = {
    Text = "Padrone... Ho bisogno di ordini. Per favore, datemi degli ordini."
  },
  Voice_5185_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5186_AwakerVoiceContent = {
    Text = "Le prestazioni del mech sono state potenziate."
  },
  Voice_5186_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_5189_AwakerVoiceContent = {Text = "Ehehe!"},
  Voice_5189_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_5190_AwakerVoiceContent = {
    Text = "Più amici!"
  },
  Voice_5190_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5191_AwakerVoiceContent = {
    Text = "Più amici!"
  },
  Voice_5191_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_5192_AwakerVoiceContent = {
    Text = "Mi dispiace, non posso lasciare la Culla... Potrebbe bloccare la vista di Tutti, quindi resterò in fondo all'aula."
  },
  Voice_5192_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_5193_AwakerVoiceContent = {
    Text = "Cosa! Non sei riuscito a procurartene nemmeno uno?! Né il tappeto di Costantinopoli, né il Tè di Ceylon, né i Churros dell'Andalusia...? Ugh, quella Donna li ottiene sempre con tale facilità! Pensavo fossero comuni!"
  },
  Voice_5193_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_5194_AwakerVoiceContent = {
    Text = "Ancora una pallida ombra della mia vera possanza."
  },
  Voice_5194_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_5194_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_5195_AwakerVoiceContent = {
    Text = "Così impaziente. Sembra un po' rozzo per qualcuno del vostro calibro."
  },
  Voice_5195_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_5196_AwakerVoiceContent = {
    Text = "Questa bestia non è che un frammento della mia volontà. La sua forma potrà anche restare immutata, ma il mio potere non conosce confini."
  },
  Voice_5196_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_5196_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_5197_AwakerVoiceContent = {
    Text = "Ah, di nuovo nell'oceano caotico. Mi piace."
  },
  Voice_5197_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_5197_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_5198_AwakerVoiceContent = {
    Text = "Bene. Ti sei impegnato abbastanza. Suppongo che ti tollererò come compagno."
  },
  Voice_5198_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_5198_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_5199_AwakerVoiceContent = {
    Text = "Frantuma queste barriere di potere, proprio come io sfonderei il muro di un labirinto!"
  },
  Voice_5199_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_5199_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_5200_AwakerVoiceContent = {
    Text = "Non strappare il cibo, non distruggere le sedie della mensa... Va bene. Lily non lo farà più."
  },
  Voice_5200_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_5200_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_5201_AwakerVoiceContent = {
    Text = "Posso chiamarti Mamma?"
  },
  Voice_5201_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_5201_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_5202_AwakerVoiceContent = {
    Text = "Qualche ordine per me, Padrone?\n\"Non uscire con le pustole. La gente si spaventerà,\" dici?\nCapito. Lily le nasconderà subito."
  },
  Voice_5202_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_5202_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_5203_AwakerVoiceContent = {
    Text = "Quindi, è così che ci si sente a diventare un Risvegliato."
  },
  Voice_5203_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_5203_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_5204_AwakerVoiceContent = {
    Text = "Mamma, posso dormire accanto a te? Quando sono sola, faccio sogni bui e spaventosi. Le mani e i piedi mi cadono... Fa tanto, tanto male..."
  },
  Voice_5204_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_5204_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_5205_AwakerVoiceContent = {
    Text = "Ah! Grazie per la vostra gentilezza, Karen non è che un'umile ancella..."
  },
  Voice_5205_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_5205_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_5206_AwakerVoiceContent = {Text = "Hehe..."},
  Voice_5206_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_5207_AwakerVoiceContent = {
    Text = "Ho bisogno di raccogliere dei materiali per la scultura, preferibilmente freschi."
  },
  Voice_5207_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_5208_AwakerVoiceContent = {
    Text = "Per favore, fa' silenzio."
  },
  Voice_5208_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_5209_AwakerVoiceContent = {
    Text = "Coloro che restano ostinati nella loro follia compiono gesta futili."
  },
  Voice_5209_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_5209_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_5210_AwakerVoiceContent = {
    Text = "Molto bene. A questo punto, riesco in qualche modo a comprendere il tuo scopo. Procedi."
  },
  Voice_5210_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_5210_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_5211_AwakerVoiceContent = {
    Text = "Vedo la tua determinazione. Prima di tornare nel vuoto, Questa Entità sarà testimone dell'erede dell'umanità che sfida il fato. Ma ora... è necessario riposare."
  },
  Voice_5211_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_5211_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_5212_AwakerVoiceContent = {
    Text = "Non è forse cosa buona seguire il volere del cielo? Perché resistere al volere del fato?"
  },
  Voice_5212_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_5212_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_5213_AwakerVoiceContent = {
    Text = "Per esaudire il tuo desiderio, sei disposto a sacrificare così tanto..."
  },
  Voice_5213_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_5213_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_5214_AwakerVoiceContent = {
    Text = "Ugh, non è irritante? Smettila di assillarmi con questa storia! ...Va bene, fa' come ti pare. È solo un modo per ammazzare il tempo, dopotutto."
  },
  Voice_5214_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5215_AwakerVoiceContent = {
    Text = "Dissoluzione... Quelle vili maree nere invadono i miei sogni. Insopportabile."
  },
  Voice_5215_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_5216_AwakerVoiceContent = {
    Text = "Il potere è un'arma a doppio taglio. Come potrei non comprenderlo? L'ho capito fin troppo tardi. Nel momento in cui mollo la presa, mi faranno a pezzi... Se solo fossi stata lucida come te fin dall'inizio, non avrei fatto una fine così tragica. Eh? Dici che d'ora in poi potrò tenere i miei salotti nella sala del preside?! Questo è... Come potrei ripagarti se non servendoti personalmente...?"
  },
  Voice_5216_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_5216_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_5217_AwakerVoiceContent = {
    Text = "Siete un ospite piuttosto irremovibile. Cosa devo fare per farvi rinunciare al privilegio che avete tra le mani? Il potere attira solo guai—una verità così semplice, sicuramente la comprendete?"
  },
  Voice_5217_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_5217_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_5218_AwakerVoiceContent = {
    Text = "Prima che il salon abbia inizio, vorreste ascoltare una storia? Il racconto di come una bambina di villaggio conquistò la corona del potere... Da dove dovremmo cominciare? Da quando i suoi genitori la costrinsero a sposare un uomo anziano, o forse dalla parte in cui sboccia nel giardino nobile?"
  },
  Voice_5218_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_5218_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_5219_AwakerVoiceContent = {
    Text = "In passato, gli ospiti mi chiamavano \"Dama in Rosso\". Naturalmente, potete anche chiamarmi \"Sorel\"—dopotutto, siete il mio ospite più speciale..."
  },
  Voice_5219_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_5219_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_5220_AwakerVoiceContent = {
    Text = "Come padrona di casa, è mio dovere assicurarmi che ogni ospite sia soddisfatto."
  },
  Voice_5220_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_5220_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_5221_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5221_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_5222_AwakerVoiceContent = {
    Text = "Mio signore? C'è qualcosa che non va nella mia postura?"
  },
  Voice_5222_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_5223_AwakerVoiceContent = {Text = "Oops!"},
  Voice_5223_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_5224_AwakerVoiceContent = {
    Text = "Ah, che sfortuna~"
  },
  Voice_5224_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_5225_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5225_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_5226_AwakerVoiceContent = {
    Text = "Ricordo questa sensazione... quel momento glorioso sta arrivando..."
  },
  Voice_5226_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_5226_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_5227_AwakerVoiceContent = {
    Text = "Non mi sono ancora cresciute le branchie, ma non provo più ansia per questo. Custode, sarò il tuo Scudo del Personaggio, e ti proteggerò con le mie pinne."
  },
  Voice_5227_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_5227_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_5228_AwakerVoiceContent = {
    Text = "Hai investito così tanto su di me... sei davvero più Paziente degli altri umani. Tu davvero... non mi disprezzi?"
  },
  Voice_5228_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_5228_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_5229_AwakerVoiceContent = {
    Text = "Perché? Perché non mi sono cresciute le branchie dopo il Rito? La trasformazione è fallita di nuovo?! Maledizione! Maledizione! Maledizione!"
  },
  Voice_5229_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_5229_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_5230_AwakerVoiceContent = {
    Text = "Quella Voce mi chiama di nuovo... quel suono etereo dal profondo Abisso!"
  },
  Voice_5230_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_5230_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_5231_AwakerVoiceContent = {
    Text = "Sbagliato! Non è qui!"
  },
  Voice_5231_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_5232_AwakerVoiceContent = {
    Text = "Sanga, la Scultrice di Cité, ti offre il suo scalpello. Potrai essere difettosa, ma meriti comunque di essere scolpita."
  },
  Voice_5232_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5238_AwakerVoiceContent = {
    Text = "Venite qui, bambini disobbedienti~"
  },
  Voice_5238_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_5239_AwakerVoiceContent = {
    Text = "La Vera Arte non ha bisogno di spiegazioni."
  },
  Voice_5239_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_5240_AwakerVoiceContent = {
    Text = "La Vera Arte non ha bisogno di spiegazioni."
  },
  Voice_5240_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_5241_AwakerVoiceContent = {
    Text = "Come posso aiutarti?"
  },
  Voice_5241_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5242_AwakerVoiceContent = {
    Text = "Suonate il corno!"
  },
  Voice_5242_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_5243_AwakerVoiceContent = {
    Text = "A qualunque costo!"
  },
  Voice_5243_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5244_AwakerVoiceContent = {
    Text = "La sensazione di essere di nuovo bagnata dalla luce del sole... Non sapevo che fosse così piacevole, così calda. Mi fa venire le lacrime agli occhi."
  },
  Voice_5244_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_5244_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_5245_AwakerVoiceContent = {
    Text = "Per esprimere la mia gratitudine... costruirò un altare nascosto per te, nelle profondità della mia angoscia."
  },
  Voice_5245_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_5245_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_5246_AwakerVoiceContent = {
    Text = "La carne del mio caro fratello e la mia si stanno fondendo sempre più perfettamente..."
  },
  Voice_5246_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_5246_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_5247_AwakerVoiceContent = {
    Text = "Sono più resistente di quanto pensiate. Siate più decisi quando mi utilizzate. Vi prego, non trattenetevi."
  },
  Voice_5247_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_5247_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_5248_AwakerVoiceContent = {
    Text = "È solo una mia impressione? Oppure... la mia brama di Sangue si è in qualche modo attenuata?"
  },
  Voice_5248_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_5248_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_5249_AwakerVoiceContent = {
    Text = "Attendevo il tuo arrivo ancor prima che fossi ufficialmente ammesso. Sembra che lavoriamo piuttosto bene insieme, eh? Partner."
  },
  Voice_5249_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_5250_AwakerVoiceContent = {
    Text = "Che vergogna."
  },
  Voice_5250_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_5251_AwakerVoiceContent = {Text = "Aah!"},
  Voice_5251_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_5252_AwakerVoiceContent = {Text = "Hahaha!"},
  Voice_5252_AwakerVoiceTitle = {
    Text = "Colpo: Mania"
  },
  Voice_5253_AwakerVoiceContent = {Text = "Hmm..."},
  Voice_5253_AwakerVoiceTitle = {
    Text = "Colpo: Depressione"
  },
  Voice_5254_AwakerVoiceContent = {
    Text = "Fammi del male quanto vuoi!"
  },
  Voice_5254_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5255_AwakerVoiceContent = {
    Text = "Ho davvero paura. No, non ho paura di voi, ma... temo di potervi portare ancora terrore e pianto."
  },
  Voice_5255_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_5256_AwakerVoiceContent = {
    Text = "I libri di fiabe di quest'epoca sono molto più divertenti di quelli che leggevo un tempo! Oh, oh! Mio signore, vi prego, non fraintendetemi! Sono troppo grande ormai per le storie della buonanotte!"
  },
  Voice_5256_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_5257_AwakerVoiceContent = {
    Text = "Fammi del male quanto vuoi!"
  },
  Voice_5257_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_5258_AwakerVoiceContent = {
    Text = "Uff... Ti ho causato qualche problema?"
  },
  Voice_5258_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_5259_AwakerVoiceContent = {
    Text = "Hai sempre mantenuto quella tua buffa fiducia, restando al mio fianco... E sia, forse sfruttarti non è una cattiva idea. Ma ricorda questo: non posso tollerare alcun tradimento, specialmente da parte tua."
  },
  Voice_5259_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_5259_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_5260_AwakerVoiceContent = {
    Text = "Il mio unico rimpianto è non aver infilzato i loro cadaveri su pali e appesi alle mura! Non risparmierò nessuno di coloro che mi hanno tradito, calpestato o insultato!"
  },
  Voice_5260_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_5260_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_5261_AwakerVoiceContent = {
    Text = "Sì, mi sono prostrato davanti a quella gente; è innegabile. Hanno approfittato della mia ignoranza, e gliel'ho fatta pagare."
  },
  Voice_5261_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_5261_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_5262_AwakerVoiceContent = {
    Text = "Credi che qualche parola melliflua e qualche giorno di falsa gentilezza bastino a farmi indossare di nuovo le catene di mia volontà e diventare il tuo trastullo?"
  },
  Voice_5262_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_5262_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_5263_AwakerVoiceContent = {
    Text = "Tutti coloro che hanno tentato di controllarmi o usarmi sono finiti negli inferi per mia mano — non mi dispiacerebbe spedirci anche te."
  },
  Voice_5263_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_5263_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_5264_AwakerVoiceContent = {
    Text = "Ah... Scusa, p-per favore non muoverti!"
  },
  Voice_5264_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_5265_AwakerVoiceContent = {
    Text = "Togliti di dosso!"
  },
  Voice_5265_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_5266_AwakerVoiceContent = {Text = "Insolenza!"},
  Voice_5266_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_5267_AwakerVoiceContent = {
    Text = "Arrenditi... Benvenuto in un reame di squisito piacere e sogni."
  },
  Voice_5267_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_5268_AwakerVoiceContent = {
    Text = "Questa è la città dove innumerevoli anime perdute vagano, per sempre incapaci di ritrovare la via di casa."
  },
  Voice_5268_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_5269_AwakerVoiceContent = {
    Text = "Io... Posso farcela!"
  },
  Voice_5269_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_5270_AwakerVoiceContent = {
    Text = "Ehm... Non riesco a controllare la mia Abilità di Assorbire la forza vitale, quindi per favore non mettere la Mano nella Culla, o ti ammalerai."
  },
  Voice_5270_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_5271_AwakerVoiceContent = {
    Text = "Spero sinceramente che non abbia malfunzionamenti durante la nostra conversazione. La mia adorabile quanto esasperante assistente... non ci sono più laboratori di riserva che possa inavvertitamente far detonare."
  },
  Voice_5271_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Erica"
  },
  Voice_5271_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Erica\""
  },
  Voice_5272_AwakerVoiceContent = {
    Text = "Le braccia, quelle maledette braccia! Si aggrappano sempre ai miei capelli. Non riesco nemmeno a controllare le mie mani — che Donna inutile che sono... Forse dovrei..."
  },
  Voice_5272_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito di Helot"
  },
  Voice_5274_AwakerVoiceContent = {
    Text = "Grazie per la tua guida. Finalmente comprendo la scelta di Faint. Davo tutto per scontato, senza rendermi conto del peso che gravava sulla sua mente. D'ora in poi, cercherò di vivere per me stessa."
  },
  Voice_5274_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_5274_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_5275_AwakerVoiceContent = {
    Text = "Attraverso i lunghi, interminabili tempi, Faint e io avevamo solo l'uno l'altra. Ma ora, ho una nuova persona importante nella mia vita. Custode, ti prego, permettimi di ritrattare ciò che avevo detto prima. Tu sei diverso. Vedi oltre le mie canzoni e il mio aspetto; vedi davvero me. È per questo che proteggerò anche te. Non distoglierò mai lo sguardo da te."
  },
  Voice_5275_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_5275_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_5276_AwakerVoiceContent = {
    Text = "Le mie stelle dormienti ora si destano dal sogno — che convergano verso il fato loro assegnato. Volgi il tuo cammino verso il Reame Divino!"
  },
  Voice_5276_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_5277_AwakerVoiceContent = {
    Text = "Perché indosso sempre questo abito? Così posso cantare per te in qualsiasi momento."
  },
  Voice_5277_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_5277_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_5278_AwakerVoiceContent = {
    Text = "Cosa voglio fare per me stessa? Scusa, non capisco cosa intendi. In realtà, Faint mi ha posto questa domanda molte volte, ma tutto ciò che desidero è che lei guarisca presto."
  },
  Voice_5278_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_5278_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_5279_AwakerVoiceContent = {
    Text = "Durante il nostro tempo sul pianeta desolato, la compassione di quelle figure influenti fornì a me e a mia sorella le risorse per sopravvivere. Alla fine, mi diedero anche la possibilità di fuggire dal pianeta, sebbene fosse limitata a una sola persona. Sono tutti miei benefattori, proprio come voi, Custode, che mi avete dato un posto dove stare."
  },
  Voice_5279_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_5279_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_5280_AwakerVoiceContent = {
    Text = "Voi siete la persona gentile che mi offre un posto dove stare. Farò come dite. Se solo potessi essere un po' più utile..."
  },
  Voice_5280_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_5281_AwakerVoiceContent = {
    Text = "Non dimenticare di riservare il luogo. Non dirmi che è ancora più piccolo di quello a Elworth?"
  },
  Voice_5281_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_5281_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_5282_AwakerVoiceContent = {
    Text = "Fantastico! Ora sono ancora più motivata! Posso pulire venti stanze al giorno!"
  },
  Voice_5282_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_5282_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_5283_AwakerVoiceContent = {
    Text = "Questa è la musica antica quanto le acque del lago, che appartiene a \"noi\". Padrone, danziamo insieme! Danzeremo e canteremo, prima che la mia voce venga presa da \"Lui\"..."
  },
  Voice_5283_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_5283_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_5284_AwakerVoiceContent = {
    Text = "Padrone! La mia voce... si sta affievolendo... Aiuto..."
  },
  Voice_5284_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_5284_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_5285_AwakerVoiceContent = {
    Text = "La mia vista è migliorata... Padrone, vi siete dimenticato di pettinarvi i capelli di nuovo?!"
  },
  Voice_5285_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_5285_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_5286_AwakerVoiceContent = {
    Text = "Forse sono diventata più forte, ma non desidero affatto vendetta. Voglio solo cantare! Danzare! Far festa!"
  },
  Voice_5286_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_5286_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_5287_AwakerVoiceContent = {
    Text = "Per sopravvivere all'Annientamento, ho condiviso il mio Spirito e il mio Sangue con troppi. Il mio Potere, ora, non è che lo spettro di ciò che era quando abbracciai per la prima volta questa Volontà Suprema..."
  },
  Voice_5287_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul passato"
  },
  Voice_5288_AwakerVoiceContent = {
    Text = "Non aspettarti di trovarmi nell'edificio didattico. Puzza di vecchi studiosi ammuffiti; non sopporto quel posto."
  },
  Voice_5288_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_5289_AwakerVoiceContent = {
    Text = "Non fuggire."
  },
  Voice_5289_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_5290_AwakerVoiceContent = {
    Text = "La mia terra natale venera il nostro Dio. Di conseguenza, il Re che seguo è naturalmente un \"Comunicatore divino.\""
  },
  Voice_5290_AwakerVoiceTitle = {
    Text = "Chat: A proposito del Regno Eterno"
  },
  Voice_5291_AwakerVoiceContent = {
    Text = "Avete una notevole raccolta di talenti qui, degna di un gran salon... State tranquilli, l'invito vi sarà recapitato dalla mia servitrice."
  },
  Voice_5291_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_5292_AwakerVoiceContent = {Text = "Avanti!"},
  Voice_5292_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5293_AwakerVoiceContent = {
    Text = "Se solo ci fossero più amici..."
  },
  Voice_5293_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_5294_AwakerVoiceContent = {
    Text = "Io non sono come lei. Lei sa solo darti brividi e terrore. Ma io? Io ti darò un amore sacro e bruciante."
  },
  Voice_5294_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Wanda"
  },
  Voice_5294_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Wanda\""
  },
  Voice_5295_AwakerVoiceContent = {
    Text = "Non osare pensare che sia finita! Ti farò pagare ogni singola goccia di questa umiliazione!"
  },
  Voice_5295_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_5296_AwakerVoiceContent = {
    Text = "Le tue mani sono calde, come la tua anima. Io... apprezzo il tuo tocco, Fiamma Pallida."
  },
  Voice_5296_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_5297_AwakerVoiceContent = {
    Text = "Che c'è di male a giocare a bridge in classe? C'è un tavolo, le persone sono qui e ho portato le carte! Questo significa che si gioca!"
  },
  Voice_5297_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_5299_AwakerVoiceContent = {Text = "Non..."},
  Voice_5299_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_5300_AwakerVoiceContent = {
    Text = "Fissa l'Abisso!"
  },
  Voice_5300_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_5301_AwakerVoiceContent = {
    Text = "Fissa l'Abisso!"
  },
  Voice_5301_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_5302_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_5302_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_5303_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_5303_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_5304_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_5304_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_5305_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_5305_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_5306_AwakerVoiceContent = {
    Text = "Immergiti nella Sua luce divina!"
  },
  Voice_5306_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_5307_AwakerVoiceContent = {Text = "Ehi!"},
  Voice_5307_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_5308_AwakerVoiceContent = {
    Text = "Un raduno di anime deboli... Che possiamo fare di buono, se non produrre rumore? Sigh..."
  },
  Voice_5308_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_5311_AwakerVoiceContent = {
    Text = "La guerra porta sempre Pain, e sopportare la sofferenza è il dovere di un guerriero. Anche se dovessi perdere le mani, i piedi e tutto il resto, continuerò a combattere per te e per la Giustizia."
  },
  Voice_5311_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_5312_AwakerVoiceContent = {
    Text = "È questo il Tributo che Gli offrite?"
  },
  Voice_5312_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_5313_AwakerVoiceContent = {
    Text = "Credi davvero che questo basti a cambiare il futuro?"
  },
  Voice_5313_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_5314_AwakerVoiceContent = {
    Text = "Lui ora è... nel mio grembo..."
  },
  Voice_5314_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_5315_AwakerVoiceContent = {
    Text = "Heh. Sei leggermente più intelligente di quanto pensassi."
  },
  Voice_5315_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_5316_AwakerVoiceContent = {
    Text = "In quanto mio Schiavo, rendere Tributo al tuo padrone è cosa del tutto naturale."
  },
  Voice_5316_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_5317_AwakerVoiceContent = {
    Text = "Sei piuttosto divertente quando cerchi di compiacermi."
  },
  Voice_5317_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_5318_AwakerVoiceContent = {
    Text = "Brownie, budino al caramello, Sachertorte, mousse al cioccolato, biscotti... Devono essere serviti su ogni singolo tavolo!"
  },
  Voice_5318_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_5318_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_5319_AwakerVoiceContent = {
    Text = "Controlla il mio vestito, presto! Niente pieghe, niente di allentato... Cosa? C'è un problema?"
  },
  Voice_5319_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_5319_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_5320_AwakerVoiceContent = {
    Text = "Benvenuti alla mia ultima Cerimonia di Illuminazione! Tutto questo è stato meticolosamente progettato da me. Certo, tu hai contribuito... un pochino."
  },
  Voice_5320_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_5320_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_5321_AwakerVoiceContent = {
    Text = "I tavoli e le sedie devono avere pizzi di mio gradimento, e le piante in vaso devono essere gigli ragno rossi... Ora, sbrigati a preparare tutto!"
  },
  Voice_5321_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_5321_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_5322_AwakerVoiceContent = {
    Text = "Va' a invitare gli ospiti! Anche un compito così semplice è troppo per te?"
  },
  Voice_5322_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_5322_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_5323_AwakerVoiceContent = {
    Text = "Nessuna via di fuga!"
  },
  Voice_5323_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5324_AwakerVoiceContent = {
    Text = "Nessuna via di fuga!"
  },
  Voice_5324_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_5325_AwakerVoiceContent = {
    Text = "Farò del mio meglio per essere all'altezza delle vostre speranze, mio signore!"
  },
  Voice_5325_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_5325_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_5326_AwakerVoiceContent = {
    Text = "Quella Donna mi piace parecchio. Abbiamo un... un... giusto, un linguaggio comune!"
  },
  Voice_5326_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Wanda"
  },
  Voice_5326_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Wanda\""
  },
  Voice_5327_AwakerVoiceContent = {Text = "Insolente!"},
  Voice_5327_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_5328_AwakerVoiceContent = {Text = "Insolente!"},
  Voice_5328_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_5329_AwakerVoiceContent = {
    Text = "Riduciti in macerie."
  },
  Voice_5329_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_5330_AwakerVoiceContent = {Text = "Frantuma."},
  Voice_5330_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5331_AwakerVoiceContent = {
    Text = "Scava attraverso la Barriera della realtà!"
  },
  Voice_5331_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5332_AwakerVoiceContent = {
    Text = "Hai intenzione di salpare presto? Potresti esaudire la mia umile richiesta e lasciarmi unire a te? Lasciami solo raggiungere il mare..."
  },
  Voice_5332_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_5332_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_5333_AwakerVoiceContent = {
    Text = "Se ancora ti fidi di me, ti prego, permettimi di essere la luce guida in questo viaggio. Tuttavia, anche in un compito così semplice, ho già fallito in passato..."
  },
  Voice_5333_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_5333_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_5334_AwakerVoiceContent = {
    Text = "Ti piacerebbe prendere il largo con me? Lascia che controlli la mappa attuale... 47°9' S, 126°43' O, andremo proprio lì."
  },
  Voice_5334_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_5334_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_5335_AwakerVoiceContent = {
    Text = "In passato ho causato molti disastri, arrivando persino quasi a portare la distruzione a certe civiltà... Se dicessi che non era intenzionale, sarebbe ormai troppo tardi?"
  },
  Voice_5335_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_5335_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_5336_AwakerVoiceContent = {
    Text = [[
Sono il guardiano dell'ingresso al Regno Eterno, guido coloro che tornano a casa. Che ironia che io, con un tale compito, abbia dimenticato la via del ritorno...
Vorresti... essere il mio faro?]]
  },
  Voice_5336_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_5336_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_5337_AwakerVoiceContent = {
    Text = "Volgi lo Sguardo all'ammasso stellare."
  },
  Voice_5337_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_5338_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5338_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_5339_AwakerVoiceContent = {
    Text = "La fitta Nebbia discende."
  },
  Voice_5339_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_5340_AwakerVoiceContent = {Text = "Hmph."},
  Voice_5340_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_5341_AwakerVoiceContent = {
    Text = "Benedire la navigazione per la maggior parte delle persone non fa alcuna differenza per me... tranne che per quella donna. Se possibile, vi prego di assegnarmi un'altra rotta."
  },
  Voice_5341_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Miryam"
  },
  Voice_5341_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risveglio \"Miryam\""
  },
  Voice_5342_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5342_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_5343_AwakerVoiceContent = {Text = "Come vuoi."},
  Voice_5343_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_5344_AwakerVoiceContent = {
    Text = "Giù le mani da me."
  },
  Voice_5344_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_5345_AwakerVoiceContent = {
    Text = "Prima che io faccia Ritorno al nostro palazzo in fondo al mare, presterò a te, un semplice umano, parte del Potere di Aequor, ma solo per questa volta."
  },
  Voice_5345_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_5346_AwakerVoiceContent = {Text = "Vai!"},
  Voice_5346_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5347_AwakerVoiceContent = {
    Text = "Cosa amo? Amo la squisita verità del dolore. Il bel rossore ardente della carne tumefatta... il modo in cui un gemito non sa distinguere il piacere dall'agonia. È l'unico desiderio onesto che abbiamo, non credi?"
  },
  Voice_5347_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_5348_AwakerVoiceContent = {
    Text = "Forza! Unisciti ad Aurita!"
  },
  Voice_5348_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_5349_AwakerVoiceContent = {
    Text = "Forza! Unisciti ad Aurita!"
  },
  Voice_5349_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5350_AwakerVoiceContent = {
    Text = "Mi guarda sempre con rabbia. Ma per qualche ragione, sembra... familiare. Sicura. Forse perché ricorda la mamma?"
  },
  Voice_5350_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito di Helot"
  },
  Voice_5350_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Helot\""
  },
  Voice_5351_AwakerVoiceContent = {
    Text = "La mia mente è più affilata; niente male davvero."
  },
  Voice_5351_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_5351_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_5352_AwakerVoiceContent = {
    Text = "Preferisco di gran lunga il lavoro in laboratorio alle missioni sul campo — credevi davvero che quegli strumenti di assistenza si materializzassero dal mare?"
  },
  Voice_5352_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_5352_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_5353_AwakerVoiceContent = {
    Text = "Che siano viti o chiodi, più ce ne sono, meglio è!"
  },
  Voice_5353_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_5354_AwakerVoiceContent = {
    Text = "Questo corpo riesce a malapena a contenere questo Potere, ma non è ancora il momento di cambiare burattino. Perché te ne stai lì impalato? Assistimi con questa gamba; sono necessarie delle regolazioni."
  },
  Voice_5354_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_5354_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_5355_AwakerVoiceContent = {
    Text = "Il fardello della Luce Guida può sopraffare anche il più puro dei santi. Se ti senti stanca, mia Fiamma Pallida, ti prego, confidati con me. Farò tutto ciò che è in mio potere per alleviare il tuo fardello e condividere il peso di queste innumerevoli benedizioni."
  },
  Voice_5355_AwakerVoiceTitle = {
    Text = "Chat: A proposito della Fatica"
  },
  Voice_5356_AwakerVoiceContent = {
    Text = "La vostra fiducia è la ragione per cui esisto come cavaliere."
  },
  Voice_5356_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_5356_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_5357_AwakerVoiceContent = {
    Text = "Immerso in un tale sacro fulgore... È questo il potere divino che Egli detiene? Così sconfinato... così sublime..."
  },
  Voice_5357_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_5357_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_5358_AwakerVoiceContent = {
    Text = "Il varco verso il Suo Reame è quasi a Portata."
  },
  Voice_5358_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_5358_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_5359_AwakerVoiceContent = {
    Text = "Più luminoso... e più chiaro..."
  },
  Voice_5359_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_5359_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_5360_AwakerVoiceContent = {
    Text = "Sono stato interamente restaurato come Risvegliato... Ora il coro del Reame Divino risuona dentro di me..."
  },
  Voice_5360_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_5360_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_5361_AwakerVoiceContent = {
    Text = "Possa Egli guidarmi nel Suo santuario, dove la Sua serenità ricopre i miei sogni..."
  },
  Voice_5361_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_5361_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_5362_AwakerVoiceContent = {
    Text = "Non preoccupatevi, siamo tutte piuttosto utili. Io so cucire e pulire, un'altra me eccelle nel combattimento, e le altre..."
  },
  Voice_5362_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_5363_AwakerVoiceContent = {
    Text = "Detesto le cose luminose e delicate. La gentilezza è come un riflesso, che rivela tutta la mia bruttezza, la mia bramosia e la mia fragilità."
  },
  Voice_5363_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_5364_AwakerVoiceContent = {
    Text = "Vuoi accarezzare Brown? Non sta a me decidere. Dovrai chiederlo a lei."
  },
  Voice_5364_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_5365_AwakerVoiceContent = {
    Text = "Vuoi compiacermi? Allora inginocchiati, offri il collo e taci finché non avrò finito di prosciugarti."
  },
  Voice_5365_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_5366_AwakerVoiceContent = {Text = "Hah!"},
  Voice_5366_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5367_AwakerVoiceContent = {
    Text = "Ieri ho sognato il giorno in cui ho ricominciato a vagare tra le stelle."
  },
  Voice_5367_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_5367_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_5368_AwakerVoiceContent = {
    Text = "In cosa posso aiutarti...?"
  },
  Voice_5368_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_5368_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_5369_AwakerVoiceContent = {Text = "Lo sento~"},
  Voice_5369_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_5370_AwakerVoiceContent = {Text = "Hah!"},
  Voice_5370_AwakerVoiceTitle = {
    Text = "Abilità: III"
  },
  Voice_5371_AwakerVoiceContent = {Text = "Attento!"},
  Voice_5371_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_5372_AwakerVoiceContent = {Text = "Indietro."},
  Voice_5372_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_5373_AwakerVoiceContent = {
    Text = "Un mondo... dove nessuno sarà ferito... verrà."
  },
  Voice_5373_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_5374_AwakerVoiceContent = {Text = "(Gemiti)"},
  Voice_5374_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_5375_AwakerVoiceContent = {
    Text = "Vi prego, permettetemi di collocare un altare a Sua immagine in questo luogo. È una Statua plasmata da mani devote e non porta alcuna Maledizione."
  },
  Voice_5375_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_5376_AwakerVoiceContent = {
    Text = "Forse, solo un pochino..."
  },
  Voice_5376_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5377_AwakerVoiceContent = {
    Text = "La mia chiave inglese non è ancora in posizione!"
  },
  Voice_5377_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_5378_AwakerVoiceContent = {
    Text = "Chimica, Fisica, Applicazioni del Nucleo d'Argento... In quest'epoca non è più necessario apprendere le Sette Arti Cavalleresche? Comprendo. In tal caso, vi prego di predisporre le lezioni appropriate per me, mio signore!"
  },
  Voice_5378_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_5379_AwakerVoiceContent = {
    Text = "Ho viaggiato! Non sono stata trascinata via dalle onde, mi sono seduta davvero in una carovana!"
  },
  Voice_5379_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_5379_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_5380_AwakerVoiceContent = {
    Text = "Meduse faro, meduse Corona, meduse fiore di pesco—si muovono tutte in gruppo. Naturalmente, anche Aurita! Voglio stare con Tutti!"
  },
  Voice_5380_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_5380_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_5381_AwakerVoiceContent = {
    Text = "Cose passate? Difficile ricordare... Ma ricordo di aver lavorato in un acquario! Mi pagavano 2 Pensh al giorno!"
  },
  Voice_5381_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_5381_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_5382_AwakerVoiceContent = {
    Text = "Ti dico un Segreto: in realtà vengo da Atlan...tide... ehm, in pratica, sono una persona di mare! Basta che mi comporti bene, mangi le verdure e faccia più amici, e quel posto di Atlan-come-si-chiama mi accoglierà!"
  },
  Voice_5382_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_5382_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_5383_AwakerVoiceContent = {
    Text = "La mia Casa, i miei amici dell'acquario, le mie meduse preferite—sono tutti spariti... Sparirai anche tu? Non puoi restare con me per sempre?"
  },
  Voice_5383_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_5383_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_5384_AwakerVoiceContent = {
    Text = "Abbiamo vinto? Questo è... bene."
  },
  Voice_5384_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_5387_AwakerVoiceContent = {
    Text = "Per la pace!"
  },
  Voice_5387_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5388_AwakerVoiceContent = {
    Text = "Per la Giustizia!"
  },
  Voice_5388_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_5389_AwakerVoiceContent = {
    Text = "Sì... So che sei dentro di me!"
  },
  Voice_5389_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_5390_AwakerVoiceContent = {
    Text = "Umani, falsi dèi, Risvegliati, persino la Dissoluzione... Tutto servirà da fondamento per la mia ricostruzione del Reame Divino."
  },
  Voice_5390_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_5391_AwakerVoiceContent = {
    Text = "Risveglio, risveglio! So che sei dentro di me!"
  },
  Voice_5391_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_5392_AwakerVoiceContent = {
    Text = "Uvhash... Mi ricorda mio fratello, riportando alla mente memorie di giorni bui, freddi e insonni."
  },
  Voice_5392_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Uvhash"
  },
  Voice_5392_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Uvhash\""
  },
  Voice_5393_AwakerVoiceContent = {
    Text = "Il nostro rapporto è come quello di Sherlock e Watson, no? Hai letto le ultime riviste?"
  },
  Voice_5393_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_5394_AwakerVoiceContent = {
    Text = "Inchinati alla bellezza."
  },
  Voice_5394_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5395_AwakerVoiceContent = {
    Text = "Inchinati alla bellezza."
  },
  Voice_5395_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_5396_AwakerVoiceContent = {
    Text = "Avversione, un verbo descrittivo, che significa sviluppare antipatia per qualcosa. Detestare, un verbo, si riferisce al sentimento di avversione quando qualcosa è sgradito ed evitato. Odio, un sostantivo, il sentimento di antipatia, <Del:Odio essere sottomesso alla Soppressione! Lasciatemi Distruggere distrugggere DISTRUGGERE> —Mi scusi, ma temo di non comprendere cosa sia l'\"odio\"."
  },
  Voice_5396_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_5397_AwakerVoiceContent = {
    Text = "In fondo, io sono solo..."
  },
  Voice_5397_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_5398_AwakerVoiceContent = {
    Text = "...sempre più lontana da ciò che ero."
  },
  Voice_5398_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_5399_AwakerVoiceContent = {
    Text = "Ricorda il mio nome, Golia. Questo nome è destinato a calpestare l'insignificante Storia dell'Umanità."
  },
  Voice_5399_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5400_AwakerVoiceContent = {
    Text = "Per favore, non preoccuparti."
  },
  Voice_5400_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_5401_AwakerVoiceContent = {
    Text = "Spero che non sprecherete il vostro potenziale e le aspettative dell'umanità, nuovo Custode."
  },
  Voice_5401_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_5402_AwakerVoiceContent = {
    Text = "Sovraccarico."
  },
  Voice_5402_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5403_AwakerVoiceContent = {
    Text = "Sovralimentazione."
  },
  Voice_5403_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_5404_AwakerVoiceContent = {
    Text = "Hmm? Vuoi sapere di quella foto nel mio Portafoglio? Ah, quello è il vecchio me. Questo aspetto attuale è stato un... Dono, dal mio compagno di scommesse e Rivale."
  },
  Voice_5404_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_5404_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_5405_AwakerVoiceContent = {
    Text = "Perfetto—ti va una scommessa? Se vinci, ti svelerò un segreto.\nMa attento, Alva potrebbe beccarti~"
  },
  Voice_5405_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_5405_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_5406_AwakerVoiceContent = {
    Text = "Ti piace questo pelo? Vuoi toccarlo? Tranquillo, non mi dà fastidio!"
  },
  Voice_5406_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_5406_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_5407_AwakerVoiceContent = {
    Text = "Certo che ci sono dei vantaggi. Ho incontrato il mio Watson, no? In confronto a quello, morire e cambiare aspetto contano ben poco."
  },
  Voice_5407_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_5407_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_5408_AwakerVoiceContent = {
    Text = "Se mi pento mai? Neanche per sogno. La Vita sarebbe troppo noiosa se tutto filasse liscio, non credi?"
  },
  Voice_5408_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_5408_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_5409_AwakerVoiceContent = {
    Text = "Ai miei tempi, le scuole erano luoghi per addestrare guerrieri. A quanto pare, lo sono ancora."
  },
  Voice_5409_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_5410_AwakerVoiceContent = {
    Text = "Mason... No, va bene così. Almeno siamo di nuovo insieme, \"24\"."
  },
  Voice_5410_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su \"24\""
  },
  Voice_5410_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"24\""
  },
  Voice_5411_AwakerVoiceContent = {
    Text = "Niente male, eh? Ora, il mio compenso. — Cosa? Pensavi che fosse gratis?!"
  },
  Voice_5411_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_5412_AwakerVoiceContent = {
    Text = "Vengo da Cité. Là tutti vogliono essere attori; nessuno si accontenta di restare a guardare. In realtà, non siamo che le misere note a piè di pagina della città."
  },
  Voice_5412_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul passato"
  },
  Voice_5413_AwakerVoiceContent = {
    Text = "Hai visto quelle antiche incisioni nella pietra? Fuse con le montagne, resistenti attraverso il tempo, che meravigliose reliquie... eppure non durano ancora abbastanza a lungo..."
  },
  Voice_5413_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_5414_AwakerVoiceContent = {
    Text = "I piccioni non sono tornati..."
  },
  Voice_5414_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_5415_AwakerVoiceContent = {Text = "Indietro!"},
  Voice_5415_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_5416_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_5416_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5417_AwakerVoiceContent = {
    Text = "Al vostro comando!"
  },
  Voice_5417_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5418_AwakerVoiceContent = {Text = "Folle"},
  Voice_5418_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5419_AwakerVoiceContent = {
    Text = "...Eh? Mi stai chiamando? Non sentivo mentre riparavo la motocicletta... A proposito, gentile straniero, hai visto la mia chiave inglese?"
  },
  Voice_5419_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_5419_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_5420_AwakerVoiceContent = {
    Text = "La mia memoria è sempre nebulosa, e riesco a concentrarmi solo su ciò che ho davanti. Tuttavia, farò del mio meglio per incidere il tuo nome nella mia mente... Com'era?"
  },
  Voice_5420_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_5420_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_5421_AwakerVoiceContent = {
    Text = "Mi sembri vagamente familiare, ma non riesco a ricordare il tuo nome... Sei il mio assistente? Potresti procurarmi sette bulloni?"
  },
  Voice_5421_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_5421_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_5422_AwakerVoiceContent = {
    Text = "Ho inciso il tuo nome sulla mia moto, la Phantom! Quando un giorno andremo all'avventura, non dimenticherò come chiamarti."
  },
  Voice_5422_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_5422_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_5423_AwakerVoiceContent = {
    Text = "Così familiare, così familiare. Deve essere successo qualcosa tra noi, giusto? Dammi un momento per ricordare... Ah, sei tu, il Custode!"
  },
  Voice_5423_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_5423_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_5424_AwakerVoiceContent = {
    Text = "Sei davvero un bambino disonesto. Per tua fortuna, ho l'eternità per aspettare..."
  },
  Voice_5424_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_5425_AwakerVoiceContent = {
    Text = "Che bel \"Lieto Fine\". Non è vero?"
  },
  Voice_5425_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_5426_AwakerVoiceContent = {
    Text = "Un teschio niente male come trofeo... Non regge il confronto con i pezzi migliori della mia collezione, ma il brivido della caccia è sempre esaltante. Invitatemi anche la prossima volta."
  },
  Voice_5426_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_5427_AwakerVoiceContent = {Text = "Hmm..."},
  Voice_5427_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_5428_AwakerVoiceContent = {
    Text = "Un'ancella professionista eliminerà tutto per il suo Padrone, inclusi i malvagi~"
  },
  Voice_5428_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_5429_AwakerVoiceContent = {
    Text = "Ormai siamo complici, no? Se mai finirai per strada, non ti lascerò sopravvivere di avanzi."
  },
  Voice_5429_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_5430_AwakerVoiceContent = {
    Text = "Cresci e prospera, mio piccolo germoglio."
  },
  Voice_5430_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_5431_AwakerVoiceContent = {
    Text = "Cresci e prospera, mio piccolo germoglio."
  },
  Voice_5431_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_5432_AwakerVoiceContent = {
    Text = "Ho la sensazione che oggi i miei dadi girino un po' meglio del solito!"
  },
  Voice_5432_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_5433_AwakerVoiceContent = {
    Text = "Wow! La tua fortuna è rovente in questo momento!"
  },
  Voice_5433_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_5434_AwakerVoiceContent = {Text = "Fortunato~"},
  Voice_5434_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_5435_AwakerVoiceContent = {
    Text = "Non avvicinarti a me!"
  },
  Voice_5435_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_5436_AwakerVoiceContent = {
    Text = "Non avvicinarti a me!"
  },
  Voice_5436_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5437_AwakerVoiceContent = {
    Text = "Devo accusarti, Custode. La tua gentilezza mi inquieta — solo il pain fisico mi sembra reale e stabile."
  },
  Voice_5437_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_5438_AwakerVoiceContent = {
    Text = "Davvero notevole."
  },
  Voice_5438_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_5439_AwakerVoiceContent = {
    Text = "Questo livello è ben lungi dall'essere sufficiente."
  },
  Voice_5439_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_5440_AwakerVoiceContent = {
    Text = "Dunque, quale ricompensa desideri?"
  },
  Voice_5440_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_5441_AwakerVoiceContent = {
    Text = "Ugh! Questo squallore e disordine ovunque... Riesco a malapena a trovare un posto adatto dove posare il piede. E sia, offrimi la tua schiena morbida, mortale."
  },
  Voice_5441_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5442_AwakerVoiceContent = {
    Text = "Finalmente... Eccola."
  },
  Voice_5442_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5443_AwakerVoiceContent = {
    Text = "Anche il pelo di Brown è diventato setoso."
  },
  Voice_5443_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_5443_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_5444_AwakerVoiceContent = {
    Text = "Senti, forse non sarò la miglior guardia di sicurezza, ma puoi fidarti di me per qualsiasi commissione o consegna."
  },
  Voice_5444_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_5444_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_5445_AwakerVoiceContent = {
    Text = "Guarda come fissi Brown.\n...Heh heh, il grande Brown vuole rosicchiare le dita dei piedi di qualche codardo stanotte. Chi sarà il fortunato?"
  },
  Voice_5445_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_5445_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_5446_AwakerVoiceContent = {
    Text = "Che finalmente crescerò un po' in altezza, allora?"
  },
  Voice_5446_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_5446_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_5447_AwakerVoiceContent = {
    Text = "È ora di mettersi al lavoro, dunque? Forza, Brown, su con le orecchie!"
  },
  Voice_5447_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_5447_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_5448_AwakerVoiceContent = {
    Text = "Agrippa? Chi era? Ops, ne ho uccisi troppi. La maggior parte non meritava di essere ricordata."
  },
  Voice_5448_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Agrippa"
  },
  Voice_5448_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Agrippa\""
  },
  Voice_5449_AwakerVoiceContent = {
    Text = "Sarebbe una persona pericolosa da avere a bordo... No, intendo puramente dal punto di vista della sicurezza della navigazione..."
  },
  Voice_5449_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Faros"
  },
  Voice_5449_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Faros\""
  },
  Voice_5450_AwakerVoiceContent = {
    Text = "Non avvicinarti!"
  },
  Voice_5450_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_5451_AwakerVoiceContent = {
    Text = "Fai attenzione!"
  },
  Voice_5451_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_5452_AwakerVoiceContent = {
    Text = "Istruzione completa... Ah. Ho combinato un altro pasticcio..."
  },
  Voice_5452_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_5453_AwakerVoiceContent = {
    Text = "Ah, questo è esattamente il pezzo di cui avevo bisogno, grazie! ...Eh? Ti ho chiesto io di cercarlo? Non lo ricordo affatto. Sei sicuro di non sbagliarti?"
  },
  Voice_5453_AwakerVoiceTitle = {
    Text = "Chat: A proposito dei Pezzi di Ricambio"
  },
  Voice_5454_AwakerVoiceContent = {
    Text = "Le Ispirazioni fluiscono senza sosta..."
  },
  Voice_5454_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_5455_AwakerVoiceContent = {
    Text = "Buon gusto."
  },
  Voice_5455_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_5456_AwakerVoiceContent = {
    Text = "Hai scelto il coltello da intaglio perfetto per me."
  },
  Voice_5456_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_5457_AwakerVoiceContent = {
    Text = "Detesto perdere il controllo. Tuttavia, la tua presenza mi ha mostrato che un tocco di sottile Caos può portare un godimento singolare."
  },
  Voice_5457_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_5458_AwakerVoiceContent = {
    Text = "Sei cresciuta un po'?"
  },
  Voice_5458_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_5459_AwakerVoiceContent = {
    Text = "Scusa, è difficile per me far crescere il mio Corpo..."
  },
  Voice_5459_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_54601_AwakerVoiceContent = {
    Text = "È così che comprenderemo i misteri del mondo."
  },
  Voice_54601_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_54602_AwakerVoiceContent = {
    Text = "È così che comprenderemo i misteri del mondo."
  },
  Voice_54602_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_54605_AwakerVoiceContent = {
    Text = "Ecco il tuo pasto!"
  },
  Voice_54605_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_54606_AwakerVoiceContent = {
    Text = "Ecco il tuo pasto!"
  },
  Voice_54606_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_54607_AwakerVoiceContent = {
    Text = "Ora, dissezioniamo l'essenza del mondo!"
  },
  Voice_54607_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_54608_AwakerVoiceContent = {
    Text = "Ora, dissezioniamo l'essenza del mondo!"
  },
  Voice_54608_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_54609_AwakerVoiceContent = {
    Text = "Sacrificio! Restituite la mia carne al Suo Trono—"
  },
  Voice_54609_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_5460_AwakerVoiceContent = {
    Text = "G-grazie per il pasto..."
  },
  Voice_5460_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_54610_AwakerVoiceContent = {
    Text = "Sacrificio! Restituite la mia carne al Suo Trono—"
  },
  Voice_54610_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_54611_AwakerVoiceContent = {
    Text = "Non ostacolarmi!"
  },
  Voice_54611_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_54612_AwakerVoiceContent = {
    Text = "Nell'Abisso... ci sarà una luce di Giustizia."
  },
  Voice_54612_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_54613_AwakerVoiceContent = {
    Text = "Non ostacolarmi!"
  },
  Voice_54613_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_54614_AwakerVoiceContent = {
    Text = "Abbandonati a questo dolore senza eguali!"
  },
  Voice_54614_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_54615_AwakerVoiceContent = {
    Text = "Abbandonati a questo dolore senza eguali!"
  },
  Voice_54615_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_54616_AwakerVoiceContent = {
    Text = "<Italic:\"...Oui tu mourus, enfant, par un fleuve emportée!\">"
  },
  Voice_54616_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_54617_AwakerVoiceContent = {
    Text = "<Italic:\"...Oui tu mourus, enfant, par un fleuve emportée!\">"
  },
  Voice_54617_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_54618_AwakerVoiceContent = {
    Text = "Oh, Progenie Informi, diventate uno scudo per il mio signore!"
  },
  Voice_54618_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_54619_AwakerVoiceContent = {
    Text = "Oh, Progenie Informi, diventate uno scudo per il mio signore!"
  },
  Voice_54619_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_5461_AwakerVoiceContent = {
    Text = "Ti sarei grato per il tuo impegno."
  },
  Voice_5461_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_5461_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_54620_AwakerVoiceContent = {
    Text = "Bestia dell'Abisso, divorali tutti!"
  },
  Voice_54620_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_54621_AwakerVoiceContent = {
    Text = "Bestia dell'Abisso, divorali tutti!"
  },
  Voice_54621_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_54622_AwakerVoiceContent = {
    Text = "Nell'Abisso... ci sarà una luce di Giustizia."
  },
  Voice_54622_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_54623_AwakerVoiceContent = {
    Text = "Io sono... colei che spezza le catene! Tekeli—Li!"
  },
  Voice_54623_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_54624_AwakerVoiceContent = {
    Text = "Io sono... colei che spezza le catene! Tekeli—Li!"
  },
  Voice_54624_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_54625_AwakerVoiceContent = {
    Text = "Sarò io a svelare il futuro!"
  },
  Voice_54625_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_54626_AwakerVoiceContent = {
    Text = "Sarò io a svelare il futuro!"
  },
  Voice_54626_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_54627_AwakerVoiceContent = {
    Text = "Prostrati e bacia la punta dei miei piedi!"
  },
  Voice_54627_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_54628_AwakerVoiceContent = {
    Text = "Tutte le viti sono qui!"
  },
  Voice_54628_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_54629_AwakerVoiceContent = {
    Text = "Tutte le viti sono qui!"
  },
  Voice_54629_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_5462_AwakerVoiceContent = {
    Text = "Solo un Aequor può sopportare un Potere così supremo. Devi invidiarmi, eh? Non è colpa tua se sei un fragile umano; fattene una ragione."
  },
  Voice_5462_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_5462_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_54630_AwakerVoiceContent = {
    Text = "Prostrati e bacia la punta dei miei piedi!"
  },
  Voice_54630_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_5463_AwakerVoiceContent = {
    Text = "Posso trasformare questi individui sconfitti nei miei Schiavi?"
  },
  Voice_5463_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_5464_AwakerVoiceContent = {Text = "Heh."},
  Voice_5464_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_5465_AwakerVoiceContent = {
    Text = "Proprio come previsto."
  },
  Voice_5465_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_5466_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5466_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_5467_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5467_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_5468_AwakerVoiceContent = {
    Text = "Se avessi saputo prima che quelle persone erano tormentate da questa maledizione divorante, io... No, non è troppo tardi. Devo sradicarla ed eliminare ogni sofferenza, anche se dovesse costarmi la vita ancora una volta."
  },
  Voice_5468_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_5469_AwakerVoiceContent = {
    Text = "Non perderti d'animo. Il mare ci accoglie tutti."
  },
  Voice_5469_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_5470_AwakerVoiceContent = {
    Text = "Con un Corpo così fragile, è troppo chiederti di essere il mio compagno. Sei semplicemente troppo debole; devi intensificare l'allenamento. Vieni, ti porto al club sportivo dell'accademia e ti apro gli Occhi."
  },
  Voice_5470_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_5471_AwakerVoiceContent = {
    Text = "Colei che mi ha prestato il suo Potere è stata tormentata dalla Dissoluzione... Che razza di sguardo è quello? Non pensarci nemmeno! Non ti dirò dove si trova!"
  },
  Voice_5471_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_5472_AwakerVoiceContent = {
    Text = "Con abbastanza fortuna, chiunque può essere invincibile."
  },
  Voice_5472_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_5473_AwakerVoiceContent = {
    Text = "Oh, ti sto causando dolore?"
  },
  Voice_5473_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_5474_AwakerVoiceContent = {
    Text = "Oh cielo, la maggior parte qui sono ancora fanciulli. Quel gentiluomo dai capelli bianchi, quel severo giovane con un braccio solo—nessuno di loro è l'ideale per dei fanciulli... Sigh, è proprio un dilemma."
  },
  Voice_5474_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_5475_AwakerVoiceContent = {
    Text = "Oh, ti sto causando dolore?"
  },
  Voice_5475_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5476_AwakerVoiceContent = {
    Text = "Rune incise con cura, idoli scolpiti con devozione, elisir proibiti raffinati più e più volte... non ne può mancare nemmeno uno."
  },
  Voice_5476_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_5476_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_5477_AwakerVoiceContent = {
    Text = "Il Trono deve essere costruito con antica pietra azzurra estratta dagli abissi dell'oceano, e l'altare deve essere ricoperto col sangue dei sacrifici umani... Ora va' a preparare!"
  },
  Voice_5477_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_5477_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_5478_AwakerVoiceContent = {
    Text = "Conducili tutti qui! Dovranno tremare e inginocchiarsi per dare il benvenuto al Suo avvento."
  },
  Voice_5478_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_5478_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_5479_AwakerVoiceContent = {
    Text = "Viaggerò fino a quella rovina abissale e mi immergerò nelle acque marine della Sua nascita..."
  },
  Voice_5479_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_5479_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_5480_AwakerVoiceContent = {
    Text = "Finalmente. Benvenuto al rito in cui assisteremo alla Sua divina nascita... Cosa? Dici che anche la Sua fine è predestinata? ...No! Non può essere... Ho già compiuto sacrifici così grandi..."
  },
  Voice_5480_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_5480_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_5481_AwakerVoiceContent = {
    Text = "Segui i comandamenti divini."
  },
  Voice_5481_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_5482_AwakerVoiceContent = {
    Text = "Il tuo fianco sarà il luogo in cui Faint e io troveremo finalmente un posto a cui appartenere?"
  },
  Voice_5482_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_5482_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_5483_AwakerVoiceContent = {
    Text = "Sì... A quel tempo persi la voce. La tua grazia me l'ha restituita."
  },
  Voice_5483_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_5483_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_5484_AwakerVoiceContent = {
    Text = "Segui i comandamenti divini."
  },
  Voice_5484_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5485_AwakerVoiceContent = {
    Text = "Il vasto cosmo, lo spazio profondo sconfinato, e il viaggio apparentemente infinito... Mi sentivo così perduta in quel periodo."
  },
  Voice_5485_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_5485_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_5486_AwakerVoiceContent = {
    Text = "Le scorciatoie possono dare una spinta, ma non trascurare l'addestramento delle abilità."
  },
  Voice_5486_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_5487_AwakerVoiceContent = {
    Text = "Quindi questo metodo si applica anche a me..."
  },
  Voice_5487_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_5488_AwakerVoiceContent = {
    Text = "Una sensazione meravigliosa."
  },
  Voice_5488_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_5492_AwakerVoiceContent = {
    Text = "Il Suo avvento porrà certamente fine alla sofferenza causata da questo oscuro liquido di morte, non è vero?"
  },
  Voice_5492_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_5493_AwakerVoiceContent = {
    Text = "Buongiorno, mio signore. Se intendete uscire per indagare, vi prego, lasciate che vi accompagni come vostra Guardia."
  },
  Voice_5493_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_5493_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_5494_AwakerVoiceContent = {
    Text = "Non sai cosa fare? Se ti annoi, vai a compilare qualche rapporto di missione."
  },
  Voice_5494_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_5495_AwakerVoiceContent = {
    Text = "Finalmente si comincia? I miei piccoli tesori sono rimasti affamati per tanto, tanto tempo..."
  },
  Voice_5495_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_5496_AwakerVoiceContent = {
    Text = "Il potere del mio sangue sta emergendo."
  },
  Voice_5496_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_5497_AwakerVoiceContent = {
    Text = "Aspetta un momento... L'ho già visto. Mi davano da bere acqua con questa melma nera dentro. Potrebbe essere collegato al mio aver ottenuto il potere della Fiamma Verde? Suppongo sia una benedizione sotto mentite spoglie."
  },
  Voice_5497_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_5498_AwakerVoiceContent = {
    Text = "Ramona Dexter, chiamami pure Ramona. Non vedo l'ora di lavorare con te, Custode."
  },
  Voice_5498_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5499_AwakerVoiceContent = {Text = "Sì."},
  Voice_5499_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_5500_AwakerVoiceContent = {
    Text = "Comando ricevuto."
  },
  Voice_5500_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5501_AwakerVoiceContent = {
    Text = "Hmph. Irrispettoso! E sia, ti concederò un piccolo gioco."
  },
  Voice_5501_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_5502_AwakerVoiceContent = {
    Text = "Cosa non mi piace? Una pipa che si spegne, una carrozza persa, la pioggia sulle scarpe nuove. In pratica, qualsiasi sfortuna è una seccatura."
  },
  Voice_5502_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_5503_AwakerVoiceContent = {
    Text = "Chiave inglese, chiave regolabile, chiave poligonale, cacciavite a taglio, cacciavite a croce, vite a testa svasata, vite a testa tonda... Se può aggiustare le cose rotte, mi piace."
  },
  Voice_5503_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_5504_AwakerVoiceContent = {
    Text = "Oh no~ Mi hai beccata~ \nNon fa niente, i Risvegliatori hanno un potere spirituale così abbondante. Devo rubare almeno 365 volte prima che diventino burattini senza mente~ Non ce la fai? Va bene, la prossima volta starò più attenta! Solo un pizzico di \"paura\" durante il taglio, ti va?"
  },
  Voice_5504_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_5504_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_5505_AwakerVoiceContent = {
    Text = "Ehi, tu conosci già i segreti della magia di Casiah, vero? Hmm, per assicurarmi che tu non sveli i segreti, dovrai seguirmi ovunque io vada in tournée~ Haha, pensi che stia raccogliendo le tue emozioni? Esatto, nulla sfugge al tuo sguardo!"
  },
  Voice_5505_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_5505_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_5506_AwakerVoiceContent = {
    Text = [[
Tu, tu sarai l'assistente magica di Casiah! Non spaventarti~ Entra nella mia scatola magica solo un momento!
Ti sei nascosto bene? Sto per inserire la spada~ Oh, ti assicuro che non ci sono trappole all'interno~]]
  },
  Voice_5506_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_5506_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_5507_AwakerVoiceContent = {
    Text = "Ecco, mettiti questo Cilindro! Poi dimmi il regalo che desideri di più. Ah, capisco! Ora, infila la mano nel cappello—"
  },
  Voice_5507_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_5507_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_5508_AwakerVoiceContent = {
    Text = "Che seccatura. Quei ragazzini vengono a ogni spettacolo, e le mie scorte si stanno esaurendo... Hmm, un mago non deve ripetere gli stessi trucchi per lo stesso pubblico. Creare nuova magia? Mi spiace, mi manca quel particolare Talento; so solo imitare!"
  },
  Voice_5508_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_5508_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_5509_AwakerVoiceContent = {
    Text = "Questa accademia... ha un disperato bisogno di essere rinnovata; solo il salotto del preside è in qualche modo presentabile. Che ne pensi?"
  },
  Voice_5509_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_5509_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_5510_AwakerVoiceContent = {
    Text = "Quegli arroganti, spregevoli stolti moriranno per mia mano."
  },
  Voice_5510_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_5511_AwakerVoiceContent = {
    Text = "La mia Lama della Vendetta si fa sempre più affilata."
  },
  Voice_5511_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_5512_AwakerVoiceContent = {
    Text = "Il mio salon non è innocente come un ballo. Siete preparati?"
  },
  Voice_5512_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_5512_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_5513_AwakerVoiceContent = {
    Text = "Il mio salon è il terreno, il giardino, dove inebriante bellezza e potere fioriranno rigogliosi..."
  },
  Voice_5513_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_5513_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_5514_AwakerVoiceContent = {
    Text = "Cuscini di seta, tè nero, macaron... Ho bisogno anche di rose fresche con la rugiada del mattino per adornare la mia sala di ricevimento."
  },
  Voice_5514_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_5514_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_5515_AwakerVoiceContent = {
    Text = "Per favore, consentite l'ingresso agli ospiti esterni. Devo tenere i miei salon. Dite loro di fare un'eccezione per me, vi prego."
  },
  Voice_5515_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_5515_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_5516_AwakerVoiceContent = {
    Text = "Errore di esecuzione, errore, errore, errore..."
  },
  Voice_5516_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_5517_AwakerVoiceContent = {
    Text = "Ah! Che ore sono?! Scusa, Maestro... Non dovrei oziare! Ma... sono così stanca... Per favoreee?"
  },
  Voice_5517_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_5518_AwakerVoiceContent = {
    Text = "La mia unica opzione era aspettare la morte? Qualcuno poteva aiutarmi? Potevo davvero resistere? Me lo chiedevo ogni giorno. La risposta era nella mia mente—solo che non ho mai osato vederla... Se non fossi apparso tu, non so se avrei avuto il coraggio di reagire.\nG-Grazie—non fraintendere, non è una dichiarazione d'amore o roba del genere!"
  },
  Voice_5518_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_5518_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_5519_AwakerVoiceContent = {
    Text = "Vivere nei loro sogni illusori, privata del mio diritto a essere normale, senza alcuna scelta... tutto per una ridicola profezia... Ero disposta a fare qualsiasi cosa per fuggire da questa vita!"
  },
  Voice_5519_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_5519_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_5520_AwakerVoiceContent = {
    Text = "<Italic:\"Le ninfee increspate sospirano intorno a lei;\nA tratti risveglia, in un ontano assopito,\nQualche nido da cui sfugge un lieve fruscio d'ali;\nUn inno misterioso scende dalle stelle dorate.\">\nAh, scusa—stavo recitando troppo forte? È una delle mie poesie preferite... Vorresti leggerla con me?"
  },
  Voice_5520_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla lettura"
  },
  Voice_5521_AwakerVoiceContent = {
    Text = "Non irrompere nella stanza di una signora, e non commentare il suo contegno. Vattene, ho bisogno di riposare."
  },
  Voice_5521_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_5521_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_5522_AwakerVoiceContent = {
    Text = "Non azzardarti a darti delle arie con me. Conosci il tuo posto! Sono io a comandare in questa stanza."
  },
  Voice_5522_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_5522_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_5523_AwakerVoiceContent = {
    Text = "Oh, devo esporre gli oggetti per te?"
  },
  Voice_5523_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_5524_AwakerVoiceContent = {
    Text = "Ben fatto. È ora di celebrare la vittoria con un barile di rum!"
  },
  Voice_5524_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_5525_AwakerVoiceContent = {Text = "Sparisci."},
  Voice_5525_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_5526_AwakerVoiceContent = {
    Text = "Lascia fare a me!"
  },
  Voice_5526_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_5527_AwakerVoiceContent = {
    Text = "La sensazione di essere schiacciati sotto i miei piedi dev'essere assolutamente divina~"
  },
  Voice_5527_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_5528_AwakerVoiceContent = {Text = "Resisti!"},
  Voice_5528_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5529_AwakerVoiceContent = {
    Text = "Curiosa di sapere cosa c'è sotto la benda? Te lo mostrerò... quando il momento sarà più appropriato. Non essere impaziente."
  },
  Voice_5529_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_5530_AwakerVoiceContent = {
    Text = "È già finita? ... La mia eccitazione stava appena iniziando a risvegliarsi."
  },
  Voice_5530_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_5531_AwakerVoiceContent = {
    Text = "Ehi, smettila di armeggiare col mio corpo. I veri guerrieri non si affidano mai ad aiuti esterni."
  },
  Voice_5531_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_5531_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_5532_AwakerVoiceContent = {
    Text = "Sono diventata più forte... Userò questi occhi per paralizzare il nemico!"
  },
  Voice_5532_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_5533_AwakerVoiceContent = {
    Text = "L'Università di Mythag non è diversa dall'esercito. Ognuno di noi sta in prima linea, affilando le proprie armi e in Preparazione alla Battaglia."
  },
  Voice_5533_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_5534_AwakerVoiceContent = {Text = "Perfetto!"},
  Voice_5534_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_5535_AwakerVoiceContent = {Text = "Perfetto!"},
  Voice_5535_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5536_AwakerVoiceContent = {
    Text = "Incatenami, trascinami per i capelli, fammi inginocchiare come tua schiava... Non m'importa, fammi quello che vuoi. Lasciami solo uccidere. Gli scultori, quella Signora Lanterna, una qualche vecchia asmatica... chiunque! Ti prometto che gli strapperò la gola e ne berrò il sangue."
  },
  Voice_5536_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_5536_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_5537_AwakerVoiceContent = {
    Text = "Dalle Ferite da Dissoluzione non cola soltanto melma nera, ma anche Ispirazione Inesauribile. Onestamente, non mi dispiacerebbe averne ancora."
  },
  Voice_5537_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_5538_AwakerVoiceContent = {
    Text = "Spaventato? Hahaha, esatto! Al diavolo tutto quanto. Voglio solo assaporare il tuo Terrore."
  },
  Voice_5538_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_5538_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_5539_AwakerVoiceContent = {
    Text = "Interessante, il tuo Sangue ha un sapore... dolce, come l'idromele."
  },
  Voice_5539_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_5539_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_5540_AwakerVoiceContent = {
    Text = "A quei tempi, decine di migliaia acclamavano il mio nome. Il fragore assordante di \"Uvhash\" sovrastava ogni cosa, celebrando il momento in cui spezzavo il collo a un debole calvo. Una sensazione incredibile. Come mio compagno, dovresti capirlo."
  },
  Voice_5540_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_5540_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_5541_AwakerVoiceContent = {Text = "A-aspetta!"},
  Voice_5541_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_5542_AwakerVoiceContent = {Text = "No!"},
  Voice_5542_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_5543_AwakerVoiceContent = {Text = "Ahi!"},
  Voice_5543_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_5544_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_5544_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_5545_AwakerVoiceContent = {
    Text = "Ricerca di \"Dissoluzione\" nell'Archivio esteso... Non necessario? Desiderate conoscere la mia posizione sulla Dissoluzione? Compreso. Ricerca di \"Armi anti-Dissoluzione\" nel dominio privato dei Risvegliati... Risultato: \"Nullo.\""
  },
  Voice_5545_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_5546_AwakerVoiceContent = {
    Text = "Falsi idoli, fragili come argilla secca, si disperdono al minimo soffio di vento..."
  },
  Voice_5546_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Murphy"
  },
  Voice_5546_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risveglio \"Murphy\""
  },
  Voice_5547_AwakerVoiceContent = {
    Text = "Sta diventando un po' rumoroso... sono gli studenti? Sono molto simili agli albatros, sai? Hanno una vitalità infinita, come se il loro viaggio non finisse mai..."
  },
  Voice_5547_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_5548_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5548_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_5549_AwakerVoiceContent = {Text = "Hmph"},
  Voice_5549_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_5550_AwakerVoiceContent = {
    Text = "Ramona è l'unica qui che meriti il mio tempo. È piuttosto dotata con la lama. Gli altri sono così rigidi e noiosi... Sei come loro? Ti piace davvero scrivere quei tediosi rapporti di missione?"
  },
  Voice_5550_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_5551_AwakerVoiceContent = {
    Text = "Non degno di menzione."
  },
  Voice_5551_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_5552_AwakerVoiceContent = {
    Text = [[
Non tutte le mamme sono uguali. Alcune sono buone e alcune sono cattive.
Tu sei una mamma buona.]]
  },
  Voice_5552_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_5552_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_5553_AwakerVoiceContent = {
    Text = "Vi chiedo perdono, mio signore, non sono riuscito a proteggervi..."
  },
  Voice_5553_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_5554_AwakerVoiceContent = {
    Text = "Hai riservato la sede? Dev'essere un giardino di almeno 150 metri quadrati!"
  },
  Voice_5554_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_5554_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_5555_AwakerVoiceContent = {
    Text = "Il sangue dei morenti è un liquido viscido. Basta un lieve taglio al collo, e il sangue scorre tra i denti, trasformandosi in rivoli caldi che lentamente mi riempiono il ventre... Heh. Delizioso."
  },
  Voice_5555_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Sangue"
  },
  Voice_5556_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5556_AwakerVoiceTitle = {
    Text = "Abilità Speciale: I"
  },
  Voice_5557_AwakerVoiceContent = {Text = "Ehi!"},
  Voice_5557_AwakerVoiceTitle = {
    Text = "Abilità Speciale: I"
  },
  Voice_5558_AwakerVoiceContent = {Text = "Eh?"},
  Voice_5558_AwakerVoiceTitle = {
    Text = "Abilità Speciale: I"
  },
  Voice_5559_AwakerVoiceContent = {
    Text = "Ti ringrazio per la gentilezza di avermi offerto rifugio. Spero di non portare un fato tragico su di te..."
  },
  Voice_5559_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_5560_AwakerVoiceContent = {
    Text = "Provengo da un lontano pianeta alieno, un luogo di tempeste di neve incessanti e freddo estremo. Ma poco importa; nel mio maniero, oltre un migliaio di servitori offrono un confortante calore con la sola loro presenza."
  },
  Voice_5560_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul passato"
  },
  Voice_5561_AwakerVoiceContent = {
    Text = "Non devo cedere prima del Suo Avvento, mio signore..."
  },
  Voice_5561_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_5562_AwakerVoiceContent = {
    Text = "Non devo cedere prima del Suo Avvento, mio signore..."
  },
  Voice_5562_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_5563_AwakerVoiceContent = {
    Text = "Oh, come può esserci un ospite così arrogante, che pretende \"l'arma più potente del mondo\"? Gli ho detto che ci sarebbe voluta una testa intrisa d'odio per ottenerla in cambio, e se n'è andato imbronciato..."
  },
  Voice_5563_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Golia"
  },
  Voice_5563_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Golia\""
  },
  Voice_5564_AwakerVoiceContent = {
    Text = "Quell'espressione eroica da martire sul tuo volto... come se fossi sempre pronto a morire per una \"causa superiore\"... mi fa prudere le giunture."
  },
  Voice_5564_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_5564_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_5565_AwakerVoiceContent = {
    Text = "Avevo l'Annientamento proprio lì, pronto a inghiottire questo cosiddetto santuario... Poi è arrivato il divieto di Ricerca. Che peccato."
  },
  Voice_5565_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_5565_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_5566_AwakerVoiceContent = {
    Text = "Sì, avevo innumerevoli corpi di riserva e svariati piani per sfuggire alla Dissoluzione. Ma ho scelto di inseguire la verità, e ne è valsa la pena."
  },
  Voice_5566_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_5566_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_5567_AwakerVoiceContent = {
    Text = "La verità del mondo, il suo inizio e la sua fine — tutto privo di significato. Ma se insisti a inseguirla... ti guiderò. Come facevo un tempo."
  },
  Voice_5567_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_5567_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_5568_AwakerVoiceContent = {
    Text = "Potresti fermarmi, ma la fine arriverà comunque... Salverò questa scuola — e te — per ultimi. Guarderemo il crollo dell'umanità dal campanile, intrisi nel crepuscolo del tempo... Poetico, no? Almeno non avremo lasciato che il nostro prezioso legame andasse sprecato."
  },
  Voice_5568_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_5568_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_5569_AwakerVoiceContent = {Text = "D'accordo."},
  Voice_5569_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5570_AwakerVoiceContent = {Text = "Sparisci."},
  Voice_5570_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_5571_AwakerVoiceContent = {
    Text = "Possano le mie preghiere risuonare come campane mattutine, destando dal dormiveglia la Terra dei Bianchi Uccelli..."
  },
  Voice_5571_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_5572_AwakerVoiceContent = {
    Text = "Non avrei mai pensato che qualcuno oltre a Tintura potesse accettarmi. Sono felice di averti incontrato, Custode. Farò del mio meglio per imparare a controllare il mio Potere, così quando ti abbraccerò non ti prosciugherò la forza vitale... Un abbraccio, giusto? Il modo umano di esprimere gratitudine?"
  },
  Voice_5572_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_5572_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_5573_AwakerVoiceContent = {
    Text = "Se resto qui, non devo pagare nulla? Posso aiutarti a ottenere prestigio qui. Basta minacciare di prosciugare le loro vite — è semplice, come facevo per Tintura... Ah! Non dirlo a nessuno!"
  },
  Voice_5573_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_5573_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_5574_AwakerVoiceContent = {
    Text = "Mi dispiace, non sono come gli altri... Sono un prodotto difettoso."
  },
  Voice_5574_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_5574_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_5575_AwakerVoiceContent = {
    Text = "Un'ancella abile può valorizzare enormemente il salon, ma un'ancella verde-azzurra... lasciatemi riconsiderare..."
  },
  Voice_5575_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Karen"
  },
  Voice_5575_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risveglio \"Karen\""
  },
  Voice_5576_AwakerVoiceContent = {
    Text = "Tintura è la mia sorella gemella. A differenza di me, lei brilla sempre intensamente... Senza il mio peso, avrebbe un futuro più luminoso, il suo canto risuonerebbe in tutta la galassia..."
  },
  Voice_5576_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_5576_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_5577_AwakerVoiceContent = {
    Text = "La Culla è angusta, non c'è spazio per distendere il corpo... Ma Tintura ha detto che, per la sicurezza di Tutti, dovrei restare nella Culla... Se questo è il suo Desiderio, obbedirò."
  },
  Voice_5577_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_5577_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_5578_AwakerVoiceContent = {
    Text = "Spesso mi sento come se esistessi nello spazio tra la vita e la morte. Ovunque io sia, la malinconia si propaga come una marea, e le tragedie si susseguono, una dopo l'altra. Anche così, desiderereste ancora che scrivessi un poema per voi? Hmm... forse meritate quello più dolce..."
  },
  Voice_5578_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_5578_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_5579_AwakerVoiceContent = {
    Text = "<Italic:\"Avvicinati, piccolo Usignolo, o il Giorno giungerà prima che la rosa sia compiuta...\">"
  },
  Voice_5579_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_5579_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_5580_AwakerVoiceContent = {
    Text = "Cosa bramate? La bellezza di parole eleganti, la fama diffusa, o la sincerità profonda intessuta in quelle parole?"
  },
  Voice_5580_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_5580_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_5581_AwakerVoiceContent = {
    Text = "Con inchiostro invisibile, tratteggio i boccioli deformi... Questo ramo di rosa spettrale ed etereo ispira davvero versi poetici..."
  },
  Voice_5581_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_5581_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_55825_AwakerVoiceContent = {
    Text = "Ascoltate le Sue parole divine."
  },
  Voice_55825_AwakerVoiceTitle = {
    Text = "Risveglio: II"
  },
  Voice_55826_AwakerVoiceContent = {
    Text = "Sacrificio! Ricostruite il Reame Divino—"
  },
  Voice_55826_AwakerVoiceTitle = {
    Text = "Risveglio: III"
  },
  Voice_5582_AwakerVoiceContent = {
    Text = "Se davvero insistete, tornerò alla luce del sole... la stessa identica luce del giorno in cui lasciai Cité..."
  },
  Voice_5582_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_5582_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_5583_AwakerVoiceContent = {
    Text = "Hehe, vuoi vedere un universo che viene distrutto? Oh, è troppo tardi per tirarti indietro!"
  },
  Voice_5583_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_5583_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_5584_AwakerVoiceContent = {
    Text = "Assaporala... la dolce carezza della morte."
  },
  Voice_5584_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_5585_AwakerVoiceContent = {
    Text = "Assaporala... la dolce carezza della morte."
  },
  Voice_5585_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_5586_AwakerVoiceContent = {Text = "Ora basta!"},
  Voice_5586_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_5587_AwakerVoiceContent = {Text = "No..."},
  Voice_5587_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_5588_AwakerVoiceContent = {
    Text = "Contempla lo splendore della possanza di Questa Qui."
  },
  Voice_5588_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5589_AwakerVoiceContent = {
    Text = "L'aria nel campus alle 4 del mattino è rinfrescante. Sono contento che tu voglia allenarti con me. Devo dire che la scultura è un bell'esercizio fisico."
  },
  Voice_5589_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul mattino"
  },
  Voice_5590_AwakerVoiceContent = {
    Text = "Questo potere è piacevole da usare."
  },
  Voice_5590_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_5590_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_5591_AwakerVoiceContent = {
    Text = "Detesto chi non paga ciò che acquista. Se gestisci un negozio abbastanza a lungo, prima o poi incontri questo problema. Non ho altra scelta che occuparmene personalmente e riscuotere il dovuto."
  },
  Voice_5591_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_5592_AwakerVoiceContent = {
    Text = "Torturali lentamente."
  },
  Voice_5592_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5593_AwakerVoiceContent = {
    Text = "Torturali lentamente."
  },
  Voice_5593_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_5594_AwakerVoiceContent = {
    Text = "Caricamento."
  },
  Voice_5594_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_5595_AwakerVoiceContent = {Text = "Inizio."},
  Voice_5595_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5596_AwakerVoiceContent = {
    Text = "Rendiamo questo il nostro clamoroso mare di felicità!"
  },
  Voice_5596_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_5597_AwakerVoiceContent = {
    Text = "Cosa? Ti aspetti davvero un \"grazie\" da parte mia?"
  },
  Voice_5597_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_5598_AwakerVoiceContent = {
    Text = "Come tributo, è ben lungi dall'essere adeguato... ma vista la tua sincerità, suppongo che lo accetterò. Solo per questa volta."
  },
  Voice_5598_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_5599_AwakerVoiceContent = {
    Text = "Credevi davvero che questo mi avrebbe convinta ad ascoltarti?"
  },
  Voice_5599_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_5600_AwakerVoiceContent = {Text = "Hah!"},
  Voice_5600_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5601_AwakerVoiceContent = {Text = "Avanti!"},
  Voice_5601_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5602_AwakerVoiceContent = {
    Text = "Mostri ingrati, assassini e sicari — riconosci loro un qualche valore? Fenomeno da baraccone."
  },
  Voice_5602_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_5602_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_5603_AwakerVoiceContent = {
    Text = "Non importa quanti cuscini impiliate, un trono di lapislazzuli non potrà mai eguagliare un letto di piume. Sotto questo aspetto, il vostro luogo ha qualcosa di encomiabile."
  },
  Voice_5603_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_5604_AwakerVoiceContent = {
    Text = "Un castigo di poco conto."
  },
  Voice_5604_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_5605_AwakerVoiceContent = {
    Text = "Temo la solitudine e l'angoscia di perdermi in un'oscurità senza fine... Perciò ti prego, promettimi che non lascerai il mio fianco."
  },
  Voice_5605_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_5606_AwakerVoiceContent = {
    Text = "Se fossi in te, chiuderei tutti i Risvegliati in gabbia! Una volta che i cani rabbiosi si liberano, mordono sempre per primo il loro padrone!"
  },
  Voice_5606_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_5606_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_5607_AwakerVoiceContent = {
    Text = "Sono arrivata con un'ora di ritardo a questo incontro — e la colpa è di quegli insulsi benpensanti che hanno abolito la schiavitù! Ora non c'è più nessuno che mi pettini i capelli!"
  },
  Voice_5607_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_5607_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_5608_AwakerVoiceContent = {
    Text = "Incredibile. Il mio Focolare è perito in questo modo... Era la grande Roma! Devi averne sentito parlare!"
  },
  Voice_5608_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_5608_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_5609_AwakerVoiceContent = {
    Text = "Bene, iniziamo alla grande!"
  },
  Voice_5609_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_5610_AwakerVoiceContent = {
    Text = "Siate testimoni della Sua Benedizione."
  },
  Voice_5610_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5611_AwakerVoiceContent = {
    Text = "Tieniti la tua pietà! La disprezzo, e non ho assolutamente bisogno della compassione di nessuno! Se continui a guardarmi così, semplicemente non riuscirò a resistere dal tormentarti. Non vuoi che le cose sfuggano di mano, vero? Quindi, sii un bravo Schiavo, ascolta, e diventa obbedientemente il mio Gladiatore..."
  },
  Voice_5611_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_5611_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_5612_AwakerVoiceContent = {
    Text = "Non chiedermelo di nuovo! Fui negligente, lasciai fuggire il Gladiatore, e la mia intera famiglia fu sterminata! Fummo ridotti in Ceneri, come l'Impero Romano!"
  },
  Voice_5612_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_5612_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_5613_AwakerVoiceContent = {
    Text = "Rispetto agli altri, Nymphaea è semplicemente una persona ordinaria, senza traguardi né valore. Perché sono diventata una Risvegliatrice... deve essere per qualche piccolo, umile desiderio."
  },
  Voice_5613_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_5614_AwakerVoiceContent = {
    Text = "Oggi ho infranto di nuovo le regole della scuola, arrivando in classe con cinque minuti di ritardo... Pertanto, chiedo sinceramente la punizione più severa, preferibilmente inflitta da te in persona."
  },
  Voice_5614_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_5615_AwakerVoiceContent = {
    Text = "Anche gli attrezzi hanno bisogno di manutenzione. Un set di attrezzi a portata di mano è l'anima di un meccanico."
  },
  Voice_5615_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_5615_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_5616_AwakerVoiceContent = {
    Text = "(Sopportare con disprezzo)"
  },
  Voice_5616_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_5617_AwakerVoiceContent = {
    Text = "Se dovesse ripetersi, presenterò richiesta per la tua sospensione disciplinare."
  },
  Voice_5617_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_5618_AwakerVoiceContent = {
    Text = "I miei doveri vanno ben oltre il combattimento. Anche durante l'Eone Archeano, avevo ben altro da fare che starmene con le mani in mano... Ehi, non dirmi che mi consideri solo una bruta che sa soltanto menare fendenti di spada?!"
  },
  Voice_5618_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul lavoro"
  },
  Voice_5619_AwakerVoiceContent = {
    Text = "Quando le persone mi si avvicinano, ricordano sempre le loro Memorie più tristi e non possono fare a meno di versare lacrime. Qualcuno come me può ancora sperare di crescere?"
  },
  Voice_5619_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_5619_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_5620_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_5621_AwakerVoiceContent = {
    Text = "Che te ne pare?"
  },
  Voice_5621_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_5622_AwakerVoiceContent = {
    Text = "Questo posto è molto meglio della lurida e puzzolente Prigione di New Gate! Che ci si sdrai sul divano o ci si stringa in un angolo, è tutto piuttosto confortevole, non trovi?"
  },
  Voice_5622_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_5623_AwakerVoiceContent = {Text = "Brown...!"},
  Voice_5623_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_5624_AwakerVoiceContent = {
    Text = "La mia vite... dov'è finita..."
  },
  Voice_5624_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_5625_AwakerVoiceContent = {
    Text = "Ehi! Così è barare!"
  },
  Voice_5625_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_5626_AwakerVoiceContent = {
    Text = "Dove sono finite le mie viti?!"
  },
  Voice_5626_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5627_AwakerVoiceContent = {
    Text = "Scorri per me, fiume di stelle..."
  },
  Voice_5627_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5628_AwakerVoiceContent = {
    Text = "Aurita non sopporta quando gli amici se ne vanno all'improvviso... Ma, se fanno Ritorno, li perdonerò!"
  },
  Voice_5628_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_5629_AwakerVoiceContent = {
    Text = "Una donna che attraverserebbe l'oceano da sola non è sempre un essere divino. È altrettanto probabile che sia pazza. Ho scambiato Miryam per una dea, ed è stato un errore stupido."
  },
  Voice_5629_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Miryam"
  },
  Voice_5629_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risveglio \"Miryam\""
  },
  Voice_5630_AwakerVoiceContent = {Text = "Certo."},
  Voice_5630_AwakerVoiceTitle = {
    Text = "Abilità Speciale: I"
  },
  Voice_56313_AwakerVoiceContent = {
    Text = "Ho osservato di nascosto lo spettacolo di magia della Sig.na Casiah. La sua esibizione ha portato tanta gioia al pubblico, ma io porto sempre tristezza... Credete che lacrime e sorrisi abbiano lo stesso valore? Forse..."
  },
  Voice_56313_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Casiah"
  },
  Voice_56313_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Casiah\""
  },
  Voice_56314_AwakerVoiceContent = {
    Text = "Poesia, fiamme e pianto si somigliano; vi avvolgono senza preavviso... Quando tornate in voi, siete già immersi nel Mondo di Poesia..."
  },
  Voice_56314_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_56315_AwakerVoiceContent = {
    Text = "Lascia che i versi del passato risveglino il giardino nascosto nel tuo cuore."
  },
  Voice_56315_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_56316_AwakerVoiceContent = {
    Text = "Poesia e fiori sono probabilmente la stessa cosa, non credete? Entrambi effimeri eppure eterni. In questo mondo sconfinato, catturano gli istanti più indimenticabili in un piccolo spazio... Credo che tutti siano ammutoliti dinanzi a una poesia, così come si fermano ad ammirare la fioritura di un fiore."
  },
  Voice_56316_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito dei suoi Poema"
  },
  Voice_56317_AwakerVoiceContent = {
    Text = "Quasi dimenticavo... Che fiori sbocciano a Cité in questa stagione?"
  },
  Voice_56317_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito di Cité"
  },
  Voice_56318_AwakerVoiceContent = {
    Text = "La vostra presenza ha ravvivato l'inchiostro nella mia penna, permettendogli di fluire ancora come un dolce ruscello. Continuerò a comporre poesie per la vostra storia."
  },
  Voice_56318_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito del Custode - 1"
  },
  Voice_56319_AwakerVoiceContent = {
    Text = "La bellezza dei fiori in boccio è pari alla tristezza del loro appassire. Per quante volte provi dolore, non posso fare a meno di fermarmi a piangerli. Se li ignorassi per paura della sofferenza, quanto sarebbero tristi questi fiori..."
  },
  Voice_56319_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito del suo Pain"
  },
  Voice_5631_AwakerVoiceContent = {
    Text = "Per studiare la struttura interna di questo corpo mentre Erica \"dorme\", Winkle ha chiesto che io riposi nel suo ufficio di notte. Dovrei menzionare che Erica mantiene una parte della sua coscienza mentre dorme?"
  },
  Voice_5631_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Winkle"
  },
  Voice_5631_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Winkle\""
  },
  Voice_56320_AwakerVoiceContent = {
    Text = "Madame Sorel è davvero splendida. La sua forza e sicurezza, il suo sorriso aggraziato di fronte al destino, e la sua vitalità vibrante eppure tenace — tutto ciò mi riempie d'invidia."
  },
  Voice_56320_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Sorel"
  },
  Voice_56320_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Sorel\""
  },
  Voice_56321_AwakerVoiceContent = {
    Text = "Ieri ho scritto una nuova poesia, ma non l'ho ancora mostrata a nessuno. Non è un granché, ma... {Male=Sig.,Female=Sig.na} Custode, sareste disposto a darle un'occhiata?"
  },
  Voice_56321_AwakerVoiceTitle = {
    Text = "Chat: A proposito del Custode - 2"
  },
  Voice_56322_AwakerVoiceContent = {
    Text = "Il Club di Poesia degli Studenti di Mythag vorrebbe che fossi la loro consulente... Non posso accettare. Non desidero smorzare il loro spirito, ma temo che porterei loro solo delusione e scoramento."
  },
  Voice_56322_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_56323_AwakerVoiceContent = {
    Text = "Non c'è nulla in questo mondo da odiare. Gli anni dorati meritano lode, mentre il declino della vecchiaia merita pietà; lo splendore della giovinezza è invidiabile, mentre i frammenti logori ispirano riflessione."
  },
  Voice_56323_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_56324_AwakerVoiceContent = {
    Text = "Ogni volta che vedo la Sig.na Nymphaea, mi torna in mente quel dipinto di ninfee. Porta con sé l'amara quiete e la fragranza delle ninfee... Chissà com'è davvero il suo mondo?"
  },
  Voice_56324_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito di Nymphaea"
  },
  Voice_56324_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Nymphaea\""
  },
  Voice_56325_AwakerVoiceContent = {
    Text = "Ho sempre avvertito la presenza di \"fantasmi\" intorno a me, come una possessione o un incantesimo inspiegabile, che prosciuga la mia speranza nel mondo. Ma se si tratta di fantasmi, come si spiega il latte e l'acqua che svaniscono nel nulla...?"
  },
  Voice_56325_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito dei fantasmi"
  },
  Voice_56326_AwakerVoiceContent = {
    Text = "Il mio corpo non è stato intaccato dalla Dissoluzione; quei liquidi neri sono semplicemente inchiostro. Ma a dire il vero, anche senza la Dissoluzione, tutto alla fine si tramuta in Illusione, non è così?"
  },
  Voice_56326_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_56327_AwakerVoiceContent = {
    Text = "Nel Keygrave, ho visto il vostro nome su una delle lapidi... Le memorie della vita erano dolorose, ma non ho mai inteso dimenticarle. Per il Custode, quelle memorie perdute devono essere altrettanto preziose, vero?"
  },
  Voice_56327_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito delle Memorie passate"
  },
  Voice_56328_AwakerVoiceContent = {
    Text = "Se la poesia esiste per celebrare la bellezza, allora la sua stessa esistenza è poesia. Quando inizia a cantare, comprendo d'un tratto ciò che gli anziani descrivevano come la voce di un usignolo..."
  },
  Voice_56328_AwakerVoiceTitle = {
    Text = "Chat: A proposito della Tintura"
  },
  Voice_56328_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Tinct\""
  },
  Voice_56329_AwakerVoiceContent = {
    Text = "Quella splendida ballerina... Le sue fiamme verde smeraldo sono irresistibili, anche se riducono in cenere..."
  },
  Voice_56329_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito di Liz"
  },
  Voice_56329_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Liz\""
  },
  Voice_5632_AwakerVoiceContent = {
    Text = "Quindi d'ora in poi mi nutrirò di questo al posto di Sepirot?"
  },
  Voice_5632_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_5633_AwakerVoiceContent = {
    Text = "Delizioso. Assolutamente delizioso."
  },
  Voice_5633_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_5634_AwakerVoiceContent = {
    Text = "Cosa desideri in cambio, caro ospite?"
  },
  Voice_5634_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_5635_AwakerVoiceContent = {
    Text = "Svelto, sbrigati! Non restare per strada."
  },
  Voice_5635_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_5636_AwakerVoiceContent = {
    Text = "Sacrificio inevitabile."
  },
  Voice_5636_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_5637_AwakerVoiceContent = {
    Text = "(Un gemito soffocato di sopportazione)"
  },
  Voice_5637_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_56386_AwakerVoiceContent = {
    Text = "Input corrente completo. Emissione in corso."
  },
  Voice_56386_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_56387_AwakerVoiceContent = {
    Text = "Non sfidare il miglior ladro di Londinium!"
  },
  Voice_56387_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_56388_AwakerVoiceContent = {
    Text = "Ecco il Tributo d'apertura!"
  },
  Voice_56388_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_56389_AwakerVoiceContent = {
    Text = "Il Miraggio dai Mille Volti è qui!"
  },
  Voice_56389_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_5638_AwakerVoiceContent = {
    Text = "Si avvicina..."
  },
  Voice_5638_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_5638_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_56390_AwakerVoiceContent = {
    Text = "Sprofonda e brucia! Danza verso la distruzione!"
  },
  Voice_56390_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_56391_AwakerVoiceContent = {
    Text = "Questa è la città dove innumerevoli anime perdute vagano, per sempre incapaci di ritrovare la via di casa."
  },
  Voice_56391_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_56392_AwakerVoiceContent = {
    Text = "Ecco il mio ultimo residuo di potere di spostamento... Prendilo!"
  },
  Voice_56392_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_56393_AwakerVoiceContent = {
    Text = "Non sfidare il miglior ladro di Londinium!"
  },
  Voice_56393_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_5639_AwakerVoiceContent = {
    Text = "È un nemico? Per favore, ordinami di attaccare.\nIl tuo nemico è la melma nera... Allora... Sono anch'io un tuo nemico?"
  },
  Voice_5639_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_5640_AwakerVoiceContent = {
    Text = "Erica l'Automa, Busto N. EA307881, Motore N. MF311028. È un piacere essere al vostro servizio."
  },
  Voice_5640_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5641_AwakerVoiceContent = {
    Text = "Combattete! Non lasciate nulla in piedi!"
  },
  Voice_5641_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_5642_AwakerVoiceContent = {
    Text = "Salve, io sono... Ehm... Puoi dirmi il mio nome?"
  },
  Voice_5642_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5643_AwakerVoiceContent = {
    Text = "Dopo essere arrivata a scuola, ho finalmente compreso la malattia chiamata Dissoluzione che mi aveva infettata. I miei genitori mi tenevano sempre lontana dall'oceano quand'ero in vita, e ora sembra che questa infezione possa davvero essere legata alla mia vicinanza al mare..."
  },
  Voice_5643_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_5644_AwakerVoiceContent = {
    Text = "Va bene. Non ti deluderò... Promesso."
  },
  Voice_5644_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_5645_AwakerVoiceContent = {
    Text = "Ah, il mio respiro rovente..."
  },
  Voice_5645_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_5646_AwakerVoiceContent = {Text = "Vai."},
  Voice_5646_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5647_AwakerVoiceContent = {Text = "Piroetta."},
  Voice_5647_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_5648_AwakerVoiceContent = {Text = "Ehi!"},
  Voice_5648_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5650_AwakerVoiceContent = {
    Text = "Il giorno è finalmente giunto..."
  },
  Voice_5650_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_5651_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5651_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5652_AwakerVoiceContent = {
    Text = "Non ho ancora finito... Che ne dici di alzarti, così posso ucciderti di nuovo?"
  },
  Voice_5652_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_5654_AwakerVoiceContent = {
    Text = "Custode, devo parlarti. Prima di ottenere la vittoria finale, certi individui non dovrebbero concedersi tali stravaganze. Ricorda, io non combatto per la vita lussuosa di gente simile!"
  },
  Voice_5654_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Sorel"
  },
  Voice_5654_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Sorel\""
  },
  Voice_5655_AwakerVoiceContent = {
    Text = "Se venissi presa come Ospite, quale crudele Fato mi attenderebbe?"
  },
  Voice_5655_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_5656_AwakerVoiceContent = {Text = "Osserva!"},
  Voice_5656_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_5657_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_5657_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_5658_AwakerVoiceContent = {
    Text = "Phew... ho così tanto sonno. Hai preparato dei rinfreschi decenti prima che vada a riposare?"
  },
  Voice_5658_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_5659_AwakerVoiceContent = {
    Text = "Mamma, vuoi accarezzarli? Dicono che siano molto morbidi."
  },
  Voice_5659_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_5659_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_5660_AwakerVoiceContent = {
    Text = "Hehehe, lalalla~ Pulire, pulire, adoro pulire, adoro tantissimo pulire~"
  },
  Voice_5660_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul lavoro"
  },
  Voice_5661_AwakerVoiceContent = {
    Text = "(Gemiti di dolore)"
  },
  Voice_5661_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_5662_AwakerVoiceContent = {
    Text = "Hmm... Niente male."
  },
  Voice_5662_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_5663_AwakerVoiceContent = {
    Text = "(Gemiti di dolore)"
  },
  Voice_5663_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_5664_AwakerVoiceContent = {
    Text = "(Gemiti di dolore)"
  },
  Voice_5664_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_5665_AwakerVoiceContent = {
    Text = "Rabbia Ardente!"
  },
  Voice_5665_AwakerVoiceTitle = {
    Text = "Abilità Speciale: I"
  },
  Voice_5666_AwakerVoiceContent = {
    Text = "Ne ho visti molti impazzire per la Dissoluzione. La verità è che sono già abbastanza folle di mio. Scommetto che quella roba non può farmi nulla."
  },
  Voice_5666_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_5667_AwakerVoiceContent = {
    Text = "Heh... Hahaha!"
  },
  Voice_5667_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5668_AwakerVoiceContent = {
    Text = "Buoni strumenti sono metà del successo!"
  },
  Voice_5668_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_5669_AwakerVoiceContent = {
    Text = "Sembra una rinascita."
  },
  Voice_5669_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_5670_AwakerVoiceContent = {
    Text = "Niente male."
  },
  Voice_5670_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_5671_AwakerVoiceContent = {
    Text = "Ora la mia lama canta di potere!"
  },
  Voice_5671_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_5672_AwakerVoiceContent = {
    Text = "Bilanciare le presenze, mantenere i progressi nella ricerca e completare gli incarichi didattici. Sembra che l'esperimento di compressione temporale inversa richieda priorità immediata."
  },
  Voice_5672_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_5672_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_5673_AwakerVoiceContent = {
    Text = "Un passo più vicini a partire ufficialmente per l'avventura!"
  },
  Voice_5673_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_5674_AwakerVoiceContent = {
    Text = "Non farmi avvicinare all'acqua, d'accordo? Non vorrei che questo delizioso, ardente amore che provo per te venisse... estinto."
  },
  Voice_5674_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_5675_AwakerVoiceContent = {
    Text = "Combattere fino alla Fine!"
  },
  Voice_5675_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5676_AwakerVoiceContent = {
    Text = "Il tuo coraggio è davvero encomiabile. Guarda questi tentacoli — non temi la follia che portano con sé?"
  },
  Voice_5676_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_5676_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_5677_AwakerVoiceContent = {Text = "Ahi!"},
  Voice_5677_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_5678_AwakerVoiceContent = {Text = "Ahi..."},
  Voice_5678_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_5679_AwakerVoiceContent = {
    Text = "Per favore, fermati!"
  },
  Voice_5679_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_5680_AwakerVoiceContent = {
    Text = "Vuoi toccarlo? Il mio cuore batte grazie alla tua presenza."
  },
  Voice_5680_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_5680_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_5681_AwakerVoiceContent = {
    Text = "Cinguettano felici. Grazie, Padrone."
  },
  Voice_5681_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_5681_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_5682_AwakerVoiceContent = {
    Text = "Una sensazione calda e dolce nel petto... Lily, Lily è così felice, le lacrime stanno...\nMamma, festeggiamo insieme."
  },
  Voice_5682_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_5682_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_5683_AwakerVoiceContent = {
    Text = "Sono felice al tuo fianco, Mamma."
  },
  Voice_5683_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_5683_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_5684_AwakerVoiceContent = {
    Text = "Sono piena... Ho la pancia piena.\nLily diventerà più forte dopo questo rituale?"
  },
  Voice_5684_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_5684_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_5685_AwakerVoiceContent = {
    Text = "Amo il mare. È ironico? Tutto ciò che possedevo giace ora sommerso nel mare profondo..."
  },
  Voice_5685_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_5686_AwakerVoiceContent = {
    Text = "Fai attenzione!"
  },
  Voice_5686_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_5687_AwakerVoiceContent = {
    Text = "Cose che odio...? Nessuna. Odieresti forse un granello di polvere o una foglia?"
  },
  Voice_5687_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_5688_AwakerVoiceContent = {
    Text = "Ho rifiutato alcune volte gli inviti al banchetto della cameriera. Sembrava un po' triste... Ma rispetto al semplice divertimento, la vostra sicurezza, mio signore, è di gran lunga più importante!"
  },
  Voice_5688_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Karen"
  },
  Voice_5688_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risveglio \"Karen\""
  },
  Voice_5689_AwakerVoiceContent = {
    Text = "Un signore è la ragione stessa dell'esistenza di un Cavaliere, perciò vi prego, non esitate a impartirmi i vostri comandi!"
  },
  Voice_5689_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_5690_AwakerVoiceContent = {
    Text = "...Potremmo aver bisogno di una chiave dinamometrica per questo... Hmm, scusa, mi hai appena chiamato?"
  },
  Voice_5690_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_5691_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_5692_AwakerVoiceContent = {Text = "Come osi!"},
  Voice_5692_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_5693_AwakerVoiceContent = {
    Text = "(Un elegante, soffocato sussulto di dolore)"
  },
  Voice_5693_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_5694_AwakerVoiceContent = {
    Text = "(Un gemito soffocato di sopportazione)"
  },
  Voice_5694_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_5695_AwakerVoiceContent = {
    Text = "Basta così."
  },
  Voice_5695_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_5696_AwakerVoiceContent = {
    Text = "Sii gentile."
  },
  Voice_5696_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_5697_AwakerVoiceContent = {
    Text = "Ugh, è ancora piuttosto difficile concentrarsi..."
  },
  Voice_5697_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_5698_AwakerVoiceContent = {
    Text = "Di notte resta spesso vicina a me. Sarà semplicemente perché la mia testa è troppo vistosa?"
  },
  Voice_5698_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Winkle"
  },
  Voice_5698_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Winkle\""
  },
  Voice_5699_AwakerVoiceContent = {
    Text = "Ho sempre atteso l'avvento della distruzione, senza mai considerare la \"resistenza\"... Aiuterai la mia anima superficiale ad attraversare l'abisso? Persino in un mondo in cui sono sopravvissuta per un soffio, tu mi concedi ancora la salvezza..."
  },
  Voice_5699_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_5699_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_5700_AwakerVoiceContent = {
    Text = "Poiché mi sono Risvegliata come tua apostola, non cerco altro che la tua pace e la tua gioia, questo è il mio desiderio... Ugh... Ahh... Sì, sì, desidero la sopravvivenza, la perseveranza, la riproduzione, dobbiamo vivere, VIVERE..."
  },
  Voice_5700_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_5700_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_5701_AwakerVoiceContent = {
    Text = "Perché non ti perdi nel mio amore? Non mi hai risvegliata per il calore del mio abbraccio?"
  },
  Voice_5701_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_5701_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_5702_AwakerVoiceContent = {
    Text = "Hmm? Diffidi di me, una donna dalle origini sconosciute? Molto bene... Fui la regina deposta di Ninive, la donna di Shinar che graffiò le porte del cielo, e la bambina a cui fu rubata la coscienza sotto il ramo sacro dell'Eufrate... Da dove vuoi che cominci, mio diffidente?"
  },
  Voice_5702_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_5702_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_5703_AwakerVoiceContent = {
    Text = "Perché mi eviti sempre? Sei timido? Che dolcezza, questa riluttanza ad affrontare i tuoi desideri."
  },
  Voice_5703_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_5703_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_5704_AwakerVoiceContent = {
    Text = "Questo posto è assolutamente orribile! Come osano pretendere che condivida un tavolo per il tè pomeridiano! ...I biscotti fatti in casa sono accettabili, però. Fatene portare un piatto in camera mia dopo cena."
  },
  Voice_5704_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_5705_AwakerVoiceContent = {Text = "Heyo!"},
  Voice_5705_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5706_AwakerVoiceContent = {Text = "Osserva!"},
  Voice_5706_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_5707_AwakerVoiceContent = {
    Text = "Dissoluzione... Sì, ci sono documenti a riguardo nelle scuole della mia città natale, ma, beh, odio leggere. Non ricordo nulla!"
  },
  Voice_5707_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_5708_AwakerVoiceContent = {
    Text = "Desideri che io spieghi le vele ancora una volta? Sono disposta a farlo... se non ti pesa il mio passato fallimento."
  },
  Voice_5708_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_5708_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_5709_AwakerVoiceContent = {
    Text = "Cose che non sopporto? A bizzeffe. Boss che ti fanno lavorare fino a tardi, suore piene di sé, stomaci che brontolano, pane nero pieno di vetro..."
  },
  Voice_5709_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_5710_AwakerVoiceContent = {
    Text = "È tutta colpa mia... Tutto è colpa mia..."
  },
  Voice_5710_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_5711_AwakerVoiceContent = {
    Text = "Poniamo fine a tutto questo, ora!"
  },
  Voice_5711_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5712_AwakerVoiceContent = {
    Text = "Grazie alla signorina Hannah, ho potuto assistere alle prove del coro. Gli inni e le canzoni marinaresche sono piuttosto diversi; durante i miei anni di benedizione delle navigazioni, non ho mai udito una melodia così singolare..."
  },
  Voice_5712_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_5713_AwakerVoiceContent = {
    Text = "PRENDI QUESTO!"
  },
  Voice_5713_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_5714_AwakerVoiceContent = {
    Text = "PRENDI QUESTO!"
  },
  Voice_5714_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5715_AwakerVoiceContent = {
    Text = "Waah, che paura!"
  },
  Voice_5715_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_5716_AwakerVoiceContent = {Text = "Ugh..."},
  Voice_5716_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_5717_AwakerVoiceContent = {
    Text = "Salve, mio caro nuovo Padrone! Il menu di oggi comprende budino di lumache, stufato di rospo e vino di fiamma verde. Cosa gradite?"
  },
  Voice_5717_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5718_AwakerVoiceContent = {
    Text = "Quella è ciò che chiamano una Forma Genesi...? No, è un po' diversa da come l'avevo immaginata. Ma se potessi diventare così, sarebbe grandioso."
  },
  Voice_5718_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla stirpe del Mare profondo"
  },
  Voice_5718_UnlockDesc = {
    Text = "Si sblocca dopo aver acquisito uno qualsiasi dei Risvegliatori: \"Tulu\", \"Murphy\", \"Miryam\" o \"Golia\"."
  },
  Voice_5719_AwakerVoiceContent = {
    Text = "Aspetta il momento giusto."
  },
  Voice_5719_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_5720_AwakerVoiceContent = {Text = "Osserva!"},
  Voice_5720_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5721_AwakerVoiceContent = {
    Text = "Agnelli, la volontà del Padre di Tutto vi redimerà."
  },
  Voice_5721_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_5722_AwakerVoiceContent = {
    Text = "Agnelli, la volontà del Padre di Tutto vi redimerà."
  },
  Voice_5722_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_5723_AwakerVoiceContent = {Text = "Muori!"},
  Voice_5723_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5724_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5724_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5725_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_5725_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5726_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5726_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5727_AwakerVoiceContent = {
    Text = "È una donna patetica, destinata a essere tormentata dal fato. La compatisco, in un certo senso, poiché in occasione della Sua vera Nascita, le concederò la misericordia della morte."
  },
  Voice_5727_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Miryam"
  },
  Voice_5727_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risveglio \"Miryam\""
  },
  Voice_5728_AwakerVoiceContent = {
    Text = "Macchiati di sangue!"
  },
  Voice_5728_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5729_AwakerVoiceContent = {
    Text = "Vendetta...!"
  },
  Voice_5729_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_5730_AwakerVoiceContent = {Text = "Fa male..."},
  Voice_5730_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_5731_AwakerVoiceContent = {
    Text = "(Gemito di dolore soffocato)"
  },
  Voice_5731_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_5732_AwakerVoiceContent = {
    Text = "(Gemito di dolore soffocato)"
  },
  Voice_5732_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_5733_AwakerVoiceContent = {Text = "Ahi..."},
  Voice_5733_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_5734_AwakerVoiceContent = {
    Text = "Vorresti sprofondare insieme a me?"
  },
  Voice_5734_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_5735_AwakerVoiceContent = {Text = "Vattene!"},
  Voice_5735_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_5736_AwakerVoiceContent = {
    Text = "Cose che detesto... una scrivania disordinata, un armadio in disordine, davanzali impolverati — sì, sto descrivendo la tua stanza. Entro le 7 di domani mattina, pretendo che sia riportata allo stato precedente alla tua occupazione."
  },
  Voice_5736_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_5737_AwakerVoiceContent = {
    Text = "(Canticchia con interesse)"
  },
  Voice_5737_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_5738_AwakerVoiceContent = {
    Text = "Interessante!"
  },
  Voice_5738_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_5739_AwakerVoiceContent = {
    Text = "(Sbuffa con disprezzo)"
  },
  Voice_5739_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_5740_AwakerVoiceContent = {
    Text = "Se la situazione lo richiede, posso lasciare la Culla anch'io..."
  },
  Voice_5740_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_5741_AwakerVoiceContent = {
    Text = "Bisognosi di attenzioni, eh?"
  },
  Voice_5741_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_5742_AwakerVoiceContent = {
    Text = "Prendete questo!"
  },
  Voice_5742_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5743_AwakerVoiceContent = {
    Text = "Raddoppia! Raddoppia ancora!"
  },
  Voice_5743_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_5744_AwakerVoiceContent = {
    Text = "Questo mi ricorda il primo paio di scarpette da ballo rosse che ricevetti quando avevo otto anni. Le adoro davvero. Grazie, Custode."
  },
  Voice_5744_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_5744_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_5745_AwakerVoiceContent = {
    Text = "Cosa sono... gli amici? Padrone? Mamma?"
  },
  Voice_5745_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_5746_AwakerVoiceContent = {
    Text = "Dunque anche la mia protezione, a volte, può fallire..."
  },
  Voice_5746_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_5747_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_5747_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_5748_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_5748_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_5749_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_5749_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_5750_AwakerVoiceContent = {
    Text = "Preferenze? Qualcuno me lo chiese una volta, sui campi di battaglia del Peloponneso... È troppo tardi. Ho abbandonato da tempo simili predilezioni personali."
  },
  Voice_5750_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_5751_AwakerVoiceContent = {
    Text = "Shh... Per favore, non lasciate che \"loro\" scoprano che sto diventando più forte."
  },
  Voice_5751_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_5752_AwakerVoiceContent = {
    Text = "\"Loro\" hanno tutti detto... Grazie."
  },
  Voice_5752_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_5753_AwakerVoiceContent = {
    Text = "Uh... Cos'è questo?"
  },
  Voice_5753_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_5754_AwakerVoiceContent = {
    Text = "Questo mi avvicinerà soltanto all'Abisso."
  },
  Voice_5754_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_5754_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_5755_AwakerVoiceContent = {
    Text = "Tu sei il mio amato servitore. So che tu lo chiami amico, compagno, camerata... Chiamalo come preferisci."
  },
  Voice_5755_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_5756_AwakerVoiceContent = {
    Text = "Ho ottenuto la mia risposta. Non quella che volevo... ma pur sempre una risposta."
  },
  Voice_5756_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_5756_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_5757_AwakerVoiceContent = {
    Text = "Quella sul tuo volto è paura? O dolore? Davvero affascinante."
  },
  Voice_5757_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_5757_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_5758_AwakerVoiceContent = {
    Text = "Il profumo della morte e dell'annientamento... È così vivido."
  },
  Voice_5758_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_5758_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_5759_AwakerVoiceContent = {
    Text = "Come mi trovo qui? A-abbastanza bene. Finché condivido qualche nozione di scienza meccanica e conoscenza sulla ricerca degli spiriti con la Signorina Doll, mi lascia tenere le luci accese."
  },
  Voice_5759_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_5760_AwakerVoiceContent = {
    Text = "Spero che Jenkin e Brown si stiano godendo il loro tempo all'accademia. I gemelli da polso di mio padre sono insignificanti. Se Jenkin li vuole, può tenerli. Sono sicura che ne abbia un'intera scatola di riserva."
  },
  Voice_5760_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Jenkin"
  },
  Voice_5760_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Jenkin\""
  },
  Voice_5761_AwakerVoiceContent = {
    Text = "Non posso andarmene da qui..."
  },
  Voice_5761_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_5762_AwakerVoiceContent = {
    Text = "Avendo trasceso le razze inferiori, non temo simili influenze. Anche se il corpo dell'Ospite andasse in frantumi, il Nobile lignaggio non perirà."
  },
  Voice_5762_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_5763_AwakerVoiceContent = {
    Text = "Detesto le persone con sorrisi falsi! Non riesci a Rubare alcuna emozione da loro!"
  },
  Voice_5763_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_5764_AwakerVoiceContent = {
    Text = "Hmm? Perché sono tutti in silenzio? Karen odia la quiete. Vi racconto una storia. C'era una volta una montagna..."
  },
  Voice_5764_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_5765_AwakerVoiceContent = {
    Text = "Lily afferrerà il futuro... Tekeli—Li!"
  },
  Voice_5765_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_5766_AwakerVoiceContent = {
    Text = "Lily afferrerà il futuro... Tekeli—Li!"
  },
  Voice_5766_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_5767_AwakerVoiceContent = {
    Text = "Se lo fai per percepire la Sua esistenza, perdonerò temporaneamente la tua insolenza."
  },
  Voice_5767_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_5768_AwakerVoiceContent = {
    Text = "Non voglio farlo..."
  },
  Voice_5768_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5769_AwakerVoiceContent = {
    Text = "Stai indietro!"
  },
  Voice_5769_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_5770_AwakerVoiceContent = {
    Text = "Poco a poco, sto trovando il mio ritmo con i vostri comandi!"
  },
  Voice_5770_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_5771_AwakerVoiceContent = {
    Text = "Mi avvicino sempre più a diventare un vero cavaliere!"
  },
  Voice_5771_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_5772_AwakerVoiceContent = {
    Text = "Vi ringrazio per questo onore, mio signore. Significa moltissimo per me."
  },
  Voice_5772_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_5773_AwakerVoiceContent = {
    Text = "Le terme sono un posto fantastico per passare il tempo! Il cibo è delizioso e offrono servizi di rilassamento muscolare! Sei tentato? Allora costruiscine uno in questa scuola immediatamente!"
  },
  Voice_5773_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_5774_AwakerVoiceContent = {
    Text = "No... N-Non lasciarmi!"
  },
  Voice_5774_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5775_AwakerVoiceContent = {Text = "Pronta."},
  Voice_5775_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5776_AwakerVoiceContent = {
    Text = "(Un'inspirazione sommessa, trattenuta)"
  },
  Voice_5776_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_5777_AwakerVoiceContent = {
    Text = "(Sopportare con disprezzo)"
  },
  Voice_5777_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_5778_AwakerVoiceContent = {
    Text = "(Sopportare con disprezzo)"
  },
  Voice_5778_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_5779_AwakerVoiceContent = {
    Text = "(Sopportare con disprezzo)"
  },
  Voice_5779_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_5780_AwakerVoiceContent = {
    Text = "Lascia fare a me."
  },
  Voice_5780_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_57818_AwakerVoiceContent = {
    Text = "Tutti coloro che mi hanno insultato ne pagheranno il prezzo!"
  },
  Voice_57818_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_57819_AwakerVoiceContent = {
    Text = "Tutti coloro che mi hanno insultato ne pagheranno il prezzo!"
  },
  Voice_57819_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_5781_AwakerVoiceContent = {
    Text = "Lascia fare a me."
  },
  Voice_5781_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_57820_AwakerVoiceContent = {
    Text = "Nessuno può fermare i miei passi verso la ricerca della terra natia!"
  },
  Voice_57820_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_57821_AwakerVoiceContent = {
    Text = "Goditi questo festino di massacro! Fino all'ultimo respiro!"
  },
  Voice_57821_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_57822_AwakerVoiceContent = {
    Text = "Nessuno può fermare i miei passi verso la ricerca della terra natia!"
  },
  Voice_57822_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_57823_AwakerVoiceContent = {
    Text = "False missioni, destini prestabiliti... li combatterò fino alla fine!"
  },
  Voice_57823_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_57824_AwakerVoiceContent = {
    Text = "False missioni, destini prestabiliti... li combatterò fino alla fine!"
  },
  Voice_57824_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_57825_AwakerVoiceContent = {
    Text = "Goditi questo festino di massacro! Fino all'ultimo respiro!"
  },
  Voice_57825_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_57826_AwakerVoiceContent = {
    Text = "Unisciti al mio rituale e diventa il mio seme!"
  },
  Voice_57826_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_57827_AwakerVoiceContent = {
    Text = "Traditore, assapora la mia disperazione e la mia rabbia!"
  },
  Voice_57827_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_57828_AwakerVoiceContent = {
    Text = "Traditore, assapora la mia disperazione e la mia rabbia!"
  },
  Voice_57828_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_57829_AwakerVoiceContent = {
    Text = "Unisciti al mio rituale e diventa il mio seme!"
  },
  Voice_57829_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_5782_AwakerVoiceContent = {
    Text = "Mi sono vergognata troppo per dire ad Aurita che non sono così giovane come crede. Non sono la sua \"sorellina\". Potresti forse accennarglielo tu?"
  },
  Voice_5782_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Aurita"
  },
  Voice_5782_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Aurita\""
  },
  Voice_57830_AwakerVoiceContent = {
    Text = "La Città perduta di Lemuria, a lungo dimenticata, è finalmente svelata."
  },
  Voice_57830_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_57831_AwakerVoiceContent = {
    Text = "La Città perduta di Lemuria, a lungo dimenticata, è finalmente svelata."
  },
  Voice_57831_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_57832_AwakerVoiceContent = {
    Text = "L'ora è giunta. La mia promessa sarà mantenuta."
  },
  Voice_57832_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_57833_AwakerVoiceContent = {
    Text = "L'ora è giunta. La mia promessa sarà mantenuta."
  },
  Voice_57833_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_57834_AwakerVoiceContent = {
    Text = "Tutto ciò fa parte del Suo piano divino."
  },
  Voice_57834_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_57835_AwakerVoiceContent = {
    Text = "Tutto ciò fa parte del Suo piano divino."
  },
  Voice_57835_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_57836_AwakerVoiceContent = {
    Text = "La Presenza delle Stelle porge il suo invito... a voi."
  },
  Voice_57836_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_57837_AwakerVoiceContent = {
    Text = "Io sono ancora... il Colore venuto dallo Spazio!"
  },
  Voice_57837_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_57838_AwakerVoiceContent = {
    Text = "Io sono ancora... il Colore venuto dallo Spazio!"
  },
  Voice_57838_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_57839_AwakerVoiceContent = {
    Text = "La Presenza delle Stelle porge il suo invito... a voi."
  },
  Voice_57839_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_5783_AwakerVoiceContent = {Text = "Indietro!"},
  Voice_5783_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_57840_AwakerVoiceContent = {
    Text = "Tutti, attacchiamo insieme!"
  },
  Voice_57840_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_57841_AwakerVoiceContent = {
    Text = "Il Dio del Labirinto Sotterraneo pronuncia il suo Giudizio su tutti voi!"
  },
  Voice_57841_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_57842_AwakerVoiceContent = {
    Text = "Il Dio del Labirinto Sotterraneo pronuncia il suo Giudizio su tutti voi!"
  },
  Voice_57842_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_57843_AwakerVoiceContent = {
    Text = "Uccello che plani nel cielo azzurro, ti prego, ascolta la mia preghiera."
  },
  Voice_57843_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_57844_AwakerVoiceContent = {
    Text = "Uccello che plani nel cielo azzurro, ti prego, ascolta la mia preghiera."
  },
  Voice_57844_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_57845_AwakerVoiceContent = {
    Text = "Non muoverti! Non muoverti! No!"
  },
  Voice_57845_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_57846_AwakerVoiceContent = {
    Text = "Tremate sotto le catene di sangue... Perite sotto le catene di sangue!"
  },
  Voice_57846_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_57847_AwakerVoiceContent = {
    Text = "Tremate sotto le catene di sangue... Perite sotto le catene di sangue!"
  },
  Voice_57847_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_57848_AwakerVoiceContent = {
    Text = "Tutti, attacchiamo insieme!"
  },
  Voice_57848_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_57849_AwakerVoiceContent = {
    Text = "Non muoverti! Non muoverti! No!"
  },
  Voice_57849_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_5784_AwakerVoiceContent = {Text = "Hehe..."},
  Voice_5784_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_57850_AwakerVoiceContent = {
    Text = "Contemplate! Questo è il Potere su cui i Filistei fanno affidamento!"
  },
  Voice_57850_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_57851_AwakerVoiceContent = {
    Text = "Contemplate! Questo è il Potere su cui i Filistei fanno affidamento!"
  },
  Voice_57851_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_5785_AwakerVoiceContent = {
    Text = "Troppo debole."
  },
  Voice_5785_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_5786_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5786_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_5787_AwakerVoiceContent = {
    Text = "Hmm... Il Padrone sembra triste? Lascia che Karen ti tiri su il morale con una faccia buffa, hehe! Ti senti meglio adesso?"
  },
  Voice_5787_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_5788_AwakerVoiceContent = {
    Text = "Svela i misteri del mondo con l'intelletto umano!"
  },
  Voice_5788_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_5789_AwakerVoiceContent = {
    Text = "Ho incontrato degli individui inquietanti nel corridoio. Le circostanze potrebbero costringerti a collaborare con loro, ma resta vigile! Il cuore umano è più crudele della guerra, e i peggiori tradimenti vengono spesso dall'interno."
  },
  Voice_5789_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito di @2"
  },
  Voice_5789_UnlockDesc = {
    Text = "Si sblocca dopo aver acquisito il Risvegliatore \"Helot\" o \"Lily\""
  },
  Voice_5790_AwakerVoiceContent = {
    Text = "Hai finito il compito, giusto? Puoi venire con me in centro... Eh? Non hai ancora finito i compiti di matematica?! Ah... scusa, non pensavo che qualcuno non capisse il calcolo infinitesimale... Lascia che ti aiuti."
  },
  Voice_5790_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sullo studio"
  },
  Voice_5791_AwakerVoiceContent = {
    Text = "Vi giuro, quella bottegaia è sicuramente apparsa in uno dei salon di Fontainebleau... Capisco, il suo aspetto non è cambiato. Chissà quanti segreti potremo scambiare con lei?"
  },
  Voice_5791_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Daffodil"
  },
  Voice_5791_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Daffodil\""
  },
  Voice_5792_AwakerVoiceContent = {
    Text = "(Esclamazione)"
  },
  Voice_5792_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_5793_AwakerVoiceContent = {
    Text = "Non romperlo."
  },
  Voice_5793_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_5794_AwakerVoiceContent = {
    Text = "Aurita adora giocare con Tutti! Ti unisci? Questa è Jelly, quella è Hela, e laggiù c'è Jelly, anche... eh?"
  },
  Voice_5794_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_5795_AwakerVoiceContent = {
    Text = "Ora mi monderò di quest'onta!"
  },
  Voice_5795_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_5796_AwakerVoiceContent = {
    Text = "Il negozio di Daffodil è ora aperto. I fanciulli che non sono preparati, per cortesia non entrate con leggerezza."
  },
  Voice_5796_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_5796_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_5797_AwakerVoiceContent = {
    Text = "Vi prego, non toccatemi il collo... Solo perché non potete vederlo, non significa che non ci sia."
  },
  Voice_5797_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_5798_AwakerVoiceContent = {
    Text = "Rispetto la convinzione, che sia in una bestia, in un Risvegliato o in un umano. Se sanno combattere, ancora meglio."
  },
  Voice_5798_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_5799_AwakerVoiceContent = {Text = "Vai."},
  Voice_5799_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5800_AwakerVoiceContent = {
    Text = "Non preoccuparti!"
  },
  Voice_5800_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_5801_AwakerVoiceContent = {
    Text = "Ramona... voglio dire, non mi piacciono gli addii. Sono troppo tristi."
  },
  Voice_5801_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_5802_AwakerVoiceContent = {
    Text = "Non sono brava a trattare con i chierici. Sono noiosi e rigidi, e hanno ceduto le loro cinture al loro amato \"Dio\". Che peccato, il Sig. Salvador ha un profumo così dolce..."
  },
  Voice_5802_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Salvador"
  },
  Voice_5802_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risveglio \"Salvador\""
  },
  Voice_5803_AwakerVoiceContent = {
    Text = "L'ebbrezza della battaglia supera ogni cosa — nemmeno la vittoria le si avvicina."
  },
  Voice_5803_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_5804_AwakerVoiceContent = {
    Text = "A chi non piace un letto morbido, e un canale di scolo senza correnti d'aria... cioè, una Stanza."
  },
  Voice_5804_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_5805_AwakerVoiceContent = {
    Text = "Non farmi ricordare... i giorni in cui ero imprigionata a Elworth..."
  },
  Voice_5805_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_5806_AwakerVoiceContent = {
    Text = "Brucia tutto!"
  },
  Voice_5806_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5807_AwakerVoiceContent = {
    Text = "Brucia tutto!"
  },
  Voice_5807_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_5808_AwakerVoiceContent = {
    Text = "Ho seguito l'odore del Sangue fino a questo luogo. Posso chiedere... avete del Sangue fresco per me?"
  },
  Voice_5808_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5809_AwakerVoiceContent = {
    Text = "Hmm... Agrippa ha molti amici, ma sembrano tutti avere paura di lei. Che sia perché ruba loro il cibo?"
  },
  Voice_5809_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Agrippa"
  },
  Voice_5809_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Agrippa\""
  },
  Voice_5810_AwakerVoiceContent = {
    Text = "La mia vita ruota attorno alla danza. Apprendere altra conoscenza è difficile per me. Ma qui sono tutti gentili; non mi venderanno per vanità o denaro — lo sento."
  },
  Voice_5810_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_5811_AwakerVoiceContent = {
    Text = "Codardo! Possiedi una possanza pari alla mia, eppure ti trattieni. In cosa differisce dall'indossare volontariamente un collare?"
  },
  Voice_5811_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Lily"
  },
  Voice_5811_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Lily\""
  },
  Voice_5812_AwakerVoiceContent = {
    Text = "Non basta... Non sono ancora abbastanza forte."
  },
  Voice_5812_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_5813_AwakerVoiceContent = {
    Text = "Torna indietro."
  },
  Voice_5813_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_5814_AwakerVoiceContent = {Text = "Argh!"},
  Voice_5814_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_5815_AwakerVoiceContent = {
    Text = "Cilindri, bombette, deerstalker, baschi... Devo ammettere che fa ridere come quei nobili \"gentiluomini\" farebbero di tutto per nascondere le loro teste calve."
  },
  Voice_5815_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sull'etichetta"
  },
  Voice_5816_AwakerVoiceContent = {
    Text = "La ammiro profondamente — la dea del mare, pura ed elegante come un giglio... Dici che nemmeno lei poté governare il proprio fato e infine sprofondò nel mare? È davvero difficile da immaginare..."
  },
  Voice_5816_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Celeste"
  },
  Voice_5816_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Celeste\""
  },
  Voice_5817_AwakerVoiceContent = {
    Text = "Nulla è paragonabile al Potere di un Gigante!"
  },
  Voice_5817_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_5818_AwakerVoiceContent = {
    Text = "Nulla è paragonabile al Potere di un Gigante!"
  },
  Voice_5818_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_5819_AwakerVoiceContent = {
    Text = "Maledizione! Maledizione! Questo potere mi tiene soltanto intrappolato in questo corpo!"
  },
  Voice_5819_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_5819_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_5820_AwakerVoiceContent = {
    Text = "Desidero restare in un luogo sempre illuminato... Sì, i poli. Su questo pianeta, solo i poli."
  },
  Voice_5820_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_5820_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_5821_AwakerVoiceContent = {
    Text = "Io... non sono in grado di sopportare grandi responsabilità. Posso solo inseguire la luce. Perciò, ti prego, non smettere mai di brillare..."
  },
  Voice_5821_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_5821_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_5822_AwakerVoiceContent = {
    Text = "Se potessi spostarmi tra le dimensioni ancora una volta, vorrei diventare una stella..."
  },
  Voice_5822_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_5822_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_5823_AwakerVoiceContent = {
    Text = "Per quanto io calcoli, la formula per il trasferimento di coscienza resta irrisolvibile..."
  },
  Voice_5823_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_5823_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_5824_AwakerVoiceContent = {
    Text = "Benvenuto! Divertiamoci insieme!"
  },
  Voice_5824_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_5825_AwakerVoiceContent = {
    Text = "Ecco il tuo pasto!"
  },
  Voice_5825_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_5826_AwakerVoiceContent = {
    Text = "Eheh... Ciao! Sono io, Aurita! Uno, due, tre... Woah! Benvenuto, Benvenuto! Nuovi amici si sono uniti a noi! Eh? Stavolta sono io la nuova amica? Beh, anche così va bene!"
  },
  Voice_5826_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5827_AwakerVoiceContent = {
    Text = "Chiami questo giocattolino una pistola? Nascondersi nell'Ombra per tendere Imboscate ai nemici... Hmph. Un'arma solo per codardi."
  },
  Voice_5827_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_5828_AwakerVoiceContent = {
    Text = "Senza senso. Tutto quanto. Perché affannarsi?"
  },
  Voice_5828_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_5829_AwakerVoiceContent = {
    Text = "Non sai assolutamente nulla."
  },
  Voice_5829_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_5830_AwakerVoiceContent = {
    Text = "Conti ancora su di me come riserva, \"Salvatore\"?"
  },
  Voice_5830_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_5831_AwakerVoiceContent = {
    Text = "Scusa, hai visto la mia vite? È strano, ma ogni volta che quel ragazzino con le orecchie da topo è nei paraggi, sembra che dimentichi più spesso dove ho messo le cose..."
  },
  Voice_5831_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Jenkin"
  },
  Voice_5831_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Jenkin\""
  },
  Voice_5832_AwakerVoiceContent = {
    Text = "Non dimenticherò ciò che hai fatto per il mio Ricongiungimento con Lui..."
  },
  Voice_5832_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_5833_AwakerVoiceContent = {
    Text = "Ascolta il Cantabile Scolpito!"
  },
  Voice_5833_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5834_AwakerVoiceContent = {
    Text = "Hai accolto il mio Desiderio?"
  },
  Voice_5834_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_5835_AwakerVoiceContent = {
    Text = "Spero che i tuoi ordini non mi deluderanno."
  },
  Voice_5835_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_5836_AwakerVoiceContent = {
    Text = "È migliorato il mio corpo o la mia coscienza? Un soggetto d'analisi intrigante."
  },
  Voice_5836_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_5836_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_5837_AwakerVoiceContent = {Text = "Indietro."},
  Voice_5837_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_5838_AwakerVoiceContent = {
    Text = "Fatti da parte."
  },
  Voice_5838_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_5839_AwakerVoiceContent = {
    Text = "Le mie vene pulsano della volontà di sopravvivere, urlano e mi spingono a versare il mio sangue su ogni centimetro di questo pianeta... Ah, ho divagato troppo a lungo; vi prego di perdonarmi. Sono Thais. Mi avete evocata? Siete pronti a fondervi con me?"
  },
  Voice_5839_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5840_AwakerVoiceContent = {
    Text = "Se solo Aigis potesse sopportare questo liquido nero per tutti... Dopotutto, Aigis non è mai esistita, e questo potrebbe essere un bene per questo mondo, no?"
  },
  Voice_5840_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_5841_AwakerVoiceContent = {
    Text = "I miei hobby includono il tentativo di risolvere l'Ipotesi di Riemann — quella, tuttavia, è la frase tipica del nostro Signor Peacock, non la mia. Personalmente, trovo gli standard di massa atomica assai più stimolanti."
  },
  Voice_5841_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_5842_AwakerVoiceContent = {
    Text = "Il sapore dell'Esilio e della deriva in mare aperto... Una volta è stata più che sufficiente."
  },
  Voice_5842_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_5844_AwakerVoiceContent = {
    Text = "Osserva bene!"
  },
  Voice_5844_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5845_AwakerVoiceContent = {
    Text = "Osserva bene!"
  },
  Voice_5845_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_5846_AwakerVoiceContent = {
    Text = "Finché saprai difendere questa giustizia, io porterò sempre il peso del dovere della lama."
  },
  Voice_5846_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_5847_AwakerVoiceContent = {
    Text = "Conoscevi la leggenda di quel certo \"Pittore\" qui? Da quei graffiti espressionisti, percepisco un tocco familiare..."
  },
  Voice_5847_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_5848_AwakerVoiceContent = {
    Text = "Fa male! Mi sento così, così bene!"
  },
  Voice_5848_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5849_AwakerVoiceContent = {
    Text = "Senti la mia ira!"
  },
  Voice_5849_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5850_AwakerVoiceContent = {
    Text = "Che questa vittoria sia incisa in versi."
  },
  Voice_5850_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_5851_AwakerVoiceContent = {
    Text = "Diventa più forte~"
  },
  Voice_5851_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5852_AwakerVoiceContent = {Text = "Osserva!"},
  Voice_5852_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_5853_AwakerVoiceContent = {Text = "Ehi!"},
  Voice_5853_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_5854_AwakerVoiceContent = {
    Text = "Forse quando sarò grande riuscirò a controllarmi e a non prosciugare la Vita degli altri... A me basta anche solo un pochino per sopravvivere."
  },
  Voice_5854_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_5854_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_5855_AwakerVoiceContent = {
    Text = "Sembra che sia diventata più pesante. La culla riesce ancora a reggere il mio peso?"
  },
  Voice_5855_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_5855_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_5856_AwakerVoiceContent = {
    Text = "Ho divorato così tanto Potere che sta per traboccare. Mi prude anche la schiena. Sto... crescendo?"
  },
  Voice_5856_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_5856_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_5857_AwakerVoiceContent = {
    Text = "Anche se sembro ancora una bambina... Ora ho il Potere di proteggerti."
  },
  Voice_5857_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_5857_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_5858_AwakerVoiceContent = {
    Text = "Farò del mio meglio per crescere."
  },
  Voice_5858_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_5858_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_5859_AwakerVoiceContent = {
    Text = "Miserabile presuntuoso, perché insisti nel volermi risvegliare?"
  },
  Voice_5859_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5860_AwakerVoiceContent = {
    Text = "Diverrò la Madre Divina!"
  },
  Voice_5860_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5861_AwakerVoiceContent = {
    Text = "Quante volte sono stata richiamata... Umano, faresti meglio ad avere abbastanza \"cibo\" pronto, o non posso garantire nulla."
  },
  Voice_5861_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5862_AwakerVoiceContent = {
    Text = "Oltre il portale!"
  },
  Voice_5862_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5863_AwakerVoiceContent = {Text = "Sciocco."},
  Voice_5863_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5864_AwakerVoiceContent = {Text = "Haha!"},
  Voice_5864_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5865_AwakerVoiceContent = {
    Text = "Hmph, niente male. Il nostro prossimo duello sarà leggendario."
  },
  Voice_5865_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_5866_AwakerVoiceContent = {Text = "Insolente!"},
  Voice_5866_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_5867_AwakerVoiceContent = {
    Text = "Talvolta, la bellezza dell'arte risiede nel suo Annientamento. Ma il tuo fallimento... chiaramente non rientra in quella categoria."
  },
  Voice_5867_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_5868_AwakerVoiceContent = {
    Text = "Sei il mio ascoltatore più importante. Ogni volta che ne avrai bisogno, sarò pronta a cantare e a donarti ogni cosa."
  },
  Voice_5868_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_5869_AwakerVoiceContent = {
    Text = "Cose preferite? Alghe, banchi di pesci, colonnati, labirinti... Certo che li ho visti! Sono tutti nel libro di zio Ornn!"
  },
  Voice_5869_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_5870_AwakerVoiceContent = {
    Text = "Si tratta dei preparativi per una missione d'indagine? Compreso."
  },
  Voice_5870_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_5870_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_5871_AwakerVoiceContent = {
    Text = "Il mio nome è Celeste. Sarò sempre qui, finché avrai ancora bisogno di me."
  },
  Voice_5871_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5872_AwakerVoiceContent = {
    Text = "Impara la lezione!"
  },
  Voice_5872_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5873_AwakerVoiceContent = {
    Text = "Porta rispetto, recluta. Nell'esercito, l'anzianità è assoluta e gli ordini si eseguono senza eccezioni. Un comportamento così scorretto verrà punito."
  },
  Voice_5873_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_5874_AwakerVoiceContent = {
    Text = "Offrirei riparazioni per quei \"gingilli\" che ho fabbricato, ma la domanda è... Hai il coraggio di accettare il mio servizio post-vendita?"
  },
  Voice_5874_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito delle sue invenzioni"
  },
  Voice_5875_AwakerVoiceContent = {
    Text = "Voi siete il padrone qui, ma anche un ospite nel mio salon. Preparerò la più raffinata ospitalità per la vostra visita—preferite una sottogonna scarlatta o una camicia da notte color rosa bianca?"
  },
  Voice_5875_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_5876_AwakerVoiceContent = {
    Text = "Scusate, la luce del Sole qui è un po' abbagliante... Un topo sotterraneo come me ha ancora bisogno di tempo per adattarsi."
  },
  Voice_5876_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_5877_AwakerVoiceContent = {
    Text = "Capace di corrodere ogni cosa, di cancellare tutto... Era un'arma niente male. Se solo l'avessi saputo allora... Heh."
  },
  Voice_5877_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_5878_AwakerVoiceContent = {
    Text = "Si dice che i corpi che si contorcono tra le fiamme sembrino danzare..."
  },
  Voice_5878_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito delle fiamme"
  },
  Voice_5880_AwakerVoiceContent = {
    Text = "Non uscire di notte! Anche con una luce da 2000 lumen, non è del tutto sicuro... Una volta che metti piede nell'oscurità, il male in agguato oltre la tua vista ti inseguirà, ti divorerà, ti inseguirà, ti divorerà... finché non resterà più nulla!"
  },
  Voice_5880_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito della notte"
  },
  Voice_5881_AwakerVoiceContent = {Text = "Piangi."},
  Voice_5881_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_5882_AwakerVoiceContent = {
    Text = "Ho ricevuto il tuo pagamento."
  },
  Voice_5882_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5883_AwakerVoiceContent = {
    Text = "È la brama di vivere che spinge il cigno a lottare per il suo ritorno al cielo lontano."
  },
  Voice_5883_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_5883_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_5884_AwakerVoiceContent = {
    Text = "È l'ora della Magia!"
  },
  Voice_5884_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5885_AwakerVoiceContent = {Text = "Aiuto!"},
  Voice_5885_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_5886_AwakerVoiceContent = {
    Text = "(Esclamazione)"
  },
  Voice_5886_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_5887_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_5887_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_5888_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5888_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_5889_AwakerVoiceContent = {
    Text = "Ah, è Brown! Io... forse dovrei allontanarmi un po'... Volevo essere sua amica, ma invece sono finita per diventare il suo incubo... Probabilmente non vuole nemmeno vedermi..."
  },
  Voice_5889_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Jenkin"
  },
  Voice_5889_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Jenkin\""
  },
  Voice_5890_AwakerVoiceContent = {
    Text = "Una cappella? Ti ringrazio, ma non sono così antiquato. Finché custodirò gli insegnamenti del Dio della Benevolenza nel mio cuore e seguirò la Sua volontà, la mia anima non si allontanerà mai dalla Sua gloria."
  },
  Voice_5890_AwakerVoiceTitle = {
    Text = "Chat: A proposito di una cappella"
  },
  Voice_5891_AwakerVoiceContent = {
    Text = "Il mio nome è Ogier. In virtù del nostro Contratto, giuro la mia Lealtà di Cavaliere a voi, per proteggervi e annientare i vostri nemici. Questo solenne giuramento io pronuncio, e non lo dimenticherò mai."
  },
  Voice_5891_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5892_AwakerVoiceContent = {
    Text = "Quella donna emaciata con la doppia pupilla ha esattamente l'odore di un insetto spartano."
  },
  Voice_5892_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Agrippa"
  },
  Voice_5892_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Agrippa\""
  },
  Voice_5893_AwakerVoiceContent = {
    Text = "Cosa mi piace? La buona sorte, ovviamente. Cerco sempre un buon presagio prima di uscire."
  },
  Voice_5893_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_5894_AwakerVoiceContent = {
    Text = "V-Vi prego, non dite alla Sig.na Hannah che mi nascondo qui. Non sono ancora pronta..."
  },
  Voice_5894_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito di Hanna"
  },
  Voice_5895_AwakerVoiceContent = {
    Text = "Che ne dici di questo?"
  },
  Voice_5895_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5896_AwakerVoiceContent = {
    Text = "Sei il mio stimato ospite. Ricorda, sei l'unico a cui è concesso mettere in conto. Dopotutto, sono anni che non vedevo un cranio così perfetto..."
  },
  Voice_5896_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_5897_AwakerVoiceContent = {Text = "Ahi!"},
  Voice_5897_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_5898_AwakerVoiceContent = {
    Text = "(Esclamazione)"
  },
  Voice_5898_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_5899_AwakerVoiceContent = {Text = "Ahi!"},
  Voice_5899_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_5900_AwakerVoiceContent = {
    Text = "Preferenze? Un re non dovrebbe indulgere... eppure, se potessi evitare riti tediosi, un morbido divano potrebbe bastare."
  },
  Voice_5900_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_5901_AwakerVoiceContent = {
    Text = "La vostra insolenza... Questo Sovrano la interpreterà come una supplica di riposo eterno."
  },
  Voice_5901_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_5902_AwakerVoiceContent = {
    Text = "Odio? Odio un fato ineluttabile e una tragedia inevitabile."
  },
  Voice_5902_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_5903_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_5903_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_5904_AwakerVoiceContent = {
    Text = "(Un gemito soffocato di dolore)"
  },
  Voice_5904_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_5905_AwakerVoiceContent = {
    Text = "Non avvicinarti!"
  },
  Voice_5905_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_5906_AwakerVoiceContent = {
    Text = "Oh, curiosi del mio segreto? Questo nome, questo corpo, questo volto, questa voce — appartennero tutti a una donna di San Pedro, a cui uno dei miei teschi apparteneva un tempo. Strinse un patto con me... Dopo la sua morte, divenni lei. Quanto a dove si trovi ora... ebbene, quello è il pezzo più squisito della mia collezione, sapete."
  },
  Voice_5906_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_5906_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_5907_AwakerVoiceContent = {
    Text = "Siete un ospite delizioso; persino io sono affascinata dal vostro teschio così singolare... Se mai pensaste di separarvene, non mancate di visitare il mio piccolo negozio. Haha... solo uno scherzo."
  },
  Voice_5907_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_5907_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_5908_AwakerVoiceContent = {
    Text = "Curiosi di conoscere la mia vera identità? È ancora troppo presto per questo. Credete solo a questo: ogni fanciullo smarrito può ritrovare la via nel mio negozio. Forse questo vale anche per voi?"
  },
  Voice_5908_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_5908_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_5909_AwakerVoiceContent = {
    Text = "Nessuno verrà ferito."
  },
  Voice_5909_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_5910_AwakerVoiceContent = {
    Text = "Non è ancora finita!"
  },
  Voice_5910_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_5911_AwakerVoiceContent = {
    Text = "Vedendo quanto ti stai impegnando, mi sento quasi in colpa a riscuotere la mia ricompensa troppo presto. Quindi, permetterò alla tua testa di restare dov'è per ora. Ma non dimenticare, è già riservata come mia proprietà personale, d'accordo?"
  },
  Voice_5911_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_5911_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_5912_AwakerVoiceContent = {
    Text = "Non sono sempre stata così; fu lei a donarmi una nuova vita. In tal senso, anche voi mi avete donato una seconda vita, perciò avrò cura anche della vostra testa."
  },
  Voice_5912_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_5912_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_5913_AwakerVoiceContent = {
    Text = "Devo fuggire dall'Oscurità!"
  },
  Voice_5913_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5914_AwakerVoiceContent = {
    Text = "Quindi l'avventura è così pericolosa..."
  },
  Voice_5914_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_5915_AwakerVoiceContent = {
    Text = "Perché quella Bambina sciocca scappa appena mi vede? La prossima volta le pesto il filo di lana e vediamo dove corre."
  },
  Voice_5915_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Aigis"
  },
  Voice_5915_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Aigis\""
  },
  Voice_5916_AwakerVoiceContent = {Text = "Ugh!"},
  Voice_5916_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5917_AwakerVoiceContent = {
    Text = "Heh... AHAHAHA!"
  },
  Voice_5917_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_5918_AwakerVoiceContent = {Text = "Hahaha!"},
  Voice_5918_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5919_AwakerVoiceContent = {
    Text = "Quella ragazzina è sveglia; serve quel tipo di arguzia per le strade. Se fossi ancora là fuori a indagare, farei sicuramente squadra con lei."
  },
  Voice_5919_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Jenkin"
  },
  Voice_5919_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Jenkin\""
  },
  Voice_5920_AwakerVoiceContent = {
    Text = "Quel Vescovo non può salvare Tutti. Potrà strappare un'anima sventurata dal fango, ma il resto? ...Non vedo l'ora di guardare la sua fede andare in frantumi."
  },
  Voice_5920_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Salvador"
  },
  Voice_5920_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risveglio \"Salvador\""
  },
  Voice_5921_AwakerVoiceContent = {
    Text = "Nelle fogne di Londinium si può trovare di tutto: salmone, sapone, whiskey bevuto a metà... Perché lo so, chiedi? Una volta ho trascinato il cadavere di mio fratello per otto chilometri lì dentro..."
  },
  Voice_5921_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulle fogne"
  },
  Voice_5922_AwakerVoiceContent = {
    Text = "In ginocchio davanti a me!"
  },
  Voice_5922_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5923_AwakerVoiceContent = {
    Text = "In ginocchio davanti a me."
  },
  Voice_5923_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_5924_AwakerVoiceContent = {
    Text = "Dopo aver intravisto il mondo reale oltre le prime linee, una volta ho messo in Domanda il valore degli \"eroi.\" Ma per fortuna ho incontrato te—onesto, coraggioso e puro. Sotto il tuo comando, combatterò instancabilmente per la pace e la stabilità. Questa volta, otterrò la mia Redenzione."
  },
  Voice_5924_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_5924_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_5925_AwakerVoiceContent = {
    Text = "Aaah! Oh no..."
  },
  Voice_5925_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_5926_AwakerVoiceContent = {
    Text = "Impurità, lordura, caos—questo è il nostro potere."
  },
  Voice_5926_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5927_AwakerVoiceContent = {
    Text = "Detesto la tua recita pretenziosa. Credi che sia pazzo? Patetico? L'Icaro qui sei tu, \"Salvatore\". Tu e il tuo piccolo gregge, con gli occhi bruciati dal bianco a forza di fissare quel sole glorioso che inseguite."
  },
  Voice_5927_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_5928_AwakerVoiceContent = {
    Text = "Lascia che apra la strada!"
  },
  Voice_5928_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_5929_AwakerVoiceContent = {
    Text = "Li percepisco come alieni. Scommetto che non sono nativi di questo pianeta."
  },
  Voice_5929_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sugli esseri extraterrestri"
  },
  Voice_5929_UnlockDesc = {
    Text = "Si sblocca dopo aver acquisito uno qualsiasi dei Risvegliatori \"Winkle\", \"Tintura\", \"Faint\" o \"Wanda\"."
  },
  Voice_5931_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_5931_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_5932_AwakerVoiceContent = {Text = "Svanisci!"},
  Voice_5932_AwakerVoiceTitle = {
    Text = "Abilità Speciale: I"
  },
  Voice_5933_AwakerVoiceContent = {
    Text = "Ti prego, non..."
  },
  Voice_5933_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_5934_AwakerVoiceContent = {
    Text = "Essere un mostro va bene. Tutto ciò che ho sempre voluto era il potere per la vendetta."
  },
  Voice_5934_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_5934_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_5935_AwakerVoiceContent = {
    Text = "Oltre a eliminare il tuo avversario, hai altri desideri? In cambio, esaudirò il tuo desiderio... nei limiti delle mie abilità, naturalmente."
  },
  Voice_5935_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_5935_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_5936_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_5936_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_5937_AwakerVoiceContent = {
    Text = "Un compagno? ... Ci penserò. Non morirmi tra le mani prima che io prenda una decisione."
  },
  Voice_5937_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_5937_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_5938_AwakerVoiceContent = {
    Text = "Dalla sua prima documentazione accertata, la Dissoluzione ha avuto un impatto su oltre un milione di vite. Le nostre azioni sono cruciali per la sopravvivenza dell'intera popolazione umana."
  },
  Voice_5938_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_5939_AwakerVoiceContent = {
    Text = "A tutto gas!"
  },
  Voice_5939_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5940_AwakerVoiceContent = {
    Text = "Guardati dalla furia dell'oceano."
  },
  Voice_5940_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_5941_AwakerVoiceContent = {
    Text = "Guardati dalla furia dell'oceano."
  },
  Voice_5941_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5942_AwakerVoiceContent = {Text = "Ehi!"},
  Voice_5942_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5943_AwakerVoiceContent = {
    Text = "Io sono Sua Figlia, e anche Sua Madre. Quanto a te, al Suo cospetto non sei che un insetto insignificante."
  },
  Voice_5943_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_5944_AwakerVoiceContent = {
    Text = "Tutto è andato bene. Puoi issare le vele trionfanti."
  },
  Voice_5944_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_5945_AwakerVoiceContent = {
    Text = "Stai lontano. Desideri diventare il mio trastullo? O forse un sacrificio per la Divina Nascita?"
  },
  Voice_5945_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_5945_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_59463_AwakerVoiceContent = {
    Text = "Facciamola facile! È la nostra vittoria totale!"
  },
  Voice_59463_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_59464_AwakerVoiceContent = {
    Text = "Facciamola facile! È la nostra vittoria totale!"
  },
  Voice_59464_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_5946_AwakerVoiceContent = {
    Text = "Ti concedo l'onore di essere testimone. Contemplerai il momento glorioso che sfida l'etica dei mortali."
  },
  Voice_5946_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_5946_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_5947_AwakerVoiceContent = {
    Text = "Una cavità? Ne creo spesso di simili durante la Telecinesi. Quelle che creo io collegano a un'altra Dimensione; quelle della Dissoluzione farebbero lo stesso?"
  },
  Voice_5947_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_5948_AwakerVoiceContent = {
    Text = "Custode, per l'Autorità della Madre Divina, ti assicuro un posto accanto al Trono. Sarai testimone dell'era che rinasce dopo la Distruzione — questa è la promessa della Madre Divina. Ora gioisci! Gioisci con gratitudine!"
  },
  Voice_5948_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_5948_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_5949_AwakerVoiceContent = {
    Text = "Vista la tua deferenza, ti concederò una risposta. All'inizio, ero davvero riluttante. Ma ho compreso: vivo questa vita sfarzosa solo grazie a Lui. La morte non è mai la fine. Lui a sua volta mi farà rinascere, e otterremo la vita eterna attraverso questo ciclo morboso..."
  },
  Voice_5949_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_5949_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_5950_AwakerVoiceContent = {
    Text = "Il desiderio di quella donna è ridicolo. Nulla può sopravvivere all'Annientamento, nemmeno il suo \"dio\"."
  },
  Voice_5950_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Thais"
  },
  Voice_5950_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Thais\""
  },
  Voice_5951_AwakerVoiceContent = {
    Text = "Non sono onnipotente. Anche io commetto errori. L'azione rovinosa di quella donna fu un mio errore di calcolo... Pertanto, necessito del tuo aiuto. Affinché tu possa rispondere al mio richiamo, puoi collocare un letto qui, nella mia camera."
  },
  Voice_5951_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_5951_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_5952_AwakerVoiceContent = {
    Text = "Portare il peso della calamità... dev'essere un fardello gravoso per la tua età. Dimmi — se avessi saputo fin dall'inizio che il destino è immutabile... avresti comunque lottato con tanto ardore? Tieni per te la tua risposta. Rifletti mentre riposo. La tua replica... mi interessa."
  },
  Voice_5952_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_5952_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_5953_AwakerVoiceContent = {
    Text = "È passato un po' da quando mi hai risvegliato. Non hai domande? Segreti divini? La profezia assoluta? Persino i tesori del continente sommerso... Nulla stuzzica la tua curiosità? Hmph... Sei davvero peculiare."
  },
  Voice_5953_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_5953_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_5954_AwakerVoiceContent = {
    Text = "Non ho mai preteso adorazione. Il fervore dei mortali non fa che esaurirmi ulteriormente... Ritirati. Ora dormirò."
  },
  Voice_5954_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_5954_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_5955_AwakerVoiceContent = {
    Text = "Non scorgo in te alcun tratto dei miei vassalli... Forse è meglio così. Il solo ricordo di quella donna mi affatica."
  },
  Voice_5955_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_5955_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_5956_AwakerVoiceContent = {
    Text = "Dio tratta tutti i Suoi figli in egual misura."
  },
  Voice_5956_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5957_AwakerVoiceContent = {
    Text = "Lo so, sei uno spettatore speciale. Non posso semplicemente spedirti in un'altra Dimensione; causerebbe grossi guai. Ehi, l'hai mai fatto a qualcun altro? Non devi chiedere, è il mio Segreto!"
  },
  Voice_5957_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_5958_AwakerVoiceContent = {
    Text = "Oh, ti incuriosisce il mio nuovo aspetto? C'è sempre un prezzo da pagare, si sa. Dev'essere uno dei miei colpi di fortuna—questa è la fortuna di Ryker!"
  },
  Voice_5958_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_5959_AwakerVoiceContent = {
    Text = "Mythag custodisce i ricordi più cari per me... è anche la mia casa più calda."
  },
  Voice_5959_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_5960_AwakerVoiceContent = {
    Text = "Lascia fare a me."
  },
  Voice_5960_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_5961_AwakerVoiceContent = {
    Text = "Che ingenuità!"
  },
  Voice_5961_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_5962_AwakerVoiceContent = {
    Text = "Inni dell'Abisso!"
  },
  Voice_5962_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5963_AwakerVoiceContent = {
    Text = "Contemplate ciò che mi è stato conferito—"
  },
  Voice_5963_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_5964_AwakerVoiceContent = {
    Text = "Se riesci ancora a vedermi come \"Ramona\"... allora ti prego, continua a usare quel nome."
  },
  Voice_5964_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5965_AwakerVoiceContent = {
    Text = "Cosa? Vuoi sfruttare anche la mia rabbia?"
  },
  Voice_5965_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_5965_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_5966_AwakerVoiceContent = {
    Text = "La verità... si rivela proprio qui."
  },
  Voice_5966_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5967_AwakerVoiceContent = {
    Text = "Mangia quello che afferri nell'istante in cui lo prendi. Questa è la legge della strada."
  },
  Voice_5967_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_5968_AwakerVoiceContent = {
    Text = "Mi sento un po' pieno, adesso."
  },
  Voice_5968_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_5969_AwakerVoiceContent = {
    Text = "Hmm... ho un prurito. Brown, vieni a grattarmi la schiena."
  },
  Voice_5969_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_5970_AwakerVoiceContent = {
    Text = "Nuovi componenti meccanici saranno di grande aiuto per il funzionamento del mio sistema—questo non conta come apprezzare qualcosa? Mi dispiace, temo di non comprendere la vostra domanda. Le preferenze non hanno significato per le bambole meccaniche."
  },
  Voice_5970_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_5971_AwakerVoiceContent = {Text = "Osserva."},
  Voice_5971_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_5972_AwakerVoiceContent = {Text = "Osserva!"},
  Voice_5972_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5974_AwakerVoiceContent = {
    Text = "Pensaci bene."
  },
  Voice_5974_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_5975_AwakerVoiceContent = {
    Text = "Mantieni la calma e rifletti."
  },
  Voice_5975_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_5976_AwakerVoiceContent = {
    Text = "La signorina Winkle, come me, non viene da questo Pianeta... Non c'è nulla che mi leghi al mio Focolare tranne Tintura. Mi chiedo cosa provi la signorina Winkle riguardo alla sua Terra dei Bianchi Uccelli."
  },
  Voice_5976_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Winkle"
  },
  Voice_5976_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Winkle\""
  },
  Voice_5977_AwakerVoiceContent = {
    Text = "Non avvicinarti alle mie spalle, a meno che tu non voglia il collo spezzato."
  },
  Voice_5977_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_5977_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_5978_AwakerVoiceContent = {
    Text = "Eh? Come avete potuto permettere a dei gatti randagi di vagare per il campus?! E se quella bestia selvaggia graffiasse qualcuno?!"
  },
  Voice_5978_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_5979_AwakerVoiceContent = {
    Text = "I miei occhi ti mettono a disagio? Bene. È la ferocia che mi ha tenuto in vita in quell'inferno."
  },
  Voice_5979_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_5979_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_5980_AwakerVoiceContent = {
    Text = "Risparmiami i bei discorsi. Che cosa vuoi da me? Ci sarà pure un motivo per aver preservato la mia sanità mentale."
  },
  Voice_5980_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_5980_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_5981_AwakerVoiceContent = {
    Text = "La mia vendetta è sempre stata diretta contro gli Spartani, ma ormai persino quella città-stato non esiste più... E sia. Diventare la tua lama non è impossibile. Ti accetto a malincuore come mio compagno, ma se oserai tradirmi, ti strapperò il cuore."
  },
  Voice_5981_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_5981_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_5982_AwakerVoiceContent = {
    Text = "Le mie mani sono macchiate di sangue. I miei deboli consanguinei non comprendono la mia vendetta; sussurrano della mia crudeltà, della mia ingratitudine, del mio tradimento... La vendetta è sempre solo per me stesso, e per nessun altro."
  },
  Voice_5982_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_5982_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_5983_AwakerVoiceContent = {
    Text = "È ora di usare più acciaio."
  },
  Voice_5983_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5984_AwakerVoiceContent = {
    Text = "È ora di usare più acciaio."
  },
  Voice_5984_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_5985_AwakerVoiceContent = {Text = "Muori."},
  Voice_5985_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_5986_AwakerVoiceContent = {
    Text = "Io sono... chiamami pure Winkle. È così che mi chiamano tutti. Sì, chiamami così, proprio come fanno loro..."
  },
  Voice_5986_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5987_AwakerVoiceContent = {
    Text = "Questo corpo sarà lo scudo del mio signore!"
  },
  Voice_5987_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_5988_AwakerVoiceContent = {
    Text = "Questo corpo sarà lo scudo del mio signore!"
  },
  Voice_5988_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_5989_AwakerVoiceContent = {
    Text = "\"Lo Schiaccianoci\" dovrebbe essere una fiaba romantica per bambine, ma quegli individui ripugnanti vedevano solo gli arti aggraziati in movimento e volgari desideri... Disgustoso."
  },
  Voice_5989_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_5990_AwakerVoiceContent = {
    Text = "Devo... eliminarlo!"
  },
  Voice_5990_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_5991_AwakerVoiceContent = {
    Text = "Pandia... Lei chiama QUELLO essere una dominatrice? Haha... Concedimi un momento di divertimento. Gli umani sono ancora troppo teneri di cuore; tutto ciò che fanno sembra un mero gioco da bambini."
  },
  Voice_5991_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito di Pandia"
  },
  Voice_5991_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Pandia\""
  },
  Voice_5992_AwakerVoiceContent = {
    Text = "Non avvicinarti!"
  },
  Voice_5992_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5993_AwakerVoiceContent = {
    Text = "Cosa? Ancora presentazioni? Va bene. Io sono Jenkin, e questo è Brown. \"Squiit!\"\nNon vi azzardate a dimenticarlo! Se sbagliate i nostri nomi, vi prendo a lanternate sul *Beep*!\n\"Squiit squiit?!\""
  },
  Voice_5993_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_5994_AwakerVoiceContent = {
    Text = "Danziamo! Danziamo!"
  },
  Voice_5994_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_5995_AwakerVoiceContent = {
    Text = "Danziamo! Danziamo!"
  },
  Voice_5995_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_5996_AwakerVoiceContent = {
    Text = "Ecco il Tributo d'apertura!"
  },
  Voice_5996_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_5997_AwakerVoiceContent = {Text = "Hmph."},
  Voice_5997_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_5998_AwakerVoiceContent = {
    Text = "Mi bastano un po' di pietra, due scalpelli e tre iris rivolti al sole... e posso creare qualsiasi cosa per te."
  },
  Voice_5998_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_5998_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_5999_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_5999_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_6000_AwakerVoiceContent = {Text = "Tutto qui?"},
  Voice_6000_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_6001_AwakerVoiceContent = {Text = "Certo."},
  Voice_6001_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_6002_AwakerVoiceContent = {
    Text = "Questa lotta senza senso..."
  },
  Voice_6002_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_6003_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_6003_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_6004_AwakerVoiceContent = {
    Text = "Dopo la morte di Tiberio, i Romani videro finalmente esaudito il loro antico Desiderio: poterlo gettare nel Tevere a sfamare i pesci. Il prezzo fu modesto: Caligola gettò quella gente a me nell'Arena per il mio diletto."
  },
  Voice_6004_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_6005_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_6005_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_6006_AwakerVoiceContent = {
    Text = "Percepisco che la bambina possiede poteri simili ai miei. Non ha ancora compreso appieno la portata della loro forza. Per il tuo bene, la addestrerò come si deve."
  },
  Voice_6006_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Lily"
  },
  Voice_6006_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Lily\""
  },
  Voice_6007_AwakerVoiceContent = {
    Text = "Maledizione! Tu... tu continui a guardarmi dall'alto in basso, vero?!"
  },
  Voice_6007_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_6008_AwakerVoiceContent = {
    Text = "Questa è la prova della mia esistenza."
  },
  Voice_6008_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_6009_AwakerVoiceContent = {
    Text = "Questa è la prova della mia esistenza."
  },
  Voice_6009_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_6010_AwakerVoiceContent = {
    Text = "Credo che ogni cosa accada per una ragione, ma... la violenza insensata, i pregiudizi che spingono fratelli a rivoltarsi l'uno contro l'altro... queste cose mi rattristano profondamente. Se c'è qualcosa che detesto, è proprio questo."
  },
  Voice_6010_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_6011_AwakerVoiceContent = {
    Text = "Vorrei davvero non dover usare questo potere."
  },
  Voice_6011_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6012_AwakerVoiceContent = {
    Text = "Non abbassare la guardia."
  },
  Voice_6012_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_6013_AwakerVoiceContent = {Text = "Hmph"},
  Voice_6013_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_6014_AwakerVoiceContent = {Text = "Basta!"},
  Voice_6014_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_6015_AwakerVoiceContent = {Text = "Basta!"},
  Voice_6015_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_6016_AwakerVoiceContent = {
    Text = "Casiah è incredibile! Riesce a far apparire un coniglietto in un batter d'occhio!"
  },
  Voice_6016_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Casiah"
  },
  Voice_6016_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Casiah\""
  },
  Voice_6017_AwakerVoiceContent = {
    Text = "La mia Magia è pronta!"
  },
  Voice_6017_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6018_AwakerVoiceContent = {
    Text = "Dissoluzione... Devo ammetterlo, ci sono cose in questo mondo che sfuggono al controllo del potere."
  },
  Voice_6018_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_6019_AwakerVoiceContent = {Text = "Ah—"},
  Voice_6019_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_6020_AwakerVoiceContent = {
    Text = "Danza tra le fiamme smeraldine."
  },
  Voice_6020_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_6021_AwakerVoiceContent = {
    Text = "Non temere; le cicatrici sono il distintivo d'onore di un guerriero!"
  },
  Voice_6021_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_6022_AwakerVoiceContent = {
    Text = "Trema davanti a questi muscoli... Sono sempre pronti a staccarti la testa."
  },
  Voice_6022_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_6024_AwakerVoiceContent = {
    Text = "Ora di mangiare? O ora di giocare?"
  },
  Voice_6024_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_6024_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_6025_AwakerVoiceContent = {
    Text = "Haha! Ora gli amici di Aurita non spariranno più!"
  },
  Voice_6025_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_6025_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_6026_AwakerVoiceContent = {
    Text = "La signorina Sylvia ha detto che dovrei dire \"grazie\" quando ricevo qualcosa... Grazie, grazie, grazie!!"
  },
  Voice_6026_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_6026_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_6027_AwakerVoiceContent = {
    Text = "Stavolta tocca a me fare il fantasma! Avete solo 5 secondi per nascondervi! 5, 4—"
  },
  Voice_6027_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_6027_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_6028_AwakerVoiceContent = {
    Text = "Tutti sono scomparsi dopo aver iniziato a giocare a Nascondersi. Stavolta sono decisa a trovare Tutti!"
  },
  Voice_6028_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_6028_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_6029_AwakerVoiceContent = {
    Text = "Hanno trovato le mie ossa sotto le onde e presumono che mi piaccia l'acqua? Ora vogliono costruire una piscina fuori dalle mie stanze? ...Ha. Facciano come vogliono. Purché smettano di importunarmi con sciocchezze."
  },
  Voice_6029_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_6030_AwakerVoiceContent = {
    Text = "Una mera goccia nelle maree, umile seguace dell'immortale, Miryam... vi porge i suoi saluti."
  },
  Voice_6030_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6031_AwakerVoiceContent = {
    Text = "È il mio turno di agire."
  },
  Voice_6031_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_6032_AwakerVoiceContent = {Text = "Hah!"},
  Voice_6032_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_6033_AwakerVoiceContent = {
    Text = "Assolutamente straordinario... Una tua osservazione casuale ha risolto un problema creativo che mi tormentava da mesi."
  },
  Voice_6033_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_6033_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_6034_AwakerVoiceContent = {
    Text = "Rispetto alle nobili signore a quella festa, il carattere di Murphy è piuttosto adorabile."
  },
  Voice_6034_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Murphy"
  },
  Voice_6034_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risveglio \"Murphy\""
  },
  Voice_6035_AwakerVoiceContent = {
    Text = "Mi chiamano un consigliere esperto? Quei Fanciulli sono troppo gentili. Faccio semplicemente del mio meglio per ascoltare e aiutarli a liberarsi delle loro angosce interiori — come ho sempre cercato di fare."
  },
  Voice_6035_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_6036_AwakerVoiceContent = {
    Text = "Non sottovalutarmi mai!"
  },
  Voice_6036_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_6037_AwakerVoiceContent = {
    Text = "Non sottovalutarmi mai!"
  },
  Voice_6037_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_6038_AwakerVoiceContent = {
    Text = "Hai sete? L'acqua pulita è un lusso raro in prigione."
  },
  Voice_6038_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_6038_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_6039_AwakerVoiceContent = {
    Text = "Allora, chi è {Male=il bravo ragazzo,Female=la brava ragazza}? I {Male=bravi ragazzi,Female=brave ragazze} non rinunciano a metà strada~"
  },
  Voice_6039_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_6039_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_6040_AwakerVoiceContent = {
    Text = "Devi essere già caduta nella mia dolce trappola a questo punto, vero?"
  },
  Voice_6040_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_6040_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_6041_AwakerVoiceContent = {
    Text = "Continua, ancora un po'~ Siamo quasi al culmine dell'estasi~"
  },
  Voice_6041_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_6041_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_6042_AwakerVoiceContent = {
    Text = "Sono entrata nel Mythag all'età di quattordici anni. Se mi fossi laureata regolarmente, ora mi chiameresti Preside."
  },
  Voice_6042_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_6043_AwakerVoiceContent = {
    Text = "Il tuo gracile cervello sembra incapace di conservare le lezioni."
  },
  Voice_6043_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_6044_AwakerVoiceContent = {
    Text = "Il mio desiderio? Garantire un viaggio sicuro e tranquillo—non è forse sufficiente? Non ho mai avuto altri desideri... ma ci rifletterò con cura e te lo dirò in seguito."
  },
  Voice_6044_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_6044_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_6045_AwakerVoiceContent = {
    Text = "\"Erano i segreti del cielo e della terra che desideravo apprendere. Volevo scoprire quale forza mi controlla?\" ...Sebbene trovi la trama di questo romanzo insoddisfacente e la sua scienza fittizia ingenuamente risibile, dopo averlo letto dovresti comprendere le mie motivazioni... Aspetta, non hai letto questo libro?"
  },
  Voice_6045_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_6045_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_6046_AwakerVoiceContent = {
    Text = "Dovere e destino si somigliano molto. Nessuno dei due può essere facilmente abbandonato, né vi è alcun bisogno di farlo."
  },
  Voice_6046_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_6046_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_6047_AwakerVoiceContent = {
    Text = "Sembro sempre occupata? Sì. Gli assistenti possono occasionalmente tornare utili, ma in certe ricerche sono semplicemente insostituibile. Vuoi aiutare? Allora controlla periodicamente se sono ancora, di fatto, viva."
  },
  Voice_6047_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_6047_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_6048_AwakerVoiceContent = {
    Text = "Sembro arrabbiata? Comprendi quanti muscoli sono necessari per un sorriso? L'ho spiegato una volta a lezione, una lezione che evidentemente è scivolata via dal tuo cervello liscio. La risposta è un minimo di diciassette, e non ho alcuna ragione logica per essere arrabbiata con te."
  },
  Voice_6048_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_6048_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_6049_AwakerVoiceContent = {
    Text = "La signorina Ramona una volta disse che non ho bisogno di compiacere tutti. Non capisco... Significa forse che la mia protezione non è più necessaria?"
  },
  Voice_6049_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_6049_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_6050_AwakerVoiceContent = {
    Text = "Tredici rapporti richiedono approvazione urgente, sei comunicatori danneggiati attendono riparazione, e devo anche monitorare i risultati di cinque distinti esperimenti di estrazione dell'Argento... Quindi, anziché dissipare il mio tempo limitato disturbandomi, perché non provi a esercitare la tua gracile materia cerebrale?"
  },
  Voice_6050_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_6050_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_6051_AwakerVoiceContent = {
    Text = "Spero che la prossima volta la mia terra natia risponda al mio richiamo."
  },
  Voice_6051_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_6052_AwakerVoiceContent = {
    Text = "Lucchetto rilasciato."
  },
  Voice_6052_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6054_AwakerVoiceContent = {
    Text = "Sono così felice... Sei così parziale e mi favorisci tanto."
  },
  Voice_6054_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_6054_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_6055_AwakerVoiceContent = {
    Text = "Gli altri potrebbero irritarsi se pensassero che mostri favoritismi."
  },
  Voice_6055_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_6055_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_6056_AwakerVoiceContent = {
    Text = "Anche tu brami me?"
  },
  Voice_6056_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_6056_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_6057_AwakerVoiceContent = {
    Text = "Finalmente è finita. Basta vedere quelle cose nere e viscide..."
  },
  Voice_6057_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_6058_AwakerVoiceContent = {
    Text = "Per tutto ciò che mi hai donato, il tuo amore è ormai divenuto tutt'uno con il mio..."
  },
  Voice_6058_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_6058_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_6059_AwakerVoiceContent = {Text = "Ehi!"},
  Voice_6059_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_6060_AwakerVoiceContent = {
    Text = "Ooh, c'è mancato poco."
  },
  Voice_6060_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_6061_AwakerVoiceContent = {
    Text = "Ti sei impegnato così tanto; è ora di goderti i frutti del tuo lavoro, no? Avvicinati, non ti deluderò~"
  },
  Voice_6061_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_6061_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_6062_AwakerVoiceContent = {
    Text = "Io... comprendo la tua Intenzione. Anche se sono ancora maldestra, combatterò per te con tutto ciò che ho!"
  },
  Voice_6062_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_6062_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_6063_AwakerVoiceContent = {
    Text = "Il vostro sguardo mi brucia... Vi ho causato qualche problema?"
  },
  Voice_6063_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_6063_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_6064_AwakerVoiceContent = {
    Text = "Sono molto in ansia... non so se potrò mai essere all'altezza delle vostre aspettative..."
  },
  Voice_6064_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_6064_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_6065_AwakerVoiceContent = {
    Text = "M-mi sento così a disagio... a essere guardata così... Non avete terrore della mia maledizione?"
  },
  Voice_6065_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_6065_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_6066_AwakerVoiceContent = {
    Text = "P-per favore, non guardatemi negli occhi... Non voglio farvi del male... Dopotutto, sono un mostro..."
  },
  Voice_6066_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_6066_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_6067_AwakerVoiceContent = {
    Text = "Il fiuto di questa Bestia? È solo fortuna, chiaro? Non fraintendere."
  },
  Voice_6067_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_6067_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_6068_AwakerVoiceContent = {
    Text = "Non posso ancora fermarmi..."
  },
  Voice_6068_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_6069_AwakerVoiceContent = {
    Text = "Assapora il mio Potere infinito!"
  },
  Voice_6069_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_6070_AwakerVoiceContent = {
    Text = "Assapora il mio Potere infinito!"
  },
  Voice_6070_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_6071_AwakerVoiceContent = {
    Text = "Ti piace il mare? Io amo il mare in ogni caso. Ricordo ancora quel giorno di tanti anni fa, quando il mare consegnò dolcemente la morte tanto attesa alla sventurata me."
  },
  Voice_6071_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_6073_AwakerVoiceContent = {
    Text = "Ho appena provato un piacere come mai prima d'ora... non so perché..."
  },
  Voice_6073_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_6074_AwakerVoiceContent = {
    Text = "Questa Corrente Sotterranea farà a pezzi i nostri nemici."
  },
  Voice_6074_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_6075_AwakerVoiceContent = {
    Text = "Questa Corrente Sotterranea farà a pezzi i nostri nemici."
  },
  Voice_6075_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_6076_AwakerVoiceContent = {
    Text = "Ho atteso qualcuno che mi insegnasse il vero amore, il dolore e il desiderio. Puoi esaudire il mio desiderio? Puoi redimermi da questa prigione oscura?"
  },
  Voice_6076_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_6076_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_6077_AwakerVoiceContent = {
    Text = "Vuoi conoscere la verità? Odio la prigione, odio l'oscurità, e la odio così tanto da morirne. Voglio essere notata. Voglio essere accesa..."
  },
  Voice_6077_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_6077_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_6078_AwakerVoiceContent = {
    Text = "Tutto questo è per il bene eterno del futuro."
  },
  Voice_6078_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_6079_AwakerVoiceContent = {
    Text = "Vuoi goderti me? Allora diventa il mio schiavo. Ti farò sciogliere dal calore~"
  },
  Voice_6079_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_6079_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_6080_AwakerVoiceContent = {
    Text = "Sia pure. Lo considererò un'umile offerta di un suddito."
  },
  Voice_6080_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_6081_AwakerVoiceContent = {
    Text = "Mi annoio così tanto! Rispetto a quei grandi prigionieri tremanti, questo è come giocare alla Casa. Perché non mi fai compagnia~"
  },
  Voice_6081_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_6081_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_6082_AwakerVoiceContent = {
    Text = "Voglio più schiavi, voglio sentire i loro gemiti e le loro suppliche... Portatemi più schiavi, vi prego!"
  },
  Voice_6082_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_6082_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_6083_AwakerVoiceContent = {
    Text = "Perdonatemi, mi sono perso nelle Memorie ancora una volta. Vi prego, non siate tristi. È il vostro turno di Narrare la vostra Storia. Vi va di scrivere un poema? Le vostre avventure, le vostre esperienze, le vostre gioie, i vostri dolori, scorreranno come un ruscello gentile dalla vostra mente alla punta delle vostre dita?"
  },
  Voice_6083_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_6083_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_6084_AwakerVoiceContent = {
    Text = "Non ero che una filigrana fugace sulla pergamena, eppure il nostro incontro mi ha indotta a indugiare. Forse questo è un miracolo. Custodirò questo miracolo e comporrò poesie immortali per voi."
  },
  Voice_6084_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_6084_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_6085_AwakerVoiceContent = {
    Text = "Qualcuno una volta mi disse che la poesia è scritta per essere apprezzata... Posso udire il vostro parere al riguardo?"
  },
  Voice_6085_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_6085_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_6086_AwakerVoiceContent = {
    Text = "Avete mai provato questo? Offrire il perdono per l'offesa altrui, solo per veder sfuggire il risultato desiderato. Porgete una rosa, eppure sulle vostre mani non resta la sua fragranza persistente, ma solo i segni sanguinanti di Spine affilate."
  },
  Voice_6086_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_6086_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_6087_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_6088_AwakerVoiceContent = {
    Text = "La mia penna e il mio inchiostro..."
  },
  Voice_6088_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_6089_AwakerVoiceContent = {
    Text = "(Esclamazione)"
  },
  Voice_6089_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_6090_AwakerVoiceContent = {
    Text = "Questa è la rima sbagliata..."
  },
  Voice_6090_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_6091_AwakerVoiceContent = {
    Text = "(Esclamazione)"
  },
  Voice_6091_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_6092_AwakerVoiceContent = {
    Text = "Questa è una Benedizione del Grande!"
  },
  Voice_6092_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_6093_AwakerVoiceContent = {
    Text = "Benedizione del Grande Pallido..."
  },
  Voice_6093_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_6094_AwakerVoiceContent = {
    Text = "Non ho tempo per il riposo. La Dissoluzione ha già reclamato due dei miei corpi. Prima che l'inevitabile fine mi raggiunga, c'è molto che devo comprendere... Assistimi, cominciando dalla preparazione dei materiali sperimentali. Confido che non sbaglierai i calcoli dell'equilibrio."
  },
  Voice_6094_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_6094_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_6095_AwakerVoiceContent = {
    Text = "Adoro le vetrate di Fontainebleau. Proiettano sfumature diverse sui volti delle persone: il viola della disperazione, il blu dell'adulazione e, naturalmente, il mio preferito—il rosso dell'ambizione..."
  },
  Voice_6095_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_6096_AwakerVoiceContent = {
    Text = "Qui, percepisco spesso la presenza del mio Signore, ma forse non sono ancora pronto ad affrontarLo... In ogni caso, grazie per avermi offerto rifugio."
  },
  Voice_6096_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_6097_AwakerVoiceContent = {
    Text = "Il tradimento trasforma le persone in mostri, indipendentemente da quale parte stiano. Ecco perché detesto i traditori."
  },
  Voice_6097_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_60985_AwakerVoiceContent = {
    Text = "Hameln, al vostro servizio."
  },
  Voice_60985_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_60986_AwakerVoiceContent = {
    Text = [[
Una volta ho incontrato qualcuno con una comprensione quasi istintiva della musica. I concerti e le sinfonie creati da questa persona erano indimenticabili.
Un vero genio.]]
  },
  Voice_60986_AwakerVoiceTitle = {
    Text = "Chat: A proposito del suo amico"
  },
  Voice_60987_AwakerVoiceContent = {
    Text = "Non mi piace dedicare tempo alla Strategia. Rispetto alla musica, l'arte della Strategia ha ben poco valore. Tuttavia, come strumento per rimuovere gli ostacoli, è necessaria. Per raggiungere il culmine della musica, non mi dispiace servirmi di essa."
  },
  Voice_60987_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito delle sue strategie"
  },
  Voice_60988_AwakerVoiceContent = {
    Text = "Maleducato."
  },
  Voice_60988_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_60989_AwakerVoiceContent = {
    Text = "Eccola di nuovo. Che melodia è questa? Da quando l'ho udita l'ultima volta, si è insediata nella mia mente, rifiutando di andarsene o di placarsi."
  },
  Voice_60989_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_60989_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_6098_AwakerVoiceContent = {
    Text = "(Esclamazione)"
  },
  Voice_6098_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_60990_AwakerVoiceContent = {
    Text = "In termini di tecnica, Pianificazione Strategica e direzione musicale non differiscono. Umanità, emozione, Desiderio... sono chiari e docili come note su un pentagramma, dispiegati davanti ai miei occhi, danzanti lungo Il Sentiero della bacchetta. Comprendere la musica è comprendere ogni cosa."
  },
  Voice_60990_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito dei vostri punti in comune"
  },
  Voice_60991_AwakerVoiceContent = {
    Text = "Ci siamo quasi, ancora un poco. Devo completarlo; devo udirlo!"
  },
  Voice_60991_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_60991_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_60992_AwakerVoiceContent = {Text = "Hmm."},
  Voice_60992_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_60993_AwakerVoiceContent = {
    Text = "Maleducato."
  },
  Voice_60993_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_60994_AwakerVoiceContent = {Text = "Hmm."},
  Voice_60994_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_60995_AwakerVoiceContent = {
    Text = "La musica trascende il linguaggio, la scrittura e ogni cosa. Se questa non è perfezione, non so cosa lo sia."
  },
  Voice_60995_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_60995_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_60996_AwakerVoiceContent = {
    Text = "Attenzione al ritmo."
  },
  Voice_60996_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_60997_AwakerVoiceContent = {
    Text = "Accordatura completa."
  },
  Voice_60997_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_60998_AwakerVoiceContent = {
    Text = "Sono lieto che comprendiate l'importanza dell'addestramento."
  },
  Voice_60998_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_60999_AwakerVoiceContent = {
    Text = "Offrirò un'esecuzione perfetta."
  },
  Voice_60999_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_6099_AwakerVoiceContent = {
    Text = "Invidioso? Queste squame resistenti sono la prova di un lignaggio Nobile."
  },
  Voice_6099_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_61000_AwakerVoiceContent = {
    Text = [[
Un tempo venivo lodato, ma... quello non era vero talento.
Le mie opere erano mere imitazioni dei miei predecessori.]]
  },
  Voice_61000_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito delle sue opere"
  },
  Voice_61001_AwakerVoiceContent = {
    Text = "Legni e archi... intrecciandosi verso l'alto e verso il basso, il motivo riappare... Ora ricordo, è il Requiem che composi per il genio prematuramente scomparso, la Stella Caduta."
  },
  Voice_61001_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_61001_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_61002_AwakerVoiceContent = {
    Text = "Hmm? Hai un nuovo brano da mostrarmi?"
  },
  Voice_61002_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_61003_AwakerVoiceContent = {
    Text = "Questa melodia è dedicata alle anime dei defunti."
  },
  Voice_61003_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_61004_AwakerVoiceContent = {
    Text = [[
La danzatrice verde possedeva un'eleganza degna di essere la prima ballerina di una compagnia di corte.
Se ne avessi l'occasione, spererei davvero di poter collaborare.]]
  },
  Voice_61004_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito di Liz"
  },
  Voice_61004_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Liz\""
  },
  Voice_61005_AwakerVoiceContent = {Text = "Arioso!"},
  Voice_61005_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_61006_AwakerVoiceContent = {
    Text = "C'è un primo violino nell'orchestra, ma un primo violino da solo non può fare un'orchestra completa. Nella mia orchestra non c'è posto per chi cerca solo di mettersi in mostra."
  },
  Voice_61006_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_61007_AwakerVoiceContent = {
    Text = "Credo di aver udito una melodia. Qualcuno sta provando qui vicino?"
  },
  Voice_61007_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_61007_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_61008_AwakerVoiceContent = {Text = "Dal Segno!"},
  Voice_61008_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_61009_AwakerVoiceContent = {Text = "Da Capo!"},
  Voice_61009_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_6100_AwakerVoiceContent = {
    Text = "Preparazione al tuo destino!"
  },
  Voice_6100_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_61010_AwakerVoiceContent = {
    Text = "Sì, sì, è questo — la messa finale, un Requiem per la musica stessa!"
  },
  Voice_61010_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_61010_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_61011_AwakerVoiceContent = {
    Text = "Ah, Custode, sei arrivato giusto in tempo. Dimmi, cosa pensi di questo movimento?"
  },
  Voice_61011_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_61012_AwakerVoiceContent = {
    Text = "Archi, cominciate."
  },
  Voice_61012_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_61013_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_61014_AwakerVoiceContent = {
    Text = "Si è fatta chiara, quella melodia sinuosa, simile ai Lamenti di un'anima... Sono certo di averla udita da qualche parte."
  },
  Voice_61014_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_61014_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_61015_AwakerVoiceContent = {
    Text = "Razionalità e ordine hanno aperto la via. Ho camminato verso l'alto e spalancato le porte della sala. Oltre di esse, nessuna delle due rimaneva — la musica veramente eterna trascende la ragione."
  },
  Voice_61015_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito di ragione e ordine"
  },
  Voice_61016_AwakerVoiceContent = {
    Text = "Osservate le mie mani: uno, due, tre."
  },
  Voice_61016_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_61017_AwakerVoiceContent = {
    Text = "Ho ascoltato l'esecuzione della vostra cosiddetta orchestra, piena di errori. Ma non temere, ho un piano dettagliato per mettere in scena uno spettacolo perfetto prima del Festival della Brina d'Argento."
  },
  Voice_61017_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_61018_AwakerVoiceContent = {
    Text = "Non potrò mai dimenticare la prima volta che udii la musica nel profondo della mia coscienza. In quelle note e quegli accordi, il mondo reale svanì; rimase soltanto musica pura e sublime."
  },
  Voice_61018_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_61019_AwakerVoiceContent = {
    Text = "Che peccato. Sembra che servano altre prove generali."
  },
  Voice_61019_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_6101_AwakerVoiceContent = {
    Text = "Questo è un ordine."
  },
  Voice_6101_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_61020_AwakerVoiceContent = {
    Text = "Di solito non rivolgo inviti simili, ma... vorresti provare? Impugna la bacchetta e insuffla nuova vita nella musica."
  },
  Voice_61020_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_61020_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_61021_AwakerVoiceContent = {
    Text = "Preferisco esprimermi attraverso la musica piuttosto che con le parole. Ma comunicare con te è come dirigere un'orchestra che ha provato innumerevoli volte — fluido, e spesso piacevolmente sorprendente.\nOccupi un posto speciale sia per la musica che per me."
  },
  Voice_61021_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_61021_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_61022_AwakerVoiceContent = {
    Text = "In una sinfonia, il coordinamento tra gli strumenti è cruciale; il modo in cui ogni sezione entra ed esce conferisce un'esperienza diversa alla musica.\nQuello che intendo è che, se comandare i Risvegliati è un'esecuzione, te la stai cavando bene."
  },
  Voice_61022_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_61022_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_61023_AwakerVoiceContent = {
    Text = "Ti piace questo brano? Presenta il motivo completo in sole quattro battute, con i fiati che spingono la melodia verso l'alto fino a raggiungere il tema. Un tale disegno ha influenzato innumerevoli successori... Scusa, sto parlando troppo?"
  },
  Voice_61023_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_61023_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_61024_AwakerVoiceContent = {
    Text = "Esecuzione perfetta."
  },
  Voice_61024_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_61025_AwakerVoiceContent = {Text = "Forte!"},
  Voice_61025_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_61026_AwakerVoiceContent = {Text = "Accento!"},
  Voice_61026_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_61027_AwakerVoiceContent = {
    Text = "Ciascuno di noi cela una melodia nel proprio cuore, imprigionata dalla ragione e dal corpo, destinata a esprimersi pienamente solo nella Follia."
  },
  Voice_61027_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_61028_AwakerVoiceContent = {
    Text = "Solo la musica merita lode."
  },
  Voice_61028_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_61029_AwakerVoiceContent = {
    Text = "Solo la musica merita lode."
  },
  Voice_61029_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_6102_AwakerVoiceContent = {Text = "Vai."},
  Voice_6102_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_61030_AwakerVoiceContent = {
    Text = "Ascolta, questo è il requiem finale!"
  },
  Voice_61030_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_6103_AwakerVoiceContent = {
    Text = "Implora pietà!"
  },
  Voice_6103_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_61049_AwakerVoiceContent = {
    Text = "Ascolta, questo è il requiem finale!"
  },
  Voice_61049_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_6104_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_6104_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_6105_AwakerVoiceContent = {
    Text = "Anche tu desideri essere consumato dalle Fiamme Verdi?"
  },
  Voice_6105_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_6107_AwakerVoiceContent = {
    Text = "Come osi distogliere lo sguardo!"
  },
  Voice_6107_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_6108_AwakerVoiceContent = {
    Text = "Concentrati!"
  },
  Voice_6108_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_6109_AwakerVoiceContent = {
    Text = "Ohh, hai un ragazzo così adorabile al tuo fianco! Gli ho chiesto se volesse diventare il mio devoto schiavo, e lui è arrossito, balbettando così dolcemente di aver giurato la sua lealtà a te... Come se la vera devozione non si potesse condividere!"
  },
  Voice_6109_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito di Ogier"
  },
  Voice_6109_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Ogier\""
  },
  Voice_6110_AwakerVoiceContent = {
    Text = "Non credere di poterti avvicinare a me."
  },
  Voice_6110_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_6111_AwakerVoiceContent = {
    Text = "Accetta il tuo destino."
  },
  Voice_6111_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_6112_AwakerVoiceContent = {
    Text = "Le porte della mia terra natia si allontanano alla deriva... No... Non di nuovo..."
  },
  Voice_6112_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_6113_AwakerVoiceContent = {
    Text = "Fuori dai piedi!"
  },
  Voice_6113_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_6114_AwakerVoiceContent = {
    Text = "Fuori dai piedi!"
  },
  Voice_6114_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_6115_AwakerVoiceContent = {
    Text = "Paga il prezzo delle tue azioni."
  },
  Voice_6115_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_6116_AwakerVoiceContent = {
    Text = "Hai forse un desiderio di morte?"
  },
  Voice_6116_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_6117_AwakerVoiceContent = {
    Text = "Credo di essere stata colpita di nuovo dalla Dissoluzione... Il mio cuore si sta dissolvendo! Bastano poche aspirine, una frusta e un po' di pain per curarmi..."
  },
  Voice_6117_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_6118_AwakerVoiceContent = {
    Text = "Nemmeno tu riesci a curare questa maledetta putrefazione? E allora perché dai la caccia alla Dissoluzione? Sei completamente fuori di testa."
  },
  Voice_6118_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_6119_AwakerVoiceContent = {
    Text = "Io sono l'ultimo guerriero romano — Uvhash!"
  },
  Voice_6119_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_6120_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_6120_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_6121_AwakerVoiceContent = {
    Text = "Io sono l'ultimo guerriero romano — Uvhash!"
  },
  Voice_6121_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_6122_AwakerVoiceContent = {
    Text = "Dissoluzione...? Certo che lo so! Significa semplicemente che il guinzaglio dello Schiavo si è spezzato. Cosa c'è di così Difficile?"
  },
  Voice_6122_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_6123_AwakerVoiceContent = {
    Text = "Sono stato chiamato; il confine tra dio e supplicante ora sanguina."
  },
  Voice_6123_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_6123_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_6124_AwakerVoiceContent = {
    Text = "Hmm... Stai migliorando nei massaggi. Bella applicazione di pressione~"
  },
  Voice_6124_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_6125_AwakerVoiceContent = {
    Text = "L'arredamento qui non è troppo antiquato? È sinistro, come se fosse infestato."
  },
  Voice_6125_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_6126_AwakerVoiceContent = {
    Text = "Qui ci sono piante rigogliose, aria tranquilla e un rimedio per la malattia di mia sorella. Per noi due, è il più meraviglioso nuovo focolare."
  },
  Voice_6126_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_6127_AwakerVoiceContent = {
    Text = "Non avrei mai pensato di rivedere Faint... Mi chiedo come sia stata in tutto questo tempo. Per quanto io le chieda, mi rassicura soltanto che sta bene... Sigh. Ah, scusami, mi sono lasciata trasportare. Prima di tutto dovrei ringraziarti per averci riunite."
  },
  Voice_6127_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito di Faint"
  },
  Voice_6127_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Faint\""
  },
  Voice_6128_AwakerVoiceContent = {
    Text = "Un'Offerta alla Sua volontà."
  },
  Voice_6128_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_6129_AwakerVoiceContent = {
    Text = "Un'Offerta alla Sua volontà."
  },
  Voice_6129_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_6130_AwakerVoiceContent = {
    Text = "Calma, calma..."
  },
  Voice_6130_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_6131_AwakerVoiceContent = {
    Text = "Ci sono molte \"me\" qui dentro. Felice, triste, arrabbiata... Amano la torta di pan di Spagna, detestano i giorni di pioggia di Londinium. Rispondono tutte al nome di \"24\", e tutte vi adorano."
  },
  Voice_6131_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_6131_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_6132_AwakerVoiceContent = {
    Text = "Un tempo lavoravo fino a mezzanotte ogni giorno—filare, lavare, pulire, badare ai bambini, persino rovistare tra i rifiuti... Facevo qualsiasi cosa per guadagnare. A quei tempi, vivere era solo sopravvivere. Ora abbiamo cibo fresco, un letto caldo e un padrone gentile come te... Va oltre i miei sogni più sfrenati."
  },
  Voice_6132_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_6132_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_6133_AwakerVoiceContent = {
    Text = "Vi prego, non preoccupatevi. Condivideremo una bistecca e un letto, e non vi causeremo mai alcun disturbo."
  },
  Voice_6133_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_6133_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_6134_AwakerVoiceContent = {
    Text = "Heh, quella donna ha così tanta paura che io esca fuori che non osa nemmeno dormire di notte. Tranquillo, non ti ucciderei—non mentre mi fai dei regali. Chi sono? Ovviamente, sono \"24\", hahaha!"
  },
  Voice_6134_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_6134_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_6135_AwakerVoiceContent = {
    Text = "Mi sento alla grande in questo momento. Cosa? Dici che la mia mente è stata presa da qualcos'altro? N-non è possibile... ehm..."
  },
  Voice_6135_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_6135_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_6136_AwakerVoiceContent = {
    Text = "Per un suddito, osservi con acume. Prima del mio prossimo lungo sonno, io... onorerò quest'era con la mia presenza."
  },
  Voice_6136_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_6137_AwakerVoiceContent = {
    Text = "Hmm... l'acqua del mare è piuttosto calda stasera..."
  },
  Voice_6137_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_6138_AwakerVoiceContent = {
    Text = "È arrivato... l'uccello bianco che volteggia nel mio sogno."
  },
  Voice_6138_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_6139_AwakerVoiceContent = {
    Text = "Come hai desiderato, la mia esistenza si è fatta più tangibile."
  },
  Voice_6139_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_6140_AwakerVoiceContent = {
    Text = "Che soddisfazione, ahaha!"
  },
  Voice_6140_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_6141_AwakerVoiceContent = {Text = "Dolcezza!"},
  Voice_6141_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_6142_AwakerVoiceContent = {
    Text = "Lascia fare a me!"
  },
  Voice_6142_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_6143_AwakerVoiceContent = {
    Text = "Lascia fare a me!"
  },
  Voice_6143_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_6144_AwakerVoiceContent = {
    Text = "Benvenuto—al nostro grande festino!"
  },
  Voice_6144_AwakerVoiceTitle = {
    Text = "Esaltazione: Mania"
  },
  Voice_6145_AwakerVoiceContent = {
    Text = "Questa ragazza... nelle sue vene scorre indubbiamente il mio sangue. No—non ho camminato su questa terra abbastanza a lungo per generare progenie. Eppure... il suo potere riflette il mio."
  },
  Voice_6145_AwakerVoiceTitle = {
    Text = "Chat: A proposito della Stirpe Divina"
  },
  Voice_6145_UnlockDesc = {
    Text = "Si sblocca dopo aver acquisito il Risvegliatore \"Aigis\" o \"Murphy\""
  },
  Voice_6146_AwakerVoiceContent = {
    Text = "La gentilezza del Padrone, Karen non osa dimenticarla nemmeno per un istante!"
  },
  Voice_6146_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_6147_AwakerVoiceContent = {
    Text = "—Ah, è così dolce e delizioso!"
  },
  Voice_6147_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_6148_AwakerVoiceContent = {
    Text = "Beh... Sono a dieta e oggi non posso mangiare troppo~"
  },
  Voice_6148_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_6149_AwakerVoiceContent = {
    Text = "Questi deboli non meritano nemmeno la mia lama."
  },
  Voice_6149_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_6150_AwakerVoiceContent = {
    Text = "Spiegare l'arte è ridicolo quanto spiegare le azioni ferroviarie — per favore, non rendete la vita più difficile a noi artisti."
  },
  Voice_6150_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_6151_AwakerVoiceContent = {
    Text = "Aigis... Ho fatto qualcosa di sbagliato?"
  },
  Voice_6151_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_6152_AwakerVoiceContent = {
    Text = "Le tue Preghiere sono state ascoltate."
  },
  Voice_6152_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_6153_AwakerVoiceContent = {
    Text = "Le tue Preghiere sono state ascoltate."
  },
  Voice_6153_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_6154_AwakerVoiceContent = {
    Text = "Hmph, insolente."
  },
  Voice_6154_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_6155_AwakerVoiceContent = {
    Text = "Ah, era il Signor N quello che ci è appena passato accanto? No, lascia stare. L'ultima volta che l'ho salutato, non mi ha riconosciuta... L'ho atteso in prigione, sperando che mi portasse via, ma non è mai venuto, nemmeno durante la rivolta."
  },
  Voice_6155_AwakerVoiceTitle = {
    Text = "Chat: A proposito di \"N\""
  },
  Voice_6155_UnlockDesc = {
    Text = "Si sblocca dopo aver completato il Capitolo 7 della Storia principale"
  },
  Voice_6156_AwakerVoiceContent = {
    Text = "Perché ho risposto alla tua chiamata? Per finire ciò che ho iniziato, ovviamente. E se diventerai abbastanza forte da sfidarmi, sarà solo un bonus."
  },
  Voice_6156_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_6157_AwakerVoiceContent = {
    Text = "Ho la Sorellona, Brown, più quella ragazza fifona dell'ospizio... Questa è la mia banda. Va bene... conterò anche te. Brown, condividi un pezzetto di caramella con {Male=him,Female=her}. \n\"Squiit?!\""
  },
  Voice_6157_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_6157_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_6158_AwakerVoiceContent = {
    Text = "I Bassifondi orientali non sono un posto per ragazzini. I vecchi capisquadra furbi trovavano ogni scusa per tagliare la paga degli strilloni, e s-sindacare sulla velocità dei lattai! Per sopravvivere là fuori, puoi contare solo su te stesso. Non vale la pena fidarsi di nessun altro."
  },
  Voice_6158_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_6158_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_6159_AwakerVoiceContent = {
    Text = "I miei \"vizi\" non cambiano da un giorno all'altro, chiaro? Dormire sotto i ponti e nei canali di scolo, sopravvivere con gli avanzi... restare in vita era già abbastanza difficile... Non puoi pretendere che mi rifaccia il letto appena sveglio! Dammi almeno due settimane per abituarmi!"
  },
  Voice_6159_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_6159_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_6160_AwakerVoiceContent = {
    Text = [[
Perdermi nello spazio mi ha fatto venire la nausea. Mi hai tirato fuori, quindi sputa il rospo su quello che ti serve, ma non aspettarti miracoli.
Sono solo un ragazzino, non vorrai mica pretendere troppo da me, vero?]]
  },
  Voice_6160_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_6160_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_6161_AwakerVoiceContent = {
    Text = "Ehi, Tipo del Distretto Ovest! Hai visto Brown? Quella piccola ghiottona ha fiutato di nuovo del cibo."
  },
  Voice_6161_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_6161_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_6162_AwakerVoiceContent = {
    Text = "Chi possiede la forza non deve usare il proprio potere per opprimere gli altri, poiché tutti condividete il mio sangue.\" Ricordo gli insegnamenti del nostro Padre Dio della Compassione. Userò questa forza solo per proteggere coloro che mi circondano."
  },
  Voice_6162_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_6162_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_6163_AwakerVoiceContent = {
    Text = "Curioso di sapere cosa ho visto all'inizio dell'universo? Certo, posso dirtelo. Ho visto il nulla."
  },
  Voice_6163_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_6163_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_6164_AwakerVoiceContent = {
    Text = "Si sta facendo più luminosa."
  },
  Voice_6164_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_6165_AwakerVoiceContent = {
    Text = "La lampada eterna..."
  },
  Voice_6165_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_6166_AwakerVoiceContent = {
    Text = "Il mio legame con la Terra dei Bianchi Uccelli si è fatto più forte."
  },
  Voice_6166_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_6167_AwakerVoiceContent = {
    Text = "Se potrò liberare questo mondo dalla sua sofferenza, sarò appagato."
  },
  Voice_6167_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_6168_AwakerVoiceContent = {
    Text = "Impartiscimi i tuoi ordini, Pallido Messaggero. Possano le tue fiamme illuminare sempre il mio sentiero."
  },
  Voice_6168_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_6169_AwakerVoiceContent = {
    Text = "(Esclamazione)"
  },
  Voice_6169_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_6170_AwakerVoiceContent = {
    Text = "La tempra di una persona non riguarda solo il corpo, ma anche il cuore."
  },
  Voice_6170_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_6171_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_6171_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_6172_AwakerVoiceContent = {Text = "Ahi!"},
  Voice_6172_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_6173_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_6173_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_6174_AwakerVoiceContent = {
    Text = "Ugh! La tua temperatura è un po' alta per il corallo. Ma... è calda e intensa. Mi piace."
  },
  Voice_6174_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_6175_AwakerVoiceContent = {
    Text = "Lah... Oh, hai bisogno di qualcosa? Se possibile, parliamo nel backstage."
  },
  Voice_6175_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_6176_AwakerVoiceContent = {
    Text = "Appassire prima di sbocciare, come una ninfea... Cercare pace nelle fredde maree furiose, troppo timida per inseguire la propria gioia... Questo è il tipo di persona che sono, Custode."
  },
  Voice_6176_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_6176_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_6177_AwakerVoiceContent = {
    Text = "Un tempo mi dibattevo in questo dilemma: il dolore è più lungo della vita stessa? Se così fosse, un placido dormiveglia è più felice di una veglia tormentata? Dopo il risveglio, anch'io ne fui intrappolata, finché tu non mi hai donato questo rifugio sicuro..."
  },
  Voice_6177_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_6177_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_6178_AwakerVoiceContent = {
    Text = "Durante la mia permanenza al sanatorio, ho provato a fare amicizia, ma le persone erano riluttanti ad avvicinarsi a me... È forse a causa di questo \"veleno\" che corrode le ossa? Ti prego, fai attenzione quando ti avvicini a me."
  },
  Voice_6178_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_6178_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_6179_AwakerVoiceContent = {
    Text = "Il suono della campana portato dal vento notturno dona una tale pace. Vorresti sederti sulla sedia di pietra e ascoltare per un po'? Preparerò per bene il tuo posto con una sciarpa."
  },
  Voice_6179_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_6179_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_6180_AwakerVoiceContent = {
    Text = "Hai mai sentito parlare della \"sepoltura in mare\"? Nella mia vecchia città, c'era l'usanza di immergere i defunti nel mare; l'oceano diventava l'ultimo luogo di riposo di tutti. Quanto a me, sono tornata al suo abbraccio anzitempo..."
  },
  Voice_6180_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_6180_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_6181_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_6181_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_6182_AwakerVoiceContent = {Text = "Ah!"},
  Voice_6182_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_6183_AwakerVoiceContent = {Text = "Argh!"},
  Voice_6183_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_6184_AwakerVoiceContent = {Text = "Ah!"},
  Voice_6184_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_6185_AwakerVoiceContent = {
    Text = "Il registro di combattimento è stato archiviato. Grazie per il vostro duro lavoro, Custode."
  },
  Voice_6185_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_6186_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_6186_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_6187_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_6187_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_6188_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_6188_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_6189_AwakerVoiceContent = {
    Text = "Posso continuare."
  },
  Voice_6189_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_6190_AwakerVoiceContent = {
    Text = "Gli ospiti del mio salone ricevono la più raffinata ospitalità... Come biglietto d'ingresso, avete preparato segreti degni di questo grande banchetto?"
  },
  Voice_6190_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6191_AwakerVoiceContent = {
    Text = "Adoro le novità. Nei miei millenni di viaggi, ho assistito a molte affascinanti innovazioni e invenzioni, come le forme poetiche e le scene cinematografiche. Gli esseri umani sono creature davvero intriganti."
  },
  Voice_6191_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_6192_AwakerVoiceContent = {
    Text = "Sì. Lily ricorda. Lily è rimasta a casa sua quando la mamma era fuori."
  },
  Voice_6192_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Daffodil"
  },
  Voice_6192_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Daffodil\""
  },
  Voice_6195_AwakerVoiceContent = {
    Text = "Chi osa disturbare il Dormiveglia di Questo Essere?"
  },
  Voice_6195_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6196_AwakerVoiceContent = {
    Text = "Dèi? Solo gli stolti affiderebbero la propria Vita a esseri così intangibili. Invece di scommettere la tua Vita sui cosiddetti dèi, faresti meglio a concentrarti su come diventare più Forte."
  },
  Voice_6196_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_6197_AwakerVoiceContent = {
    Text = "Quel \"padrone di schiavi\", \"proprietario di gladiatori\"... Ha. Non è che un insetto senza valore."
  },
  Voice_6197_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Agrippa"
  },
  Voice_6197_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Agrippa\""
  },
  Voice_6198_AwakerVoiceContent = {
    Text = "Dopo la vittoria, permettimi di prelevare i materiali necessari alla riproduzione."
  },
  Voice_6198_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_6199_AwakerVoiceContent = {
    Text = "Grande amico! Compagno! Hoo-hoo, restiamo migliori amici per sempre, va bene?"
  },
  Voice_6199_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_6200_AwakerVoiceContent = {
    Text = "Sono davvero, davvero eccitata in questo momento... Se tieni ancora alla vita, è meglio che ti allontani da me."
  },
  Voice_6200_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_6201_AwakerVoiceContent = {
    Text = "È... È davvero giusto che lei tratti gli altri in quel modo? La signora Sarah ha detto che i bambini non dovrebbero fare i capricci..."
  },
  Voice_6201_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Murphy"
  },
  Voice_6201_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risveglio \"Murphy\""
  },
  Voice_6202_AwakerVoiceContent = {
    Text = "La gloria della vittoria è vostra, mio signore."
  },
  Voice_6202_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_6203_AwakerVoiceContent = {
    Text = "T-Ti prego, sono tutta piena~"
  },
  Voice_6203_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_6204_AwakerVoiceContent = {
    Text = "Il Vuoto interiore è stato colmato~"
  },
  Voice_6204_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_6205_AwakerVoiceContent = {
    Text = "Sì, sto diventando più calda..."
  },
  Voice_6205_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_6206_AwakerVoiceContent = {
    Text = "Conosco quella bambina. A volte resta in lontananza, a osservare il mio spettacolo. Meglio che non si avvicini, altrimenti il mio piccolo pubblico finirà esausto nel corpo e nella mente!"
  },
  Voice_6206_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito di Faint"
  },
  Voice_6206_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Faint\""
  },
  Voice_6207_AwakerVoiceContent = {
    Text = "Tintura ha detto: «Ricambia la gentilezza.» Quindi, finché è nelle mie possibilità aiutare, darò una Mano..."
  },
  Voice_6207_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_6208_AwakerVoiceContent = {
    Text = "Ciao, Custode. Come posso assisterti?"
  },
  Voice_6208_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_6209_AwakerVoiceContent = {
    Text = "Un giorno, farò Ritorno sul campo di battaglia come comandante in prima linea."
  },
  Voice_6209_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_6209_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_6210_AwakerVoiceContent = {
    Text = "Riesci a crederci? Riesco a sentire il mio osso fratturato della gamba che guarisce."
  },
  Voice_6210_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_6210_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_6211_AwakerVoiceContent = {
    Text = "Ti ringrazio sinceramente per la fiducia che hai riposto nell'addestrarmi fino a questo Livello. Anche tu devi essere qualcuno che persegue la Giustizia; pertanto, continuerò a portare gloria alla nostra causa qui."
  },
  Voice_6211_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_6211_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_6212_AwakerVoiceContent = {
    Text = "Il giorno di un'altra spedizione si avvicina rapidamente, e il mio Sangue ribolle di determinazione."
  },
  Voice_6212_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_6212_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_6213_AwakerVoiceContent = {
    Text = "L'onore di essere un guerriero si sta restaurando."
  },
  Voice_6213_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_6213_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_6214_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_6214_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_6215_AwakerVoiceContent = {Text = "Ahi!"},
  Voice_6215_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_6216_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_6216_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_6217_AwakerVoiceContent = {
    Text = "Imbroglione!"
  },
  Voice_6217_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_6218_AwakerVoiceContent = {
    Text = "Ops, colpa mia! La prossima volta ci riuscirò, promesso!"
  },
  Voice_6218_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_6219_AwakerVoiceContent = {
    Text = "Sento qualcuno chiamare il mio nome: Agrippa, Agrippa, Agrippina..."
  },
  Voice_6219_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_6219_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_6220_AwakerVoiceContent = {
    Text = "Ho visto... Quella cosa risalire dall'Oscurità del pozzo; innumerevoli Occhi apparire sul suo uovo di carne. Mi fissavano, mi chiamavano... Dio del Labirinto!"
  },
  Voice_6220_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_6220_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_6221_AwakerVoiceContent = {
    Text = "Ho un fortissimo desiderio di assistere a un duello... Sarebbe ancora meglio se fosse in un Labirinto!"
  },
  Voice_6221_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_6221_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_6222_AwakerVoiceContent = {
    Text = "Contratto... Sì, voglio stipulare un Contratto con te; un eterno Contratto padrone-servo..."
  },
  Voice_6222_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_6222_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_6223_AwakerVoiceContent = {
    Text = "Hmph... Niente male. Dammene ancora. Devo nutrire questi piccoli ragnetti."
  },
  Voice_6223_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_6223_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_6224_AwakerVoiceContent = {
    Text = "Che lordura, che abominio! Ah—basta! Ti prego! Non farmelo vedere, non parlarne vicino a me..."
  },
  Voice_6224_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_6225_AwakerVoiceContent = {
    Text = "Il mio passato era fatto di routine e quiete, come i mari prossimi all'equatore; non vi è nulla degno di nota."
  },
  Voice_6225_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_6225_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_6226_AwakerVoiceContent = {
    Text = "Hmm...? Mamma, in braccio? ...Sei così calda..."
  },
  Voice_6226_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_6227_AwakerVoiceContent = {
    Text = "O Polvere di Stelle..."
  },
  Voice_6227_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_6228_AwakerVoiceContent = {
    Text = "Oh, ci siamo persi?"
  },
  Voice_6228_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_6229_AwakerVoiceContent = {Text = "Inutile."},
  Voice_6229_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_6230_AwakerVoiceContent = {
    Text = "Ogni volta che ricordo quei traditori in ginocchio a implorare pietà piangendo, provo un'ondata di soddisfazione, e le fiamme nel mio cuore sembrano placarsi."
  },
  Voice_6230_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_6231_AwakerVoiceContent = {
    Text = "Fui condotta sulla nave e investita della missione di fanciulla della nave molti anni fa. Da allora, la mia vita — e il suo significato — sono sfuggiti al mio controllo. Mi è stato detto che dovrei vivere per i miei desideri, almeno in questa seconda vita da Risvegliata... Mi aiutereste? Aiutatemi a diventare egoista, aiutatemi a trovare il mio desiderio."
  },
  Voice_6231_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_6231_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_6232_AwakerVoiceContent = {
    Text = "Sono Agrippa. Non ho nulla da dirti — a meno che tu non abbia il coraggio di offrirti volontario come mio Gladiatore."
  },
  Voice_6232_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6233_AwakerVoiceContent = {
    Text = "Tawil... è molto più pericolosa di quanto crediamo. Quando non ci sarò più, dovrai essere estremamente cauto con lei."
  },
  Voice_6233_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Tawil"
  },
  Voice_6235_AwakerVoiceContent = {
    Text = "Con questo dispositivo di ragionamento deduttivo... interpreterò il mondo!"
  },
  Voice_6235_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_6236_AwakerVoiceContent = {
    Text = "Con questo dispositivo di ragionamento deduttivo... interpreterò il mondo!"
  },
  Voice_6236_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_6237_AwakerVoiceContent = {
    Text = "Risplendi per me!"
  },
  Voice_6237_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6238_AwakerVoiceContent = {
    Text = "Al meglio delle mie Abilità."
  },
  Voice_6238_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_6239_AwakerVoiceContent = {
    Text = "Al meglio delle mie Abilità."
  },
  Voice_6239_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_6240_AwakerVoiceContent = {
    Text = "Marciremo... insieme."
  },
  Voice_6240_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_6241_AwakerVoiceContent = {
    Text = "Marciremo... insieme."
  },
  Voice_6241_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_6242_AwakerVoiceContent = {
    Text = "Sorrisi e buone maniere fungono da corazza, aiutandomi a mantenere le distanze dagli altri ed evitare fastidi tediosi. Quanto al mio vero io... non mi dispiace mostrartelo."
  },
  Voice_6242_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_6242_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_6243_AwakerVoiceContent = {
    Text = "I miei pensieri si accumulano come calcare bianco e vengono plasmati in splendido corallo. Si fondono con me, pulsando col mio battito cardiaco... Vorrai ascoltarli?"
  },
  Voice_6243_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_6243_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_6244_AwakerVoiceContent = {
    Text = "L'Ispirazione è come bolle che affiorano nel mare: un tocco delicato, e svaniscono. Sei forse la stessa cosa?"
  },
  Voice_6244_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_6244_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_6245_AwakerVoiceContent = {
    Text = "Guerra, saccheggio e fama sono tutti desideri umani. L'umile Scultore non ha alcun interesse per ciò che gli umani perseguono; desidera soltanto essere Schiavo della bellezza."
  },
  Voice_6245_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_6245_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_6246_AwakerVoiceContent = {
    Text = "Una Vita meravigliosa risiede nell'Indulgenza. A volte, non dovresti essere troppo dura con te stessa."
  },
  Voice_6246_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_6246_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_6247_AwakerVoiceContent = {
    Text = "Solo un graffio..."
  },
  Voice_6247_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_6249_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_6249_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_6250_AwakerVoiceContent = {
    Text = "Maledizione!"
  },
  Voice_6250_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_6251_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_6251_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_6252_AwakerVoiceContent = {
    Text = "La dissoluzione porta caos e disastri. Forse la mia terra natia è sprofondata nel mare profondo a causa sua..."
  },
  Voice_6252_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_6253_AwakerVoiceContent = {Text = "Hah!"},
  Voice_6253_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_6254_AwakerVoiceContent = {Text = "Agh!"},
  Voice_6254_AwakerVoiceTitle = {
    Text = "Abilità Speciale: I"
  },
  Voice_6255_AwakerVoiceContent = {
    Text = "Comando assoluto."
  },
  Voice_6255_AwakerVoiceTitle = {
    Text = "Abilità Speciale: I"
  },
  Voice_6256_AwakerVoiceContent = {
    Text = "Prova questo!"
  },
  Voice_6256_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_6257_AwakerVoiceContent = {
    Text = "Sacrificio inevitabile."
  },
  Voice_6257_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_6258_AwakerVoiceContent = {
    Text = "Niente male; questa è la gloria di un guerriero!"
  },
  Voice_6258_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_6259_AwakerVoiceContent = {
    Text = "Tu! Come hai potuto far entrare quella Donna qui?! Stabilisci immediatamente un perimetro! Tienila ad almeno cinquanta passi da me!"
  },
  Voice_6259_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Miryam"
  },
  Voice_6259_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risveglio \"Miryam\""
  },
  Voice_6260_AwakerVoiceContent = {
    Text = "La ragione per diventare più Forte? Nella mia tribù, i deboli vengono denudati, rasati a zero e sottoposti alla più vile delle umiliazioni immaginabili — il prezzo della Debolezza non è qualcosa che Tutti possano sopportare."
  },
  Voice_6260_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_6260_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_6261_AwakerVoiceContent = {
    Text = "Dea della Fortuna, sorridi per me solo questa volta!"
  },
  Voice_6261_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6262_AwakerVoiceContent = {
    Text = "Credo... che la forza umana abbia i suoi limiti..."
  },
  Voice_6262_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_6263_AwakerVoiceContent = {
    Text = "Bene. Meno sforzo, più potere."
  },
  Voice_6263_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_6263_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_6264_AwakerVoiceContent = {
    Text = "È questa la manifestazione del tuo desiderio, approfondire il mio affetto?"
  },
  Voice_6264_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_6264_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_6265_AwakerVoiceContent = {Text = "Esulta!"},
  Voice_6265_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6266_AwakerVoiceContent = {
    Text = "(Esclamazione)"
  },
  Voice_6266_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_6267_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_6267_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_6268_AwakerVoiceContent = {
    Text = "(Esclamazione)"
  },
  Voice_6268_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_6269_AwakerVoiceContent = {
    Text = "Ah, imperdonabile..."
  },
  Voice_6269_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_6270_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_6271_AwakerVoiceContent = {
    Text = "Non farebbe male essere un po' spericolati!"
  },
  Voice_6271_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_6272_AwakerVoiceContent = {Text = "Bang!"},
  Voice_6272_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_6273_AwakerVoiceContent = {
    Text = "Continua così! I tuoi voti finali sono promettenti."
  },
  Voice_6273_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_6274_AwakerVoiceContent = {
    Text = "Ho sentito che un ladro dei bassifondi si è fatto vivo, portandosi dietro un topo grasso? Hehehe... Guardate come elimino questa minaccia per il mio Maestro!"
  },
  Voice_6274_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Jenkin"
  },
  Voice_6274_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Jenkin\""
  },
  Voice_6275_AwakerVoiceContent = {
    Text = "Forza, fai un respiro profondo—"
  },
  Voice_6275_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6276_AwakerVoiceContent = {
    Text = "Interessante. La tua crescita in battaglia supera di gran lunga le mie aspettative. Con il tempo, potresti diventare... Strano. Anche dopo tutto questo tempo, trovo ancora speranza in una creatura apparentemente debole come te."
  },
  Voice_6276_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_6276_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_6277_AwakerVoiceContent = {
    Text = "Forse è giunto il momento. Ascolta bene. Lotan, la Bestia delle Stelle, ti sfida formalmente. Non temere; garantirò la tua sopravvivenza finché non raggiungerai il tuo apice. Non permetterò che il mio avversario prescelto subisca ancora la stessa sorte."
  },
  Voice_6277_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_6277_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_6278_AwakerVoiceContent = {
    Text = "Hmph... Ancora non riesco a capire perché Ramona ti abbia scelto come partner. Puzzi di forza, sì, ma non sei neanche lontanamente al mio livello."
  },
  Voice_6278_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_6278_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_6279_AwakerVoiceContent = {
    Text = "Sì, contemplami. Sono l'essere più antico di questo pianeta, e pretendo reverenza dagli insignificanti. Ho custodito questo pianeta per eoni. È davvero troppo chiedere in cambio una battaglia esaltante?"
  },
  Voice_6279_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_6279_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_6280_AwakerVoiceContent = {
    Text = "Hah! Non ho tempo per giochi infantili. Trovati un angolo e levati dai piedi."
  },
  Voice_6280_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_6280_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_6281_AwakerVoiceContent = {
    Text = "Anime prive di protezione, vi concederò la pace finale."
  },
  Voice_6281_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_6282_AwakerVoiceContent = {Text = "Allerta."},
  Voice_6282_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_6283_AwakerVoiceContent = {Text = "Allerta."},
  Voice_6283_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_6284_AwakerVoiceContent = {
    Text = "Qualcosa si lamenta... nella mia mente."
  },
  Voice_6284_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_6284_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_6285_AwakerVoiceContent = {
    Text = "È come se un velo di nebbia bianca offuscasse i miei pensieri."
  },
  Voice_6285_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_6285_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_6286_AwakerVoiceContent = {
    Text = "Il suono è più forte ora. La nebbia si infittisce."
  },
  Voice_6286_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_6286_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_6287_AwakerVoiceContent = {
    Text = "È quello il suono... delle lancette dell'orologio che girano?"
  },
  Voice_6287_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_6287_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_6288_AwakerVoiceContent = {
    Text = "Quando l'ultimo rintocco di campana risuonerà... sarò ancora qui?"
  },
  Voice_6288_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_6288_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_6289_AwakerVoiceContent = {
    Text = "Che trucco maldestro... Hmph. Sciocco ingenuo. Credevi davvero di potermi vincolare così facilmente?"
  },
  Voice_6289_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6290_AwakerVoiceContent = {
    Text = "Scusate... Avete visto mia sorella, Jenkin? È una Bambina che porta con sé un topo e può essere piuttosto feroce... Non potrei mai confonderla."
  },
  Voice_6290_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Jenkin"
  },
  Voice_6290_UnlockDesc = {
    Text = "Si sblocca dopo aver completato il Capitolo 2 della Storia Principale"
  },
  Voice_6292_AwakerVoiceContent = {
    Text = "Grazie. Sei troppo gentile."
  },
  Voice_6292_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_6293_AwakerVoiceContent = {Text = "Pronta."},
  Voice_6293_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_6294_AwakerVoiceContent = {
    Text = "Ti prego, attendi con ansia la mia esibizione."
  },
  Voice_6294_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_6295_AwakerVoiceContent = {
    Text = "Canterò per te."
  },
  Voice_6295_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_6296_AwakerVoiceContent = {
    Text = "Un nuovo Custode? Avanti, dacci dentro con tutto ciò che hai. Vediamo se sei degno di affrontarmi!"
  },
  Voice_6296_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6297_AwakerVoiceContent = {
    Text = "Sebbene io sia pacifista, \"loro\" la pensano chiaramente in modo diverso..."
  },
  Voice_6297_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_6298_AwakerVoiceContent = {Text = "Ha!"},
  Voice_6298_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_6299_AwakerVoiceContent = {Text = "Indietro!"},
  Voice_6299_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_6300_AwakerVoiceContent = {
    Text = "Come osi infliggermi un'umiliazione simile..."
  },
  Voice_6300_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_6301_AwakerVoiceContent = {
    Text = "Pronti? Lo spettacolo di magia di Casiah sta per cominciare! Non distogliere lo sguardo, non vorrai perderti il meglio. È l'Inizio dello Spettacolo!"
  },
  Voice_6301_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6302_AwakerVoiceContent = {
    Text = "Tekeli—Li!"
  },
  Voice_6302_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_6303_AwakerVoiceContent = {Text = "Ha!"},
  Voice_6303_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_6304_AwakerVoiceContent = {
    Text = "Ho ottenuto il tuo programma da Sylvia, ed è troppo impegnativo per le reclute. Capisco che stai facendo la cosa giusta, ma sovraccaricare i novellini potrebbe causare problemi inutili alla squadra.\nDici di non essere una recluta? No, lo vedo dal tuo sguardo; ci sono molte cose che non hai ancora sperimentato."
  },
  Voice_6304_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_6304_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_6305_AwakerVoiceContent = {
    Text = "Detesto davvero i miei fallimenti... Oh! Non c'è bisogno di consolarmi! Quelle sofferenze passate sono diventate ciò che mi spinge a crescere. Non sono forse già diventato il vostro Irremovibile sostegno?"
  },
  Voice_6305_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_6306_AwakerVoiceContent = {
    Text = "Non riesco proprio ad andare d'accordo con quel tipo. La vita non è tutta peccato e punizione, no? Cosa c'è di male nel cogliere l'attimo?"
  },
  Voice_6306_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Salvador"
  },
  Voice_6306_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risveglio \"Salvador\""
  },
  Voice_6307_AwakerVoiceContent = {
    Text = "Il tempo stringe. Muoviamoci."
  },
  Voice_6307_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_6308_AwakerVoiceContent = {
    Text = "Detesto le candele che si spengono facilmente, il pane nero e i fili sciolti sulle gonne... Senza motivo, semplicemente li aborrisco. Non è forse naturale?"
  },
  Voice_6308_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_6309_AwakerVoiceContent = {
    Text = "Dato che mi avete incoronata vostra Santa Ancella, vi sottometterete!"
  },
  Voice_6309_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_6310_AwakerVoiceContent = {
    Text = "Dato che mi avete incoronata vostra Santa Ancella, vi sottometterete!"
  },
  Voice_6310_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_6311_AwakerVoiceContent = {
    Text = "Canta per me."
  },
  Voice_6311_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_6312_AwakerVoiceContent = {
    Text = "\"Il guardaroba della signora\" e \"La Guida della Donna lavoratrice\" sono entrambe letture eccellenti... Anche se non posso permettermi quei bei vestiti, ammirarli è già un piacere."
  },
  Voice_6312_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_6313_AwakerVoiceContent = {
    Text = "È strano. Di solito faccio molta fatica a ricordare le cose, eppure ti ho memorizzato in pochi giorni... Cosa? Sono già passati tre mesi? Mi dispiace, ho dimenticato di nuovo."
  },
  Voice_6313_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_6314_AwakerVoiceContent = {
    Text = "Assaporalo."
  },
  Voice_6314_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_6316_AwakerVoiceContent = {
    Text = "Continua a migliorare la tua Compostezza."
  },
  Voice_6316_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_6317_AwakerVoiceContent = {
    Text = "Fouetté. Altre venti volte."
  },
  Voice_6317_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_6318_AwakerVoiceContent = {
    Text = "I miei movimenti sono abbastanza precisi?"
  },
  Voice_6318_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_6319_AwakerVoiceContent = {
    Text = "Prego, avanti!"
  },
  Voice_6319_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_6320_AwakerVoiceContent = {
    Text = "Presto, afferra Brown e filiamocela!"
  },
  Voice_6320_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_6321_AwakerVoiceContent = {
    Text = "Inginocchiati dinanzi al trono."
  },
  Voice_6321_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_6322_AwakerVoiceContent = {
    Text = "Inginocchiati dinanzi al trono."
  },
  Voice_6322_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_6323_AwakerVoiceContent = {
    Text = "I volti umani distorti dal desiderio non smettono mai di divertirmi. Così fragili, così piccoli... Questo solo basta a farmi sentire come se un gatto mi graffiasse il cuore..."
  },
  Voice_6323_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_6324_AwakerVoiceContent = {
    Text = "Ho visto eventi passati della Dissoluzione nelle sue memorie... Ma ogni volta che provo a parlarne, la mia coscienza si spezza. Credo sia opera sua."
  },
  Voice_6324_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_6325_AwakerVoiceContent = {
    Text = "Bene. Ora svaniremo semplicemente nell'oblio."
  },
  Voice_6325_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_6326_AwakerVoiceContent = {
    Text = "Un servitore qualificato dev'essere malleabile e vacuo — preferisco agnelli obbedienti."
  },
  Voice_6326_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_6327_AwakerVoiceContent = {
    Text = "Il nostro incontro dev'essere una promessa del Padre a coloro che soffrono. Tu sei la Fiamma Pallida che dissipa le calamità, e io sarò il tuo braccio, fedelmente al tuo fianco."
  },
  Voice_6327_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6328_AwakerVoiceContent = {Text = "Ora basta!"},
  Voice_6328_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_6329_AwakerVoiceContent = {
    Text = "Ti hanno mai iniettato della D-melma nelle vene? La melassa nera si avvolge attorno al cuore come una vipera, e poi... boom! Il tuo Corpo esplode in un caldo ammasso di polpa. Disgustoso, ma efficace."
  },
  Voice_6329_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_6330_AwakerVoiceContent = {
    Text = "Hmph, un rifugio dove i deboli si stringono l'uno all'altro."
  },
  Voice_6330_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_6331_AwakerVoiceContent = {
    Text = "Di tanto in tanto, la bambina sulla motocicletta mi aiuta con la manutenzione dell'arto protesico. Tuttavia, ultimamente, la frequenza dei controlli non è stata eccessivamente alta?"
  },
  Voice_6331_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Nautila"
  },
  Voice_6331_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Nautila\""
  },
  Voice_6332_AwakerVoiceContent = {
    Text = "La nostra relazione? Hai davvero bisogno di chiedere? È esattamente ciò che stai immaginando!"
  },
  Voice_6332_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_6333_AwakerVoiceContent = {
    Text = "Non è il mio genere di versi prediletto, ma se insistete, tenterò."
  },
  Voice_6333_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_6334_AwakerVoiceContent = {
    Text = "Le tue occhiaie peggiorano... Perché affaticarti così? Dovresti essere più come me e imparare a concederti l'ozio."
  },
  Voice_6334_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_6334_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_6335_AwakerVoiceContent = {
    Text = "Aspetta, senza il mio permesso..."
  },
  Voice_6335_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_6335_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_6336_AwakerVoiceContent = {
    Text = "Bene... Mi avvicino alla mia forma originaria."
  },
  Voice_6336_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_6336_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_6337_AwakerVoiceContent = {
    Text = "Questo è il Potere per contrastare la \"Corruzione Verde\"... Hai toccato qualcosa di proibito. Quanto a me, non ti lascerò mai più andare."
  },
  Voice_6337_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_6337_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_6338_AwakerVoiceContent = {
    Text = "Shh... Il bagliore mattutino della valle — dev'essere la prima volta che lo vedi, no? Consideralo la tua ricompensa per la lealtà."
  },
  Voice_6338_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_6338_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_6339_AwakerVoiceContent = {
    Text = "Questo tomo, \"La @1@2 Rivelazione,\" ora è tuo. Aiuta a Illuminare la mente, o forse, a invitare rapidamente il Dormiveglia."
  },
  Voice_6339_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_6339_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_6340_AwakerVoiceContent = {
    Text = "Il clamore dei mortali mi affatica. Un angolo tranquillo in questa accademia basterebbe... No, non ho bisogno di un camino. Solo l'austerità può portare le mie preghiere a Lui..."
  },
  Voice_6340_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_6341_AwakerVoiceContent = {
    Text = "È cera o miele quello che cola dal mio Corpo? Perché non dai una leccatina e lo scopri da solo?"
  },
  Voice_6341_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_6341_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_6342_AwakerVoiceContent = {
    Text = "C-Ciao... Piacere di conoscerti. Il mio nome è Aigis... P-Per favore, non farci caso! Fai finta che io non esista..."
  },
  Voice_6342_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6343_AwakerVoiceContent = {
    Text = "Finché sono ancora \"Ramona\"... siamo ancora compagni, non è vero?"
  },
  Voice_6343_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_6344_AwakerVoiceContent = {
    Text = "Quella signora con le occhiaie pesanti una volta mi ha consultato riguardo al \"vivere per sempre al sole\"... Le bastava migrare tra due Dimensioni. Eppure, si rifiuta di entrare nel Tunnel Dimensionale. È stato davvero un grattacapo."
  },
  Voice_6344_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Winkle"
  },
  Voice_6344_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Winkle\""
  },
  Voice_6345_AwakerVoiceContent = {
    Text = "Benvenuto nel mio Paradise! Allora, sei pronto per la mia frusta?"
  },
  Voice_6345_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6346_AwakerVoiceContent = {
    Text = "Poiché Egli vi ha ritenuto degno, non vi considererò più un avversario."
  },
  Voice_6346_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_6347_AwakerVoiceContent = {
    Text = "Cosa vuol dire \"l'ho preso io\"? Non è giusto! Quando le sue stupide viti sono sparite, io ero impegnato... Brown, smettila! ... Heh, dimentica quello che hai visto, d'accordo?"
  },
  Voice_6347_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Nautila"
  },
  Voice_6347_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Nautila\""
  },
  Voice_6348_AwakerVoiceContent = {
    Text = "L'avventura è emozionante proprio come nelle storie! Qual era quella storia...?"
  },
  Voice_6348_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_6349_AwakerVoiceContent = {
    Text = "...Hic. Ah, scusa, ho consumato troppa energia di nuovo."
  },
  Voice_6349_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_6350_AwakerVoiceContent = {
    Text = "Una volta dentro un involucro umano, persi ogni contatto con i miei simili. Sono terrorizzata al pensiero che gli altri non siano sfuggiti al demone e che io possa essere l'ultima della mia specie... Ti prego, Custode, salvami! Lasciami restare al tuo fianco, non abbandonarmi all'oscurità..."
  },
  Voice_6350_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_6350_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_6351_AwakerVoiceContent = {
    Text = "Quando il mio pianeta fu distrutto, abbandonai il mio corpo e trasferii la mia coscienza in un involucro umano... Ma il demone nero mi inseguì senza sosta, vincolando il mio spirito e impedendomi la fuga! Cerca di trascinare questo mondo in un abisso di oscurità!"
  },
  Voice_6351_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_6351_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_6352_AwakerVoiceContent = {
    Text = "Ti prego, Custode... Purché tu mi lasci restare al localizzatore senza muovermi, farò qualsiasi cosa, tranne entrare nell'oscurità e affrontare quella... quella cosa nera! Non posso lasciare questo posto! Ancora un poco e avrò localizzato le spoglie del mio pianeta natale! Mancano solo 1,2 miliardi di calcoli!"
  },
  Voice_6352_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_6352_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_6353_AwakerVoiceContent = {
    Text = "Potresti usare la tua quota di rifornimenti per procurarmi due confezioni di integratori di caffeina?... Non riesco a dormire. Perché dovrei dormire? Non devo dormire mai! Appena chiudo gli occhi, tutto diventa oscurità... oscurità senza fine..."
  },
  Voice_6353_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_6353_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_6354_AwakerVoiceContent = {
    Text = "Whoa! Stai lontano da me! P-Prima devi dimostrare di non essere un servitore dell'oscurità! Già, togliti i vestiti e fammi vedere che non hai quella disgustosa melma nera sul corpo, così saprò che non sei malvagio..."
  },
  Voice_6354_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_6354_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_6355_AwakerVoiceContent = {
    Text = "Non chiedere! Non chiedere! Sai benissimo cosa temo e odio di più! L'oscurità! L'oscurità senza fine!"
  },
  Voice_6355_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_6356_AwakerVoiceContent = {
    Text = "Un metodo per curare la Dissoluzione? Una cosa del genere non esiste da nessuna parte. Chiedi come faccio a non essere infetta? Hehe... Basta \"non farsi vedere\"."
  },
  Voice_6356_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_6357_AwakerVoiceContent = {
    Text = "Grazie, Padrone."
  },
  Voice_6357_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_6358_AwakerVoiceContent = {
    Text = "Anche le pustole sono felici."
  },
  Voice_6358_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_6359_AwakerVoiceContent = {
    Text = "Lily è diventata più grande."
  },
  Voice_6359_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_6360_AwakerVoiceContent = {
    Text = "Li schiaccio?"
  },
  Voice_6360_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_6361_AwakerVoiceContent = {
    Text = "Come osi evocarlo! Quell'inutile, pigro buono a nulla! Un tempo lo tenevo in grande considerazione! Via di qui! Mi rifiuto di guardare quello stolto!"
  },
  Voice_6361_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Tulu"
  },
  Voice_6361_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Tulu\""
  },
  Voice_6362_AwakerVoiceContent = {
    Text = "Disgustoso!"
  },
  Voice_6362_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_6363_AwakerVoiceContent = {
    Text = "Tsk, che seccatura!"
  },
  Voice_6363_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_6364_AwakerVoiceContent = {
    Text = "La prossima volta, andiamo a vedere il mare insieme. Febvre va bene; posso farti da guida. O in qualsiasi altro luogo, persino ai confini della terra — voglio andarci con te."
  },
  Voice_6364_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_6364_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_6365_AwakerVoiceContent = {
    Text = "Il mare ha un suo linguaggio. Proprio così... a volte riesco a chiacchierare con i pesciolini nello stagno della nostra terra natale. Se sei curioso, posso aiutarti a tradurre."
  },
  Voice_6365_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_6365_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_6366_AwakerVoiceContent = {
    Text = "Essere salvata da te... spesso provo una gioia che mi terrorizza... Ti prego, dimmi che questo non è un sogno, e che non svanirai nel mare senza lasciare traccia, vero?"
  },
  Voice_6366_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_6366_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_6367_AwakerVoiceContent = {
    Text = "Questo sentimento può davvero essere chiamato \"Gioia\"? Io... non ho mai osato sperarlo prima d'ora."
  },
  Voice_6367_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_6367_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_6368_AwakerVoiceContent = {
    Text = "Il mio corpo si sente caldo, come se fosse dolcemente avvolto dal mare. È davvero incredibile."
  },
  Voice_6368_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_6368_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_6369_AwakerVoiceContent = {
    Text = "Quel ragazzo è il Frammento di Lui? Niente male. Ha certamente un portamento regale."
  },
  Voice_6369_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Tulu"
  },
  Voice_6369_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Tulu\""
  },
  Voice_6370_AwakerVoiceContent = {
    Text = "No, non farlo! Non continuare! Mi troverà! Mi troverà!"
  },
  Voice_6370_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_6371_AwakerVoiceContent = {
    Text = "Questo dovrebbe tenermi sveglio."
  },
  Voice_6371_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_6372_AwakerVoiceContent = {
    Text = "È finita! È finita! È finita! Lo scopriranno di sicuro..."
  },
  Voice_6372_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_6373_AwakerVoiceContent = {
    Text = "Abbiamo vinto. Sei felice? Che sensazione dà essere \"felici\"?"
  },
  Voice_6373_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_6374_AwakerVoiceContent = {
    Text = "Cose che mi piacciono? Mi piacciono le ninne nanne di Tintura... Certo, anche il tuo canto è meraviglioso!"
  },
  Voice_6374_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_6375_AwakerVoiceContent = {
    Text = "Era una Lama degna. Un tempo lo chiamavo \"compagno\"... La mia scelta di parole ti disturba? Allora, ti prego, illuminami."
  },
  Voice_6375_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Golia"
  },
  Voice_6375_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Golia\""
  },
  Voice_6378_AwakerVoiceContent = {
    Text = "O Meteora..."
  },
  Voice_6378_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_6379_AwakerVoiceContent = {Text = "Ah—"},
  Voice_6379_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_6380_AwakerVoiceContent = {
    Text = "Il potere dilaga, senza sosta, riempiendo tutto il mio corpo..."
  },
  Voice_6380_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_6381_AwakerVoiceContent = {
    Text = "Ecco a voi! Volate!"
  },
  Voice_6381_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_6382_AwakerVoiceContent = {
    Text = "Niente male. Sei meno inutile di quanto sembri."
  },
  Voice_6382_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_6383_AwakerVoiceContent = {
    Text = "Venti, ventuno, ventiquattro... Aspetta, a che numero ero? Uno, due, tre..."
  },
  Voice_6383_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_6383_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_6384_AwakerVoiceContent = {
    Text = "Finalmente ho capito quanti materiali avevo prima, così posso finire le riparazioni più in fretta— Aspetta, da dove sono saltati fuori questi?"
  },
  Voice_6384_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_6384_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_6385_AwakerVoiceContent = {
    Text = "Grazie al tuo aiuto, l'efficienza delle riparazioni recenti è migliorata. Presto potremo partire per l'avventura!"
  },
  Voice_6385_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_6385_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_6386_AwakerVoiceContent = {
    Text = "Credo di iniziare a ricordare qualcosa... Mi hai passato una chiave inglese n. 7 ieri?"
  },
  Voice_6386_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_6386_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_6387_AwakerVoiceContent = {
    Text = "Riparazione completa! Un'avventura sconosciuta, un mondo misterioso, arrivo!"
  },
  Voice_6387_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_6387_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_6388_AwakerVoiceContent = {Text = "Boom—"},
  Voice_6388_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_6389_AwakerVoiceContent = {
    Text = "Non ingannare te stesso. Le catene mentali restano catene e non possono dirsi eque."
  },
  Voice_6389_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_6390_AwakerVoiceContent = {
    Text = "Ora il confine tra me e il Risvegliato è ancora più sfumato. Prenditi cura di me, d'accordo?"
  },
  Voice_6390_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_6390_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_6391_AwakerVoiceContent = {
    Text = "Andiamo. Abbiamo un mondo da salvare."
  },
  Voice_6391_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_6391_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_6392_AwakerVoiceContent = {
    Text = "È rinvigorente come leggere \"L'origine delle specie\" tutto d'un fiato."
  },
  Voice_6392_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_6392_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_6393_AwakerVoiceContent = {
    Text = "Sono diventato più forte. Lasciami provare a gestire la prossima missione da solo, d'accordo?"
  },
  Voice_6393_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_6393_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_6394_AwakerVoiceContent = {
    Text = "A parte l'abilità in combattimento, la mia memoria e il mio pensiero logico non sono migliorati granché. In effetti, non dovrei affidarmi a qualcos'altro per pensare al posto mio."
  },
  Voice_6394_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_6394_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_6395_AwakerVoiceContent = {
    Text = "Voglio che provino cosa significhi veder la propria vita stravolta, perdere tutto ed essere calpestati da tutti."
  },
  Voice_6395_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_6395_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_6396_AwakerVoiceContent = {
    Text = "L'umiliazione che ho sopportato, tutto ciò che ho perso... Gliela farò pagare. La farò pagare a tutti loro."
  },
  Voice_6396_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_6396_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_6397_AwakerVoiceContent = {
    Text = "Un odio così dolce, condito col sangue dei nemici, è senza dubbio il piatto più squisito del mondo."
  },
  Voice_6397_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_6397_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_6398_AwakerVoiceContent = {
    Text = "Aaah! Non avvicinarti di soppiatto alle mie spalle!"
  },
  Voice_6398_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_6399_AwakerVoiceContent = {
    Text = "Le fiamme ardenti bruciano nel mio petto... Sì, non ho mai dimenticato, né potrò mai dimenticare."
  },
  Voice_6399_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_6399_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_6400_AwakerVoiceContent = {
    Text = "Brucia, o anima della poesia."
  },
  Voice_6400_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6401_AwakerVoiceContent = {
    Text = "(Canticchia)"
  },
  Voice_6401_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_6402_AwakerVoiceContent = {
    Text = "(Canticchia)"
  },
  Voice_6402_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_6403_AwakerVoiceContent = {
    Text = "(Canticchia)"
  },
  Voice_6403_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_6404_AwakerVoiceContent = {
    Text = "(Canticchia)"
  },
  Voice_6404_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_6405_AwakerVoiceContent = {
    Text = "Mi fa il solletico! Proprio come quando l'Ancella usa una piuma per solleticarmi la pianta dei piedi. Non l'hai fatto apposta, vero?!"
  },
  Voice_6405_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_6405_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_6406_AwakerVoiceContent = {
    Text = "Che tu possa fare un dolce Sogno."
  },
  Voice_6406_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_6407_AwakerVoiceContent = {
    Text = "Che tu possa fare un dolce Sogno."
  },
  Voice_6407_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_6408_AwakerVoiceContent = {
    Text = "Concedi serenità...!"
  },
  Voice_6408_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_6409_AwakerVoiceContent = {
    Text = "Muoviti con eleganza."
  },
  Voice_6409_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_6410_AwakerVoiceContent = {
    Text = "Riesci a sentirmi? A udire la mia voce?"
  },
  Voice_6410_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_6411_AwakerVoiceContent = {
    Text = "Riesci a sentirmi? A udire la mia voce?"
  },
  Voice_6411_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_6412_AwakerVoiceContent = {
    Text = "Piove. La Pioggia lava via ogni cosa: il cibo andato a male, la sporcizia Ostinata, e persone come me... le superflue."
  },
  Voice_6412_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_6413_AwakerVoiceContent = {
    Text = "La Marea furente della vendetta non si placa mai!"
  },
  Voice_6413_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6414_AwakerVoiceContent = {
    Text = "Bàgnati nel sangue dei miei nemici!"
  },
  Voice_6414_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6415_AwakerVoiceContent = {Text = "Argh!"},
  Voice_6415_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_6416_AwakerVoiceContent = {
    Text = "Guarda da questa parte!"
  },
  Voice_6416_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_6417_AwakerVoiceContent = {
    Text = "Non puoi spaventarmi."
  },
  Voice_6417_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_6418_AwakerVoiceContent = {Text = "Attento!"},
  Voice_6418_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_6419_AwakerVoiceContent = {
    Text = "Un mondo intatto dal Pianto, incontaminato dal dolore, libero dalla pena e immune dalla sofferenza... forse un'Illusione irraggiungibile, ma è l'ideale che ho perseguito per tutta la vita."
  },
  Voice_6419_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_6420_AwakerVoiceContent = {
    Text = "Contempla la magnificenza del Regno Eterno!"
  },
  Voice_6420_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_6421_AwakerVoiceContent = {
    Text = "Contempla la magnificenza del Regno Eterno!"
  },
  Voice_6421_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_6422_AwakerVoiceContent = {
    Text = "Offri i tuoi tributi obbedientemente, ancora una volta? Che {Male=bravo ragazzo,Female=brava ragazza}."
  },
  Voice_6422_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_6422_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_6423_AwakerVoiceContent = {
    Text = "Ti fa male?"
  },
  Voice_6423_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_6424_AwakerVoiceContent = {
    Text = "Resta concentrata."
  },
  Voice_6424_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_6425_AwakerVoiceContent = {
    Text = "Il passaggio dei millenni mi ha resa alquanto incauta."
  },
  Voice_6425_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_6426_AwakerVoiceContent = {
    Text = "Quel giorno, le fiamme della gelosia si propagarono come un mare di rose rosso sangue in piena fioritura... Tutti i poemi si ridussero in Ceneri infrante tra le lingue Cremisi del fuoco."
  },
  Voice_6426_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_6426_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_6427_AwakerVoiceContent = {
    Text = "Ho imparato una nuova tecnica!"
  },
  Voice_6427_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_6428_AwakerVoiceContent = {
    Text = "Fa' attenzione."
  },
  Voice_6428_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_6429_AwakerVoiceContent = {
    Text = "La mia bacchetta vuole danzare!"
  },
  Voice_6429_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_6430_AwakerVoiceContent = {
    Text = "Ah, questa familiare sensazione di vuoto!"
  },
  Voice_6430_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_6431_AwakerVoiceContent = {
    Text = "La coordinazione dei miei movimenti è notevolmente migliorata."
  },
  Voice_6431_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_6432_AwakerVoiceContent = {
    Text = "Quella presenza oscura mi ricorda la mia Spada-Scudo Informe... Oh! State tranquillo, mio signore, la mia Spada guardiana non vi farà mai del male!"
  },
  Voice_6432_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_6433_AwakerVoiceContent = {Text = "Avanti."},
  Voice_6433_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_6434_AwakerVoiceContent = {
    Text = "Niente male, suppongo."
  },
  Voice_6434_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_6435_AwakerVoiceContent = {
    Text = "Farò del mio meglio."
  },
  Voice_6435_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6436_AwakerVoiceContent = {
    Text = "Oggi si gioca qui?"
  },
  Voice_6436_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_6437_AwakerVoiceContent = {
    Text = "Quel seminterrato era pieno d'acqua, morbida e fredda. Così, il mio corpo era sempre avvolto dall'umidità... Come se fossi l'unico essere fisico rimasto tra cielo e terra. A volte, desideravo davvero dissolvermi nell'acqua. Ma allora non esisterei e non ti avrei mai incontrato."
  },
  Voice_6437_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_6437_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_6438_AwakerVoiceContent = {
    Text = "Ti svelo un segreto... In realtà detesto il sangue. Ne odio il colore, il sapore. Ma non posso vivere senza... Ingoio il sangue, poi lo vomito tutto... Ah, come mi odio."
  },
  Voice_6438_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_6438_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_6439_AwakerVoiceContent = {
    Text = "Ah! Il tuo sangue... sa di idromele. Suppongo di essere l'unica a conoscere questo segreto, vero?"
  },
  Voice_6439_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_6439_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_6440_AwakerVoiceContent = {
    Text = "Nelle mie fantasie, un valoroso cavaliere mi trascina fuori dall'oscurità, poi mi lega in catene. {Male=He,Female=She} può colpirmi, maledirmi, fare tutto ciò che {Male=he,Female=she} desidera—il dolore è la mia prova di vita. Vorresti... essere il mio cavaliere?"
  },
  Voice_6440_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_6440_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_6441_AwakerVoiceContent = {
    Text = "Il sangue scorre come un fiume. Sono tua. Mai l'ho sentito con tanta forza."
  },
  Voice_6441_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_6441_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_6442_AwakerVoiceContent = {
    Text = "Questa è la volontà delle Tre Dee della Vendetta!"
  },
  Voice_6442_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_6443_AwakerVoiceContent = {
    Text = "La mia lama è pronta."
  },
  Voice_6443_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_6444_AwakerVoiceContent = {Text = "Uh-uh!"},
  Voice_6444_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_6445_AwakerVoiceContent = {
    Text = "Oh, che piccola sporcacciona!"
  },
  Voice_6445_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_6446_AwakerVoiceContent = {
    Text = "...Io... Ora lo vedo!"
  },
  Voice_6446_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_6447_AwakerVoiceContent = {
    Text = "...Io... Ora lo vedo!"
  },
  Voice_6447_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_6448_AwakerVoiceContent = {
    Text = "Mance, ovviamente, mance! Guardate quei camerieri della mensa scolastica completamente incapaci! Non si preoccupano nemmeno di preparare le sdraio in anticipo, eppure pretendono una paga extra? Continuate a sognare!"
  },
  Voice_6448_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_6449_AwakerVoiceContent = {Text = "È nero."},
  Voice_6449_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_6450_AwakerVoiceContent = {
    Text = "Fatemi uscire!"
  },
  Voice_6450_AwakerVoiceTitle = {
    Text = "Abilità: I: Mania"
  },
  Voice_6451_AwakerVoiceContent = {
    Text = "Non farlo..."
  },
  Voice_6451_AwakerVoiceTitle = {
    Text = "Abilità: I: Depressione"
  },
  Voice_6452_AwakerVoiceContent = {
    Text = "Non c'è bisogno di cerimonie, Pallido Messaggero. Non dovrebbero esserci barriere tra noi, poiché siamo entrambi creature del Padre di Tutto, in cammino insieme su questo sentiero fangoso e arduo."
  },
  Voice_6452_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_6452_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_6453_AwakerVoiceContent = {
    Text = "No, non li temo. Provo solo pietà per quelle povere anime tormentate dalla Dissoluzione. So che non posso sopportare la loro sofferenza al posto loro, ma darei tutto ciò che ho se potesse recare loro un momento di conforto."
  },
  Voice_6453_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_6453_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_6454_AwakerVoiceContent = {
    Text = "Vuoi pregare con me, mia Fiamma Pallida? Preghiamo per coloro che sono caduti nella nostra battaglia odierna. Benché maledetti dalla dissoluzione e dalla follia, sono pur sempre figli del Padre di Tutto, nostri fratelli e sorelle. Possano ora trovare la pace che meritano."
  },
  Voice_6454_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_6454_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_6455_AwakerVoiceContent = {
    Text = "Anche se le fiamme rosse mi turbano, salirei ancora una volta sulla piattaforma ardente per te. Non tormentarti, mia Fiamma Pallida. Il mio Sacrificio è insignificante rispetto alle benedizioni che porti."
  },
  Voice_6455_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_6455_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_6456_AwakerVoiceContent = {
    Text = "Rimpianti? No, certo che no. La mia morte ha alleviato la loro sofferenza e ha concesso più tempo, e questo è sufficiente. Ma... poiché sei stato sincero con me, non ti nasconderò questo: il rogo di quel giorno ha lasciato le sue cicatrici nel mio cuore."
  },
  Voice_6456_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_6456_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_6457_AwakerVoiceContent = {
    Text = "Stringi una promessa con me? Promettimi che, qualunque cosa accada, ricorderai \"Ramona\"."
  },
  Voice_6457_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_6457_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_6458_AwakerVoiceContent = {
    Text = "Non rimpiango ciò che sono diventata, Custode; lo sceglierei di nuovo. Ma ho paura... paura che la \"Ramona\" che ero un tempo non lasci alcuna traccia di sé."
  },
  Voice_6458_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_6458_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_6459_AwakerVoiceContent = {
    Text = "La benda sull'occhio non compromette la mia vista. Semmai, mi aiuta a evitare di vedere troppo."
  },
  Voice_6459_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_6459_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_6460_AwakerVoiceContent = {
    Text = "Ti sembro... diversa? Ho cercato di mantenere il controllo. La sua presenza si fa sempre più forte."
  },
  Voice_6460_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_6460_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_6461_AwakerVoiceContent = {
    Text = "Troppi misteri, troppe persone da salvare. Non so per quanto potrò andare avanti così... Non posso proteggere tutti. È difficile."
  },
  Voice_6461_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_6461_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_6462_AwakerVoiceContent = {
    Text = "Vuoi ancora scommettere su di me? A quanto pare vivere spensierati non è facile come sembra. Non preoccuparti, risolverò i tuoi problemi... con un sacco di pause."
  },
  Voice_6462_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_6462_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_6463_AwakerVoiceContent = {
    Text = "Bene, sembra che tocchi tirare fuori l'artiglieria pesante, no? Dov'è la scena del crimine? Brucerò fino all'ultimo briciolo di fortuna per portare il sospettato prima della scadenza!"
  },
  Voice_6463_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_6463_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_6464_AwakerVoiceContent = {
    Text = "Sigh, ti devo troppi Favori per mantenere questo Segreto: in realtà, potrei essere il tizio più sfortunato del mondo intero."
  },
  Voice_6464_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_6464_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_6465_AwakerVoiceContent = {
    Text = "A quanto pare non hai preso sul serio il mio avvertimento... Ah, lascia stare. Ti aiuterò comunque a fare a pezzi il nemico. Dopotutto, questi Artigli e queste zanne li ho vinti per caso, no?"
  },
  Voice_6465_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_6465_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_6466_AwakerVoiceContent = {
    Text = "La mia fortuna potrebbe non contagiare i miei compagni. Conosci il detto, no? \"La zampa di coniglio non porta fortuna al coniglio.\""
  },
  Voice_6466_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_6466_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_6467_AwakerVoiceContent = {
    Text = "Cerchi forse il sigillo di Questa Entità marchiato sulla tua anima?"
  },
  Voice_6467_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_6468_AwakerVoiceContent = {
    Text = "Brami il mio Potere con tanta disperazione?"
  },
  Voice_6468_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_6469_AwakerVoiceContent = {
    Text = "Non lasciarti ingannare dal mio aspetto; un tempo ero anch'io una nobildonna... Ricamavo, leggevo Tennyson... Oh, e una volta cantavo canzoni: \"Scorre come un fiume infinito nelle mie vene...\""
  },
  Voice_6469_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_6470_AwakerVoiceContent = {
    Text = "Pickman e io stiamo lavorando a un'affascinante installazione artistica, esplorando la ricostruzione del rappresentazionismo astratto attraverso la decostruzione del primitivismo visivo... Eh, perché Aurita è svenuta?"
  },
  Voice_6470_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Aurita"
  },
  Voice_6470_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Aurita\""
  },
  Voice_6471_AwakerVoiceContent = {
    Text = [[
Vuoi che sorrida?
Sto... sorridendo adesso?]]
  },
  Voice_6471_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito del suo sorriso"
  },
  Voice_6472_AwakerVoiceContent = {
    Text = "Che sorpresa, ho ottenuto una compagnia alla pari.\nTuttavia... chiedo di mantenere il diritto di comandarti, semplicemente per il nostro reciproco divertimento. Vieni nelle mie stanze stasera; ho ancora molto da imparare sulla sensibilità umana..."
  },
  Voice_6472_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_6472_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_6473_AwakerVoiceContent = {
    Text = "Sai cosa ti rende più affascinante? È quando mi dici \"no\". Il tuo naso si arriccia, le tue sopracciglia si sollevano appena... Sì, esattamente così."
  },
  Voice_6473_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_6473_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_6474_AwakerVoiceContent = {
    Text = "Adoro i miei servitori. Queste graziose creaturine, tremanti per la Dissoluzione e nascoste dietro di me, sono così adorabili. Le lacrime di una bellezza sono sempre ammalianti. E tu? Temi la Dissoluzione?"
  },
  Voice_6474_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_6474_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_6475_AwakerVoiceContent = {
    Text = "Custode, c'è qualcuno che non ti piace? Come Favore, posso dargli una lezione. Entro una settimana, sarà una persona diversa, che si prostra obbedientemente ai tuoi piedi."
  },
  Voice_6475_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_6475_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_6476_AwakerVoiceContent = {
    Text = "Hmm... Anche se sei noioso, non sei del tutto sgradevole. Da domani, mi servirai.\nNon vuoi...? Ha. Questa non è una richiesta; è un ordine."
  },
  Voice_6476_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_6476_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_6477_AwakerVoiceContent = {
    Text = "Era da tanto che non provavo qualcosa di simile. Salirò sul palco in forma perfetta e ti dedicherò un canto che abbraccia l'intero cosmo, solo per te."
  },
  Voice_6477_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_6477_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_6478_AwakerVoiceContent = {
    Text = "Dovresti sapere che tutto questo è inutile."
  },
  Voice_6478_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_6478_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_6479_AwakerVoiceContent = {
    Text = "Dopo aver colto il fiore della vittoria, vorrei reclamare un piccolo premio..."
  },
  Voice_6479_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_6480_AwakerVoiceContent = {Text = "Ah!"},
  Voice_6480_AwakerVoiceTitle = {
    Text = "Colpo Subito: Depressione: III"
  },
  Voice_6481_AwakerVoiceContent = {
    Text = "La nave spaziale era angusta e claustrofobica, come una bara di metallo alla deriva nello spazio. Avevo atteso la mia Stella del Mattino da un'eternità, finché non sei apparso tu per me."
  },
  Voice_6481_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_6481_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_6482_AwakerVoiceContent = {
    Text = "Come è possibile?!"
  },
  Voice_6482_AwakerVoiceTitle = {
    Text = "Impatto: Isteria: I"
  },
  Voice_6483_AwakerVoiceContent = {Text = "Ugh..."},
  Voice_6483_AwakerVoiceTitle = {
    Text = "Impatto: Depressione: I"
  },
  Voice_6484_AwakerVoiceContent = {Text = "Ahi..."},
  Voice_6484_AwakerVoiceTitle = {
    Text = "Colpo Subito: Depressione: II"
  },
  Voice_6485_AwakerVoiceContent = {
    Text = "Punizione Divina!"
  },
  Voice_6485_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_6486_AwakerVoiceContent = {
    Text = "Punizione Divina!"
  },
  Voice_6486_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_6487_AwakerVoiceContent = {Text = "Noioso."},
  Voice_6487_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_6488_AwakerVoiceContent = {
    Text = "(Esclamazione)"
  },
  Voice_6488_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_6489_AwakerVoiceContent = {
    Text = "Posso ancora resistere."
  },
  Voice_6489_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_6490_AwakerVoiceContent = {
    Text = "(Esclamazione)"
  },
  Voice_6490_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_6491_AwakerVoiceContent = {
    Text = "(Esclamazione)"
  },
  Voice_6491_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_6492_AwakerVoiceContent = {
    Text = "Che gli irriverenti si dissolvano in questa rovente quiete."
  },
  Voice_6492_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_6493_AwakerVoiceContent = {
    Text = "Attento! Se infili la mano in un altro spazio dimensionale, potresti non riaverla indietro!"
  },
  Voice_6493_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_6494_AwakerVoiceContent = {
    Text = "Un branco di incompetenti. Se preferite non finire come carne tritata, fareste bene a prestare più attenzione la prossima volta."
  },
  Voice_6494_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_6495_AwakerVoiceContent = {
    Text = "Oh cielo, stai diventando affettuoso con me? Questo è problematico. Se continua così, non riuscirò ad aspettare che tu maturi completamente, mio caro {Male=Mr.,Female=Miss} Custode..."
  },
  Voice_6495_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_6496_AwakerVoiceContent = {
    Text = "Immergiti negli abissi del libero arbitrio!"
  },
  Voice_6496_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6497_AwakerVoiceContent = {
    Text = "Odio? Disprezzo chi rinuncia a metà strada. Il solo pensiero mi fa venire voglia di rigurgitare il pasto di ieri sera."
  },
  Voice_6497_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_6498_AwakerVoiceContent = {
    Text = "Contemplate il vostro volto, o teschi senza fine!"
  },
  Voice_6498_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_6499_AwakerVoiceContent = {
    Text = "Contemplate il vostro volto, o teschi senza fine!"
  },
  Voice_6499_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_6500_AwakerVoiceContent = {Text = "Hah!"},
  Voice_6500_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_6501_AwakerVoiceContent = {Text = "Hah!"},
  Voice_6501_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_6502_AwakerVoiceContent = {
    Text = "Ti fidi così tanto di me?"
  },
  Voice_6502_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_6502_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_6503_AwakerVoiceContent = {
    Text = "Torna indietro."
  },
  Voice_6503_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_6504_AwakerVoiceContent = {Text = "Bene!"},
  Voice_6504_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_6505_AwakerVoiceContent = {
    Text = "Sì, certo che la conosco. È il mio altro io, un'altra possibilità. Ma perché resiste? Se accettasse il suo destino di Prescelto, non otterrebbe tutto ciò che desidera a portata di mano?"
  },
  Voice_6505_AwakerVoiceTitle = {
    Text = "Chat: A proposito di \"Murphy\""
  },
  Voice_6505_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risveglio \"Murphy\""
  },
  Voice_6506_AwakerVoiceContent = {
    Text = "Salve, il mio nome è Daffodil. Ho fatto uno scambio con un ospite che mi ha chiesto di assisterti. Quindi, dimmi di cosa hai bisogno. \nOh cielo... quello che desideri ha un prezzo piuttosto alto, non è vero?"
  },
  Voice_6506_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6507_AwakerVoiceContent = {
    Text = "Merda! Che stai facendo?! Che tu ci creda o no, ti taglio la Mano!"
  },
  Voice_6507_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_6508_AwakerVoiceContent = {Text = "Hahaha!"},
  Voice_6508_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_6509_AwakerVoiceContent = {Text = "Hahaha!"},
  Voice_6509_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_6510_AwakerVoiceContent = {
    Text = "Le Spine delle rose mi pungono le dita, il loro Cremisi scorre nella poesia."
  },
  Voice_6510_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_6511_AwakerVoiceContent = {
    Text = "Piegato sotto questo inchiostro profondo di Pianto, divieni un canto funebre..."
  },
  Voice_6511_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_6512_AwakerVoiceContent = {Text = "Osserva!"},
  Voice_6512_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_6513_AwakerVoiceContent = {Text = "Hmm...!"},
  Voice_6513_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_6514_AwakerVoiceContent = {
    Text = "Il Cataclisma discende!"
  },
  Voice_6514_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6515_AwakerVoiceContent = {Text = "Dammelo."},
  Voice_6515_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_6516_AwakerVoiceContent = {
    Text = "Il mio nome, ehm, non ricordo. Oh, giusto, \"24\", è così che mi chiamano... No! Fermati! Non uscire! Non puoi, non adesso..."
  },
  Voice_6516_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6517_AwakerVoiceContent = {
    Text = "Segno d'inchiostro, dove stai andando?..."
  },
  Voice_6517_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_6518_AwakerVoiceContent = {
    Text = "Emergi per me..."
  },
  Voice_6518_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_6519_AwakerVoiceContent = {
    Text = "Non merito il titolo di \"Voce Celestiale\". Finché il mio canto ti piace, è tutto ciò che conta."
  },
  Voice_6519_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito del canto"
  },
  Voice_6520_AwakerVoiceContent = {
    Text = "Ah, il mio vestito è sporco. Dovrei cambiarmi prima del prossimo salon."
  },
  Voice_6520_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_6521_AwakerVoiceContent = {
    Text = "Mi sta raggiungendo, l'eterna oscurità... Nessuno può sfuggire..."
  },
  Voice_6521_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_6522_AwakerVoiceContent = {
    Text = "Ogni volta che ti vedo, penso alle catene invisibili che mi hai imposto. Lasciarti vivere è il mio più grande atto di tolleranza."
  },
  Voice_6522_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_6523_AwakerVoiceContent = {
    Text = "Non importa quante volte dovremo ricominciare, camminerò al tuo fianco."
  },
  Voice_6523_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_6524_AwakerVoiceContent = {
    Text = "Che il Suo amore divino riscaldi la tua anima."
  },
  Voice_6524_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_6525_AwakerVoiceContent = {
    Text = "Mi piace vagare senza meta. Paludi, cimiteri, infermerie, castelli abbandonati... In questi luoghi trovo sempre delizie inaspettate."
  },
  Voice_6525_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_6526_AwakerVoiceContent = {
    Text = "Sentiti onorato, poiché le porte del Regno Eterno sono qui!"
  },
  Voice_6526_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_6527_AwakerVoiceContent = {
    Text = "Eheh—mi fa il solletico! Non scappare! Devo ricambiare il grattino!"
  },
  Voice_6527_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_6528_AwakerVoiceContent = {
    Text = "\"Il Cigno Morente,\" una performance in cui la danzatrice usa il linguaggio del corpo per trasmettere la brama e la lotta della vita. Quella figura contorta tra le fiamme non è forse la stessa cosa?"
  },
  Voice_6528_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_6529_AwakerVoiceContent = {
    Text = "Taglia, taglia, squarcia. Proprio come hanno fatto a me... Hehe... HAHAHA!"
  },
  Voice_6529_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_6530_AwakerVoiceContent = {
    Text = "Faresti meglio a non avvicinarti troppo a Lady Thais... No, non sono gelosa. Temo solo che qualcuno possa cadere nei suoi tranelli."
  },
  Voice_6530_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Thais"
  },
  Voice_6530_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Thais\""
  },
  Voice_6531_AwakerVoiceContent = {Text = "...Grazie."},
  Voice_6531_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_6531_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_6532_AwakerVoiceContent = {
    Text = "Molto bene... Hai occhio nel riconoscere le persone capaci."
  },
  Voice_6532_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_6532_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_6533_AwakerVoiceContent = {
    Text = "La mia città natale è bellissima! È una città di pietra in un lago. Ogni luna piena, danziamo in silenzio tra le fiamme, in adorazione... Onestamente, quando sono arrivata in questa scuola, mi mancava casa ogni notte e piangevo a letto. Ma ora ho una nuova casa e una nuova famiglia. Tutto sta migliorando!"
  },
  Voice_6533_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_6533_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_6534_AwakerVoiceContent = {
    Text = "Oh~ Ancora non sei soddisfatto? Avvicinati, ti insegnerò il vero piacere~"
  },
  Voice_6534_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_6535_AwakerVoiceContent = {
    Text = "Muscoli deboli, un volto emaciato—solo quegli occhi morti hanno un qualche valore. Sono perfetti per nutrire i ragni!"
  },
  Voice_6535_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_6536_AwakerVoiceContent = {
    Text = "G-Grazie... per tutto quello che hai fatto. Farò del mio meglio in assoluto... per non deluderti!"
  },
  Voice_6536_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_6537_AwakerVoiceContent = {
    Text = "(Grido di Terrore)"
  },
  Voice_6537_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_6538_AwakerVoiceContent = {Text = "No!"},
  Voice_6538_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_6539_AwakerVoiceContent = {
    Text = "Risparmiami..."
  },
  Voice_6539_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_6540_AwakerVoiceContent = {
    Text = "(Grido di Terrore)"
  },
  Voice_6540_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_6541_AwakerVoiceContent = {
    Text = "La tecnica di Spada di Lady Ramona è piuttosto diversa da quella che ho appreso. Se il mio signore lo consente, desidererei ardentemente esercitarmi con lei... Solo per migliorare me stesso, naturalmente!"
  },
  Voice_6541_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_6541_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_6542_AwakerVoiceContent = {
    Text = "Mi chiedete perché non gioco con gli altri Fanciulli? È difficile a dirsi... Nella mia vita passata, raramente ho avuto occasione di giocare. La mia unica compagna era la Principessa che servivo... Oh! Parlare di un altro sovrano dinanzi a voi, mio signore, vi prego, perdonate la mia leggerezza."
  },
  Voice_6542_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_6542_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_6543_AwakerVoiceContent = {
    Text = "Siete riconosciuto dall'Università di Mythag come Custode, pertanto vi concederò i permessi di accesso corrispondenti."
  },
  Voice_6543_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito del \"Protagonista\""
  },
  Voice_6544_AwakerVoiceContent = {
    Text = "Vi interessano le Sette Arti Cavalleresche che ho appreso? Meraviglioso! Ah... ehm... vi prego di perdonare la mia scortesia di poco fa, mio signore. Intendevo dire che, se desiderate esercitarvi nel tiro con l'arco a cavallo, sarebbe per me un onore essere il vostro compagno d'allenamento!"
  },
  Voice_6544_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_6544_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_6545_AwakerVoiceContent = {
    Text = "Non sono un Cavaliere degno di tale nome. Che fosse la vile Peste o i nemici invasori, non sono riuscito a proteggere il mio precedente signore. Ora, la fiducia che riponete in qualcuno come me è un immenso onore... Giuro sul mio onore cavalleresco e su questa modesta vita che vigilerò per sempre sul vostro cammino."
  },
  Voice_6545_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_6545_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_6546_AwakerVoiceContent = {
    Text = "Non fare del male."
  },
  Voice_6546_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_6547_AwakerVoiceContent = {Text = "Dai~"},
  Voice_6547_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_6548_AwakerVoiceContent = {Text = "Hah!"},
  Voice_6548_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_6549_AwakerVoiceContent = {
    Text = "Non uccidere."
  },
  Voice_6549_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_6550_AwakerVoiceContent = {Text = "Ah, sì~!"},
  Voice_6550_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_6551_AwakerVoiceContent = {
    Text = "Ormai siamo semplicemente acqua e olio. Mai mescolabili."
  },
  Voice_6551_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_6552_AwakerVoiceContent = {
    Text = "Non ho preferenze particolari. Se proprio devo dire, la sensazione di partire per le missioni è piuttosto piacevole."
  },
  Voice_6552_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_6553_AwakerVoiceContent = {
    Text = "Perché, perché rinchiudermi qui? Haha... non otterrete ciò che volete. Farò a pezzi queste catene, questa prigione, ridotte in Frammenti!"
  },
  Voice_6553_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_6554_AwakerVoiceContent = {
    Text = "Lily proteggerà."
  },
  Voice_6554_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_6555_AwakerVoiceContent = {
    Text = "Voi, non vi stancate mai di guardare lo spettacolo di magia? State fermi, d'accordo? Se salite di nuovo sul palco, vi scaravento in un'altra Dimensione!"
  },
  Voice_6555_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito dei Fanciulli"
  },
  Voice_6555_UnlockDesc = {
    Text = "Si sblocca dopo aver acquisito uno qualsiasi tra i Risvegliatori \"Aigis\", \"Jenkin\", \"Lily\", \"Murphy\", \"Karen\" o \"Aurita\""
  },
  Voice_6556_AwakerVoiceContent = {
    Text = "Accetterò il tuo generoso dono con gratitudine."
  },
  Voice_6556_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_6557_AwakerVoiceContent = {
    Text = "Che tipo di dono di ritorno potrebbe eguagliare la vostra dedizione?"
  },
  Voice_6557_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_6558_AwakerVoiceContent = {
    Text = "Che meraviglia..."
  },
  Voice_6558_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_6559_AwakerVoiceContent = {
    Text = "Rilevata corrente elevata, avvio manutenzione... Correzione: perché non si verifica alcun surriscaldamento?"
  },
  Voice_6559_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_6559_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_6560_AwakerVoiceContent = {
    Text = "Dall'ultimo rituale di Illuminazione, ho visioni frammentate durante lo stato di dormienza. In esse, possiedo un corpo umano come il vostro, e lacrime scendono dai miei occhi. È forse un sogno?"
  },
  Voice_6560_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_6560_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_6561_AwakerVoiceContent = {
    Text = "Dopo ogni rituale, viene rilevato un alto livello di calore nella zona toracica, ma non sono presenti componenti correlati all'energia. Sapete perché?"
  },
  Voice_6561_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_6561_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_6562_AwakerVoiceContent = {
    Text = "L'ho visto. Tutto dovrebbe <Del:perire nella corrente eterna>. S-s-scusate, il modulo sembra—Allarme, allarme. Attività di coscienza non-Erica in aumento. Distruggere, distruggeredistruggere DISTRUGGERE... Salve, come posso assistervi?"
  },
  Voice_6562_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_6562_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_6563_AwakerVoiceContent = {
    Text = "Dopo un'attenta analisi, ho dedotto che ciò che ho visto nel mio stato di dormienza non era un sogno nel senso tradizionale, bensì un mio <Del:quel vostro patetico involucro di carne andrebbe distrutto> ricordo. Quanto al calore bruciante simile a un sovraccarico, potrebbe trattarsi dell'emozione nota come \"Riluttanza.\""
  },
  Voice_6563_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_6563_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_6564_AwakerVoiceContent = {
    Text = "Se vuoi assistere al mio spettacolo, siediti composto tra il pubblico!"
  },
  Voice_6564_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_6564_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_6565_AwakerVoiceContent = {
    Text = "Le fiamme dell'odio ardono feroci, mai destinate a spegnersi."
  },
  Voice_6565_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_6567_AwakerVoiceContent = {
    Text = "La volontà con cui mi sono fusa è alquanto chiassosa; più in alto ascendo, più la Sua voce si fa nitida... come le oche di Hyde Park, perennemente strepitanti."
  },
  Voice_6567_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_6567_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_6568_AwakerVoiceContent = {
    Text = "Userò questo Potere per Divorare il traditore."
  },
  Voice_6568_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_6569_AwakerVoiceContent = {Text = "...Grazie."},
  Voice_6569_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_6570_AwakerVoiceContent = {
    Text = "Tu, il grande Custode salvatore del mondo? Ridicolo. Svegliati. Questo sogno è andato a male."
  },
  Voice_6570_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6571_AwakerVoiceContent = {
    Text = "Il Sangue della vendetta ribolle..."
  },
  Voice_6571_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_6572_AwakerVoiceContent = {
    Text = "Muoviti, cane."
  },
  Voice_6572_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6573_AwakerVoiceContent = {
    Text = "Non affogare!"
  },
  Voice_6573_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_6574_AwakerVoiceContent = {Text = "Whoosh!"},
  Voice_6574_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_6575_AwakerVoiceContent = {
    Text = "Ho buttato via le trappole per topi vicino alla porta sul retro della mensa. E se quella goffa di Brown ci finisse sopra?! È troppo pericoloso!"
  },
  Voice_6575_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_6576_AwakerVoiceContent = {
    Text = "Che sensazione strana... Sto morendo? No, salvatemi! Aiuto! No!!"
  },
  Voice_6576_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_6576_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_6579_AwakerVoiceContent = {
    Text = "Voglio una lampada che non si spenga mai. Lei ha detto che potrei acquistarla con... con un esemplare di \"hydra volante senz'ali.\" Dove posso trovare una specie così bizzarra?!"
  },
  Voice_6579_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Daffodil"
  },
  Voice_6579_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Daffodil\""
  },
  Voice_6582_AwakerVoiceContent = {Text = "Pericolo."},
  Voice_6582_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_6583_AwakerVoiceContent = {
    Text = "Avvertimento."
  },
  Voice_6583_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_6584_AwakerVoiceContent = {
    Text = "Colpo Subito."
  },
  Voice_6584_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_6585_AwakerVoiceContent = {
    Text = "Un tesoro segreto che luccica come carte di caramelle... Lo custodirò con cura."
  },
  Voice_6585_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_6586_AwakerVoiceContent = {
    Text = "Danno subito."
  },
  Voice_6586_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_6587_AwakerVoiceContent = {
    Text = "Il mio negozio esiste in qualsiasi dimensione, in qualsiasi luogo dell'universo, e naturalmente può trovarsi anche qui. Del resto, mi piacciono quei fanciulli incauti di Mythag."
  },
  Voice_6587_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_6588_AwakerVoiceContent = {
    Text = "Peperone verde... cattivo."
  },
  Voice_6588_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_6589_AwakerVoiceContent = {
    Text = "Il mio rapporto con te è come quello tra una vela e una nave. Senza la nave, la vela non dovrebbe esistere; senza la vela, la nave difficilmente può navigare lontano. Non è forse vero?"
  },
  Voice_6589_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_6590_AwakerVoiceContent = {
    Text = "La devota danzatrice è morta, e la blasfema dell'arte è morta anch'essa, entrambe perite tra fiamme intrise dell'odore di catrame. La morte non è la fine, ma l'inizio, poiché solo gli esseri umani muoiono; la danza e l'arte sono eterne."
  },
  Voice_6590_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_6590_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_6591_AwakerVoiceContent = {
    Text = "Grazie per la tua comprensione. Forse è giunto il momento di riconciliarmi con ciò che ero... Credo di stare facendo la cosa giusta e di non aver disonorato l'eredità della mia famiglia nella danza. Salirò sul palco che hai preparato e risplenderò come desideri."
  },
  Voice_6591_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_6591_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_6592_AwakerVoiceContent = {
    Text = "Fa' attenzione."
  },
  Voice_6592_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_6593_AwakerVoiceContent = {
    Text = "Vuoi che salga sul palco e brilli? Ora è impossibile. Questi occhi sono stati consumati dall'odio. Tutto ciò che posso fare è ridurre tutto in cenere."
  },
  Voice_6593_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_6593_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_6594_AwakerVoiceContent = {
    Text = "Capisci quella sensazione? Girare, girare, girare, senza mai fermarsi. Le ginocchia tese allo spasimo, le dita dei piedi che sanguinano nero, inzuppando le scarpette da ballo, eppure senza mai una pausa. Tutto perché mi rifiuto di accettare il fato di essere un semplice giocattolo..."
  },
  Voice_6594_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_6594_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_6595_AwakerVoiceContent = {
    Text = "Non ho bruciato abili danzatrici di corte, né aggraziati maestri di balletto, né nobili che apprezzano la bellezza. Ho bruciato stolti inutili che vendevano i propri corpi, adulatori incuranti degli altri, ed esseri immondi perduti nella lussuria... Mi capisci, vero?"
  },
  Voice_6595_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_6595_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_6596_AwakerVoiceContent = {
    Text = "Detesto quei viscidi tentacoli, e non mi piace il mare profondo... Non guardarmi con quell'aria saputa! Non sono una bambina che ha paura dei genitori!"
  },
  Voice_6596_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_6596_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_6597_AwakerVoiceContent = {
    Text = "La vostra generosità mi è infinitamente cara..."
  },
  Voice_6597_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_6598_AwakerVoiceContent = {Text = "Svanisci!"},
  Voice_6598_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_6599_AwakerVoiceContent = {Text = "Svanisci!"},
  Voice_6599_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_6600_AwakerVoiceContent = {
    Text = "Presto, afferra Brown e filiamocela!"
  },
  Voice_6600_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_6601_AwakerVoiceContent = {Text = "Non..."},
  Voice_6601_AwakerVoiceTitle = {
    Text = "Difesa: Depressione"
  },
  Voice_6602_AwakerVoiceContent = {Text = "Sparisci!"},
  Voice_6602_AwakerVoiceTitle = {
    Text = "Difesa: Mania"
  },
  Voice_6603_AwakerVoiceContent = {
    Text = "Chi è Leigh? Oh, la Donna che mi supplicava di picchiarla. Haha, interessante... Dopotutto questo posto non è poi così noioso."
  },
  Voice_6603_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Leigh"
  },
  Voice_6603_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Leigh\""
  },
  Voice_6604_AwakerVoiceContent = {
    Text = "Il Tramonto sulla piccola collina mi ricorda spesso i miei giorni a Cleveland... Cleveland. Non riesco a credere di ricordare ancora quel nome, il luogo che mi ha lasciato queste cicatrici."
  },
  Voice_6604_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul crepuscolo"
  },
  Voice_6605_AwakerVoiceContent = {
    Text = "Ah... le Stelle... sono cadute..."
  },
  Voice_6605_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_6606_AwakerVoiceContent = {
    Text = "Senza alcun dubbio, gli umani. Esistono creature più immonde degli umani?"
  },
  Voice_6606_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_6607_AwakerVoiceContent = {Text = "È adesso!"},
  Voice_6607_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_6608_AwakerVoiceContent = {Text = "Ehi!"},
  Voice_6608_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_6609_AwakerVoiceContent = {
    Text = "Dissoluzione? Hmm... Sì! Il gelato si scioglie! Ma se lo condividiamo, possiamo mangiarlo prima che diventi Completo... ehm, completamente crema!"
  },
  Voice_6609_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_6610_AwakerVoiceContent = {
    Text = "Userò questa forza per tenervi al sicuro."
  },
  Voice_6610_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_6610_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_6611_AwakerVoiceContent = {
    Text = "Oh cielo, niente resi sugli oggetti venduti qui! D'altronde ti serve un sottomarino per immergerti nelle profondità del mare, non è vero?"
  },
  Voice_6611_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito di Caecus"
  },
  Voice_6611_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Caecus\""
  },
  Voice_6612_AwakerVoiceContent = {
    Text = "Ah, questo è il Livello migliore! Le persone all'Università di Mythag capiscono tutte che il mio spettacolo è vera magia! Questo dev'essere ciò che chiamano il pubblico ideale di un mago, giusto?"
  },
  Voice_6612_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_6613_AwakerVoiceContent = {
    Text = "L'ordine dell'universo muta in questo luogo; il futuro della Distruzione è il credo fondamentale del mago!"
  },
  Voice_6613_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_6613_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_6614_AwakerVoiceContent = {
    Text = "Posso restare qui ancora un po'? Rimarrò in silenzio, non farò alcun rumore, e farò del mio meglio per non disturbarvi..."
  },
  Voice_6614_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_6614_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_6615_AwakerVoiceContent = {
    Text = "Svela i misteri del mondo con l'intelletto umano!"
  },
  Voice_6615_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_6616_AwakerVoiceContent = {
    Text = "Nei miei sogni, sento spesso il suono della marea, sempre più flebile. So che potrei restare qui per sempre, Umano."
  },
  Voice_6616_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Aequor"
  },
  Voice_6617_AwakerVoiceContent = {
    Text = "Più Memorie, più emozioni, più sogni—"
  },
  Voice_6617_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_6617_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_6618_AwakerVoiceContent = {
    Text = "È l'ora della Magia!"
  },
  Voice_6618_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_6619_AwakerVoiceContent = {
    Text = "Non battere ciglio!"
  },
  Voice_6619_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_6620_AwakerVoiceContent = {
    Text = "Una volta che Egli sarà nato... non dovrò più sopportare tale umiliazione..."
  },
  Voice_6620_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_6621_AwakerVoiceContent = {
    Text = "Scegliete me, scegliete me! Dove c'è una festa, c'è Karen!"
  },
  Voice_6621_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_6622_AwakerVoiceContent = {
    Text = "Hmm? Vi interesso? Allora suppongo... che siate anche pronti a pagarne il prezzo?"
  },
  Voice_6622_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_6623_AwakerVoiceContent = {
    Text = "Nessuna pietà, nessuna pietà...!"
  },
  Voice_6623_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_6624_AwakerVoiceContent = {
    Text = "Ancora canto del Colore venuto dallo Spazio..."
  },
  Voice_6624_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_6625_AwakerVoiceContent = {
    Text = "Canta, intona la Cantilena per me!"
  },
  Voice_6625_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_6626_AwakerVoiceContent = {
    Text = "Amo la Mamma!"
  },
  Voice_6626_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_6627_AwakerVoiceContent = {Text = "Avanti."},
  Voice_6627_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_6628_AwakerVoiceContent = {
    Text = "Fa' attenzione."
  },
  Voice_6628_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_6629_AwakerVoiceContent = {
    Text = "I Risvegliati potrebbero mangiare per curiosità, ma il cibo non è essenziale per la nostra esistenza. Pertanto, non è necessario convocarmi a ogni tè pomeridiano. L'assunzione di zuccheri non fa che accelerare l'usura delle giunture sferiche di questo corpo."
  },
  Voice_6629_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul tè pomeridiano"
  },
  Voice_6632_AwakerVoiceContent = {
    Text = "Vi prego, risparmiate il mio Padrone. F-fate quello che volete con Karen!"
  },
  Voice_6632_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_6633_AwakerVoiceContent = {
    Text = "Questi... sono per me? Posso mangiare? Davvero?"
  },
  Voice_6633_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_6633_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_6634_AwakerVoiceContent = {
    Text = "Cosa... odio? Posso dirlo? Odio me stessa per essere così inutile... Ma se lo dicessi, Jenkin si arrabbierebbe davvero tanto..."
  },
  Voice_6634_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_6635_AwakerVoiceContent = {
    Text = "Riduciti in Ceneri."
  },
  Voice_6635_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_6636_AwakerVoiceContent = {
    Text = "Riduciti in Ceneri."
  },
  Voice_6636_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_6637_AwakerVoiceContent = {
    Text = "Ben fatto, Custode. Allora, chi devo Uccidere stavolta?"
  },
  Voice_6637_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_6637_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_6638_AwakerVoiceContent = {
    Text = "La Dissoluzione è la ragione per cui questa accademia è stata fondata e il motivo per cui ci siamo incontrati. Per salvare la scintilla dell'umanità dalla Dissoluzione, diamo il meglio di noi, partner."
  },
  Voice_6638_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_6639_AwakerVoiceContent = {
    Text = "Percepisco l'ostilità di quella bambina; il mio amore per te ha acceso il fuoco della sua gelosia... Guarda, persino quella megattera spalanca la bocca per l'invidia."
  },
  Voice_6639_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Lotan"
  },
  Voice_6639_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Lotan\""
  },
  Voice_6640_AwakerVoiceContent = {
    Text = "Maestro, Maestro! Karen ha visto una spilla cammeo incredibilmente splendida da Harold oggi! Potresti comprarla per Karen? È la richiesta della mia vita!"
  },
  Voice_6640_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_6641_AwakerVoiceContent = {
    Text = "Sarò la tua luce guida nell'oscurità, ma non per sempre."
  },
  Voice_6641_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_6642_AwakerVoiceContent = {
    Text = "Mamma... Fa male... Mamma..."
  },
  Voice_6642_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_6643_AwakerVoiceContent = {
    Text = "Arrenditi! La vittoria è già mia!"
  },
  Voice_6643_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_6644_AwakerVoiceContent = {
    Text = "Arrenditi! La vittoria è già mia!"
  },
  Voice_6644_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_6645_AwakerVoiceContent = {
    Text = "Dissoluzione... Ehm, la mia capacità cerebrale è limitata e non riesco a comprendere malattie così complesse... Se hai bisogno di riparare qualche macchinario, vieni a cercarmi!"
  },
  Voice_6645_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_6646_AwakerVoiceContent = {
    Text = "Oh no! Mi hanno trovata! Come penalità per aver perso, puoi chiedermi una cosa—solo per favore non farmi andare a lezione, ti prego ti prego!"
  },
  Voice_6646_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_6647_AwakerVoiceContent = {
    Text = "Aprire il Sentiero per il Suo glorioso Ritorno..."
  },
  Voice_6647_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_6648_AwakerVoiceContent = {
    Text = "Un giorno, zio Ornn mi riporterà al mio Focolare sottomarino. Fino ad allora, posso essere il tuo amico, con riluttanza."
  },
  Voice_6648_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_6648_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_6649_AwakerVoiceContent = {
    Text = "\"La nostra famiglia porta un grande lignaggio; il prescelto godrà di pace eterna negli abissi del mare.\" Non mi sarei mai aspettato di provare questa pace dopo aver lasciato il mare e essere venuto all'accademia. Tu sei diverso da quelli che mi tormentano, perciò non permetterò che altri tormentino te."
  },
  Voice_6649_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_6649_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_6650_AwakerVoiceContent = {
    Text = "Materiale su misura super resistente!"
  },
  Voice_6650_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6651_AwakerVoiceContent = {
    Text = "Questo involucro per metà umano davvero... mi disgusta. Mi ero finalmente liberato del passato, e ora devo rievocarlo di nuovo..."
  },
  Voice_6651_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_6651_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_6652_AwakerVoiceContent = {
    Text = "Pensare che l'erede della grande stirpe si abbasserebbe a servire un umano... Hmph. Non credere di potermi comandare a tuo piacimento."
  },
  Voice_6652_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_6652_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_6653_AwakerVoiceContent = {
    Text = "Hmph, tu fragile umano hai un certo Talento nel comando... e ti mostrerei il mio vero Potere se non fosse per questo involucro inferiore."
  },
  Voice_6653_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_6653_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_6654_AwakerVoiceContent = {
    Text = "Il mio corpo si sta scaldando."
  },
  Voice_6654_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_6655_AwakerVoiceContent = {
    Text = "Corsa... devo correre! Via da qui!"
  },
  Voice_6655_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_6656_AwakerVoiceContent = {
    Text = "Corsa... devo correre! Via da qui!"
  },
  Voice_6656_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_6657_AwakerVoiceContent = {
    Text = "Grazie per i tuoi sforzi. Permettimi di ricompensarti adeguatamente."
  },
  Voice_6657_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_6658_AwakerVoiceContent = {
    Text = "È gestibile."
  },
  Voice_6658_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_6659_AwakerVoiceContent = {
    Text = "(Un'inspirazione sommessa, trattenuta)"
  },
  Voice_6659_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_6660_AwakerVoiceContent = {
    Text = "Fragile umano, la tua convinzione è sufficiente. Sarò la tua arma. Seminiamo un po' di Caos insieme!"
  },
  Voice_6660_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_6660_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_6662_AwakerVoiceContent = {
    Text = "Questo è IL MIO salone."
  },
  Voice_6662_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6664_AwakerVoiceContent = {
    Text = "Una scuola dove tutti sono trattati allo stesso modo... chissà che sciocchi sogni coltivi. Anche se non hai commesso alcun torto, ti calpesteranno comunque. Quella sensazione, la conosco bene."
  },
  Voice_6664_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_6665_AwakerVoiceContent = {
    Text = "Questa è la Fonte dell'Impurità..."
  },
  Voice_6665_AwakerVoiceTitle = {
    Text = "Esaltazione: Depressione"
  },
  Voice_6666_AwakerVoiceContent = {
    Text = "Sono stata punita per non essere riuscita a proteggere i marinai, perduti per sempre alle loro famiglie. Mi hanno chiamata la principale colpevole della tragedia... È questo ciò che si intende per Dissoluzione?"
  },
  Voice_6666_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_6667_AwakerVoiceContent = {
    Text = "Più vicino... sempre più vicino al mio signore..."
  },
  Voice_6667_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_6668_AwakerVoiceContent = {
    Text = "Perché? Mio signore, perché ancora... resistete al risveglio?"
  },
  Voice_6668_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_6669_AwakerVoiceContent = {
    Text = "Sono Horla, vengo da Cité, e il mio pseudonimo è... Ah, perdonatemi, ho fatto una promessa di non rivelarlo a nessuno. Le mie più profonde scuse, ma vi prego, chiamatemi semplicemente Horla."
  },
  Voice_6669_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6670_AwakerVoiceContent = {
    Text = "Mi oppongo a ogni atto di ingiustizia; il tradimento è il peggiore di tutti. Nell'esercito, se non puoi o non osi fidarti dei tuoi compagni perché ti coprano le spalle, l'intera unità andrà in pezzi."
  },
  Voice_6670_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_6671_AwakerVoiceContent = {
    Text = "Perché appari così oscuro, eppure così radioso...? No, lascia perdere, ignorami, sto solo farneticando."
  },
  Voice_6671_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_6672_AwakerVoiceContent = {Text = "(Gemito)"},
  Voice_6672_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_6673_AwakerVoiceContent = {
    Text = "(Gemito soffocato)"
  },
  Voice_6673_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_6674_AwakerVoiceContent = {Text = "Cosa?!"},
  Voice_6674_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_6675_AwakerVoiceContent = {
    Text = "Amo ogni forma di vita. Amo la luce. Voglio che Faint emerga dal suo guscio solitario e sperimenti il mondo con i propri occhi e le proprie orecchie."
  },
  Voice_6675_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_6676_AwakerVoiceContent = {
    Text = "Non puoi vedermi!"
  },
  Voice_6676_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_6677_AwakerVoiceContent = {
    Text = "È necessario proseguire con i lavori di manutenzione?"
  },
  Voice_6677_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_6678_AwakerVoiceContent = {
    Text = "La manutenzione dei componenti è stata completata."
  },
  Voice_6678_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_6679_AwakerVoiceContent = {
    Text = "Le persone possono tradire, ma gli strumenti mai. Se usata correttamente, anche la Dissoluzione può diventare uno strumento di vendetta."
  },
  Voice_6679_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_6680_AwakerVoiceContent = {
    Text = "Questo momento è finalmente giunto, dopo migliaia di anni di Attesa... Io sono l'unica e sola sovrana dei Filistei!"
  },
  Voice_6680_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_6680_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_6681_AwakerVoiceContent = {
    Text = "Era un Abissale mezzosangue quello che abbiamo appena incrociato? Hmm... Guarda come se ne sta tutto rigido. Stanotte, lo vedrò inarcare quella bella schienina, strisciando ai miei piedi."
  },
  Voice_6681_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito di Caecus"
  },
  Voice_6681_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Caecus\""
  },
  Voice_6682_AwakerVoiceContent = {
    Text = "Sto riacquistando le forze... Il prossimo passo sarà reclamare il Dominio che mi spetta di diritto!"
  },
  Voice_6682_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_6682_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_6683_AwakerVoiceContent = {
    Text = "Non male. Un passo più vicino a strappare il velo a quella donna ipocrita."
  },
  Voice_6683_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_6683_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_6684_AwakerVoiceContent = {
    Text = "Calma, calma..."
  },
  Voice_6684_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_6685_AwakerVoiceContent = {
    Text = "Non c'è bisogno di preoccuparsi. La mia soglia del dolore potrebbe essere ben oltre la vostra immaginazione."
  },
  Voice_6685_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_6685_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_6686_AwakerVoiceContent = {
    Text = "Se me lo chiedi, i bei folli sono i migliori. Sfortunatamente, ci sono fin troppe menti astute ma inutili da queste parti."
  },
  Voice_6686_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_6687_AwakerVoiceContent = {
    Text = "Alimentata dalla fusione nucleare di una gigante rossa, integrata dall'energia di una stella in collasso, si potrebbe avviare un moto perpetuo e accendere una lampada eterna... Eh? Dici che qui non c'è modo di costruire un moto perpetuo, e nemmeno una gigante rossa? Hmm..."
  },
  Voice_6687_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_6688_AwakerVoiceContent = {
    Text = "Il sangue del nemico non si è ancora prosciugato del tutto."
  },
  Voice_6688_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_6689_AwakerVoiceContent = {
    Text = "Sacrificio! Sacrificate tutto... a me!"
  },
  Voice_6689_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_6690_AwakerVoiceContent = {
    Text = "Sacrificio! Sacrificate tutto... a me!"
  },
  Voice_6690_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_6691_AwakerVoiceContent = {
    Text = "È ora di dirigersi al campo di battaglia!"
  },
  Voice_6691_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_6692_AwakerVoiceContent = {
    Text = "È il momento!"
  },
  Voice_6692_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_6693_AwakerVoiceContent = {
    Text = "Il mio sonno riversa sogni come veleno. Non avvicinatevi mentre dormo—e non svegliatemi mai senza ragione."
  },
  Voice_6693_AwakerVoiceTitle = {
    Text = "Chat: A proposito del Dormiveglia"
  },
  Voice_6694_AwakerVoiceContent = {
    Text = "È il momento!"
  },
  Voice_6694_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_6695_AwakerVoiceContent = {
    Text = "Sebbene Herbert sia una persona terrificante, i suoi gatti sono molto docili... No, per essere precisi, i gatti sono due, giusto?"
  },
  Voice_6695_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito di Herbert"
  },
  Voice_6695_UnlockDesc = {
    Text = "Si sblocca dopo aver completato il Capitolo 2 della Storia Principale"
  },
  Voice_6696_AwakerVoiceContent = {
    Text = "Quella donna Murphy si veste in modo troppo appariscente... No, Karen non può perdere contro di lei! O forse, la ucciderò e basta..."
  },
  Voice_6696_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Murphy"
  },
  Voice_6696_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risveglio \"Murphy\""
  },
  Voice_6697_AwakerVoiceContent = {Text = "Ah..."},
  Voice_6697_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_6698_AwakerVoiceContent = {
    Text = "Ti fa stare bene?"
  },
  Voice_6698_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_6699_AwakerVoiceContent = {
    Text = "Quando ho stretto la collaborazione con l'Università di Mythag, era chiaramente stipulato che non sarei stato mandato in battaglia..."
  },
  Voice_6699_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_6699_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_6700_AwakerVoiceContent = {
    Text = "Non lasciarti trasportare. Talvolta, il confine tra il Nobile e il meschino è solo un singolo passo."
  },
  Voice_6700_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_6700_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_6701_AwakerVoiceContent = {
    Text = "Faros ti saluta. Richiamarmi qui deve significare che sei pronto a spiegare le vele."
  },
  Voice_6701_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6702_AwakerVoiceContent = {
    Text = "Yahoo—sono così stanca, posso andare a giocare adesso!"
  },
  Voice_6702_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_6703_AwakerVoiceContent = {
    Text = "Ah... Il suo splendore è così intenso e abbagliante, impossibile da ignorare! Fu uno zelo sciocco ad annebbiare i miei sensi... No, non accamperò scuse per la mia stupidità..."
  },
  Voice_6703_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Tulu"
  },
  Voice_6703_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Tulu\""
  },
  Voice_6705_AwakerVoiceContent = {
    Text = "Le mie stelle dormienti ora si destano dal sogno — che convergano verso il fato loro assegnato. Volgi il tuo cammino verso il Reame Divino!"
  },
  Voice_6705_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_6706_AwakerVoiceContent = {
    Text = "Non trovi affascinante sospingere ogni cosa verso la propria fine, arrestare gli ingranaggi rotanti dell'universo?"
  },
  Voice_6706_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_6707_AwakerVoiceContent = {
    Text = "Bevi fino in fondo!"
  },
  Voice_6707_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_6708_AwakerVoiceContent = {
    Text = "Fantastico！"
  },
  Voice_6708_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_6709_AwakerVoiceContent = {
    Text = "Inserire comando di battaglia."
  },
  Voice_6709_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_6710_AwakerVoiceContent = {
    Text = "Durante i miei giorni alla deriva Tra le Stelle, ho sognato questo momento innumerevoli volte... Grazie per avermi riunita a Tintura."
  },
  Voice_6710_AwakerVoiceTitle = {
    Text = "Chat: A proposito della Tintura"
  },
  Voice_6710_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Tinct\""
  },
  Voice_6711_AwakerVoiceContent = {
    Text = "L'Università di Mythag è un posto fantastico, soprattutto con il casinò clandestino che spunta ogni settimana...\nAspetta, non lo sapevi? Ops, mi è scappata la lingua."
  },
  Voice_6711_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_6712_AwakerVoiceContent = {
    Text = "\"Resistere alla crisi della Dissoluzione\"... Ah. L'Arroganza umana non manca mai di divertire."
  },
  Voice_6712_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_6713_AwakerVoiceContent = {
    Text = "Dopotutto, gli esseri umani sono solo creature superficiali. Poche parole, un'allusione, e cominciano a combattersi tra loro... Sigh, questo livello di conflitto è ben lungi dall'essere sufficiente a ispirare."
  },
  Voice_6713_AwakerVoiceTitle = {
    Text = "Chat: A proposito degli Umani"
  },
  Voice_6714_AwakerVoiceContent = {
    Text = "Forse sono stata troppo frettolosa nel liquidarti come un semplice mortale. Come può qualcuno che non è stato sfiorato dalla grazia aggrapparsi ancora a uno scopo? Questa è la curiosità di Miryam, non una Domanda della Santa Madre dei mari. Vorrai... concedermelo?"
  },
  Voice_6714_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_6714_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_6715_AwakerVoiceContent = {
    Text = "Come potrebbe uno straordinario come te non stancarsi di questo mondo transitorio e tumultuoso? Troverai la tua giusta dimora nel regno eterno. Là, i tuoi piedi baceranno il suolo consacrato, i tuoi respiri si rinnoveranno in acque sacre, e la tua anima fiorirà in terra benedetta... Ti unirai a me in questo santo pellegrinaggio. Unisciti a me in questo santo pellegrinaggio. Insieme ci eleveremo ben oltre i confini mortali, finché non staremo uniti al Trono, e assaporeremo la gioia matura nella sua luce..."
  },
  Voice_6715_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_6715_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_6716_AwakerVoiceContent = {
    Text = "Siamo tutti miseri mortali nella polvere, ma il Saggio cammina in disparte. Egli è l'Emissario, un'Incarnazione divina. I suoi consigli risuonano delle voci degli dèi, guidando la nostra fragile civiltà verso l'immortalità... Non mi aspetto che la tua mente vuota comprenda la Devozione ora, ma un giorno anche tu ti inginocchierai dinanzi al Suo trono."
  },
  Voice_6716_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_6716_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_6717_AwakerVoiceContent = {
    Text = "I Prescelti sono davvero Benedetti, non trovi? La loro carne è stata plasmata dalla Sua santa volontà, le loro vite prolungate oltre ogni misura mortale. Quando Egli camminerà sulla riva, essi si leveranno come Suo coro. Non è forse questa la più alta dolcezza e la suprema felicità per i mortali, fragili come granelli di sabbia?"
  },
  Voice_6717_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_6717_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_6718_AwakerVoiceContent = {
    Text = "L'estasi di essere illuminati dalla Sua gloria è al di là della vostra empia comprensione... Possa Egli, nella Sua misericordia, perdonare la vostra cecità e la vostra impudenza."
  },
  Voice_6718_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_6718_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_6719_AwakerVoiceContent = {
    Text = "Facciamo in fretta, Custode."
  },
  Voice_6719_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_6720_AwakerVoiceContent = {Text = "Ehe!"},
  Voice_6720_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_6720_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_6721_AwakerVoiceContent = {
    Text = "Preparati a morire, insetto spartano."
  },
  Voice_6721_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_6722_AwakerVoiceContent = {
    Text = "La Signorina Doll dice che potrei evitare temporaneamente la Dissoluzione abbandonando il mio corpo come lei... No, non posso farlo! Non posso farlo! Perderò conoscenza durante la procedura, e l'oscurità prenderà il sopravvento!"
  },
  Voice_6722_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito di Doll"
  },
  Voice_6722_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Doll\""
  },
  Voice_6723_AwakerVoiceContent = {
    Text = "Hmph. Che c'è stavolta? Sei pronto ad abbracciare il tuo destino di annientamento, ora?"
  },
  Voice_6723_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_6724_AwakerVoiceContent = {
    Text = "Ancora tormentato dall'insonnia, Maestro? Ho preparato il tranquillante di Dobie per te~! Anche se la dose potrebbe essere un po' alta, dormire bene è la priorità assoluta!"
  },
  Voice_6724_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_6724_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_6725_AwakerVoiceContent = {
    Text = "Stavamo bevendo e cantando quando all'improvviso ci siamo trasformati in mostri! Ma va tutto bene, questo colorito verdastro è piuttosto divertente!"
  },
  Voice_6725_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_6725_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_6726_AwakerVoiceContent = {
    Text = "Il mio sogno? Hmm... Comprare una bella collana di perle e indossarla a un ballo. Allora sarò al centro dell'attenzione di tutti!"
  },
  Voice_6726_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_6726_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_67276_AwakerVoiceContent = {
    Text = "L'Eone del Desiderio, Tifere Yesod, ha trovato la sua via di sopravvivenza. Di fronte alla Creatura Sconosciuta, nessuno può giudicare la nobiltà o la bassezza dei suoi metodi."
  },
  Voice_67276_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Eone del Desiderio"
  },
  Voice_67276_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Thais\""
  },
  Voice_67277_AwakerVoiceContent = {
    Text = "Attraversa il Portale della Chiave d'Argento per raggiungere il Loro Trono."
  },
  Voice_67277_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_67278_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_67279_AwakerVoiceContent = {
    Text = "Non lasciare che la Loro conoscenza e le Loro memorie vadano sprecate."
  },
  Voice_67279_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_6727_AwakerVoiceContent = {
    Text = "Spazzata a sinistra, strofinata a destra, spazziamo via la polvere e le preoccupazioni~!"
  },
  Voice_6727_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_6727_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_67280_AwakerVoiceContent = {
    Text = "Io non sono qui."
  },
  Voice_67280_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_67281_AwakerVoiceContent = {
    Text = "Un frammento dall'infinito continuum spazio-temporale giunge alla mia coscienza."
  },
  Voice_67281_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_67282_AwakerVoiceContent = {
    Text = "Ho contemplato il tutto."
  },
  Voice_67282_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_67283_AwakerVoiceContent = {
    Text = "Tutto esiste nel vuoto."
  },
  Voice_67283_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_67284_AwakerVoiceContent = {
    Text = "Ti sei spinto in profondità, molto in profondità. Presto, sarai testimone di uno straordinario Miracolo. Spero che tu possa restare lucido e calmo come lo sei ora."
  },
  Voice_67284_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_67284_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_67285_AwakerVoiceContent = {
    Text = "Odio... l'\"Ignoranza.\" No, cercare con diligenza la verità ultima non è ignoranza. La vera ignoranza risiede nel vivere in una nebbia, inconsapevoli di ciò che non si conosce."
  },
  Voice_67285_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_67286_AwakerVoiceContent = {
    Text = "Ti mostrerò i miei sogni. Tutto ciò che di bizzarro e caotico vedrai è più vicino alla vera natura di questo mondo della realtà che conosci."
  },
  Voice_67286_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_67286_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_67287_AwakerVoiceContent = {
    Text = "Ecco il mio consiglio: mantieni la calma. Quando ti senti stanco, fermati immediatamente e conserva le tue forze. Altrimenti, sarai perduto per sempre nel reame dei sogni."
  },
  Voice_67287_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_67287_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_67288_AwakerVoiceContent = {
    Text = "L'universo cicla senza fine."
  },
  Voice_67288_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_67289_AwakerVoiceContent = {
    Text = "La sincronizzazione tra noi non dovrebbe richiedere un adattamento così lungo. Tuttavia, per preservare la tua lucidità mentale dalle illusioni, procederò gradualmente."
  },
  Voice_67289_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_67289_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_6728_AwakerVoiceContent = {
    Text = "Dissoluzione... ho lavorato a un caso che la sfiorava. Ma scomparire sembra piuttosto naturale, non trovi? Tutti svaniscono, alla fine."
  },
  Voice_6728_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_67290_AwakerVoiceContent = {
    Text = "Il Primo Portale. L'universo infinito nacque da un punto."
  },
  Voice_67290_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_67290_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_67291_AwakerVoiceContent = {
    Text = "Il Secondo Portale. Una linea si estende da un punto, protendendosi verso polarità infinite."
  },
  Voice_67291_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_67291_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_67292_AwakerVoiceContent = {
    Text = "Il Quarto Portale. L'archetipo eterno si solidificò in uno spazio di dimensioni."
  },
  Voice_67292_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_67292_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_67293_AwakerVoiceContent = {
    Text = "Il Terzo Portale. I piani sono costrutti parziali e unilaterali."
  },
  Voice_67293_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_67293_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_67294_AwakerVoiceContent = {
    Text = "La Porta degli estremi. Il vuoto ultimo che collega innumerevoli universi. Attraversala, e i misteri del mondo ti saranno rivelati."
  },
  Voice_67294_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_67294_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_67295_AwakerVoiceContent = {
    Text = "La Quinta Porta. Lo scorrere del tempo non è che un'illusione; non vi è mai stato un principio, e dunque, nessuna fine."
  },
  Voice_67295_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_67295_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_67296_AwakerVoiceContent = {
    Text = "Avrei dovuto essere soltanto la tua Guida, condurti in questo viaggio prima di tornare a riposare nelle acque illusorie. Ora, tu sei il mio Connettore, e il nostro legame è così intricato che è difficile reciderlo."
  },
  Voice_67296_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_67297_AwakerVoiceContent = {
    Text = "Desideri confermare qualcosa? I sensi di questo corpo sono troppo limitati. Se ci incontrassimo nell'Abisso, potrei mostrarti molto di più."
  },
  Voice_67297_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_67298_AwakerVoiceContent = {
    Text = "Lei è un Frammento di me proveniente da un'altra Dimensione che è stata eternamente annientata. Purtroppo, pur avendo padroneggiato l'Inversione Temporale, non è riuscita a cogliere l'essenza del Trascendere lo spaziotempo, soccombendo ripetutamente all'angoscia. La colpa è mia."
  },
  Voice_67298_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Ramona: Logorata dal tempo"
  },
  Voice_67298_UnlockDesc = {
    Text = "Si sblocca dopo aver acquisito il Risvegliatore \"Ramona: Consunta dal tempo\""
  },
  Voice_67299_AwakerVoiceContent = {Text = "Lo so."},
  Voice_67299_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_6729_AwakerVoiceContent = {
    Text = "Sei curioso riguardo all'aspetto del mio attuale involucro? Non pensarci troppo. Sono nato con un volto umano."
  },
  Voice_6729_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_67300_AwakerVoiceContent = {Text = "Capisco."},
  Voice_67300_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_67301_AwakerVoiceContent = {
    Text = "Insignificante."
  },
  Voice_67301_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_67302_AwakerVoiceContent = {
    Text = "Mantieni la compostezza."
  },
  Voice_67302_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_67303_AwakerVoiceContent = {
    Text = "Collegarsi direttamente con un Eone danneggerà la tua mente. Tuttavia, poiché insisti, risponderò alla tua chiamata."
  },
  Voice_67303_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_67304_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_67305_AwakerVoiceContent = {
    Text = "Quella bambina ha sopportato fin troppo a causa del Frammento di me che porta in sé. Per fortuna, la sua anima resta limpida come Argento fluente."
  },
  Voice_67305_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Ramona"
  },
  Voice_67305_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Ramona\""
  },
  Voice_67306_AwakerVoiceContent = {
    Text = "Visita il Loro sogno e scorgi i segreti proibiti dell'universo."
  },
  Voice_67306_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_67307_AwakerVoiceContent = {Text = "Hmm."},
  Voice_67307_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_67308_AwakerVoiceContent = {
    Text = "La Porta degli estremi si apre per te. Abbraccia il mondo di silenzio mortale che giace oltre."
  },
  Voice_67308_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_67308_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_67309_AwakerVoiceContent = {
    Text = "Ho solo aiutato a fondare questa istituzione per la \"Conservazione.\" La scuola ha ottenuto più di quanto avessi previsto."
  },
  Voice_67309_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_6730_AwakerVoiceContent = {
    Text = "La Dissoluzione è un dono divino. Il Pain che porta è appena sufficiente a paralizzare i nostri nervi, permettendoci di abbandonarci anima e corpo al cibo, al vino e ai festeggiamenti, mentre scivoliamo verso l'estinzione."
  },
  Voice_6730_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sulla Dissoluzione"
  },
  Voice_67310_AwakerVoiceContent = {
    Text = "Passato, presente, futuro. Un miliardo di splendori si fondono in uno!"
  },
  Voice_67310_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_67311_AwakerVoiceContent = {
    Text = "Passato, presente, futuro. Un miliardo di splendori si fondono in uno!"
  },
  Voice_67311_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_67312_AwakerVoiceContent = {
    Text = "La Porta degli estremi si è aperta. Contempla il Tutto-in-Uno e l'Uno-in-Tutto!"
  },
  Voice_67312_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_67313_AwakerVoiceContent = {
    Text = "La Porta degli estremi si è aperta. Contempla il Tutto-in-Uno e l'Uno-in-Tutto!"
  },
  Voice_67313_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_67314_AwakerVoiceContent = {
    Text = "Ascolta la voce della saggezza."
  },
  Voice_67314_AwakerVoiceTitle = {
    Text = "Abilità Speciale: II"
  },
  Voice_67315_AwakerVoiceContent = {
    Text = "Infinito, sconfinato, perpetuo, illimitato."
  },
  Voice_67315_AwakerVoiceTitle = {
    Text = "Abilità Speciale: III"
  },
  Voice_67316_AwakerVoiceContent = {
    Text = "È la Loro volontà... No, è uno sguardo inconscio che avvolge ogni cosa nel Loro respiro."
  },
  Voice_67316_AwakerVoiceTitle = {
    Text = "Chiacchiere: Riguardo alla Crisi"
  },
  Voice_67317_AwakerVoiceContent = {
    Text = "Non sono riuscito... a vedere ogni cosa...."
  },
  Voice_67317_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_67318_AwakerVoiceContent = {
    Text = "Rivelerò la verità."
  },
  Voice_67318_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_67319_AwakerVoiceContent = {
    Text = "Amo... la \"Risposta.\" È per questo amore che ho custodito questa Porta, e per questo amore che ho posto la sua Chiave nella tua mano."
  },
  Voice_67319_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_6731_AwakerVoiceContent = {
    Text = "Devo... Devo tornare..."
  },
  Voice_6731_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_6732_AwakerVoiceContent = {
    Text = "Cielo e Terra, seguite il ciclo della causalità!"
  },
  Voice_6732_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_6733_AwakerVoiceContent = {
    Text = "Cielo e Terra, seguite il ciclo della causalità!"
  },
  Voice_6733_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_6734_AwakerVoiceContent = {
    Text = "La Lama non ha ancora perso il suo filo."
  },
  Voice_6734_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_6735_AwakerVoiceContent = {
    Text = "L'addestramento non va trascurato!"
  },
  Voice_6735_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_6736_AwakerVoiceContent = {
    Text = "Ora sono più agile."
  },
  Voice_6736_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_6737_AwakerVoiceContent = {
    Text = "Le Progenie Informi saranno ai vostri ordini."
  },
  Voice_6737_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_6737_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_6738_AwakerVoiceContent = {
    Text = "Senti il mio respiro rovente!"
  },
  Voice_6738_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_6739_AwakerVoiceContent = {
    Text = "Diventeremo tutti... parte della Fiamma Verde..."
  },
  Voice_6739_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_6740_AwakerVoiceContent = {
    Text = "Il mio scudo brillerà sempre per voi, mio signore."
  },
  Voice_6740_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_6740_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_6741_AwakerVoiceContent = {
    Text = "Io... sono diventato un po' più Forte. Ve ne sono davvero grato!"
  },
  Voice_6741_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_6741_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_6743_AwakerVoiceContent = {Text = "Tsk..."},
  Voice_6743_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_6744_AwakerVoiceContent = {
    Text = "(Sopportare con disprezzo)"
  },
  Voice_6744_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_6745_AwakerVoiceContent = {
    Text = "(Sopportare con disprezzo)"
  },
  Voice_6745_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_6746_AwakerVoiceContent = {
    Text = "(Sopportare con disprezzo)"
  },
  Voice_6746_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_6747_AwakerVoiceContent = {
    Text = "Il tempo trascorso con gli amici è sempre così... rilassante."
  },
  Voice_6747_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_6748_AwakerVoiceContent = {
    Text = "La Catena Insanguinata della Carneficina, Messaggera di Tisifone, Lama dell'Odio... Non m'importa. È così che mi chiamavano. Beh, non mi dispiace certo essere all'altezza di quei nomi."
  },
  Voice_6748_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito di Helot"
  },
  Voice_6749_AwakerVoiceContent = {
    Text = "(Esclamazione)"
  },
  Voice_6749_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_6750_AwakerVoiceContent = {Text = "ALL-IN!"},
  Voice_6750_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_6751_AwakerVoiceContent = {
    Text = "(Esclamazione)"
  },
  Voice_6751_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_6752_AwakerVoiceContent = {
    Text = "(Esclamazione)"
  },
  Voice_6752_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_6753_AwakerVoiceContent = {
    Text = "Possiamo andare più lontano stavolta? Andiamo alla spiaggia!"
  },
  Voice_6753_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_6754_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_6755_AwakerVoiceContent = {
    Text = "Wow—grazie, caro amico~"
  },
  Voice_6755_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_6756_AwakerVoiceContent = {
    Text = "Amici~ Ancora amici~"
  },
  Voice_6756_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_6757_AwakerVoiceContent = {
    Text = "Uvhash... è speciale. Pensavi che la prosperità della mia famiglia fosse arrivata facilmente? È tutto merito suo, che uccideva come un cane rabbioso nell'Arena. Era la nostra più grande gallina dalle uova d'oro."
  },
  Voice_6757_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Uvhash"
  },
  Voice_6757_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Uvhash\""
  },
  Voice_6758_AwakerVoiceContent = {Text = "Sciocco!"},
  Voice_6758_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_6759_AwakerVoiceContent = {Text = "Heh."},
  Voice_6759_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_6760_AwakerVoiceContent = {
    Text = "Avanti! Impartisci il comando di Battaglia!"
  },
  Voice_6760_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_6761_AwakerVoiceContent = {
    Text = "Nell'Abisso... ci sarà una luce di Giustizia."
  },
  Voice_6761_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_6762_AwakerVoiceContent = {
    Text = "La luce della Giustizia si accende qui!"
  },
  Voice_6762_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_6763_AwakerVoiceContent = {
    Text = "Le emozioni umane sono fragili e preziose come fiori..."
  },
  Voice_6763_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito di Colette"
  },
  Voice_6764_AwakerVoiceContent = {
    Text = "Carta, stai, Blackjack!"
  },
  Voice_6764_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_6765_AwakerVoiceContent = {
    Text = "Carta, stai, Blackjack!"
  },
  Voice_6765_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_67754_AwakerVoiceContent = {
    Text = "Non resistere. Non piangere. Diventa nulla!"
  },
  Voice_67754_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_67756_AwakerVoiceContent = {
    Text = "Non resistere. Non piangere. Diventa nulla!"
  },
  Voice_67756_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_67772_AwakerVoiceContent = {
    Text = "Portale, apriti per me."
  },
  Voice_67772_AwakerVoiceTitle = {
    Text = "Abilità Speciale: I"
  },
  Voice_79297_AwakerVoiceContent = {Text = "Oh."},
  Voice_79297_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_79298_AwakerVoiceContent = {Text = "Hmm...?"},
  Voice_79298_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_80092_AwakerVoiceContent = {
    Text = "Idroterapia, terapia elettroconvulsiva, terapia di contenzione... quelle non sono cure, ma torture. Perciò ho curato a modo mio i pazienti di quegli ospedali, pro bono. Alla fine, tutti hanno raggiunto la guarigione e trovato la vera libertà."
  },
  Voice_80092_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_80092_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_80093_AwakerVoiceContent = {
    Text = "Povero signor White. La sua famiglia lo teneva in un porcile perché i manicomi del vicinato erano pieni. L'ho curato gratuitamente, e dopo di allora, finalmente comprese di essere una persona, non bestiame. Riconquistò poi la sua dignità, con le proprie mani."
  },
  Voice_80093_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_80093_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_80094_AwakerVoiceContent = {
    Text = "Tessitori, avvocati, baroni... non rifiuterò mai un paziente per una questione di compenso. Per me, sono tutti semplicemente pazienti bisognosi di guarigione."
  },
  Voice_80094_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_80094_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_80095_AwakerVoiceContent = {
    Text = "Ammetto di averti sottovalutato. La tua esistenza è Pain essa stessa. Questa volta non servono visite di controllo. Voglio restare al tuo fianco e vedere l'esito con i miei occhi."
  },
  Voice_80095_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_80095_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_80096_AwakerVoiceContent = {
    Text = "Questi pazienti mi hanno donato memorie meravigliose. Ora tocca a te, Custode. Ho già scelto un finale perfetto per te. Sarà la consultazione più squisita della mia carriera."
  },
  Voice_80096_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_80096_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_81138_AwakerVoiceContent = {
    Text = "Rifiutare l'aiuto di un dottore non ti gioverà. Forse la prossima volta proveremo l'ipnosi profonda."
  },
  Voice_81138_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_81139_AwakerVoiceContent = {
    Text = "Una stanza buia, completamente solo, insieme agli innumerevoli sussurri dolorosi che riecheggiano senza sosta nella mia mente... questo è il modo migliore per assaporare il tempo."
  },
  Voice_81139_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_81140_AwakerVoiceContent = {
    Text = "Per quanto possa sembrare scortese dirlo, parlare con quella bambina mi annoia soltanto. Si può vedere una sola espressione... un sorriso."
  },
  Voice_81140_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Aurita"
  },
  Voice_81140_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Aurita\""
  },
  Voice_81141_AwakerVoiceContent = {
    Text = "Perdona la mia intrusione, ho semplicemente percepito un'energia psicologica bassa e sono venuto a controllare. Ora, Custode, ci imbarchiamo in un viaggio attraverso la tua mente?"
  },
  Voice_81141_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_81143_AwakerVoiceContent = {
    Text = "Un tempo gli psichiatri curavano i pazienti perforando loro il cranio con la tecnica della trapanazione... Ti prego, rilassati. Era molto tempo fa. Da allora abbiamo sviluppato metodi ben più raffinati per addentrarci nella mente."
  },
  Voice_81143_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_81143_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_81144_AwakerVoiceContent = {
    Text = "Per comprendersi, bisogna aprire il proprio cuore. Tocca qui, e il mio cuore d'argento si aprirà per te."
  },
  Voice_81144_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_81145_AwakerVoiceContent = {
    Text = "Se cerchi le mie opinioni, potresti restare deluso. Sono più bravo ad ascoltare che a offrire commenti."
  },
  Voice_81145_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_81146_AwakerVoiceContent = {
    Text = "Ah, ho udito la Sua voce... quei Deliri, ogni sillaba colma della più profonda Agonia."
  },
  Voice_81146_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_81147_AwakerVoiceContent = {
    Text = "Ricorderò il dolore di questo istante... rievocandolo e assaporandolo ancora e ancora."
  },
  Voice_81147_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_81148_AwakerVoiceContent = {
    Text = "In quanto frammento di quell'esistenza, porti il Loro profumo... Un profumo bellissimo, intriso di dolore. Rende qualsiasi tua memoria incredibilmente deliziosa da assaporare."
  },
  Voice_81148_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_81149_AwakerVoiceContent = {
    Text = "Ricorda quei terrori, descrivi nel dettaglio le tue sensazioni di Pain. L'essenza della terapia a impatto emotivo è affrontare il Pain direttamente e conquistarlo. Ecco, ti asciugo le lacrime. Prenditi il tuo tempo. Raccontami quelle memorie nel dettaglio..."
  },
  Voice_81149_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_81149_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_81150_AwakerVoiceContent = {
    Text = "Congratulazioni, sei guarito. Sì, quelle allucinazioni e illusioni sono normali; sono la prova della tua guarigione."
  },
  Voice_81150_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_81150_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_81151_AwakerVoiceContent = {
    Text = "La tua visuale è probabilmente colma di allucinazioni bizzarre, ora, il che è del tutto normale. Disegnale, e il tuo subconscio e i tuoi istinti riveleranno ogni cosa."
  },
  Voice_81151_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_81151_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_81152_AwakerVoiceContent = {
    Text = "Ora passiamo alla terapia morale di Philippe Pinel. Devi esprimere i tuoi desideri e terrori più intimi. È una procedura necessaria per liberare la mente dalle catene e risvegliare l'umanità sopita."
  },
  Voice_81152_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_81152_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_81153_AwakerVoiceContent = {
    Text = "Custode, puoi aiutarmi con un piccolo test? Il test delle macchie di Rorschach. Mi aiuterà a scrutare le profondità del tuo io interiore... Diventerò l'unico Risvegliato a svelare i segreti del tuo cuore."
  },
  Voice_81153_AwakerVoiceTitle = {
    Text = "Chat: A proposito dell'Analisi Psicologica"
  },
  Voice_81154_AwakerVoiceContent = {
    Text = "Per prima cosa, ascoltiamo un po' di musica. Come trovi questa melodia? Rilassante e delicata. Ora, lascia che il tuo corpo e la tua mente risuonino con la musica, entrando in uno stato di rilassamento spirituale."
  },
  Voice_81154_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_81154_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_81155_AwakerVoiceContent = {
    Text = "Osserva il pendolo... seguine il movimento con gli occhi."
  },
  Voice_81155_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_81156_AwakerVoiceContent = {
    Text = "Shh... silenzio. Ora, cammina verso il finale a cui ti guiderò."
  },
  Voice_81156_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_81157_AwakerVoiceContent = {
    Text = "Un'anima intorpidita non suscita alcun interesse in me. Le loro anime sono già morte. Per quanto le si agiti, non si leverà un'increspatura."
  },
  Voice_81157_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_81158_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_81159_AwakerVoiceContent = {
    Text = "Ti ascolto. Prego, continua."
  },
  Voice_81159_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_81160_AwakerVoiceContent = {
    Text = "Per favore, resta in silenzio."
  },
  Voice_81160_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_81161_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_81162_AwakerVoiceContent = {
    Text = "Fidati un po' di più di me."
  },
  Voice_81162_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_81163_AwakerVoiceContent = {
    Text = "Esponi il tuo pain."
  },
  Voice_81163_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_81164_AwakerVoiceContent = {
    Text = "Non essere timido, non c'è bisogno di nascondersi. Sono la tua unica confidente. Avanti, riversami il tuo Pain più profondo."
  },
  Voice_81164_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_81165_AwakerVoiceContent = {
    Text = "Aigis sembra molto più luminosa ora. Naturalmente, se il mio piccolo ospite ha bisogno d'aiuto, sono felice di offrirlo. Intendo dire, aiuto genuino."
  },
  Voice_81165_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Aigis"
  },
  Voice_81165_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Aigis\""
  },
  Voice_81166_AwakerVoiceContent = {
    Text = "Mostrami il tuo vero io."
  },
  Voice_81166_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_81168_AwakerVoiceContent = {
    Text = "Assaporerò questo dolce pain."
  },
  Voice_81168_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_81169_AwakerVoiceContent = {
    Text = "Non essere timido, non c'è bisogno di nascondersi. Sono la tua unica confidente. Avanti, riversami il tuo Pain più profondo."
  },
  Voice_81169_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_81170_AwakerVoiceContent = {
    Text = "La malattia mentale non è esclusiva di quest'epoca; trascende il tempo e lo spazio. La Dissoluzione è la stessa cosa. Entrambe trascendono i confini della cognizione umana, non è vero?"
  },
  Voice_81170_AwakerVoiceTitle = {
    Text = "Chiacchiere: Riguardo alla Crisi"
  },
  Voice_81171_AwakerVoiceContent = {
    Text = "Shh... silenzio. Ora, cammina verso il finale a cui ti guiderò."
  },
  Voice_81171_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_81172_AwakerVoiceContent = {
    Text = "Questo luogo è colmo di tracce della storia, e in un certo senso, la storia rappresenta memorie... memorie dolorose dei defunti."
  },
  Voice_81172_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_81173_AwakerVoiceContent = {
    Text = "Fai un respiro profondo."
  },
  Voice_81173_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_81174_AwakerVoiceContent = {
    Text = "Pain, disperazione, morte... queste memorie hanno il sapore di un dessert dopo un pasto raffinato."
  },
  Voice_81174_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_81175_AwakerVoiceContent = {
    Text = "Non c'è bisogno di tanto nervosismo. Questa è soltanto una normale consultazione."
  },
  Voice_81175_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_81176_AwakerVoiceContent = {
    Text = "Ascolta la mia guida."
  },
  Voice_81176_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_84185_AwakerVoiceContent = {
    Text = "Un imprevisto si è verificato durante il Rito. Perdonami per averti colpito il braccio con la bandiera; dovevo mantenerti cosciente."
  },
  Voice_84185_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_84185_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_84186_AwakerVoiceContent = {
    Text = "Qui incontro molti tipi di navi e lavoro con strumenti di navigazione avanzati. Lo trovo profondamente gratificante. Soprattutto, credo che questa \"nave\" stia tracciando la rotta giusta per la storia dell'umanità."
  },
  Voice_84186_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_84187_AwakerVoiceContent = {
    Text = "Il Rito è Completo. Grazie per la tua collaborazione. La prossima volta farò Preparazione di bandiere speciali per guidarci in modo più sicuro attraverso il Rito."
  },
  Voice_84187_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_84187_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_84188_AwakerVoiceContent = {
    Text = "Non so perché esista. So solo questo: devo navigare con successo e riportare tutti a casa."
  },
  Voice_84188_AwakerVoiceTitle = {
    Text = "Chiacchiere: Riguardo alla Crisi"
  },
  Voice_84189_AwakerVoiceContent = {
    Text = "Stai tranquillo, userò questo Potere per guidare la nave in sicurezza, e non ne abuserò mai."
  },
  Voice_84189_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_84190_AwakerVoiceContent = {
    Text = "Per favore, smetti di resistere."
  },
  Voice_84190_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_84191_AwakerVoiceContent = {
    Text = "Avete il mio pieno rispetto. Giuro di eseguire ogni ordine che impartirete."
  },
  Voice_84191_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_84192_AwakerVoiceContent = {
    Text = "Perdonami. Capisco le navi meglio delle persone. Ma se posso permettermi: la tua chiglia non è né di legno né di ferro, ma d'acciaio. Forte. Irremovibile. Davvero ammirevole."
  },
  Voice_84192_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_84192_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_84193_AwakerVoiceContent = {Text = "Arrenditi."},
  Voice_84193_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_84194_AwakerVoiceContent = {
    Text = "Più che \"simpatia,\" preferisco la parola \"devozione.\" Quando guardo direttamente quel dio indescrivibile, la mia mente perde la ragione e si colma di estasi. Dovrei temerLo, ma non riesco a trattenermi."
  },
  Voice_84194_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_84195_AwakerVoiceContent = {
    Text = "Non mi lascerò sconfiggere da questa tempesta."
  },
  Voice_84195_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_84196_AwakerVoiceContent = {
    Text = "Senza ordine, cosa resta in questo mondo? Solo il caos."
  },
  Voice_84196_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_84197_AwakerVoiceContent = {
    Text = "Nella nostra prossima navigazione, vorrei salire a bordo in una veste diversa dal navigatore. Ehm... intendo, come qualcuno che segue la tua guida. Hai la mia fiducia completa, Custode."
  },
  Voice_84197_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_84197_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_84198_AwakerVoiceContent = {
    Text = "Non faccio che adempiere al mio dovere di navigatore: non necessito né di rapporti né di elogi."
  },
  Voice_84198_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_84199_AwakerVoiceContent = {
    Text = "Il sistema del faro alleggerisce le esigenze della navigazione. Il suo fascio è forte e chiaro. Sono lieto di navigare con Faros."
  },
  Voice_84199_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Faros"
  },
  Voice_84199_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Faros\""
  },
  Voice_84200_AwakerVoiceContent = {
    Text = "Marinai, seguite la mia Guida. Mi assicurerò che raggiungiamo il porto in sicurezza."
  },
  Voice_84200_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_84201_AwakerVoiceContent = {
    Text = "Il legame spirituale è stato stabilito. Percepisco la vostra presenza. È la prima volta che navigo nel vuoto. Se qualcosa dovesse deviare dalla rotta, vi prego di correggermi immediatamente."
  },
  Voice_84201_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_84201_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_84202_AwakerVoiceContent = {
    Text = "Nuvola di tipo cirro avvistata, con un calo continuo della pressione barometrica. Allerta a tutto l'equipaggio. La nave sta per entrare in una tempesta."
  },
  Voice_84202_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_84203_AwakerVoiceContent = {
    Text = "Questo Caos è il risultato di un mio errore di Calcolo della rotta. Sono disposto ad accettare la Punizione in conformità alle Regole."
  },
  Voice_84203_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_84204_AwakerVoiceContent = {
    Text = "Misurazione dell'angolo di altitudine dei corpi celesti."
  },
  Voice_84204_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_84205_AwakerVoiceContent = {
    Text = "Questa sensazione di vertigine somiglia molto al mal di mare. Per favore, chiudi gli occhi, prendi la mia mano e appoggiati a me. Dovrebbe alleviare un poco il disagio."
  },
  Voice_84205_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_84205_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_84206_AwakerVoiceContent = {
    Text = "Ammainate le vele dell'albero di trinchetto. Le onde premono sul lato di babordo. Timoniere, correggi la rotta secondo i miei calcoli."
  },
  Voice_84206_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_84207_AwakerVoiceContent = {
    Text = "Queste esperienze sono inestimabili. Le annoterò nel dettaglio nel giornale di bordo, per i Marinaio futuri."
  },
  Voice_84207_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_84208_AwakerVoiceContent = {
    Text = "Il Rito di Approfondimento della connessione spirituale comporta rischi e risultati sconosciuti. Ma stai tranquillo, navigherò per te affinché il Rito si completi senza intoppi."
  },
  Voice_84208_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_84208_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_84209_AwakerVoiceContent = {
    Text = "Ridistribuzione del peso in corso."
  },
  Voice_84209_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_84210_AwakerVoiceContent = {
    Text = "Garantire la sicurezza della nave sopra ogni altra cosa."
  },
  Voice_84210_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_84211_AwakerVoiceContent = {
    Text = "Alcune persone sono come navi a vapore—lente a reagire, ma capaci di grande velocità. Altre, navi diesel—rapide a partire, ma con Potere limitato. E tu, Custode, che tipo sei?"
  },
  Voice_84211_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_84211_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_84212_AwakerVoiceContent = {
    Text = "Credo fermamente nella legge fondamentale secondo cui l'impegno porta ricompensa, e in futuro mi adopererò con ancora maggiore dedizione."
  },
  Voice_84212_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_84213_AwakerVoiceContent = {
    Text = "Hai dimostrato il tuo valore in molteplici occasioni. Credo che tu sia un eccellente navigatore, forse più capace di me."
  },
  Voice_84213_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_84213_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_84214_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_84215_AwakerVoiceContent = {
    Text = "Finché avrai bisogno, Corposant sarà sempre pronta."
  },
  Voice_84215_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_84215_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_84216_AwakerVoiceContent = {
    Text = "Marinai, seguite la mia Guida. Mi assicurerò che raggiungiamo il porto in sicurezza."
  },
  Voice_84216_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_84217_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_84218_AwakerVoiceContent = {
    Text = "La navigatrice Corposant si presenta in servizio! La bandiera è stata preparata, le condizioni personali sono ottime, prego impartire l'ordine di lancio, Custode."
  },
  Voice_84218_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_84219_AwakerVoiceContent = {
    Text = "Condurrò la mia nave sulla rotta corretta."
  },
  Voice_84219_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_84220_AwakerVoiceContent = {
    Text = "Il mio cappello è storto? Mi scuso, ma non sono sicuro di cosa intendiate. Vi prego, datemi istruzioni chiare."
  },
  Voice_84220_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_84221_AwakerVoiceContent = {
    Text = "La bandiera è il linguaggio del navigatore, e anche il suo epitaffio. Quando la nave affonda, i recuperatori leggeranno l'ultimo messaggio che ho lasciato dai resti della bandiera."
  },
  Voice_84221_AwakerVoiceTitle = {
    Text = "Chat: A proposito della sua bandiera"
  },
  Voice_84222_AwakerVoiceContent = {
    Text = "Valutazione dell'assetto e dell'equilibrio della nave."
  },
  Voice_84222_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_84223_AwakerVoiceContent = {
    Text = "Ammainate le vele dell'albero di trinchetto. Le onde premono sul lato di babordo. Timoniere, correggi la rotta secondo i miei calcoli."
  },
  Voice_84223_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_84224_AwakerVoiceContent = {
    Text = "La bandiera E trasmette istruzioni."
  },
  Voice_84224_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_84225_AwakerVoiceContent = {
    Text = "Quando necessario, un navigatore addestrato nella cooperazione in sala macchine può fungere da timoniere. Ma per la sicurezza della nave, preferisco comunque affidare quel compito a qualcuno di più esperto."
  },
  Voice_84225_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Celeste"
  },
  Voice_84225_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Celeste\""
  },
  Voice_84226_AwakerVoiceContent = {
    Text = "Sento... una sensazione di assenza di gravità, seguita da violente scosse—come se la nave venisse sballottata. Custode, segui i miei movimenti per trovare il tuo centro e mantenere l'Equilibrio."
  },
  Voice_84226_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_84226_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_84406_AwakerVoiceContent = {
    Text = "Inizio dell'aggiornamento della carta nautica con le correzioni."
  },
  Voice_84406_AwakerVoiceTitle = {
    Text = "Abilità Speciale: I"
  },
  Voice_84407_AwakerVoiceTitle = {
    Text = "Abilità Speciale: III"
  },
  Voice_84408_AwakerVoiceContent = {
    Text = "La bandiera C conferma le istruzioni."
  },
  Voice_84408_AwakerVoiceTitle = {
    Text = "Abilità Speciale: II"
  },
  Voice_84409_AwakerVoiceTitle = {
    Text = "Abilità Speciale: III"
  },
  Voice_90333_AwakerVoiceContent = {
    Text = "Non passerai oltre me."
  },
  Voice_90333_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_90334_AwakerVoiceContent = {
    Text = "Come dovrebbero andare d'accordo gli amici? A Pollux piace darmi ordini quando potrebbe fare quelle cose da solo. E io sono disposto ad aiutarlo in quei compiti, è il nostro modo di stare insieme. Se vuoi, farò qualcosa anche per te."
  },
  Voice_90334_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_90334_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_90335_AwakerVoiceContent = {
    Text = "Che venga il Cataclisma. Questa Carne dell'Immortale resterà indistruttibile!"
  },
  Voice_90335_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_90336_AwakerVoiceContent = {
    Text = "Ancor prima di quel libro, ci interrogavamo sul mondo oltre l'isola del lago, oltre le mura scarlatte. Eppure, quando Pollux ha sofferto, non mi sono opposto. Mi manca il suo coraggio. A differenza di Pollux, io sono molto più codardo e maldestro."
  },
  Voice_90336_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_90336_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_90337_AwakerVoiceContent = {
    Text = "Sembro... stupido? Scusa, ti prego perdona la mia ignoranza. La mia Conoscenza inizia e finisce con le dottrine della Lanterna. Insegnami ciò che ti piace e ciò che non ti piace — lo imprimerò nella Memoria."
  },
  Voice_90337_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_90337_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_90338_AwakerVoiceContent = {
    Text = "Siate testimoni di questa mia volontà — questa fame di libertà."
  },
  Voice_90338_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_90339_AwakerVoiceContent = {
    Text = "Un negozio capace di esaudire qualsiasi desiderio, traboccante di innumerevoli tesori... Fa esitare ad avvicinarsi. Non che dubiti del potere della signora, ma \"per ottenere qualcosa, bisogna pagare il prezzo corrispondente\" — questa è una lezione che Pollux e io abbiamo appreso a caro prezzo, più e più volte."
  },
  Voice_90339_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Daffodil"
  },
  Voice_90339_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Daffodil\""
  },
  Voice_90340_AwakerVoiceContent = {
    Text = "Queste ali maledette troveranno mai la forza di spiccare di nuovo il volo..."
  },
  Voice_90340_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_90341_AwakerVoiceContent = {
    Text = "Non puoi distruggermi!"
  },
  Voice_90341_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_90342_AwakerVoiceContent = {
    Text = "Vorresti toccare le mie Piume? Certo, fai pure. Devo distenderle di più?"
  },
  Voice_90342_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_90343_AwakerVoiceContent = {
    Text = "La tua generosità mi inquieta. I libri costosi, i cristalli di meteorite che mi hai donato... c'è un prezzo da pagare? Scusa, ti prego perdona la mia Diffidenza. Non dovrei dubitare di te in questo modo."
  },
  Voice_90343_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_90343_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_90344_AwakerVoiceContent = {
    Text = "Ogni uccello, prima o poi, trova il proprio cielo."
  },
  Voice_90344_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_90345_AwakerVoiceContent = {
    Text = "Ah, ho sentito che è un maestro cuoco... La Conoscenza del preparare il cibo è davvero molto necessaria. Anche se non sono così esigente riguardo al cibo, Pollux è estremamente schizzoloso. Dovrei trovare il tempo di imparare da lui... Non dovrei andare? Perché? Il cibo che prepara quel signore sembra delizioso, però."
  },
  Voice_90345_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Doresain"
  },
  Voice_90345_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Doresain\""
  },
  Voice_90346_AwakerVoiceContent = {
    Text = "Ora che ci rifletto, le ancelle che portavano le lanterne non erano poi così diverse da Pollux e me. Vivevamo tutti incatenati da vincoli invisibili, sottomessi in silenzio al nostro destino. Eppure quella serva in verde... lei era diversa. C'era una leggerezza in lei, come se trovasse genuino piacere nei suoi compiti. Forse... forse aveva già scoperto la vera libertà."
  },
  Voice_90346_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Karen"
  },
  Voice_90346_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risveglio \"Karen\""
  },
  Voice_90347_AwakerVoiceContent = {
    Text = "Non puoi distruggermi!"
  },
  Voice_90347_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_90348_AwakerVoiceContent = {
    Text = "Credo di non... esserne mai uscito, eh..."
  },
  Voice_90348_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_90349_AwakerVoiceContent = {
    Text = "Dissolvetevi nel vento!"
  },
  Voice_90349_AwakerVoiceTitle = {
    Text = "Abilità Speciale: II"
  },
  Voice_90350_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_90351_AwakerVoiceContent = {
    Text = "Salve. Sono Castor... C'era altro che avrei dovuto dire? Perdonatemi — le parole non mi vengono facilmente. Se avete bisogno di qualcosa, chiedete pure."
  },
  Voice_90351_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_90352_AwakerVoiceContent = {
    Text = "Solo un graffio..."
  },
  Voice_90352_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_90353_AwakerVoiceContent = {Text = "A terra!"},
  Voice_90353_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_90354_AwakerVoiceContent = {
    Text = "Tanto di non visto... tanto di incompiuto. Quei desolati laghi verde cupo e la fitta nebbia che vi aleggia non ci tratterranno più. Oceani, città, fattorie dalle pagine di quel libro... li vedrò. Con Pollux. Con te."
  },
  Voice_90354_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_90354_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_90355_AwakerVoiceContent = {
    Text = "Quando sentirai le foglie frusciare tra gli alberi, saprai che sono al tuo fianco."
  },
  Voice_90355_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_90355_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_90356_AwakerVoiceContent = {
    Text = "Queste piume oscure si fanno più pesanti ogni giorno."
  },
  Voice_90356_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_90357_AwakerVoiceContent = {
    Text = "Ciò che più bramo è il modo in cui ti affidi ai tuoi compagni senza sforzo. Essere dimenticati... traditi... le ferite non svaniscono mai."
  },
  Voice_90357_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_90358_AwakerVoiceContent = {
    Text = "Quel maestro ladro si è offerto di insegnarmi le migliori tecniche di sopravvivenza per soli cinquecento Fiorini Leoniani... Sono stato ingannato? No, credo che questa sia Conoscenza degna di essere appresa, ed è precisamente ciò che manca a Pollux e a me... È una questione di denaro? Capisco. Allora, che ne dici se andassi a negoziare con lei e le pagassi quattrocentocinquanta Fiorini Leoniani?"
  },
  Voice_90358_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Jenkin"
  },
  Voice_90358_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Jenkin\""
  },
  Voice_90359_AwakerVoiceContent = {
    Text = "Posso sopportare di più..."
  },
  Voice_90359_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_90360_AwakerVoiceContent = {
    Text = "Quando eravamo bambini, le regole non erano così rigide. A volte Pollux se ne andava in giro, diceva qualcosa, e come per magia otteneva una manciata di caramelle. Quella dolcezza... è come questo momento, adesso."
  },
  Voice_90360_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_90360_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_90361_AwakerVoiceContent = {
    Text = "Che venga il Cataclisma. Questa Carne dell'Immortale resterà indistruttibile!"
  },
  Voice_90361_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_90362_AwakerVoiceContent = {
    Text = "Potresti insegnarmi come commerciare? Come scambiare oggetti e come gestire la valuta ottenuta — è davvero una materia profonda. Ottenere la libertà è solo l'Inizio; Pollux e io abbiamo ancora molto da imparare per vivere in modo indipendente. Posso contare su di te?"
  },
  Voice_90362_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_90363_AwakerVoiceContent = {
    Text = "Dissolvetevi nel vento!"
  },
  Voice_90363_AwakerVoiceTitle = {
    Text = "Abilità Speciale: I"
  },
  Voice_90364_AwakerVoiceContent = {
    Text = "Vento, trascinali nelle fauci della morte!"
  },
  Voice_90364_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_90365_AwakerVoiceContent = {
    Text = "Pollux... La Lanterna gli ha riempito la mente di idee velenose, ma in realtà è buono. Non è che sia egoista... È solo terrorizzato. Terrorizzato di perdere l'approvazione della Lanterna, di svanire senza quel fragile senso di identità. La sua disperazione nel compiacerli... è il panico di chi si aggrappa all'unico \"sé\" che abbia mai conosciuto."
  },
  Voice_90365_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Pollux"
  },
  Voice_90365_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Pollux\""
  },
  Voice_90366_AwakerVoiceContent = {
    Text = "Scusa, non volevo distrarmi... Mi hai chiesto cos'è questa piuma? Questa è... la cosa a cui teneva di più... e ora è mia. Ti piace? È bella, vero?"
  },
  Voice_90366_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_90367_AwakerVoiceContent = {
    Text = "Le lezioni di Teologia sotto Albino e il Guardiano della Luce riempivano le nostre giornate. Sognavo Scritture Divine più brevi — meno versetti su cui inciampare, meno rimproveri."
  },
  Voice_90367_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_90367_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_90368_AwakerVoiceContent = {
    Text = "Grazie... per la chiave della mia libertà. Per avermi permesso di afferrare il mio destino."
  },
  Voice_90368_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_90369_AwakerVoiceContent = {
    Text = "Queste ali sono ormai completamente sviluppate. Così robuste, così possenti. Ora posso portare in volo sia Pollux che te. Chiamami quando desideri volare."
  },
  Voice_90369_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_90369_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_90370_AwakerVoiceContent = {
    Text = "Riparatevi dietro le mie ali!"
  },
  Voice_90370_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_90371_AwakerVoiceContent = {
    Text = "Finalmente... ho visto le stelle da quelle pagine."
  },
  Voice_90371_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_90372_AwakerVoiceContent = {
    Text = "La Somma Sacerdotessa... Juliette. Era gentile con noi, allora. I suoi sorrisi calorosi rendevano la disobbedienza impensabile. Una carezza sulla testa zittiva ogni protesta. Non volevamo deluderla. Sì, non preoccuparti, non mi sento più così... Puoi accarezzare la mia testa al suo posto."
  },
  Voice_90372_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_90372_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_90373_AwakerVoiceContent = {
    Text = "Sono rimasto immerso in quella melma nera e vischiosa per molto, molto tempo — così a lungo da dimenticare il tempo stesso, così a lungo che persino Polluce si dimenticò di me. Non portava dolore fisico... solo terrore, guardare la mia anima dissolversi."
  },
  Voice_90373_AwakerVoiceTitle = {
    Text = "Chiacchiere: Riguardo alla Crisi"
  },
  Voice_90374_AwakerVoiceContent = {
    Text = "Non ci era permesso parlare con altre persone fin dall'Infanzia. \"Amico\" era un concetto a me estraneo... fino a poco tempo fa. Pollux e io eravamo tutto l'uno per l'altro: fratelli, amici, Prigionieri, l'unico conforto reciproco. Ora... forse dovrei farmi qualche nuovo amico."
  },
  Voice_90374_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_90374_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_90375_AwakerVoiceContent = {Text = "Indietro!"},
  Voice_90375_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_90376_AwakerVoiceContent = {
    Text = "Una scuola senza Teologia? Dove scegli le lezioni... le salti? Sembra un Sogno."
  },
  Voice_90376_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_90377_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_90378_AwakerVoiceContent = {
    Text = "Fuori dai piedi!"
  },
  Voice_90378_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_95050_AwakerVoiceContent = {
    Text = "Voi blasfemi... sarete puniti..."
  },
  Voice_95050_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_95051_AwakerVoiceContent = {
    Text = "Il mio cuore è una Fiamma del Cuore!"
  },
  Voice_95051_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_95052_AwakerVoiceContent = {Text = "Lordura."},
  Voice_95052_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_95053_AwakerVoiceContent = {
    Text = "Ah, quella credente fanatica. Il mondo potrebbe vederla come una pazza delirante. Sebbene un tempo abbia commesso il male, una devozione così fervente — la volontà di offrire tutto al proprio dio — è una tenacia che le anime comuni non potrebbero mai trovare in sé. Cosa penso di lei, chiedete? ...Provo soltanto... una certa commiserazione. Un'affinità, con chi è stato gettato alla deriva nello stesso mare in tempesta."
  },
  Voice_95053_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Miryam"
  },
  Voice_95053_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risveglio \"Miryam\""
  },
  Voice_95054_AwakerVoiceContent = {
    Text = "Porterò Guida e Giudizio; che la Notte Bianca purghi i vostri peccati!"
  },
  Voice_95054_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_95055_AwakerVoiceContent = {
    Text = "Ha... Dopo tutto questo tempo, non è cambiato di una virgola. Da bambina non avrei mai immaginato che sarei stata io a ferire mio fratello — che avrei contratto con lui un debito così grande da bruciare di vergogna, per un destino che non abbiamo scelto. Abbiamo sofferto abbastanza la Separazione. Ora che sono tornata, lo giuro: nulla ci separerà mai più. Nemmeno la morte stessa."
  },
  Voice_95055_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito di Castor"
  },
  Voice_95055_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risveglio \"Castor\""
  },
  Voice_95056_AwakerVoiceContent = {
    Text = "Un tempo odiavo molte cose: i servitori maleducati, gli attendenti irrispettosi, gli eretici che profanavano la Luce... Ma ora? Odio la Lanterna. Solo la Lanterna! Juliette e la sua Chiesa hanno inflitto a me e a mio fratello un dolore irreparabile. Lo giuro sul mio titolo di ex Divus: non permetterò mai che un simile dolore si abbatta su un altro!"
  },
  Voice_95056_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_95057_AwakerVoiceContent = {
    Text = "Camminerò sul sentiero della luce fino al mio ultimo respiro."
  },
  Voice_95057_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_95058_AwakerVoiceContent = {
    Text = "Che la radiosità del Portatore di Luce squarci questa notte senza fine!"
  },
  Voice_95058_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_95059_AwakerVoiceContent = {
    Text = "La vostra generosità e compassione non conoscono fine; mediterò sul calore della vostra luce."
  },
  Voice_95059_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_95060_AwakerVoiceContent = {
    Text = "L'Apostolo del Portatore di Luce, rampollo della Notte Bianca, Colui che Dissipa l'Oscurità, Divus del Cuore Divino — io, Pollux, ho risposto al vostro richiamo. Vi offro il mio potere sull'Oscurità, e la mia anima forgiata di Luce."
  },
  Voice_95060_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_95061_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_95062_AwakerVoiceContent = {
    Text = "Purgate i vostri peccati!"
  },
  Voice_95062_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_95063_AwakerVoiceContent = {
    Text = "Mi fu detto che questa tenebra abissale era degna di fede. Che era una benedizione che avrei dispensato ai fedeli. Ora, questa oscurità mi ha corroso da tempo, fondendosi con il mio stesso essere... Eppure il cuore che batte in questo vaso peccaminoso resta un sacrario che nulla potrà mai contaminare. State certi: userò il potere che mi ha conferito per portare vera benedizione a questo mondo!"
  },
  Voice_95063_AwakerVoiceTitle = {
    Text = "Chiacchiere: Riguardo alla Crisi"
  },
  Voice_95064_AwakerVoiceContent = {
    Text = "Sarò Araldo del vostro nome glorioso, e tutto ciò che è impuro e contaminato sarà purificato dalla sua radiosità."
  },
  Voice_95064_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_95065_AwakerVoiceContent = {
    Text = "I peccati del passato sono stati commessi; non fuggirò più da essi. Devo anche correggere gli errori della Lanterna e guidare chi si è smarrito verso il vero sentiero. Lasciate che porti il peso dei miei peccati. Allora, risponderò alla luce del vostro richiamo e percorrerò il giusto cammino come Divus."
  },
  Voice_95065_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_95065_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_95066_AwakerVoiceContent = {
    Text = "La vostra è un'anima compassionevole, per perdonare chi è così gravato dal peccato. Sento la luce pura e radiosa nel vostro spirito — eclissa la fiamma più splendente. Forse potete guidare il mio cuore, che ha smarrito la via..."
  },
  Voice_95066_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_95066_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_95067_AwakerVoiceContent = {
    Text = "L'Oscurità... l'Oscurità propagata dall'incantesimo di Juliette, è rimasta nella mia mente... E ora, un singolo raggio di luce l'ha squarciata! Quel flebile bagliore sta forse cercando di dirmi qualcosa?"
  },
  Voice_95067_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_95067_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_95068_AwakerVoiceContent = {
    Text = "Ho sentito dire che un tempo era una Fanciulla Divina. Ma con quei modi così rozzi e quel comportamento brutale... Come? Non sa recitare nemmeno una Preghiera? Che profonda empietà... Provo vergogna al posto della sua divinità."
  },
  Voice_95068_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Murphy"
  },
  Voice_95068_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risveglio \"Murphy\""
  },
  Voice_95069_AwakerVoiceContent = {
    Text = "Colui che può condurre tutti fuori dalla nebbia è il vero Portatore di Luce, forgiato del più puro argento. Il paradise senza peccato predicato da Juliette è, in verità, edificato sulle ossa dei fedeli. Come Divus, seminerò il nuovo vangelo tra tutti coloro che sono degni di salvezza."
  },
  Voice_95069_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_95070_AwakerVoiceContent = {
    Text = "Mi avete guidato e concesso la Luce. Per così tanto tempo sono stato accecato da un falso scopo. Ora ho trovato la mia vera vocazione: correggere gli eretici ignoranti e distorti e portare Luce eterna a questo mondo. Conosco il vostro altruismo; non avete bisogno della mia devozione né delle mie offerte. Allora vi imploro: permettetemi di camminare al vostro fianco, di annotare ogni sacra parola e ogni sacro gesto, affinché possano guidare il mio cammino attraverso l'oscurità."
  },
  Voice_95070_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_95070_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_95071_AwakerVoiceContent = {
    Text = "Avvinto in catene, immerso in una melma oscura, inseguirò quel raggio di luce, a qualunque costo... È questo ciò che volevate insegnarmi?"
  },
  Voice_95071_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_95071_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_95072_AwakerVoiceContent = {
    Text = "Ho perduto la mia luce, e questa cieca sofferenza mi tormenta. Vi imploro, salvate la mia anima perduta. Vi prego, prendete la mia mano mentre guido la vostra su questo Sacro Cuore nel mio petto. Vi prego, guidatemi verso la luce..."
  },
  Voice_95072_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_95072_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_95073_AwakerVoiceContent = {
    Text = "Che creatura sfortunata. Poiché si è consacrata alla vostra causa, otterrà certamente la redenzione suprema. Ma perché anche la sua compagna simile a una scimmia ha ricevuto la vostra misericordia? Quella bambina malvagia mi ha persino rubato i sacramentali! Un torrente di peccati deve imperversare nella sua anima. Ahh, che mancanza di rispetto! UNA MANCANZA DI RISPETTO ASSOLUTA!"
  },
  Voice_95073_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito di Aigis e Jenkin"
  },
  Voice_95073_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto i Risvegliatori \"Aigis\" e \"Jenkin\""
  },
  Voice_95074_AwakerVoiceContent = {Text = "Sparite."},
  Voice_95074_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_95075_AwakerVoiceContent = {
    Text = "Che la radiosità del Portatore di Luce squarci questa notte senza fine!"
  },
  Voice_95075_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_95076_AwakerVoiceContent = {
    Text = "Ah... ora vedo! Vedo una possanza così immane, vedo la verità del mondo... Ho errato in passato. Voi siete il vero Portatore di Luce! Vi prego, concedetemi di divenire il vostro fedele Apostolo. Questo cuore, nato per il Portatore di Luce, d'ora innanzi batterà e tremerà al vostro solo servizio..."
  },
  Voice_95076_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_95076_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_95077_AwakerVoiceContent = {
    Text = "La cieca caccia alla redenzione di quel sacerdote è il colmo della follia. La grazia divina dovrebbe essere concessa unicamente ai devoti e ai giusti. Se persino lui, un apostolo, manca del discernimento per separare il grano dalla pula, premiando peccatori impenitenti e permettendo loro di profanare il regno della sua divinità... non è forse il più profondo tradimento della sua fede e delle anime giuste che afferma di servire?"
  },
  Voice_95077_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Salvador"
  },
  Voice_95077_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risveglio \"Salvador\""
  },
  Voice_95078_AwakerVoiceContent = {
    Text = "Il mio cuore è una Fiamma del Cuore!"
  },
  Voice_95078_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_95079_AwakerVoiceContent = {Text = "Hah!"},
  Voice_95079_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_95080_AwakerVoiceContent = {
    Text = "In gioventù ero determinato a fuggire da quel luogo. Mi aveva portato solo dolore, e lo ritenevo indegno di rimpianto. Ma ora, a cui è stata concessa una seconda vita, comprendo che la libertà non è il mio unico desiderio. Il vero significato dell'essere Divus è contemplare i volti devoti, speranzosi e riconoscenti dei seguaci quando apprendono che la redenzione è vicina."
  },
  Voice_95080_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_95081_AwakerVoiceContent = {
    Text = "Nel tempo in cui ho seguito Juliette, ho commesso gravi errori e non ero degno della vostra fiducia. Eppure mi avete scelto ugualmente... Siatene certo, cercherò ancora una volta la mia convinzione. Come Divus, non deluderò più i miei sudditi, né deluderò voi."
  },
  Voice_95081_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_95081_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_95082_AwakerVoiceContent = {
    Text = "Il dono che mi avete concesso lo impugnerò con la più profonda gratitudine."
  },
  Voice_95082_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_95083_AwakerVoiceContent = {Text = "Impudenza!"},
  Voice_95083_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_95084_AwakerVoiceContent = {
    Text = "Dannazione."
  },
  Voice_95084_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_95085_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_95086_AwakerVoiceContent = {
    Text = "In nome mio!"
  },
  Voice_95086_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_95087_AwakerVoiceContent = {
    Text = "La vedo! Quella luce, che risplende nel profondo della mia coscienza — si fa più intensa! Mi chiama..."
  },
  Voice_95087_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_95087_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_95088_AwakerVoiceContent = {
    Text = "Nella nostra infanzia, Castor e io servimmo insieme come i Divi Gemelli. L'ho sempre ritenuto troppo ottuso, troppo maldestro, convinto che solo io dovessi guidare il nostro futuro. Ora, avendo testimoniato il sentiero che percorrete, comprendo che le fondamenta del mondo sono erette e lastricate da coloro come voi e lui: gli irremovibili e i retti."
  },
  Voice_95088_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_95088_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_95089_AwakerVoiceContent = {
    Text = "Mia Luce, da quando ho ricevuto la vostra guida, credo di aver intrapreso l'unico vero cammino. Eppure il vostro credente alquanto ottuso resta perplesso dinanzi a una domanda: anche il leggendario paradise privo di peccato ricade sotto il vostro dominio? \"Non esiste,\" dite...? Potrebbe essere... intendete dire che il paradise esiste qui, nel mondo mortale, nei cuori puri dei giusti?"
  },
  Voice_95089_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_95090_AwakerVoiceContent = {
    Text = "Questo cuore, che un tempo obbediva alla volontà divina, ora batte più vicino al vostro."
  },
  Voice_95090_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_95091_AwakerVoiceContent = {
    Text = "A-Avete un ordine per me, mia Luce? Il vostro Apostolo è sempre pronto a udire il vostro insegnamento."
  },
  Voice_95091_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_95092_AwakerVoiceContent = {
    Text = "Vi prego, illuminatemi, mia Luce Guida! Grazie alla vostra luce, ho ora veduto tutto ciò che doveva essere veduto... Userò questa forma maledetta per purificare tutto ciò che è stato, e lascerò che tutto ciò che verrà si bagni nella vostra radiosità!"
  },
  Voice_95092_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_95092_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_95093_AwakerVoiceContent = {
    Text = "Luce cantata!"
  },
  Voice_95093_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_95391_AwakerVoiceContent = {
    Text = "Cerchi la salvezza in questo mondo orrendo? Continua così, piccolo pieno di speranza."
  },
  Voice_95391_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_95391_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_95392_AwakerVoiceContent = {
    Text = "Tieni, prendi questi. Reliquie proibite da qualche rovina. Stavo per bruciarle, ma ho pensato che potessero tornarti utili. Come le ho ottenute? Diciamo che qualcuno le ha cedute <Italic:volontariamente>. E non preoccuparti, la provenienza è pulita."
  },
  Voice_95392_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_95392_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_95393_AwakerVoiceContent = {
    Text = "Caccia finita. Il pagamento? Regalami un sorriso. Quello basterà."
  },
  Voice_95393_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_95394_AwakerVoiceContent = {
    Text = "Sai, queste pistole non sparano proiettili. Sparano desiderio e malvagità. Sette colpi, e tutto brucia. Queste fiamme caotiche, simili a carne, trascineranno ogni cosa nell'inferno."
  },
  Voice_95394_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito delle armi"
  },
  Voice_95395_AwakerVoiceContent = {
    Text = "Non sforzarti troppo, Custode. So che là fuori è dura, e un passo falso significa il disastro. Ma se continui così, crollerai. Vieni a cercarmi quando hai bisogno di qualcuno con cui parlare. Siamo famiglia."
  },
  Voice_95395_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_95395_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_95396_AwakerVoiceContent = {
    Text = "Brucia. Frantuma. Ulula!"
  },
  Voice_95396_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_95397_AwakerVoiceContent = {Text = "Sparisci."},
  Voice_95397_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_95398_AwakerVoiceContent = {
    Text = "Ora vedo più chiaramente. Vedo ciò che si contorce sotto l'abisso... Io, Noi, necessitiamo di più potere. Per te. Per la mia famiglia. Devo..."
  },
  Voice_95398_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_95398_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_95399_AwakerVoiceContent = {
    Text = "Vieni qui. Siediti più vicino. Non c'è bisogno di essere così rigido. \nBuffo, vero? Quando ci siamo incontrati la prima volta, non avrei mai pensato di poter abbassare la guardia così. Ah, la potente Fiamma Vivente, che anela a una famiglia di cui fidarsi completamente.\nOra, promettimi una cosa. Quando verrà il giorno... quando non riuscirai più a resistere— pronuncia il Mio nome. E Io, Noi, verremo. Ti accoglieremo nel Nostro Regno. Forse ritarderà solo l'inevitabile... ma nei tuoi ultimi istanti, riposerai, cullato nel Nostro abbraccio."
  },
  Voice_95399_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_95399_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_95400_AwakerVoiceContent = {
    Text = "La tua fine è vicina."
  },
  Voice_95400_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_95401_AwakerVoiceContent = {Text = "Ugh!"},
  Voice_95401_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_95402_AwakerVoiceContent = {
    Text = "Nella fornace dell'ira infinita e dei desideri... Brucia!"
  },
  Voice_95402_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_95403_AwakerVoiceContent = {
    Text = "Dopo una buona caccia viene un buon festino. Tieni, prova il mio cammello arrosto e tequila fresca. Come? Non reggi l'alcol? Va bene, allora prendi del succo."
  },
  Voice_95403_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_95403_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_95404_AwakerVoiceContent = {
    Text = "Che succede, piccola? Hai bisogno di un abbraccio? Vieni qui. La sorellona ti ha preso... Haha, non essere timida."
  },
  Voice_95404_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_95406_AwakerVoiceContent = {
    Text = "Dannazione."
  },
  Voice_95406_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_95407_AwakerVoiceContent = {
    Text = "La Morte color ambra è qui."
  },
  Voice_95407_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_95408_AwakerVoiceContent = {
    Text = "Ripiegate, vi copro io... Non temere, io torno sempre vivo."
  },
  Voice_95408_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_95409_AwakerVoiceContent = {
    Text = "Forza. Diamo fuoco a questo mondo intero!"
  },
  Voice_95409_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_95410_AwakerVoiceContent = {
    Text = "Fuoco ardente, sorgi dalle ceneri e dall'oblio!"
  },
  Voice_95410_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_95411_AwakerVoiceContent = {
    Text = "Il fuoco arde più intenso. Vuoi vedere un vero spettacolo pirotecnico, piccolo?"
  },
  Voice_95411_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_95412_AwakerVoiceContent = {
    Text = "Quei bastardi malati che giocano con le vite umane nell'ombra? Già. Li ammazzo tutti. Fino all'ultimo."
  },
  Voice_95412_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_95413_AwakerVoiceContent = {Text = "Bang!"},
  Voice_95413_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_95414_AwakerVoiceContent = {
    Text = "Lo troverò. Non importa dove si nasconda in questo universo marcio. Quel lurido ratto la pagherà. Ogni singola briciola della Sua \"estasi e delizia\" brucerà nel fuoco infernale. Stai tranquillo, ti riserverò un posto in prima fila al Suo funerale... così potremo assaporare insieme le Sue ultime urla."
  },
  Voice_95414_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito di N"
  },
  Voice_95415_AwakerVoiceContent = {
    Text = "Ascolta. Sono le grida morenti delle stelle che si dissolvono."
  },
  Voice_95415_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_95415_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_95416_AwakerVoiceContent = {
    Text = "La tua fine è vicina."
  },
  Voice_95416_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_95417_AwakerVoiceContent = {
    Text = "Sei la mia famiglia. E sono dannatamente fiera di te. Quindi tieni la testa alta, %player% mio! Qualunque cosa accada, io ti copro le spalle."
  },
  Voice_95417_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_95418_AwakerVoiceContent = {
    Text = "Quelle cose innominabili strisciano nell'oscurità, rodendo i confini del mondo. Prima o poi, dovrai affrontarle. Ma non preoccuparti, io ti copro le spalle. Sempre."
  },
  Voice_95418_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_95418_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_95420_AwakerVoiceContent = {
    Text = "Brucia. Frantuma. Ulula!"
  },
  Voice_95420_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_95421_AwakerVoiceContent = {
    Text = "Mantieni la calma."
  },
  Voice_95421_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_95422_AwakerVoiceContent = {
    Text = "Fai un passo indietro."
  },
  Voice_95422_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_95423_AwakerVoiceContent = {
    Text = "Cosa penso della Dissoluzione? Chiedi a un topo di fogna cosa pensa del re. La mia risposta è semplice: un disgusto profondo, istintivo. Datemi l'occasione e mi verserò un bicchiere di vino al latte di cammello per ascoltare le loro urla mentre le mie pistole li riducono in cenere."
  },
  Voice_95423_AwakerVoiceTitle = {
    Text = "Chiacchiere: Riguardo alla Crisi"
  },
  Voice_95424_AwakerVoiceContent = {
    Text = "Vuoi far ardere le fiamme ancora più intense?"
  },
  Voice_95424_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_95424_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_95425_AwakerVoiceContent = {
    Text = "Vengo solo quando c'è lavoro. Hai bisogno di me? Dì le parole. Avanti, ripeti con me: ...@4...@2Ia! Kathigu-Ra!"
  },
  Voice_95425_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_95426_AwakerVoiceContent = {
    Text = "In quella fogna di città, sopravvivevamo essendo più spietati degli altri. Anche dopo esserci fatti strada con le unghie e coi denti, dovevamo guardarci le spalle — signori, guardie, quei maledetti \"nobili cavalieri\" aggrappati al passato. Ora è diverso. Loro sono la mia famiglia. La mia Stirpe. Basta inchinarsi. C'è solo un piccolo randagio ancora là fuori... ma quello? Quello se la caverà benissimo. Si è sempre preso cura degli altri al posto mio mentre ero via."
  },
  Voice_95426_AwakerVoiceTitle = {
    Text = "Chiacchiere: A proposito della famiglia"
  },
  Voice_95427_AwakerVoiceContent = {
    Text = "Quello è il tuo nemico? Allora la caccia è aperta."
  },
  Voice_95427_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_95428_AwakerVoiceContent = {
    Text = "Io sono il Signore della Fiamma Viva—indimenticabile, inarrestabile! Contemplate ora, L'ANNIENTAMENTO DI OGNI COSA!"
  },
  Voice_95428_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_95429_AwakerVoiceContent = {
    Text = "Bruciare e Distruzione sono il mio tutto, sono ossessionata dalla morte che viene dalla caccia... Pensi davvero che direi una cosa del genere? Ahah. Mi è sempre importato solo della mia famiglia... Ancora più che di me stessa."
  },
  Voice_95429_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_95430_AwakerVoiceContent = {
    Text = "Sei nei guai, ragazzino? Kathigu-Ra sta arrivando, e porta con sé la Distruzione. Di' addio ai tuoi problemi. Puf! Spariti."
  },
  Voice_95430_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_95431_AwakerVoiceContent = {
    Text = "Ah, il sapore del potere... Troviamo qualche povero disgraziato su cui metterlo alla prova?"
  },
  Voice_95431_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_95431_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_95432_AwakerVoiceContent = {
    Text = "Io sono il Signore della Fiamma Viva—indimenticabile, inarrestabile! Contemplate ora, L'ANNIENTAMENTO DI OGNI COSA!"
  },
  Voice_95432_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_95433_AwakerVoiceContent = {
    Text = "La leggendaria Regina di Aram, il Grande Eone del Desiderio, Tifere Yesod... L'ho vista una volta, quando davo la caccia a N. Non condivido i suoi metodi, ma... se fosse stato l'unico modo per proteggere la mia famiglia dal \"Suo\" sguardo... avrei fatto lo stesso. Non siamo poi così diverse, lei e io."
  },
  Voice_95433_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Thais"
  },
  Voice_95433_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Thais\""
  },
  Voice_95434_AwakerVoiceContent = {
    Text = "Bel lavoro tenere il tuo ferro pulito. Un'arma lucida è un'arma felice."
  },
  Voice_95434_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_95435_AwakerVoiceContent = {
    Text = "Noi siamo il Fuoco. La Fiamma Eterna. Il Caos Immortale. E vi riporteremo tutti... a casa..."
  },
  Voice_95435_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_95435_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_96361_AwakerVoiceContent = {
    Text = "Adoro la bellezza classica della torre dell'orologio gotica di questa istituzione. E i Risvegliati qui, ah... Emanano un aroma che non ho mai assaporato: una miscela perfetta di fragranza di defunto e una traccia di profumo vivente. Mi fa davvero venire voglia di dare un piccolo morso."
  },
  Voice_96361_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Mythag"
  },
  Voice_96362_AwakerVoiceContent = {
    Text = "Se la morte è ciò che cercate, allora esaudirò il vostro desiderio."
  },
  Voice_96362_AwakerVoiceTitle = {
    Text = "Esaltazione: II"
  },
  Voice_96363_AwakerVoiceContent = {
    Text = "Sono piuttosto impaziente di cominciare."
  },
  Voice_96363_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_96364_AwakerVoiceContent = {
    Text = "Ho finalmente destato il vostro interesse? Venite, mio caro ospite, sedetevi alla mia tavola e prendete parte a questo grande banchetto. Lasciate che vi faccia da guida mentre assaporiamo insieme il delicato bagliore residuo di ogni spirito."
  },
  Voice_96364_AwakerVoiceTitle = {
    Text = "Illuminare: Fioritura"
  },
  Voice_96364_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 15"
  },
  Voice_96365_AwakerVoiceContent = {
    Text = "Shhh, per favore, fate silenzio. Ascoltiamo le voci dei Defunti."
  },
  Voice_96365_AwakerVoiceTitle = {
    Text = "Affinità: I"
  },
  Voice_96365_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 2"
  },
  Voice_96366_AwakerVoiceContent = {
    Text = "Il mio popolo e io veneriamo la bellezza della permanenza. La Dissoluzione corrode lentamente una persona vivente, cancellando ogni traccia della sua esistenza... Una tortura così crudele non dovrebbe essere permessa."
  },
  Voice_96366_AwakerVoiceTitle = {
    Text = "Chiacchiere: Riguardo alla Crisi"
  },
  Voice_96367_AwakerVoiceContent = {
    Text = "Come me, il Sig. Pickman è alla Caccia della bellezza immortalata. Avremmo potuto diventare amici più intimi. Ma lui considera il cibarsi una violazione dell'eternità preservata. Una filosofia artistica così limitata."
  },
  Voice_96367_AwakerVoiceTitle = {
    Text = "Chat: A proposito di Pickman"
  },
  Voice_96367_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Pickman\""
  },
  Voice_96368_AwakerVoiceContent = {Text = "Ha!"},
  Voice_96368_AwakerVoiceTitle = {Text = "Colpo: I"},
  Voice_96369_AwakerVoiceContent = {
    Text = "Nessun aggettivo può descrivere l'inebriante fragranza del tuo corpo. È come il retrogusto asprigno di un ricco vino di Bordeaux, e l'aroma denso di un soffice pan di Spagna burroso e vellutato. Il giorno della tua morte sarà forse l'evento più importante del tempo che mi resta."
  },
  Voice_96369_AwakerVoiceTitle = {
    Text = "Chiacchiere: Sul Custode"
  },
  Voice_96370_AwakerVoiceContent = {
    Text = "C'era un uomo che intagliava lentamente la carne di una giovane ragazza, le unghie, le mani e i piedi, il tutto mentre la guariva senza sosta. Non voleva che morisse, né che vivesse. Io, naturalmente, non potevo concedergli una morte serena. Così gli feci assaggiare la sua stessa medicina. Mi chiedo quanti anni sia rimasto intrappolato laggiù... Per chi profana la morte, è piuttosto equo, non trovate?"
  },
  Voice_96370_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che odio"
  },
  Voice_96371_AwakerVoiceContent = {
    Text = "Io presiedo alla morte, ma vi prego, non fraintendetemi. Non la creo mai; mi limito a seguirne la scia, raccogliendo i bocconi più prelibati lasciati indietro."
  },
  Voice_96371_AwakerVoiceTitle = {
    Text = "Illuminare: Osservazione"
  },
  Voice_96371_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 1"
  },
  Voice_96372_AwakerVoiceContent = {
    Text = "Anche voi bramate il sapore della mia carne, caro Custode?"
  },
  Voice_96372_AwakerVoiceTitle = {
    Text = "Chiacchiere: Tocco"
  },
  Voice_96373_AwakerVoiceContent = {
    Text = "Chi avrà l'onore di sedere alla mia tavola oggi, mi chiedo?"
  },
  Voice_96373_AwakerVoiceTitle = {
    Text = "Indagine avviata"
  },
  Voice_96374_AwakerVoiceContent = {
    Text = "Vi conferirò l'onore di diventare il festino di questa sera."
  },
  Voice_96374_AwakerVoiceTitle = {
    Text = "Indagine Riuscita"
  },
  Voice_96375_AwakerVoiceContent = {
    Text = "Quanto terribilmente inelegante."
  },
  Voice_96375_AwakerVoiceTitle = {
    Text = "Colpo Subito: III"
  },
  Voice_96376_AwakerVoiceContent = {
    Text = "Vi porterò un riposo sereno."
  },
  Voice_96376_AwakerVoiceTitle = {
    Text = "Abilità: I"
  },
  Voice_96377_AwakerVoiceContent = {
    Text = "Prima di ogni pasto, converso con i Defunti. Per loro, essere consumati e assaporati con sincera devozione è una continuazione della vita e il loro ultimo, più glorioso momento.\nCome io anelo a loro, anch'essi anelano a me."
  },
  Voice_96377_AwakerVoiceTitle = {
    Text = "Affinità: III"
  },
  Voice_96377_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 6"
  },
  Voice_96378_AwakerVoiceContent = {
    Text = "Silenzio, volete?"
  },
  Voice_96378_AwakerVoiceTitle = {
    Text = "Colpo Subito: IV"
  },
  Voice_96379_AwakerVoiceContent = {
    Text = "Disperdetevi e svanite nelle ombre!"
  },
  Voice_96379_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_96380_AwakerVoiceContent = {
    Text = "Manteniamo le distanze."
  },
  Voice_96380_AwakerVoiceTitle = {Text = "Difesa: I"},
  Voice_96381_AwakerVoiceContent = {
    Text = "Disperdetevi e svanite nelle ombre!"
  },
  Voice_96381_AwakerVoiceTitle = {
    Text = "Abilità: IV"
  },
  Voice_96382_AwakerVoiceContent = {
    Text = "Perché siete così diffidente nei miei confronti? Non dovete e non dovreste allarmarvi; nutrirsi di un essere umano vivo è contrario alla mia estetica."
  },
  Voice_96382_AwakerVoiceTitle = {
    Text = "Chat: A proposito del cibo"
  },
  Voice_96383_AwakerVoiceContent = {
    Text = "Se la morte è ciò che cercate, allora esaudirò il vostro desiderio."
  },
  Voice_96383_AwakerVoiceTitle = {
    Text = "Esaltazione"
  },
  Voice_96384_AwakerVoiceContent = {
    Text = "Quanto terribilmente inelegante."
  },
  Voice_96384_AwakerVoiceTitle = {
    Text = "Colpo Subito: I"
  },
  Voice_96385_AwakerVoiceContent = {
    Text = "Fa' attenzione."
  },
  Voice_96385_AwakerVoiceTitle = {Text = "Difesa: II"},
  Voice_96386_AwakerVoiceContent = {
    Text = "Per quanto l'entusiasmo di quella signora sia molto commovente, il suo corpo emana un odore umido, come di fermentazione eccessiva. Nonostante continui a supplicarmi di assaggiare, semplicemente non si addice al mio palato. Che tormento."
  },
  Voice_96386_AwakerVoiceTitle = {
    Text = "Chiacchiere: Su Leigh"
  },
  Voice_96386_UnlockDesc = {
    Text = "Si sblocca dopo aver ottenuto il Risvegliato \"Leigh\""
  },
  Voice_96387_AwakerVoiceContent = {
    Text = [[
Lo sapete?
Ogni vita possiede un'eco duratura nel momento in cui svanisce.
Variano in altezza e tono, allungandosi poco a poco dall'istante in cui la morte giunge fino a dissiparsi nei cieli e nella terra, simili a un pianto sospirante.]]
  },
  Voice_96387_AwakerVoiceTitle = {
    Text = "Affinità: II"
  },
  Voice_96387_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 4"
  },
  Voice_96388_AwakerVoiceContent = {
    Text = "State tranquillo, {Male=Sig.,Female=Sig.na} Custode, resterò al vostro fianco fino al giorno in cui la vostra vita incontrerà la fine che il destino le ha assegnato. Quel giorno, con tutta la dovuta solennità, consumerò il vostro corpo pezzo per pezzo. E la vostra anima dimorerà in me, per sempre."
  },
  Voice_96388_AwakerVoiceTitle = {
    Text = "Affinità: V"
  },
  Voice_96388_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 10"
  },
  Voice_96389_AwakerVoiceContent = {
    Text = "Non riesci a sentire il tuo stesso odore? Ah, che peccato. Ti stai perdendo il più dolce, il più sublime... Oh, cielo, cos'è? Perché ti ritrai?"
  },
  Voice_96389_AwakerVoiceTitle = {
    Text = "Affinità: IV"
  },
  Voice_96389_UnlockDesc = {
    Text = "Si sblocca al Livello di Affinità 8"
  },
  Voice_96390_AwakerVoiceContent = {
    Text = "Vedo altre morti imminenti. L'altro lato si fa sempre più nitido..."
  },
  Voice_96390_AwakerVoiceTitle = {
    Text = "Potenziamento: III"
  },
  Voice_96391_AwakerVoiceContent = {
    Text = "Vi prego, affidatemi il vostro corpo. Vi assaporerò meticolosamente: ogni goccia di sangue, ogni brandello di carne, ogni singolo osso."
  },
  Voice_96391_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione"
  },
  Voice_96392_AwakerVoiceContent = {
    Text = "Ingredienti diversi esigono preparazioni diverse. Gli organi vanno marinati. I tendini delle zampe danno il meglio in uno stufato. Le parti grasse sono perfette per la fermentazione e la stagionatura, mentre i pezzi più delicati possono essere fritti, arrostiti, o persino trasformati in gelatine dalla forma squisita. Queste scelte sono tutte una questione di discernimento. Poiché senza preservare ed esaltare il sapore naturale dell'ingrediente, non vi è rispetto."
  },
  Voice_96392_AwakerVoiceTitle = {
    Text = "Illuminare: Intuizione"
  },
  Voice_96392_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 7"
  },
  Voice_96393_AwakerVoiceContent = {
    Text = "Potrebbe essere un po' gelido."
  },
  Voice_96393_AwakerVoiceTitle = {Text = "Colpo: II"},
  Voice_96394_AwakerVoiceContent = {
    Text = "Anche l'abbinamento delle portate riveste grande importanza."
  },
  Voice_96394_AwakerVoiceTitle = {
    Text = "Illuminare: Elevazione"
  },
  Voice_96394_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 11"
  },
  Voice_96395_AwakerVoiceContent = {
    Text = "Vi ringrazio infinitamente per il vostro entusiasmo. L'onore è tutto mio."
  },
  Voice_96395_AwakerVoiceTitle = {
    Text = "Potenziamento: II"
  },
  Voice_96396_AwakerVoiceContent = {
    Text = "Il cibo davvero delizioso vale sempre l'attesa."
  },
  Voice_96396_AwakerVoiceTitle = {
    Text = "Indagine interrotta"
  },
  Voice_96397_AwakerVoiceContent = {
    Text = "Non sono una bestia barbarica che si ingozza di carne cruda. Il consumo della morte è un affare solenne ed elegante. Bisogna entrare in comunione con ogni ingrediente e comprenderne davvero il sapore unico."
  },
  Voice_96397_AwakerVoiceTitle = {
    Text = "Illuminare: Meditazione"
  },
  Voice_96397_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 2"
  },
  Voice_96398_AwakerVoiceContent = {
    Text = "I defunti che hanno trovato pace sono belli e fragranti. La loro bellezza non risiede nella carne, né prima né dopo la morte, ma nelle loro anime. L'illuminazione di quelle anime riguardo alla morte, il loro anelito per la vita e il desiderio di essere ricordati sono le prelibatezze che ho sempre sognato."
  },
  Voice_96398_AwakerVoiceTitle = {
    Text = "Chiacchiere: Ciò che mi piace"
  },
  Voice_96399_AwakerVoiceContent = {
    Text = "Nessun profumo è paragonabile alla fragranza naturale del corpo umano. Conoscere una persona dal suo odore è un piacere semplicemente divino."
  },
  Voice_96399_AwakerVoiceTitle = {
    Text = "Illuminare: Riflessione"
  },
  Voice_96399_UnlockDesc = {
    Text = "Si sblocca al Livello di Illuminazione 3"
  },
  Voice_96400_AwakerVoiceContent = {
    Text = "Ah, che profumo indimenticabile... Non vedo l'ora di darti il benvenuto nel mio santuario."
  },
  Voice_96400_AwakerVoiceTitle = {Text = "Risveglio"},
  Voice_96401_AwakerVoiceContent = {
    Text = "Vi prego, affidatemi il vostro corpo. Vi assaporerò meticolosamente: ogni goccia di sangue, ogni brandello di carne, ogni singolo osso."
  },
  Voice_96401_AwakerVoiceTitle = {
    Text = "Sovra-Esaltazione: II"
  },
  Voice_96402_AwakerVoiceContent = {
    Text = "Vi porterò un riposo sereno."
  },
  Voice_96402_AwakerVoiceTitle = {
    Text = "Abilità: II"
  },
  Voice_96403_AwakerVoiceContent = {
    Text = "Silenzio, volete?"
  },
  Voice_96403_AwakerVoiceTitle = {
    Text = "Colpo Subito: II"
  },
  Voice_96404_AwakerVoiceContent = {
    Text = "Il tuo fragrante aroma è assolutamente inebriante."
  },
  Voice_96404_AwakerVoiceTitle = {
    Text = "Potenziamento: I"
  },
  Voice_98324_AwakerVoiceContent = {
    Text = "Nella fornace dell'ira infinita e dei desideri... Brucia!"
  },
  Voice_98324_AwakerVoiceTitle = {
    Text = "Abilità Speciale: I"
  }
})
return Text_Voice
